// SPDX-License-Identifier: Apache-2.0

pragma solidity ^0.8.20;

import {Paymaster} from "./Paymaster.sol";
import {ContractStatus} from "../abstract/ContractStatus.sol";
import {INamed} from "../interfaces/INamed.sol";
import {IVersioned} from "../interfaces/IVersioned.sol";

contract PaymasterManager is INamed, IVersioned, ContractStatus {
    string private constant _NAME = "PaymasterManager";
    string private constant _VERSION = "1.0.0";

    event PaymasterDeployed(address indexed deployer, address indexed paymasterAddress);

    mapping(address => bool) public validPaymasters;
    mapping(address => address[]) public deployedPaymasters;

    constructor(address hubAddress) ContractStatus(hubAddress) {}

    function name() public pure virtual returns (string memory) {
        return _NAME;
    }

    function version() external pure virtual returns (string memory) {
        return _VERSION;
    }

    function deployPaymaster() external {
        address paymasterAddress = address(new Paymaster(address(hub)));

        validPaymasters[paymasterAddress] = true;
        deployedPaymasters[msg.sender].push(paymasterAddress);

        emit PaymasterDeployed(msg.sender, paymasterAddress);
    }
}

contracts/archive/PublishingConvictionAc.content:
// SPDX-License-Identifier: Apache-2.0

pragma solidity ^0.8.20;

import {INamed} from "../interfaces/INamed.sol";
import {IVersioned} from "../interfaces/IVersioned.sol";
import {IInitializable} from "../interfaces/IInitializable.sol";
import {ContractStatus} from "../abstract/ContractStatus.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";

/**
 * @title PublishingConvictionAccount
 * @notice Publishers who lock TRAC long-term receive discounted publishing fees.
 *
 * The locked TRAC IS the spending balance — each publish deducts from it at the
 * discounted rate. The discount is flat: determined by the initial lock duration
 * and amount, not by remaining lock time.
 *
 * conviction = lockedTRAC × initialLockEpochs
 * discount   = maxDiscount × conviction / (conviction + C_half)
 */
contract PublishingConvictionAccount is INamed, IVersioned, ContractStatus, IInitializable {
    string private constant _NAME = "PublishingConvictionAccount";
    string private constant _VERSION = "1.0.0";

    uint256 public constant MAX_DISCOUNT_BPS = 5000; // 50% in basis points
    uint256 public constant C_HALF = 3_000_000 ether;
    uint256 public constant BPS_DENOMINATOR = 10000;

    struct Account {
        address admin;
        uint96 balance;
        uint96 initialDeposit;
        uint40 lockEpochs;
        uint40 createdAtEpoch;
        uint256 conviction;
    }

    IERC20 public tokenContract;
    uint256 public nextAccountId;
    mapping(uint256 => Account) public accounts;
    mapping(uint256 => mapping(address => bool)) public authorizedKeys;
    mapping(address => uint256) public adminToAccountId;

    event AccountCreated(uint256 indexed accountId, address indexed admin, uint96 amount, uint40 lockEpochs);
    event FundsAdded(uint256 indexed accountId, uint96 amount, uint96 newBalance);
    event LockExtended(uint256 indexed accountId, uint40 newTotalLockEpochs, uint256 newConviction);
    event AuthorizedKeyAdded(uint256 indexed accountId, address indexed key);
    event AuthorizedKeyRemoved(uint256 indexed accountId, address indexed key);
    event CostCovered(uint256 indexed accountId, uint96 baseCost, uint96 discountedCost);
    event Withdrawal(uint256 indexed accountId, uint96 amount);

    error AccountNotFound(uint256 accountId);
    error NotAccountAdmin(uint256 accountId, address caller);
    error NotAuthorized(uint256 accountId, address caller);
    error InsufficientBalance(uint256 accountId, uint96 required, uint96 available);
    error LockNotExpired(uint256 accountId, uint40 expiresAtEpoch);
    error InvalidLockEpochs();
    error InvalidAmount();
    error AdminAlreadyHasAccount(address admin);

    constructor(address hubAddress) ContractStatus(hubAddress) {}

    function initialize() public onlyHub {
        tokenContract = IERC20(hub.getContractAddress("Token"));
        if (nextAccountId == 0) nextAccountId = 1;
    }

    function name() public pure virtual returns (string memory) {
        return _NAME;
    }

    function version() external pure virtual returns (string memory) {
        return _VERSION;
    }

    function createAccount(uint96 amount, uint40 lockEpochs) external returns (uint256 accountId) {
        if (amount == 0) revert InvalidAmount();
        if (lockEpochs == 0) revert InvalidLockEpochs();
        if (adminToAccountId[msg.sender] != 0) revert AdminAlreadyHasAccount(msg.sender);

        accountId = nextAccountId++;
        uint256 conviction = uint256(amount) * uint256(lockEpochs);

        accounts[accountId] = Account({
            admin: msg.sender,
            balance: amount,
            initialDeposit: amount,
            lockEpochs: lockEpochs,
            createdAtEpoch: 0, // set externally or by Chronos if available
            conviction: conviction
        });

        authorizedKeys[accountId][msg.sender] = true;
        adminToAccountId[msg.sender] = accountId;

        if (!tokenContract.transferFrom(msg.sender, address(this), amount)) {
            revert InvalidAmount();
        }

        emit AccountCreated(accountId, msg.sender, amount, lockEpochs);
    }

    function addFunds(uint256 accountId, uint96 amount) external {
        Account storage acct = _requireAccount(accountId);
        if (acct.admin != msg.sender) revert NotAccountAdmin(accountId, msg.sender);
        if (amount == 0) revert InvalidAmount();

        acct.balance += amount;

        if (!tokenContract.transferFrom(msg.sender, address(this), amount)) {
            revert InvalidAmount();
        }

        emit FundsAdded(accountId, amount, acct.balance);
    }

    function extendLock(uint256 accountId, uint40 additionalEpochs) external {
        Account storage acct = _requireAccount(accountId);
        if (acct.admin != msg.sender) revert NotAccountAdmin(accountId, msg.sender);
        if (additionalEpochs == 0) revert InvalidLockEpochs();

        acct.lockEpochs += additionalEpochs;
        acct.conviction = uint256(acct.initialDeposit) * uint256(acct.lockEpochs);

        emit LockExtended(accountId, acct.lockEpochs, acct.conviction);
    }

    function addAuthorizedKey(uint256 accountId, address key) external {
        Account storage acct = _requireAccount(accountId);
        if (acct.admin != msg.sender) revert NotAccountAdmin(accountId, msg.sender);

        authorizedKeys[accountId][key] = true;
        emit AuthorizedKeyAdded(accountId, key);
    }

    function removeAuthorizedKey(uint256 accountId, address key) external {
        Account storage acct = _requireAccount(accountId);
        if (acct.admin != msg.sender) revert NotAccountAdmin(accountId, msg.sender);

        authorizedKeys[accountId][key] = false;
        emit AuthorizedKeyRemoved(accountId, key);
    }

    /**
     * @notice Called by KnowledgeAssets contract to cover publishing cost at a discount.
     * Only authorized keys of the account can trigger this.
     */
    function coverPublishingCost(uint256 accountId, uint96 baseCost, address caller) external onlyContracts returns (uint96) {
        Account storage acct = _requireAccount(accountId);
        if (!authorizedKeys[accountId][caller]) revert NotAuthorized(accountId, caller);

        uint96 discountedCost = _applyDiscount(acct.conviction, baseCost);

        if (acct.balance < discountedCost) {
            revert InsufficientBalance(accountId, discountedCost, acct.balance);
        }

        acct.balance -= discountedCost;

        // v4.0.0 — TRAC vault moved from StakingStorage to CSS.
        if (!tokenContract.transfer(hub.getContractAddress("ConvictionStakingStorage"), discountedCost)) {
            revert InvalidAmount();
        }

        emit CostCovered(accountId, baseCost, discountedCost);
        return discountedCost;
    }

    function withdraw(uint256 accountId, uint96 amount) external {
        Account storage acct = _requireAccount(accountId);
        if (acct.admin != msg.sender) revert NotAccountAdmin(accountId, msg.sender);

        // Lock check is simplified — in production, integrate with Chronos for epoch tracking
        // For now, allow withdrawal only when balance exceeds initial deposit commitment
        if (acct.balance < amount) {
            revert InsufficientBalance(accountId, amount, acct.balance);
        }

        acct.balance -= amount;

        if (!tokenContract.transfer(msg.sender, amount)) {
            revert InvalidAmount();
        }

        emit Withdrawal(accountId, amount);
    }

    // ========================================================================
    // View Functions
    // ========================================================================

    function getDiscount(uint256 accountId) external view returns (uint256 discountBps) {
        Account storage acct = _requireAccount(accountId);
        return _computeDiscount(acct.conviction);
    }

    function getDiscountedCost(uint256 accountId, uint96 baseCost) external view returns (uint96) {
        Account storage acct = _requireAccount(accountId);
        return _applyDiscount(acct.conviction, baseCost);
    }

    function getAccountInfo(uint256 accountId) external view returns (
        address admin,
        uint96 balance,
        uint96 initialDeposit,
        uint40 lockEpochs,
        uint256 conviction,
        uint256 discountBps
    ) {
        Account storage acct = _requireAccount(accountId);
        return (
            acct.admin,
            acct.balance,
            acct.initialDeposit,
            acct.lockEpochs,
            acct.conviction,
            _computeDiscount(acct.conviction)
        );
    }

    // ========================================================================
    // Internal Helpers
    // ========================================================================

    function _requireAccount(uint256 accountId) internal view returns (Account storage) {
        Account storage acct = accounts[accountId];
        if (acct.admin == address(0)) revert AccountNotFound(accountId);
        return acct;
    }

    function _computeDiscount(uint256 conviction) internal pure returns (uint256) {
        if (conviction == 0) return 0;
        return (MAX_DISCOUNT_BPS * conviction) / (conviction + C_HALF);
    }

    function _applyDiscount(uint256 conviction, uint96 baseCost) internal pure returns (uint96) {
        uint256 discountBps = _computeDiscount(conviction);
        return uint96(uint256(baseCost) * (BPS_DENOMINATOR - discountBps) / BPS_DENOMINATOR);
    }
}

contracts/archive/Staking.sol.content:
// SPDX-License-Identifier: Apache-2.0

pragma solidity ^0.8.20;

import {ShardingTable} from "../ShardingTable.sol";
import {Ask} from "../Ask.sol";
import {IdentityStorage} from "../storage/IdentityStorage.sol";
import {ParametersStorage} from "../storage/ParametersStorage.sol";
import {ProfileStorage} from "../storage/ProfileStorage.sol";
import {ShardingTableStorage} from "../storage/ShardingTableStorage.sol";
import {StakingStorage} from "../storage/StakingStorage.sol";
import {DelegatorsInfo} from "./DelegatorsInfo.sol";
import {ContractStatus} from "../abstract/ContractStatus.sol";
import {IInitializable} from "../interfaces/IInitializable.sol";
import {INamed} from "../interfaces/INamed.sol";
import {IVersioned} from "../interfaces/IVersioned.sol";
import {ProfileLib} from "../libraries/ProfileLib.sol";
import {ShardingTableLib} from "../libraries/ShardingTableLib.sol";
import {StakingLib} from "../libraries/StakingLib.sol";
import {TokenLib} from "../libraries/TokenLib.sol";
import {IdentityLib} from "../libraries/IdentityLib.sol";
import {Permissions} from "../libraries/Permissions.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {RandomSamplingStorage} from "../storage/RandomSamplingStorage.sol";
import {Chronos} from "../storage/Chronos.sol";
import {EpochStorage} from "../storage/EpochStorage.sol";

contract Staking is INamed, IVersioned, ContractStatus, IInitializable {
    string private constant _NAME = "Staking";
    string private constant _VERSION = "1.0.1";
    uint256 public constant SCALE18 = 1e18;
    uint256 private constant EPOCH_POOL_INDEX = 1;

    Ask public askContract;
    ShardingTableStorage public shardingTableStorage;
    ShardingTable public shardingTableContract;
    IdentityStorage public identityStorage;
    ParametersStorage public parametersStorage;
    ProfileStorage public profileStorage;
    StakingStorage public stakingStorage;
    DelegatorsInfo public delegatorsInfo;
    IERC20 public tokenContract;
    RandomSamplingStorage public randomSamplingStorage;
    Chronos public chronos;
    EpochStorage public epochStorage;

    // solhint-disable-next-line no-empty-blocks
    constructor(address hubAddress) ContractStatus(hubAddress) {}

    modifier onlyAdmin(uint72 identityId) {
        _checkAdmin(identityId);
        _;
    }

    modifier profileExists(uint72 identityId) {
        _checkProfileExists(identityId);
        _;
    }

    /**
     * @dev Initializes the contract by connecting to all required Hub dependencies
     * Called once during deployment to set up contract references
     * Only the Hub can call this function
     */
    function initialize() external onlyHub {
        askContract = Ask(hub.getContractAddress("Ask"));
        shardingTableStorage = ShardingTableStorage(hub.getContractAddress("ShardingTableStorage"));
        shardingTableContract = ShardingTable(hub.getContractAddress("ShardingTable"));
        identityStorage = IdentityStorage(hub.getContractAddress("IdentityStorage"));
        parametersStorage = ParametersStorage(hub.getContractAddress("ParametersStorage"));
        profileStorage = ProfileStorage(hub.getContractAddress("ProfileStorage"));
        stakingStorage = StakingStorage(hub.getContractAddress("StakingStorage"));
        delegatorsInfo = DelegatorsInfo(hub.getContractAddress("DelegatorsInfo"));
        tokenContract = IERC20(hub.getContractAddress("Token"));
        randomSamplingStorage = RandomSamplingStorage(hub.getContractAddress("RandomSamplingStorage"));
        chronos = Chronos(hub.getContractAddress("Chronos"));
        epochStorage = EpochStorage(hub.getContractAddress("EpochStorageV8"));
    }

    /**
     * @dev Returns the name of this contract
     * Used for contract identification and versioning
     */
    function name() external pure virtual override returns (string memory) {
        return _NAME;
    }

    /**
     * @dev Returns the version of this contract
     * Used for contract identification and versioning
     */
    function version() external pure virtual override returns (string memory) {
        return _VERSION;
    }

    /**
     * @dev Stakes tokens to a specific node, increasing both delegator and node stake
     * Transfers tokens from caller to StakingStorage, updates sharding table and active set
     * Validates token allowance, balance, and maximum stake limits
     * Must settle any pending previous epoch rewards before changing stake
     * @param identityId The node to stake to (must exist)
     * @param addedStake Amount of tokens to stake (must be > 0)
     */
    function stake(uint72 identityId, uint96 addedStake) external profileExists(identityId) {
        _stake(identityId, addedStake);
    }

    function _stake(uint72 identityId, uint96 addedStake) internal {
        IERC20 token = tokenContract;
        StakingStorage ss = stakingStorage;

        if (addedStake == 0) {
            revert TokenLib.ZeroTokenAmount();
        }
        if (token.allowance(msg.sender, address(this)) < addedStake) {
            revert TokenLib.TooLowAllowance(address(token), token.allowance(msg.sender, address(this)), addedStake);
        }
        if (token.balanceOf(msg.sender) < addedStake) {
            revert TokenLib.TooLowBalance(address(token), token.balanceOf(msg.sender), addedStake);
        }

        // Validate that all claims have been settled for the node before changing stake
        _validateDelegatorEpochClaims(identityId, msg.sender);

        bytes32 delegatorKey = _getDelegatorKey(msg.sender);
        uint256 currentEpoch = chronos.getCurrentEpoch();
        // settle all pending score changes for the node's delegator
        _prepareForStakeChange(currentEpoch, identityId, delegatorKey);

        uint96 delegatorStakeBase = stakingStorage.getDelegatorStakeBase(identityId, delegatorKey);

        uint96 totalNodeStakeBefore = ss.getNodeStake(identityId);
        uint96 totalNodeStakeAfter = totalNodeStakeBefore + addedStake;
        if (totalNodeStakeAfter > parametersStorage.maximumStake()) {
            revert StakingLib.MaximumStakeExceeded(parametersStorage.maximumStake());
        }
        ss.setDelegatorStakeBase(identityId, delegatorKey, delegatorStakeBase + addedStake);
        ss.setNodeStake(identityId, totalNodeStakeAfter);
        ss.increaseTotalStake(addedStake);

        _addNodeToShardingTable(identityId, totalNodeStakeAfter);

        askContract.recalculateActiveSet();

        // Check if this is first time staking
        _manageDelegatorStatus(identityId, msg.sender);

        token.transferFrom(msg.sender, address(ss), addedStake);
    }

    /**
     * @dev Moves stake from one node to another without unstaking/restaking process
     * Validates both source and destination nodes exist and all claims are settled
     * Updates stake amounts, sharding table, and active set for both nodes
     * Handles delegator removal if all stake is moved from source node and no score was earned in the current epoch
     * Must settle any pending previous epoch rewards before redelegating
     * @param fromIdentityId Source node to move stake from
     * @param toIdentityId Destination node to move stake to (cannot be same as source)
     * @param stakeAmount Amount of stake to move (must be > 0 and <= delegator's stake)
     */
    function redelegate(
        uint72 fromIdentityId,
        uint72 toIdentityId,
        uint96 stakeAmount
    ) external profileExists(fromIdentityId) profileExists(toIdentityId) {
        StakingStorage ss = stakingStorage;
        Ask ask = askContract;

        if (fromIdentityId == toIdentityId) {
            revert("Cannot redelegate to the same node");
        }

        if (stakeAmount == 0) {
            revert TokenLib.ZeroTokenAmount();
        }

        bytes32 delegatorKey = _getDelegatorKey(msg.sender);
        uint256 currentEpoch = chronos.getCurrentEpoch();

        // Validate that all claims have been settled for the source and destination nodes before changing stake
        _validateDelegatorEpochClaims(fromIdentityId, msg.sender);
        _validateDelegatorEpochClaims(toIdentityId, msg.sender);

        // Prepare for stake change on the source and destination nodes
        uint256 fromDelegatorEpochScore18 = _prepareForStakeChange(currentEpoch, fromIdentityId, delegatorKey);
        // settle all pending score changes for the node's delegator
        _prepareForStakeChange(currentEpoch, toIdentityId, delegatorKey);

        uint96 fromDelegatorStakeBase = ss.getDelegatorStakeBase(fromIdentityId, delegatorKey);

        if (stakeAmount > fromDelegatorStakeBase) {
            revert StakingLib.WithdrawalExceedsStake(fromDelegatorStakeBase, stakeAmount);
        }

        uint96 maxStake = parametersStorage.maximumStake();
        if (ss.getNodeStake(toIdentityId) + stakeAmount > maxStake) {
            revert StakingLib.MaximumStakeExceeded(maxStake);
        }

        // calculate new delegator stake base on the source node
        uint96 newFromDelegatorStakeBase = fromDelegatorStakeBase - stakeAmount;

        // calculate new total node stake on the source node
        uint96 totalFromNodeStakeBefore = ss.getNodeStake(fromIdentityId);
        uint96 totalFromNodeStakeAfter = totalFromNodeStakeBefore - stakeAmount;

        // calculate new total node stake on the destination node
        uint96 totalToNodeStakeBefore = ss.getNodeStake(toIdentityId);
        uint96 totalToNodeStakeAfter = totalToNodeStakeBefore + stakeAmount;

        // update the delegator stake base and the total node stake on the source node
        ss.setDelegatorStakeBase(fromIdentityId, delegatorKey, newFromDelegatorStakeBase);
        ss.setNodeStake(fromIdentityId, totalFromNodeStakeAfter);

        _removeNodeFromShardingTable(fromIdentityId, totalFromNodeStakeAfter);

        // update the delegator stake base and the total node stake on the destination node
        ss.increaseDelegatorStakeBase(toIdentityId, delegatorKey, stakeAmount);
        ss.setNodeStake(toIdentityId, totalToNodeStakeAfter);

        _addNodeToShardingTable(toIdentityId, totalToNodeStakeAfter);

        ask.recalculateActiveSet();

        // Check if all stake is being removed from the source node
        if (newFromDelegatorStakeBase == 0) {
            _handleDelegatorRemovalOnZeroStake(fromIdentityId, msg.sender, fromDelegatorEpochScore18, currentEpoch);
        }

        _manageDelegatorStatus(toIdentityId, msg.sender);
    }

    /**
     * @dev Initiates withdrawal process for staked tokens with time delay
     * For nodes above maximum stake: tokens are transferred immediately
     * For other nodes: creates withdrawal request with delay period
     * Updates sharding table/active set
     * Removes delegator from node if all stake is withdrawn and no score was earned in the current epoch
     * Must settle any pending previous epoch rewards before withdrawing
     * @param identityId Node to withdraw stake from (must exist)
     * @param removedStake Amount to withdraw (must be > 0 and <= delegator's stake)
     */
    function requestWithdrawal(uint72 identityId, uint96 removedStake) external profileExists(identityId) {
        StakingStorage ss = stakingStorage;

        if (removedStake == 0) {
            revert TokenLib.ZeroTokenAmount();
        }

        // Validate that all claims have been settled for the node before changing stake
        _validateDelegatorEpochClaims(identityId, msg.sender);

        bytes32 delegatorKey = _getDelegatorKey(msg.sender);
        uint256 currentEpoch = chronos.getCurrentEpoch();

        // settle all pending score changes for the node's delegator
        uint256 delegatorEpochScore18 = _prepareForStakeChange(currentEpoch, identityId, delegatorKey);

        uint96 delegatorStakeBase = ss.getDelegatorStakeBase(identityId, delegatorKey);
        if (removedStake > delegatorStakeBase) {
            revert StakingLib.WithdrawalExceedsStake(delegatorStakeBase, removedStake);
        }

        uint96 newDelegatorStakeBase = delegatorStakeBase - removedStake;
        uint96 totalNodeStakeBefore = ss.getNodeStake(identityId);
        uint96 totalNodeStakeAfter = totalNodeStakeBefore - removedStake;

        ss.setDelegatorStakeBase(identityId, delegatorKey, newDelegatorStakeBase);
        ss.setNodeStake(identityId, totalNodeStakeAfter);
        ss.decreaseTotalStake(removedStake);

        _removeNodeFromShardingTable(identityId, totalNodeStakeAfter);
        askContract.recalculateActiveSet();

        if (newDelegatorStakeBase == 0) {
            _handleDelegatorRemovalOnZeroStake(identityId, msg.sender, delegatorEpochScore18, currentEpoch);
        }

        if (totalNodeStakeAfter >= parametersStorage.maximumStake()) {
            ss.transferStake(msg.sender, removedStake);
        } else {
            (uint96 prevDelegatorWithdrawalAmount, , ) = ss.getDelegatorWithdrawalRequest(identityId, delegatorKey);
            ss.createDelegatorWithdrawalRequest(
                identityId,
                delegatorKey,
                removedStake + prevDelegatorWithdrawalAmount,
                0, // no indexed rewards any more
                block.timestamp + parametersStorage.stakeWithdrawalDelay()
            );
        }
    }

    /**
     * @dev Completes withdrawal process after the delay period has passed
     * Transfers the withdrawn tokens from StakingStorage to the delegator
     * Validates that withdrawal was initiated and delay period is complete
     * Removes the withdrawal request after successful transfer
     * @param identityId Node that withdrawal was requested from (must exist)
     */
    function finalizeWithdrawal(uint72 identityId) external profileExists(identityId) {
        StakingStorage ss = stakingStorage;

        bytes32 delegatorKey = _getDelegatorKey(msg.sender);
        (uint96 withdrawalAmount, , uint256 withdrawalReleaseTimestamp) = ss.getDelegatorWithdrawalRequest(
            identityId,
            delegatorKey
        );

        if (withdrawalAmount == 0) {
            revert StakingLib.WithdrawalWasntInitiated();
        }
        if (block.timestamp < withdrawalReleaseTimestamp) {
            revert StakingLib.WithdrawalPeriodPending(block.timestamp, withdrawalReleaseTimestamp);
        }

        ss.deleteDelegatorWithdrawalRequest(identityId, delegatorKey);
        ss.transferStake(msg.sender, withdrawalAmount);
    }

    /**
     * @dev Cancels pending withdrawal and restakes the tokens back to the node
     * If restaking would exceed maximum stake, partial amount is restaked and rest remains pending
     * Settles rewards and updates sharding table/active set
     * Validates that withdrawal was initiated and no rewards are pending claim
     * Must settle any pending previous epoch rewards before cancelling withdrawal
     * @param identityId Node to cancel withdrawal from (must exist)
     */
    function cancelWithdrawal(uint72 identityId) external profileExists(identityId) {
        StakingStorage ss = stakingStorage;

        bytes32 delegatorKey = _getDelegatorKey(msg.sender);
        (uint96 prevDelegatorWithdrawalAmount /*unused*/, , uint256 withdrawalReleaseTimestamp) = ss
            .getDelegatorWithdrawalRequest(identityId, delegatorKey);
        if (prevDelegatorWithdrawalAmount == 0) revert StakingLib.WithdrawalWasntInitiated();

        // Validate that all claims have been settled for the node before changing stake
        _validateDelegatorEpochClaims(identityId, msg.sender);

        // settle all pending score changes for the node's delegator
        _prepareForStakeChange(chronos.getCurrentEpoch(), identityId, delegatorKey);

        uint96 nodeStakeBefore = ss.getNodeStake(identityId);
        uint96 maxStake = parametersStorage.maximumStake();
        uint96 restake;
        uint96 keepPending = 0;

        if (nodeStakeBefore + prevDelegatorWithdrawalAmount > maxStake) {
            restake = maxStake - nodeStakeBefore; // might be zero
            keepPending = prevDelegatorWithdrawalAmount - restake;
        } else {
            restake = prevDelegatorWithdrawalAmount;
        }

        if (restake > 0) {
            uint96 newBase = ss.getDelegatorStakeBase(identityId, delegatorKey) + restake;

            ss.setDelegatorStakeBase(identityId, delegatorKey, newBase);
            ss.setNodeStake(identityId, nodeStakeBefore + restake);
            ss.increaseTotalStake(restake);

            // the delegator might have had zero stake before the cancel
            // If delegator was inactive and is now restaking, reset their lastStakeHeldEpoch
            _manageDelegatorStatus(identityId, msg.sender);
        }

        if (keepPending == 0) {
            ss.deleteDelegatorWithdrawalRequest(identityId, delegatorKey); // request fully cancelled
        } else {
            ss.createDelegatorWithdrawalRequest(
                identityId,
                delegatorKey,
                keepPending,
                0, // indexed-out rewards no longer exist
                withdrawalReleaseTimestamp // keep the original release time
            );
        }

        _addNodeToShardingTable(identityId, ss.getNodeStake(identityId));
        askContract.recalculateActiveSet();
    }

    /**
     * @dev Converts accumulated operator fees back into stake for the node
     * Only the node admin can perform this operation
     * Settles rewards, validates fee balance, and updates stake amounts
     * Updates sharding table and active set after restaking
     * Must settle any pending previous epoch rewards before restaking
     * @param identityId Node to restake fees for (caller must be admin)
     * @param addedStake Amount of fees to convert to stake (must be > 0 and <= fee balance)
     */
    function restakeOperatorFee(uint72 identityId, uint96 addedStake) external onlyAdmin(identityId) {
        StakingStorage ss = stakingStorage;

        if (addedStake == 0) {
            revert TokenLib.ZeroTokenAmount();
        }

        uint96 oldOperatorFeeBalance = ss.getOperatorFeeBalance(identityId);
        if (addedStake > oldOperatorFeeBalance) {
            revert StakingLib.AmountExceedsOperatorFeeBalance(oldOperatorFeeBalance, addedStake);
        }

        // Validate that all claims have been settled for the node before changing stake
        _validateDelegatorEpochClaims(identityId, msg.sender);
        bytes32 delegatorKey = _getDelegatorKey(msg.sender);
        // settle all pending score changes for the node's delegator
        _prepareForStakeChange(chronos.getCurrentEpoch(), identityId, delegatorKey);

        ss.setOperatorFeeBalance(identityId, oldOperatorFeeBalance - addedStake);

        uint96 delegatorStakeBase = ss.getDelegatorStakeBase(identityId, delegatorKey);
        uint96 totalNodeStakeBefore = ss.getNodeStake(identityId);
        uint96 totalNodeStakeAfter = totalNodeStakeBefore + addedStake;

        if (totalNodeStakeAfter > parametersStorage.maximumStake()) {
            revert StakingLib.MaximumStakeExceeded(parametersStorage.maximumStake());
        }

        ss.setDelegatorStakeBase(identityId, delegatorKey, delegatorStakeBase + addedStake);
        ss.setNodeStake(identityId, totalNodeStakeAfter);
        ss.addOperatorFeeCumulativePaidOutRewards(identityId, addedStake); // bookkeeping
        ss.increaseTotalStake(addedStake);

        _manageDelegatorStatus(identityId, msg.sender);

        _addNodeToShardingTable(identityId, totalNodeStakeAfter);
        askContract.recalculateActiveSet();
    }

    /**
     * @dev Initiates withdrawal process for accumulated operator fees
     * Only the node admin can perform this operation
     * Creates withdrawal request with delay period before funds can be claimed
     * Validates that sufficient fees are available for withdrawal
     * @param identityId Node to withdraw fees from (caller must be admin)
     * @param withdrawalAmount Amount of fees to withdraw (must be > 0 and <= fee balance)
     */
    function requestOperatorFeeWithdrawal(uint72 identityId, uint96 withdrawalAmount) external onlyAdmin(identityId) {
        StakingStorage ss = stakingStorage;

        if (withdrawalAmount == 0) {
            revert TokenLib.ZeroTokenAmount();
        }

        // Check if there's an existing withdrawal request
        uint96 existingRequestAmount = ss.getOperatorFeeWithdrawalRequestAmount(identityId);
        uint96 currentOperatorFeeBalance = ss.getOperatorFeeBalance(identityId);

        // If there's an existing request, add it back to the balance first
        if (existingRequestAmount > 0) {
            currentOperatorFeeBalance += existingRequestAmount;
        }

        // Calculate total request amount (existing + new)
        uint96 totalRequestAmount = existingRequestAmount + withdrawalAmount;

        if (totalRequestAmount > currentOperatorFeeBalance) {
            revert StakingLib.AmountExceedsOperatorFeeBalance(currentOperatorFeeBalance, totalRequestAmount);
        }

        uint256 withdrawalReleaseTimestamp = block.timestamp + parametersStorage.stakeWithdrawalDelay();
        // Deduct total request amount from balance
        ss.setOperatorFeeBalance(identityId, currentOperatorFeeBalance - totalRequestAmount);
        // Create request with total amount (existing + new)
        ss.createOperatorFeeWithdrawalRequest(
            identityId,
            totalRequestAmount,
            /*indexed*/ 0,
            withdrawalReleaseTimestamp
        );
    }

    /**
     * @dev Completes operator fee withdrawal after delay period has passed
     * Only the node admin can perform this operation
     * Transfers the withdrawn fees to the admin and updates bookkeeping
     * Validates that withdrawal was initiated and delay period is complete
     * @param identityId Node to finalize fee withdrawal for (caller must be admin)
     */
    function finalizeOperatorFeeWithdrawal(uint72 identityId) external onlyAdmin(identityId) {
        StakingStorage ss = stakingStorage;

        (uint96 operatorFeeWithdrawalAmount, , uint256 withdrawalReleaseTimestamp) = ss.getOperatorFeeWithdrawalRequest(
            identityId
        );
        if (operatorFeeWithdrawalAmount == 0) revert StakingLib.WithdrawalWasntInitiated();
        if (block.timestamp < withdrawalReleaseTimestamp)
            revert StakingLib.WithdrawalPeriodPending(block.timestamp, withdrawalReleaseTimestamp);

        ss.deleteOperatorFeeWithdrawalRequest(identityId);
        ss.addOperatorFeeCumulativePaidOutRewards(identityId, operatorFeeWithdrawalAmount);
        ss.transferStake(msg.sender, operatorFeeWithdrawalAmount);
    }

    /**
     * @dev Cancels pending operator fee withdrawal and returns fees to balance
     * Only the node admin can perform this operation
     * Validates that withdrawal was initiated and restores the fee balance
     * No delay period restrictions apply for cancellation
     * @param identityId Node to cancel fee withdrawal for (caller must be admin)
     */
    function cancelOperatorFeeWithdrawal(uint72 identityId) external onlyAdmin(identityId) {
        StakingStorage ss = stakingStorage;

        uint96 operatorFeeWithdrawalAmount = ss.getOperatorFeeWithdrawalRequestAmount(identityId);
        if (operatorFeeWithdrawalAmount == 0) {
            revert StakingLib.WithdrawalWasntInitiated();
        }

        ss.deleteOperatorFeeWithdrawalRequest(identityId);
        ss.increaseOperatorFeeBalance(identityId, operatorFeeWithdrawalAmount);
    }

    /**
     * @dev Claims rewards for a delegator for a specific epoch. Claiming is not the same as withdrawing.
     * Claiming adds delegator's rewards to their stake. Withdrawing takes delegator's stake out of the system.
     * Handles operator fee distribution and delegator reward calculation
     * Must claim epochs in sequential order starting from last claimed + 1
     * If more than one epoch rewards are pending, the rewards are accumulated in rolling rewards
     * Automatically restakes rewards if no other epoch rewards are pending
     * Updates delegator status and handles removal when appropriate
     * @param identityId Node to which delegator has delegated (must exist)
     * @param epoch Epoch to claim rewards for (must be finalized and in sequence)
     * @param delegator Address of the delegator to claim for (must be a node delegator)
     */
    function claimDelegatorRewards(
        uint72 identityId,
        uint256 epoch,
        address delegator
    ) public profileExists(identityId) {
        uint256 currentEpoch = chronos.getCurrentEpoch();
        require(epoch < currentEpoch, "Epoch not finalised");

        // Cannot claim rewards for a delegator that is not a node delegator
        require(delegatorsInfo.isNodeDelegator(identityId, delegator), "Delegator not found");

        uint256 lastClaimed = delegatorsInfo.getLastClaimedEpoch(identityId, delegator);
        if (lastClaimed == 0) {
            uint256 v81ReleaseEpoch = parametersStorage.v81ReleaseEpoch();
            delegatorsInfo.setLastClaimedEpoch(identityId, delegator, v81ReleaseEpoch - 1);
            lastClaimed = v81ReleaseEpoch - 1;
        }

        if (lastClaimed == currentEpoch - 1) {
            revert("Already claimed all finalised epochs");
        }

        if (epoch <= lastClaimed) {
            revert("Epoch already claimed");
        }

        if (epoch > lastClaimed + 1) {
            revert("Must claim older epochs first");
        }

        bytes32 delegatorKey = _getDelegatorKey(delegator);
        require(
            !delegatorsInfo.hasDelegatorClaimedEpochRewards(epoch, identityId, delegatorKey),
            "Already claimed rewards for this epoch"
        );

        // settle all pending score changes for the node's delegator
        uint256 delegatorScore18 = _prepareForStakeChange(epoch, identityId, delegatorKey);
        uint256 nodeScore18 = randomSamplingStorage.getNodeEpochScore(epoch, identityId);
        uint256 reward;

        // If nodeScore18 = 0, rewards are 0 too
        if (nodeScore18 > 0) {
            // netNodeRewards (rewards for node's delegators) = grossNodeRewards - operator fee
            uint256 netNodeRewards;
            if (!delegatorsInfo.isOperatorFeeClaimedForEpoch(identityId, epoch)) {
                // Operator fee has not been claimed for this epoch, calculate it
                uint256 allNodesScore18 = randomSamplingStorage.getAllNodesEpochScore(epoch);
                if (allNodesScore18 > 0) {
                    uint256 grossNodeRewards = (epochStorage.getEpochPool(EPOCH_POOL_INDEX, epoch) * nodeScore18) /
                        allNodesScore18;
                    uint96 operatorFeeAmount = uint96(
                        (grossNodeRewards * profileStorage.getLatestOperatorFeePercentage(identityId)) /
                            parametersStorage.maxOperatorFee()
                    );
                    netNodeRewards = grossNodeRewards - operatorFeeAmount;
                    // Mark the operator fee as claimed for this epoch
                    delegatorsInfo.setIsOperatorFeeClaimedForEpoch(identityId, epoch, true);
                    // Set node's delegators net rewards for this epoch so we don't have to calculate it again
                    delegatorsInfo.setNetNodeEpochRewards(identityId, epoch, netNodeRewards);
                    stakingStorage.increaseOperatorFeeBalance(identityId, operatorFeeAmount);
                }
            } else {
                // Operator fee has been claimed for this epoch already, use the previously calculated node's delegators net rewards for this epoch
                netNodeRewards = delegatorsInfo.getNetNodeEpochRewards(identityId, epoch);
            }

            reward = (delegatorScore18 * netNodeRewards) / nodeScore18;
        }

        // If the operator fee flag has not been set for the epoch (because it had no score), set it now.
        // This ensures that Profile.updateOperatorFee is not blocked by rewardless epochs.
        if (!delegatorsInfo.isOperatorFeeClaimedForEpoch(identityId, epoch)) {
            delegatorsInfo.setIsOperatorFeeClaimedForEpoch(identityId, epoch, true);
        }

        // update state even when reward is zero
        // Mark the delegator's rewards as claimed for this epoch
        delegatorsInfo.setHasDelegatorClaimedEpochRewards(epoch, identityId, delegatorKey, true);
        uint256 lastClaimedEpoch = delegatorsInfo.getLastClaimedEpoch(identityId, delegator);
        delegatorsInfo.setLastClaimedEpoch(identityId, delegator, epoch);

        // Check if this completes all required claims and reset lastStakeHeldEpoch
        uint256 lastStakeHeldEpoch = delegatorsInfo.getLastStakeHeldEpoch(identityId, delegator);
        if (lastStakeHeldEpoch > 0 && epoch >= lastStakeHeldEpoch) {
            // They've now claimed all rewards they're entitled to, reset the tracker
            delegatorsInfo.setLastStakeHeldEpoch(identityId, delegator, 0);

            // Check if they should be removed from delegators list
            if (reward == 0 && stakingStorage.getDelegatorStakeBase(identityId, delegatorKey) == 0) {
                delegatorsInfo.removeDelegator(identityId, delegator);
            }
        }

        uint256 rolling = delegatorsInfo.getDelegatorRollingRewards(identityId, delegator);

        if (reward == 0 && rolling == 0) return;

        // if there are still older epochs pending, accumulate; otherwise restake immediately
        if ((currentEpoch - 1) - lastClaimedEpoch > 1) {
            delegatorsInfo.setDelegatorRollingRewards(identityId, delegator, rolling + reward);
        } else {
            uint96 total = uint96(reward + rolling);
            delegatorsInfo.setDelegatorRollingRewards(identityId, delegator, 0);
            stakingStorage.increaseDelegatorStakeBase(identityId, delegatorKey, total);
            stakingStorage.increaseNodeStake(identityId, total);
            stakingStorage.increaseTotalStake(total);
        }
        //Should it increase on roling rewards or on stakeBaseIncrease only?
        stakingStorage.addDelegatorCumulativeEarnedRewards(identityId, delegatorKey, uint96(reward));
    }

    /**
     * @dev Claims rewards for multiple delegators across multiple epochs in batch
     * Calls claimDelegatorRewards internally for each epoch-delegator combination
     * Provides gas-efficient way to process multiple reward claims
     * All standard reward claiming rules and validations apply
     * @param identityId Node to claim rewards from (must exist)
     * @param epochs Array of epochs to claim for (each must be valid for claiming)
     * @param delegators Array of delegator addresses (each must be a node delegator)
     */
    function batchClaimDelegatorRewards(
        uint72 identityId,
        uint256[] memory epochs,
        address[] memory delegators
    ) external profileExists(identityId) {
        for (uint256 i = 0; i < epochs.length; i++) {
            for (uint256 j = 0; j < delegators.length; j++) {
                claimDelegatorRewards(identityId, epochs[i], delegators[j]);
            }
        }
    }

    /**
     * @dev Internal function to validate that delegator has claimed all required epoch rewards
     * Ensures delegators claim rewards before changing stake to prevent reward loss
     * Handles special cases for new delegators and those with zero stake
     * Auto-advances claim state when no rewards exist for previous epoch
     * @param identityId Node to validate claims for
     * @param delegator Address of delegator to validate
     */
    function _validateDelegatorEpochClaims(uint72 identityId, address delegator) internal {
        bytes32 delegatorKey = _getDelegatorKey(delegator);
        uint256 currentEpoch = chronos.getCurrentEpoch();
        uint256 previousEpoch = currentEpoch - 1;

        if (delegatorsInfo.hasEverDelegatedToNode(identityId, delegator)) {
            // If delegator has delegated to the node before, and has removed all their stake from the node at some point
            if (stakingStorage.getDelegatorStakeBase(identityId, delegatorKey) == 0) {
                uint256 lastStakeHeldEpoch = delegatorsInfo.getLastStakeHeldEpoch(identityId, delegator);
                // If lastStakeHeldEpoch > 0 and < currentEpoch, delegator has unclaimed rewards for a past epoch
                if (lastStakeHeldEpoch > 0 && lastStakeHeldEpoch < currentEpoch) {
                    revert("Must claim rewards up to the lastStakeHeldEpoch before changing stake");
                }
                // If lastStakeHeldEpoch == currentEpoch, rewards aren't claimable yet - allow operation
                // If lastStakeHeldEpoch == 0, delegator claimed all rewards they are entitled to
                delegatorsInfo.setLastClaimedEpoch(identityId, delegator, previousEpoch);
            }
        } else {
            // delegator is delegating to a node for the first time ever, set the last claimed epoch to the previous epoch
            delegatorsInfo.setHasEverDelegatedToNode(identityId, delegator, true);
            delegatorsInfo.setLastClaimedEpoch(identityId, delegator, previousEpoch);
        }

        uint256 lastClaimedEpoch = delegatorsInfo.getLastClaimedEpoch(identityId, delegator);

        // If delegator is up to date with claims, no validation needed
        if (lastClaimedEpoch == previousEpoch) {
            return;
        }

        // Check if delegator has multiple unclaimed epochs
        if (lastClaimedEpoch < previousEpoch - 1) {
            revert("Must claim all previous epoch rewards before changing stake");
        }

        // Delegator has exactly one unclaimed epoch (previousEpoch)
        // Check if there are actually rewards to claim for that epoch
        uint256 delegatorScore18 = randomSamplingStorage.getEpochNodeDelegatorScore(
            previousEpoch,
            identityId,
            delegatorKey
        );

        uint256 nodeScorePerStake36 = randomSamplingStorage.getNodeEpochScorePerStake(previousEpoch, identityId);

        uint256 delegatorLastSettledScorePerStake36 = randomSamplingStorage
            .getDelegatorLastSettledNodeEpochScorePerStake(previousEpoch, identityId, delegatorKey);

        // If no rewards exist for this delegator in the previous epoch, auto-advance their claim state
        if (delegatorScore18 == 0 && nodeScorePerStake36 == delegatorLastSettledScorePerStake36) {
            delegatorsInfo.setLastClaimedEpoch(identityId, delegator, previousEpoch);
            return;
        }

        // Delegator has unclaimed rewards that must be claimed first
        revert("Must claim the previous epoch rewards before changing stake");
    }

    function validateDelegatorEpochClaims(uint72 identityId, address delegator) external onlyContracts {
        _validateDelegatorEpochClaims(identityId, delegator);
    }

    /**
     * @dev Internal function to settle delegator rewards before stake changes
     * Calculates and applies newly earned score for the delegator in the epoch
     * Updates delegator's last settled score-per-stake index to current value
     * Handles edge cases for delegators with zero stake
     * @param epoch Epoch to settle score for
     * @param identityId Node to settle score for
     * @param delegatorKey Keccak256 hash of delegator address
     * @return delegatorEpochScore Total score for the delegator in the epoch after settlement
     */
    function _prepareForStakeChange(
        uint256 epoch,
        uint72 identityId,
        bytes32 delegatorKey
    ) internal returns (uint256 delegatorEpochScore) {
        // 1. Current "score-per-stake"
        uint256 nodeScorePerStake36 = randomSamplingStorage.getNodeEpochScorePerStake(epoch, identityId);

        uint256 currentDelegatorScore18 = randomSamplingStorage.getEpochNodeDelegatorScore(
            epoch,
            identityId,
            delegatorKey
        );

        // 2. Last index at which this delegator was settled
        uint256 delegatorLastSettledNodeEpochScorePerStake36 = randomSamplingStorage
            .getDelegatorLastSettledNodeEpochScorePerStake(epoch, identityId, delegatorKey);

        // Nothing new to settle
        if (nodeScorePerStake36 == delegatorLastSettledNodeEpochScorePerStake36) {
            return currentDelegatorScore18;
        }

        uint96 stakeBase = stakingStorage.getDelegatorStakeBase(identityId, delegatorKey);

        // If the delegator has no stake, just bump the index and exit
        if (stakeBase == 0) {
            randomSamplingStorage.setDelegatorLastSettledNodeEpochScorePerStake(
                epoch,
                identityId,
                delegatorKey,
                nodeScorePerStake36
            );
            return currentDelegatorScore18;
        }
        // 4. Newly earned score for this delegator in the epoch
        uint256 scorePerStakeDiff36 = nodeScorePerStake36 - delegatorLastSettledNodeEpochScorePerStake36;
        uint256 scoreEarned18 = (uint256(stakeBase) * scorePerStakeDiff36) / SCALE18;

        // 5. Persist results
        if (scoreEarned18 > 0) {
            randomSamplingStorage.addToEpochNodeDelegatorScore(epoch, identityId, delegatorKey, scoreEarned18);
        }

        randomSamplingStorage.setDelegatorLastSettledNodeEpochScorePerStake(
            epoch,
            identityId,
            delegatorKey,
            nodeScorePerStake36
        );

        return currentDelegatorScore18 + scoreEarned18;
    }

    function prepareForStakeChange(
        uint256 epoch,
        uint72 identityId,
        bytes32 delegatorKey
    ) external onlyContracts returns (uint256 delegatorEpochScore) {
        return _prepareForStakeChange(epoch, identityId, delegatorKey);
    }

    /**
     * @dev Internal function to manage delegator registration and status tracking
     * Adds delegator to node's delegator list if not already registered
     * Marks delegator as having ever delegated to the node (for claim validation)
     * Resets lastStakeHeldEpoch when delegator becomes active again
     * @param identityId Node to manage delegator status for
     * @param delegator Address of the delegator
     */
    function _manageDelegatorStatus(uint72 identityId, address delegator) internal {
        if (!delegatorsInfo.isNodeDelegator(identityId, delegator)) {
            delegatorsInfo.addDelegator(identityId, delegator);
        }
        // If operator was inactive and is now restaking fees, reset their lastStakeHeldEpoch
        uint256 lastStakeHeldEpoch = delegatorsInfo.getLastStakeHeldEpoch(identityId, delegator);
        if (lastStakeHeldEpoch > 0) {
            delegatorsInfo.setLastStakeHeldEpoch(identityId, delegator, 0);
        }
    }

    /**
     * @dev Internal function to add node to sharding table when stake requirements are met
     * Only adds node if it doesn't exist and has minimum required stake
     * Validates that sharding table isn't full before adding
     * @param identityId Node to potentially add to sharding table
     * @param newStake Current stake amount for the node
     */
    function _addNodeToShardingTable(uint72 identityId, uint96 newStake) internal {
        ShardingTableStorage sts = shardingTableStorage;
        ParametersStorage params = parametersStorage;

        if (!sts.nodeExists(identityId) && newStake >= params.minimumStake()) {
            if (sts.nodesCount() >= params.shardingTableSizeLimit()) {
                revert ShardingTableLib.ShardingTableIsFull();
            }
            shardingTableContract.insertNode(identityId);
        }
    }

    /**
     * @dev Internal function to remove node from sharding table when stake falls below minimum
     * Only removes node if it exists and stake is below minimum threshold
     * @param identityId Node to potentially remove from sharding table
     * @param newStake Current stake amount for the node
     */
    function _removeNodeFromShardingTable(uint72 identityId, uint96 newStake) internal {
        if (shardingTableStorage.nodeExists(identityId) && newStake < parametersStorage.minimumStake()) {
            shardingTableContract.removeNode(identityId);
        }
    }

    /**
     * @dev Internal function to validate that caller is an admin of the specified node
     * Checks if caller's address has admin key purpose for the identity
     * Used by functions that require node admin permissions
     * @param identityId Node identity to check admin rights for
     */
    function _checkAdmin(uint72 identityId) internal view virtual {
        if (!identityStorage.keyHasPurpose(identityId, _getDelegatorKey(msg.sender), IdentityLib.ADMIN_KEY)) {
            revert Permissions.OnlyProfileAdminFunction(msg.sender);
        }
    }

    /**
     * @dev Internal function to validate that a node profile exists
     * Used by modifiers and functions to ensure operations target valid nodes
     * @param identityId Node identity to check existence for
     */
    function _checkProfileExists(uint72 identityId) internal view virtual {
        if (!profileStorage.profileExists(identityId)) {
            revert ProfileLib.ProfileDoesntExist(identityId);
        }
    }

    /**
     * @dev Internal function to handle delegator cleanup when stake reaches zero
     * If delegator earned score in current epoch: keeps them for future reward claims
     * If no score earned: removes delegator from node immediately
     * Prevents loss of rewards while optimizing storage usage
     * @param identityId Node to handle delegator removal for
     * @param delegator Address of delegator with zero stake
     * @param delegatorEpochScore18 Score earned by delegator in current epoch
     * @param currentEpoch Current epoch number
     */
    function _handleDelegatorRemovalOnZeroStake(
        uint72 identityId,
        address delegator,
        uint256 delegatorEpochScore18,
        uint256 currentEpoch
    ) internal {
        // Don't remove delegator immediately - they might still be eligible for rewards in current epoch
        if (delegatorEpochScore18 > 0) {
            // Delegator earned score in current epoch (can claim), keep them for future reward claims
            delegatorsInfo.setLastStakeHeldEpoch(identityId, delegator, currentEpoch);
        } else {
            // No score earned in current epoch, safe to remove immediately
            delegatorsInfo.removeDelegator(identityId, delegator);
        }
    }

    /**
     * @dev Helper function to get delegator key from address
     * @param delegator Address to convert to key
     * @return bytes32 hash of the delegator address
     */
    function _getDelegatorKey(address delegator) internal pure returns (bytes32) {
        return keccak256(abi.encodePacked(delegator));
    }

    // ========================================================================
    // V10 Two-Layer Staking Wire — NFT-backed stake recording
    // ========================================================================

    /**
     * @notice Emitted when an NFT-backed stake is recorded via the two-layer
     *         wire. `tokenId` doubles as the StakingStorage delegator key
     *         (`bytes32(tokenId)`), disjoint from the V8 legacy
     *         `keccak256(delegator)` key space.
     */
    event StakeRecorded(
        uint256 indexed tokenId,
        uint72 indexed identityId,
        uint96 amount,
        uint40 lockEpochs,
        address indexed caller
    );

    /**
     * @notice V10 permissioned entry for recording NFT-backed stake into
     *         `StakingStorage`. Callable ONLY by the Hub-registered
     *         `DKGStakingConvictionNFT` contract.
     *
     * @dev Source: V10 implementation plan Phase 4 ("two-layer staking
     *      wire") — see `.ai/v10-implementation-plan.md` §"Phase 4 —
     *      `Staking._recordStake` permissioned internal entry".
     *
     *      Delegator key scheme: `bytes32(tokenId)`, disjoint from the V8
     *      legacy `keccak256(abi.encodePacked(delegator))` key space. This is
     *      what allows multiple NFT positions for the same (delegator, node)
     *      pair to be settled independently.
     *
     *      Trust model (grill-me-decisions.md — "Staker Conviction Flow"):
     *      this function is pure on-chain accounting and performs NO token
     *      transfer. The resolved flow is:
     *         user -approve-> DKGStakingConvictionNFT
     *         user -> NFT.createConviction(...)
     *         NFT  -transferFrom(user, stakingStorage, amount)-> StakingStorage
     *         NFT  -> Staking._recordStake(...)  // this function
     *      TRAC flows user → StakingStorage in ONE hop and never sits in the
     *      NFT contract (grill-me: "TRAC should go to StakingStorage at
     *      creation time, not sit in NFT contract" / "Stakers always get
     *      their TRAC because it's already in StakingStorage from day
     *      one"). This entry therefore trusts the caller to have already
     *      moved TRAC before invoking it; the trust boundary is enforced
     *      by the double gate (`onlyContracts` + explicit
     *      `DKGStakingConvictionNFT` identity check) and by the fact that
     *      the only permitted caller is a Hub-registered, audited contract.
     *      Any future caller added to the Hub under that name inherits the
     *      same obligation: move the TRAC first, then call.
     *
     *      Gate: `onlyContracts` ensures the caller is a Hub-registered
     *      contract; the explicit `msg.sender` check pins the caller to the
     *      DKGStakingConvictionNFT contract specifically, so no other
     *      Hub-registered contract can spoof NFT-backed stake. The
     *      `profileExists` modifier mirrors the V8 `stake()` guard and
     *      prevents phantom nodes — without it `_addNodeToShardingTable`
     *      would happily insert a ghost node at `sha256("")` for any
     *      unregistered `identityId`.
     *
     *      The leading underscore in the function name reflects its semantic
     *      role as the internal entry of the two-layer wire, even though the
     *      visibility is `external` so `DKGStakingConvictionNFT` can call it
     *      cross-contract.
     *
     * @param tokenId     NFT position id — also the delegator key (bytes32(tokenId))
     * @param identityId  Target node (must be an existing profile)
     * @param amount      Stake amount in TRAC (>0)
     * @param lockEpochs  Conviction lock duration (recorded in the event only;
     *                    authoritative lock data lives in `ConvictionStakingStorage`)
     */
    function _recordStake(
        uint256 tokenId,
        uint72 identityId,
        uint96 amount,
        uint40 lockEpochs
    ) external onlyContracts profileExists(identityId) {
        if (msg.sender != hub.getContractAddress("DKGStakingConvictionNFT")) {
            revert StakingLib.OnlyConvictionNFT();
        }
        if (amount == 0) {
            revert TokenLib.ZeroTokenAmount();
        }

        StakingStorage ss = stakingStorage;
        bytes32 delegatorKey = bytes32(tokenId);

        // Freshness invariant: reject replays of the same tokenId on ANY
        // node. V10 treats each NFT as a create-once, one-position entity
        // (Phase 0d removed the legacy `increaseStake` top-up path as a
        // gaming vector — every additional stake must be a new NFT with
        // its own conviction commitment, and an NFT is bound to exactly
        // one node for its lifetime). Without a global guard, a buggy or
        // malicious caller could:
        //   - replay on the SAME node → `+= amount` writes would
        //     double-count `nodeStake`/`totalStake` while
        //     `setDelegatorStakeBase` overwrote the delegator base back
        //     to the latest amount, corrupting accounting by the
        //     inflated delta; or
        //   - replay on a DIFFERENT node → the per-(node, key) bucket
        //     would be fresh, so a per-node guard would miss it, and
        //     the same tokenId would end up staked on two nodes at once
        //     — semantic violation, double-pays rewards.
        // StakingStorage already maintains `delegatorNodes[bytes32(key)]`
        // via `_updateDelegatorActivity` on every `setDelegatorStakeBase`
        // write, so `getDelegatorNodesCount(delegatorKey)` is the
        // authoritative global-scope check: non-zero iff this tokenId is
        // currently registered on ANY node. Zero gas overhead vs. the
        // per-node read it replaces.
        if (ss.getDelegatorNodesCount(delegatorKey) != 0) {
            revert StakingLib.TokenIdAlreadyRecorded(tokenId, identityId);
        }

        uint96 maxStake = parametersStorage.maximumStake();
        uint96 totalNodeStakeAfter = ss.getNodeStake(identityId) + amount;
        if (totalNodeStakeAfter > maxStake) {
            revert StakingLib.MaximumStakeExceeded(maxStake);
        }

        // Baseline the fresh delegator key (bytes32(tokenId)) at the node's
        // current score-per-stake index for the current epoch. Without
        // this, a later reward claim on this NFT would start from the
        // zero-initialised `delegatorLastSettledNodeEpochScorePerStake`
        // and collect score the node earned *before* this NFT ever
        // existed. `_prepareForStakeChange` takes the `stakeBase == 0`
        // fast-path for fresh keys: it bumps
        // `delegatorLastSettledNodeEpochScorePerStake` to the current
        // node index and returns without mutating any score totals —
        // matching exactly what V8 `stake()` already does for first-time
        // address-keyed delegators.
        _prepareForStakeChange(chronos.getCurrentEpoch(), identityId, delegatorKey);

        ss.setDelegatorStakeBase(identityId, delegatorKey, amount);
        ss.setNodeStake(identityId, totalNodeStakeAfter);
        ss.increaseTotalStake(amount);

        _addNodeToShardingTable(identityId, totalNodeStakeAfter);
        askContract.recalculateActiveSet();

        emit StakeRecorded(tokenId, identityId, amount, lockEpochs, msg.sender);
    }
}

contracts/Ask.sol.content:
// SPDX-License-Identifier: Apache-2.0

pragma solidity ^0.8.20;

import {AskStorage} from "./storage/AskStorage.sol";
import {ShardingTableStorage} from "./storage/ShardingTableStorage.sol";
import {ParametersStorage} from "./storage/ParametersStorage.sol";
import {ProfileStorage} from "./storage/ProfileStorage.sol";
import {ConvictionStakingStorage} from "./storage/ConvictionStakingStorage.sol";
import {INamed} from "./interfaces/INamed.sol";
import {IVersioned} from "./interfaces/IVersioned.sol";
import {IInitializable} from "./interfaces/IInitializable.sol";
import {ContractStatus} from "./abstract/ContractStatus.sol";

contract Ask is INamed, IVersioned, ContractStatus, IInitializable {
    string private constant _NAME = "Ask";
    // Version history:
    //   1.0.0 — initial active-set / weighted-ask reader (V8 stake source).
    //   2.0.0 — v4.0.0 storage consolidation: reads V10 canonical stake
    //           (`ConvictionStakingStorage.getNodeStakeV10`) so post-migration
    //           V10 nodes are not silently filtered out of the active set.
    string private constant _VERSION = "10.0.2";

    uint256 public constant ASK_SCALING_FACTOR = 1e18;

    AskStorage public askStorage;
    ShardingTableStorage public shardingTableStorage;
    ParametersStorage public parametersStorage;
    ProfileStorage public profileStorage;
    /// @notice v4.0.0 — V10 canonical node stake source. Replaces the prior
    ///         `stakingStorage` field; V8 `getNodeStake` is unmaintained for
    ///         post-migration nodes and would zero-skip every V10 node.
    ConvictionStakingStorage public convictionStakingStorage;

    // solhint-disable-next-line no-empty-blocks
    constructor(address hubAddress) ContractStatus(hubAddress) {}

    function initialize() public onlyHub {
        askStorage = AskStorage(hub.getContractAddress("AskStorage"));
        shardingTableStorage = ShardingTableStorage(hub.getContractAddress("ShardingTableStorage"));
        parametersStorage = ParametersStorage(hub.getContractAddress("ParametersStorage"));
        profileStorage = ProfileStorage(hub.getContractAddress("ProfileStorage"));
        convictionStakingStorage = ConvictionStakingStorage(hub.getContractAddress("ConvictionStakingStorage"));
    }

    function name() public pure virtual returns (string memory) {
        return _NAME;
    }

    function version() external pure virtual returns (string memory) {
        return _VERSION;
    }

    function recalculateActiveSet() external onlyContracts {
        AskStorage ass = askStorage;
        ShardingTableStorage sts = shardingTableStorage;
        ConvictionStakingStorage cs = convictionStakingStorage;
        ParametersStorage params = parametersStorage;
        ProfileStorage ps = profileStorage;

        ass.setPrevWeightedActiveAskSum(ass.weightedActiveAskSum());
        ass.setPrevTotalActiveStake(ass.totalActiveStake());

        uint96 minimumStake = params.minimumStake();
        uint96 maximumStake = params.maximumStake();

        uint256 askLowerBound;
        uint256 askUpperBound;

        if (ass.prevTotalActiveStake() > 0 && ass.prevWeightedActiveAskSum() > 0) {
            (askLowerBound, askUpperBound) = ass.getAskBounds();
        } else {
            (askLowerBound, askUpperBound) = (0, type(uint256).max);
        }

        uint256 newWeightedActiveAskSum;
        uint96 newTotalActiveStake;

        uint72 count = sts.nodesCount();
        for (uint72 i; i < count; i++) {
            uint72 nodeIdentityId = sts.indexToIdentityId(i);
            // v4.0.0 — V10 raw stake. Cast safe because the very next line
            // caps at `maximumStake` (uint96) before the uint96 multiplications
            // / accumulators below; CSS's `nodeStakeV10` is `uint256` only
            // because the migration sums could theoretically exceed uint96
            // when modelled mid-flight, but the cap eliminates any overflow
            // risk in this loop.
            uint256 stake256 = cs.getNodeStakeV10(nodeIdentityId);

            if (stake256 < minimumStake) {
                continue;
            }

            uint96 stake = stake256 > maximumStake ? maximumStake : uint96(stake256);
            uint256 nodeAskScaled = uint256(ps.getAsk(nodeIdentityId)) * ASK_SCALING_FACTOR;
            if (nodeAskScaled >= askLowerBound && nodeAskScaled <= askUpperBound) {
                newWeightedActiveAskSum += (nodeAskScaled / ASK_SCALING_FACTOR) * stake;
                newTotalActiveStake += stake;
            }
        }

        ass.setWeightedActiveAskSum(newWeightedActiveAskSum);
        ass.setTotalActiveStake(newTotalActiveStake);
    }
}

contracts/ContextGraphs.sol.content:
// SPDX-License-Identifier: Apache-2.0

pragma solidity ^0.8.20;

import {ContractStatus} from "./abstract/ContractStatus.sol";
import {IDKGPublishingConvictionNFT} from "./interfaces/IDKGPublishingConvictionNFT.sol";
import {IInitializable} from "./interfaces/IInitializable.sol";
import {INamed} from "./interfaces/INamed.sol";
import {IVersioned} from "./interfaces/IVersioned.sol";
import {ContextGraphStorage} from "./storage/ContextGraphStorage.sol";
import {KnowledgeAssetsLib} from "./libraries/KnowledgeAssetsLib.sol";
import {TokenLib} from "./libraries/TokenLib.sol";
import {ParametersStorage} from "./storage/ParametersStorage.sol";
import {ConvictionStakingStorage} from "./storage/ConvictionStakingStorage.sol";
import {EpochStorage} from "./storage/EpochStorage.sol";
import {Chronos} from "./storage/Chronos.sol";
import {CGWeightTreeStorage} from "./storage/CGWeightTreeStorage.sol";
import {ContextGraphValueStorage} from "./storage/ContextGraphValueStorage.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title ContextGraphs
 * @notice Stateless logic facade for Context Graph operations. All state lives in
 *         ContextGraphStorage (ERC-721 registry). This contract is replaceable via Hub.
 *
 * @dev The legacy `addBatchToContextGraph` attestation / inclusion-proof
 *      path is REMOVED (closes audit H2). Per-CG hosting committees and
 *      per-CG quorum were removed in SPEC_CG_MEMORY_MODEL: every CG is
 *      hosted by the sharding table at publish time, and the ACK quorum
 *      is the system parameter `parametersStorage.minimumRequiredSignatures()`.
 *      The only per-CG participant list is the EOA allow-list used for
 *      curated / PCA flows.
 *
 *      Publish authorization supports the three curator types encoded in
 *      ContextGraphStorage (see decision #22):
 *
 *        1. EOA    — publishAuthority = wallet, accountId = 0
 *                    Read path: direct address match against stored authority.
 *        2. Safe   — publishAuthority = multisig contract, accountId = 0
 *                    (Safe executes txs as msg.sender, so address equality
 *                    works transparently; ERC-1271 is not required here)
 *        3. PCA    — accountId = DKGPublishingConvictionNFT account id;
 *                    `publishAuthority` is a CREATE-TIME SNAPSHOT only.
 *                    Read path LIVE-RESOLVES `ownerOf(accountId)` and
 *                    accepts that owner or any registered agent of the
 *                    same account. The stored snapshot is IGNORED at read
 *                    time because it goes stale the moment the PCA NFT
 *                    transfers. Governance mutators (participant-agent
 *                    allow-list) similarly live-resolve via
 *                    `_isOwnerOrAuthority`, and agents are NOT granted
 *                    governance rights — only the NFT holder is.
 *                    (Closes Codex HIGH: PCA auth drift on NFT transfer.)
 *
 *      The NFT reference is resolved from the Hub on every authorization
 *      check so that a Phase 6 deployment made *after* the Phase 7 facade
 *      starts working without a facade redeployment.
 *
 *      N17 note: KAV10's current callsite still passes the recovered node
 *      signer wallet into `isAuthorizedPublisher`. That's a Phase 8 fix at
 *      the caller — this facade is responsible for the logic being correct
 *      when a correct principal is supplied.
 */
contract ContextGraphs is INamed, IVersioned, ContractStatus, IInitializable, ReentrancyGuard {
    string private constant _NAME = "ContextGraphs";
    string private constant _VERSION = "10.0.4";

    ContextGraphStorage public contextGraphStorage;

    // OT-RFC-53 — refs for the registration-deposit escrow. The deposit is
    // pulled into the CSS vault at creation and credited to the staker reward
    // pool (via EpochStorage) when consumed by publishing or swept by admin.
    IERC20 public tokenContract;
    ParametersStorage public parametersStorage;
    ConvictionStakingStorage public convictionStakingStorage;
    EpochStorage public epochStorage;
    Chronos public chronos;

    /// @notice Emitted when a CG registration deposit is pulled at creation.
    event ContextGraphRegistrationDeposited(
        uint256 indexed contextGraphId,
        address indexed payer,
        uint96 amount
    );

    /// @notice Emitted when an admin sweeps a CG's residual escrow to the pool.
    event ContextGraphEscrowSwept(uint256 indexed contextGraphId, uint96 amount);

    constructor(address hubAddress) ContractStatus(hubAddress) {}

    function initialize() public onlyHub {
        contextGraphStorage = ContextGraphStorage(
            hub.getAssetStorageAddress("ContextGraphStorage")
        );
        // OT-RFC-53 deposit stack — resolve EACH dependency through a tolerant,
        // individually-catchable Hub lookup (`getContractAddress` reverts for an
        // unregistered name). The feature is enabled ONLY when the WHOLE stack
        // resolves; any missing dependency leaves every ref zero and the deposit
        // disabled (createContextGraph guards on `parametersStorage != 0`). This
        // keeps ContextGraphs deployable on partial fixtures/upgrades without
        // declaring the economic stack as hard deploy dependencies, and avoids
        // the prior bug where a `try` over only the first lookup let a later
        // lookup (Token/CSS/Epoch/Chronos) revert uncaught.
        address ps = _tryResolveContract("ParametersStorage");
        address tok = _tryResolveContract("Token");
        address css = _tryResolveContract("ConvictionStakingStorage");
        address es = _tryResolveContract("EpochStorageV8");
        address chr = _tryResolveContract("Chronos");
        if (ps != address(0) && tok != address(0) && css != address(0) && es != address(0) && chr != address(0)) {
            parametersStorage = ParametersStorage(ps);
            tokenContract = IERC20(tok);
            convictionStakingStorage = ConvictionStakingStorage(css);
            epochStorage = EpochStorage(es);
            chronos = Chronos(chr);
        }
    }

    /// @dev Tolerant single-contract Hub lookup: returns address(0) instead of
    ///      reverting when the name is unregistered. Used to resolve the
    ///      OT-RFC-53 deposit stack so a partial deployment disables the feature
    ///      rather than bricking initialize().
    function _tryResolveContract(string memory contractName) internal view returns (address) {
        try hub.getContractAddress(contractName) returns (address a) {
            return a;
        } catch {
            return address(0);
        }
    }

    function name() public pure virtual returns (string memory) {
        return _NAME;
    }

    function version() external pure virtual returns (string memory) {
        return _VERSION;
    }

    // --- Creation ---

    /**
     * @notice Create a new context graph. Mints an ERC-721 to msg.sender.
     * @param participantAgents         EOA allow-list (no zeros, no dups)
     * @param metadataBatchId           Batch ID describing the CG metadata (0 if none)
     * @param accessPolicy              0 = public/discoverable, 1 = private/curated
     * @param publishPolicy             0 = curated, 1 = open
     * @param publishAuthority          Curator address (required when curated; ignored when open)
     * @param publishAuthorityAccountId Non-zero -> PCA curator type. Requires curated. Ignored when open.
     * @param nameHash                  OT-RFC-38 / LU-6 Phase B — opt-in stable wire
     *                                  identifier the curator commits to (intended to be
     *                                  `keccak256(bytes(cleartextId))` so hosting cores
     *                                  can auto-subscribe to the SWM gossip topic on
     *                                  receipt of `ContextGraphCreated`). Pass
     *                                  `bytes32(0)` to opt out (host-mode discovery for
     *                                  that CG then runs through the beacon path only).
     * @return contextGraphId           Newly assigned context graph ID (= ERC-721 token ID)
     *
     * @dev Hosts and ACK quorum are network-level concerns: the sharding table
     *      supplies hosts at publish time and `parametersStorage.minimumRequiredSignatures()`
     *      sets the quorum. CGs do not declare a per-CG hosting committee.
     */
    function createContextGraph(
        address[] calldata participantAgents,
        uint256 metadataBatchId,
        uint8 accessPolicy,
        uint8 publishPolicy,
        address publishAuthority,
        uint256 publishAuthorityAccountId,
        bytes32 nameHash
    ) external nonReentrant returns (uint256 contextGraphId) {
        // Storage validates sorting/dedup/zero-rejection, but a friendly
        // default for curated CGs: if caller passes zero authority and the
        // policy is curated, use msg.sender.
        address authority = publishAuthority;
        if (publishPolicy == 0 && authority == address(0)) {
            authority = msg.sender;
        }

        // Coherence gate: when a PCA accountId is supplied, the claimed
        // authority MUST equal the current owner of the NFT at that accountId.
        // See _validatePCACoherence for rationale (closes "silent broadening"
        // authorization vector where a mismatched pair stacks EOA + PCA
        // curators on the same CG).
        _validatePCACoherence(authority, publishAuthorityAccountId);

        contextGraphId = contextGraphStorage.createContextGraph(
            msg.sender,
            participantAgents,
            metadataBatchId,
            accessPolicy,
            publishPolicy,
            authority,
            publishAuthorityAccountId,
            nameHash
        );

        // OT-RFC-53: anti-spam registration deposit, held as the CG's prepaid
        // publishing escrow. Skipped when ParametersStorage is unresolved
        // (deposit feature off) or the param is 0 (dormant default).
        if (address(parametersStorage) != address(0)) {
            uint96 deposit = parametersStorage.contextGraphRegistrationDeposit();
            if (deposit > 0) {
                _pullRegistrationDeposit(contextGraphId, deposit);
            }
        }
    }

    // -----------------------------------------------------------------------
    // OT-RFC-53 — registration-deposit pull + admin sweep
    // -----------------------------------------------------------------------

    /// @dev Pulls the full `deposit` TRAC (GROSS) from the creator into the CSS
    ///      vault and records it as the CG's escrow. No treasury fee is skimmed
    ///      HERE (at deposit) — the deposit is escrowed gross. The protocol
    ///      treasury fee is instead taken per-publish at CONSUME, on the escrow
    ///      actually spent (`KnowledgeAssetsLifecycle._chargeEscrowTreasuryFee`),
    ///      at parity with the wallet path's `_addTokens` — so escrow-funded
    ///      publishing is not a fee loophole, and an unspent or admin-swept
    ///      deposit owes no fee. The escrow is later spent on publishing or swept
    ///      by admin — never cash-refunded.
    function _pullRegistrationDeposit(uint256 contextGraphId, uint96 deposit) internal {
        IERC20 token = tokenContract;
        uint256 allowance = token.allowance(msg.sender, address(this));
        if (allowance < deposit) {
            revert TokenLib.TooLowAllowance(address(token), allowance, deposit);
        }
        if (token.balanceOf(msg.sender) < deposit) {
            revert TokenLib.TooLowBalance(address(token), token.balanceOf(msg.sender), deposit);
        }
        // The deposit is escrowed GROSS in the CSS vault and tracked gross, so the
        // consume path subtracts it directly from the gross publish cost (no
        // net-vs-gross mismatch). The protocol treasury fee is NOT skimmed at
        // deposit; it is taken at CONSUME on the escrow actually spent, via
        // `KnowledgeAssetsLifecycle._chargeEscrowTreasuryFee` (parity with the
        // wallet path's `_addTokens`). Charging at consume — not deposit — keeps
        // the fee on real publishing: an unspent or admin-swept deposit owes none.
        if (!token.transferFrom(msg.sender, address(convictionStakingStorage), deposit)) {
            revert TokenLib.TransferFailed();
        }
        contextGraphStorage.setRegistrationEscrow(contextGraphId, deposit);
        emit ContextGraphRegistrationDeposited(contextGraphId, msg.sender, deposit);
    }

    /// @notice Admin: RETIRE a CG and reclaim its residual registration escrow
    ///         into the staker reward pool (current epoch). For abandoned / spam
    ///         CGs whose deposit was never spent on publishing. Deactivation is
    ///         ATOMIC with the sweep, so this can never silently drain an ACTIVE
    ///         CG owner's prepaid publishing budget while leaving the CG live —
    ///         sweeping a CG is retiring it. The TRAC is already in the CSS vault,
    ///         so this only deactivates, credits the epoch pool, and clears the
    ///         per-CG accounting. Never refunds to the depositor.
    function sweepContextGraphEscrow(uint256 contextGraphId) external onlyHubOwner {
        // RandomSampling invariant (RS leaf-zeroing mandate, see RandomSampling.sol):
        // retiring a CG must not strand its sampling weight. Settle the CG's leaf to
        // its TRUE current value first — an abandoned/expired CG (this sweep's target)
        // settles to 0, so any stale leaf is zeroed before deactivation. A CG that
        // still holds LIVE value is REFUSED: deactivating a weighted CG strands its
        // leaf, and past MAX_CG_RETRIES RandomSampling reverts challenge selection.
        // Gated on the sampling stack being deployed — always true in production; a
        // minimal deploy without CGWeightTreeStorage has no sampling weight to strand.
        // Storages resolved at call time (admin-only path; no cached binding to stale).
        if (hub.isContract("CGWeightTreeStorage")) {
            CGWeightTreeStorage(hub.getContractAddress("CGWeightTreeStorage")).settle(contextGraphId);
            if (
                ContextGraphValueStorage(hub.getContractAddress("ContextGraphValueStorage"))
                    .getCurrentCGValue(contextGraphId) != 0
            ) {
                revert KnowledgeAssetsLib.InvalidContextGraphConfig("CG has live value");
            }
        }
        // Atomic retire-then-reclaim: deactivate first so a live CG's prepaid
        // budget can't be drained out from under its owner while the CG stays
        // active (otReviewAgent finding). An already-inactive CG is swept as-is.
        if (contextGraphStorage.isContextGraphActive(contextGraphId)) {
            contextGraphStorage.deactivateContextGraph(contextGraphId);
        }
        uint96 swept = contextGraphStorage.clearRegistrationEscrow(contextGraphId);
        if (swept == 0) {
            revert KnowledgeAssetsLib.InvalidContextGraphConfig("no escrow");
        }
        uint256 currentEpoch = chronos.getCurrentEpoch();
        epochStorage.addTokensToEpochRange(1, currentEpoch, currentEpoch, swept);
        emit ContextGraphEscrowSwept(contextGraphId, swept);
    }

    // --- Governance (token-holder gated) ---

    modifier onlyContextGraphOwner(uint256 contextGraphId) {
        if (contextGraphStorage.getContextGraphOwner(contextGraphId) != msg.sender) {
            revert KnowledgeAssetsLib.NotContextGraphOwner(contextGraphId, msg.sender);
        }
        _;
    }

    /**
     * @notice Allow the CG NFT holder OR the configured curator (EOA/Safe
     *         direct address, or the LIVE PCA NFT owner) to mutate the
     *         participant-agent allow-list.
     *
     * @dev For open-policy CGs `publishAuthority` is `address(0)` and the
     *      stored accountId is 0, so only the owner branch can ever pass —
     *      the authority comparison is dead code in that case. This matches
     *      the design: open CGs don't have curators, and agent allow-lists
     *      only matter for curated flows.
     *
     *      In PCA curator mode (`publishAuthorityAccountId != 0`), the stored
     *      `publishAuthority` is a write-time snapshot that goes STALE when
     *      the PCA NFT transfers. We therefore live-resolve the current PCA
     *      NFT owner via `IDKGPublishingConvictionNFT.ownerOf(accountId)`
     *      instead of trusting the stored snapshot. This closes the Codex
     *      HIGH "PCA auth drift on NFT transfer" finding, where the old PCA
     *      owner would otherwise retain governance rights on the CG after
     *      transferring the PCA.
     *
     *      PCA REGISTERED AGENTS are NOT granted governance rights through
     *      this modifier — agents can publish on behalf of the PCA owner
     *      (see `isAuthorizedPublisher`), but only the PCA NFT holder
     *      themselves can mutate the CG's participant-agent allow-list.
     *      Governance lives with the account, not with its operational
     *      wallets.
     */
    modifier onlyContextGraphOwnerOrAuthority(uint256 contextGraphId) {
        if (!_isOwnerOrAuthority(contextGraphId, msg.sender)) {
            revert KnowledgeAssetsLib.NotContextGraphOwnerOrAuthority(contextGraphId, msg.sender);
        }
        _;
    }

    /**
     * @dev Single source of truth for owner-or-authority governance checks.
     *      Extracted from the modifier so the same branching logic can be
     *      reused by future governance mutators without duplicating the
     *      PCA live-resolve dance.
     *
     *      Returns true when any of the following is true:
     *        1. `caller` is the current CG NFT token holder.
     *        2. Curator mode is EOA/Safe (accountId == 0) AND `caller` is the
     *           stored static authority.
     *        3. Curator mode is PCA (accountId != 0) AND `caller` is the
     *           LIVE current owner of the PCA NFT at `accountId`. The stored
     *           `publishAuthority` is ignored in PCA mode — it's a
     *           create-time snapshot that goes stale on PCA transfer.
     *
     *      Fail-closed behavior: if the DKGPublishingConvictionNFT contract
     *      is not resolvable from the Hub, or `ownerOf(accountId)` reverts
     *      (account burned or never minted), governance defaults to the CG
     *      owner branch only.
     */
    function _isOwnerOrAuthority(
        uint256 contextGraphId,
        address caller
    ) internal view returns (bool) {
        if (contextGraphStorage.getContextGraphOwner(contextGraphId) == caller) {
            return true;
        }

        uint256 accountId = contextGraphStorage.getPublishAuthorityAccountId(contextGraphId);

        if (accountId == 0) {
            // EOA / Safe curator: static stored authority is authoritative.
            (, address authority) = contextGraphStorage.getPublishPolicy(contextGraphId);
            return caller == authority;
        }

        // PCA curator: live-resolve current NFT owner. Stored authority is
        // ignored — it's a stale-on-transfer snapshot. Agents are NOT
        // granted governance rights; only the NFT holder is.
        address nftAddr;
        try hub.getContractAddress("DKGPublishingConvictionNFT") returns (address addr) {
            nftAddr = addr;
        } catch {
            return false;
        }
        if (nftAddr == address(0)) return false;

        try IDKGPublishingConvictionNFT(nftAddr).ownerOf(accountId) returns (address currentOwner) {
            return caller == currentOwner;
        } catch {
            return false;
        }
    }

    function updatePublishPolicy(
        uint256 contextGraphId,
        uint8 publishPolicy,
        address publishAuthority,
        uint256 publishAuthorityAccountId
    ) external onlyContextGraphOwner(contextGraphId) {
        // Coherence gate (see _validatePCACoherence): if the new config
        // switches to PCA mode, the authority must own the target NFT.
        _validatePCACoherence(publishAuthority, publishAuthorityAccountId);

        contextGraphStorage.updatePublishPolicy(
            contextGraphId,
            publishPolicy,
            publishAuthority,
            publishAuthorityAccountId
        );
    }

    function updatePublishAuthority(
        uint256 contextGraphId,
        address newAuthority,
        uint256 newAuthorityAccountId
    ) external onlyContextGraphOwner(contextGraphId) {
        // Coherence gate (see _validatePCACoherence): if the rotated
        // authority carries a non-zero accountId, the new authority must
        // own the target NFT.
        _validatePCACoherence(newAuthority, newAuthorityAccountId);

        contextGraphStorage.updatePublishAuthority(
            contextGraphId,
            newAuthority,
            newAuthorityAccountId
        );
    }

    function addParticipantAgent(
        uint256 contextGraphId,
        address agent
    ) external onlyContextGraphOwnerOrAuthority(contextGraphId) {
        contextGraphStorage.addParticipantAgent(contextGraphId, agent);
    }

    function removeParticipantAgent(
        uint256 contextGraphId,
        address agent
    ) external onlyContextGraphOwnerOrAuthority(contextGraphId) {
        contextGraphStorage.removeParticipantAgent(contextGraphId, agent);
    }

    // --- Publish authorization ---

    /**
     * @notice Check whether `publisher` is authorized to publish to a context graph.
     *
     * @dev Implements the 3-curator-type model per decision #22:
     *
     *      - Open CGs (publishPolicy == 1) allow any non-zero principal.
     *      - Curated + EOA curator (accountId == 0): direct address equality
     *        against the STORED `publishAuthority`. The storage layer auto-
     *        rotates this field when the CG NFT transfers, so it is always
     *        live for EOA/Safe mode.
     *      - Curated + Safe multisig (accountId == 0): same direct address
     *        equality. A Gnosis Safe IS `msg.sender` when it executes a
     *        transaction, so any call made on behalf of the Safe arrives
     *        here with `publisher == safeAddress`. No ERC-1271 signature
     *        check is required at this layer.
     *      - Curated + PCA (accountId != 0): the stored `publishAuthority`
     *        is a CREATE-TIME SNAPSHOT that goes STALE the moment the PCA
     *        NFT transfers. The stored snapshot is therefore IGNORED for
     *        authorization. Instead we LIVE-RESOLVE the current PCA NFT
     *        owner via `IDKGPublishingConvictionNFT.ownerOf(accountId)` and
     *        accept either (a) that live owner directly or (b) a registered
     *        agent whose `agentToAccountId(publisher) == accountId`. Both
     *        mappings on the NFT contract are cleared by the transfer hook,
     *        so stale agent entries automatically stop authorizing.
     *
     *      Branch order is IMPORTANT. Because the EOA/Safe branch matches on
     *      the stored authority snapshot, it MUST NOT run in PCA mode — an
     *      unconditional direct-equality check before the accountId branch
     *      would silently authorize a stale ex-owner. (Closes Codex HIGH
     *      "PCA auth drift on NFT transfer": Alice creates a CG in PCA mode,
     *      transfers the NFT to Bob, and the stored authority still reads
     *      Alice. The pre-fix code returned true for Alice; the fix ignores
     *      the snapshot in PCA mode and live-resolves ownerOf(accountId)
     *      which now returns Bob.)
     *
     *      The DKGPublishingConvictionNFT reference is resolved on every call
     *      via a `try/catch` on `hub.getContractAddress("DKGPublishingConvictionNFT")`.
     *      Hub's `getContractAddress` reverts with `ContractDoesNotExist` when
     *      the contract is not registered (see UnorderedNamedContractDynamicSet.get),
     *      so the catch branch handles gracefully-degraded environments where
     *      Phase 6 has not been deployed yet. Using a fresh lookup each call
     *      (rather than caching on `initialize()`) lets the PCA branch start
     *      working without a facade redeployment once Phase 6 lands. Any
     *      resolution failure in PCA mode yields `false` (fail-closed read
     *      path — unlike the write path, which reverts).
     *
     *      View-only — no state mutations.
     *
     *      N17 note: the external signature intentionally takes the paying
     *      principal as `publisher` rather than the recovered publisher-node
     *      signer. The matching caller-side fix lives in `KnowledgeAssetsV10`
     *      Phase 8 — `_executePublishCore` and `_executeUpdateCore` both pass
     *      `msg.sender` here instead of the recovered node wallet.
     */
    function isAuthorizedPublisher(
        uint256 contextGraphId,
        address publisher
    ) external view returns (bool) {
        // 0. Bounds + liveness.
        uint256 latestId = contextGraphStorage.getLatestContextGraphId();
        if (contextGraphId == 0 || contextGraphId > latestId) return false;
        if (!contextGraphStorage.isContextGraphActive(contextGraphId)) return false;

        // 1. Open CGs authorize any non-zero principal.
        (uint8 policy, address storedAuthority) = contextGraphStorage.getPublishPolicy(contextGraphId);
        if (policy == 1) {
            return publisher != address(0);
        }

        // 2. Curated: never authorize the zero address.
        if (publisher == address(0)) return false;

        // 3. Determine curator type from accountId FIRST — we must not run
        //    the direct-equality branch in PCA mode because the stored
        //    authority is a stale-on-transfer snapshot in that case.
        uint256 authorityAccountId = contextGraphStorage.getPublishAuthorityAccountId(contextGraphId);

        if (authorityAccountId == 0) {
            // 3a. EOA / Safe curator: direct address match against the
            //     stored authority. Storage auto-rotates this field on CG
            //     NFT transfer, so it is always live for this mode.
            return publisher == storedAuthority;
        }

        // 3b. PCA curator: IGNORE the stored authority snapshot entirely.
        //     Live-resolve the NFT's current owner and accept it or any
        //     registered agent of the same account. A missing / burned NFT
        //     yields `false` (fail-closed read path).
        address nftAddr;
        try hub.getContractAddress("DKGPublishingConvictionNFT") returns (address addr) {
            nftAddr = addr;
        } catch {
            return false;
        }
        if (nftAddr == address(0)) return false;

        // Live owner match — supersedes the stale stored authority.
        try IDKGPublishingConvictionNFT(nftAddr).ownerOf(authorityAccountId) returns (address currentOwner) {
            if (publisher == currentOwner) return true;
        } catch {
            // Account burned or never existed — refuse gracefully.
            return false;
        }

        // Registered agent of the authorized account. `agentToAccountId`
        // is cleared by the NFT's `_update` transfer hook, so stale agent
        // entries automatically stop authorizing post-transfer.
        uint256 publisherAccountId = IDKGPublishingConvictionNFT(nftAddr).agentToAccountId(publisher);
        return publisherAccountId != 0 && publisherAccountId == authorityAccountId;
    }

    // --- KA registration (Phase 8 publish flow entry point) ---

    /**
     * @notice Bind a Knowledge Asset to a Context Graph via the facade.
     * @dev Thin wrapper over `ContextGraphStorage.registerKnowledgeAssetToContextGraph`.
     *      Exists so Phase 8's `KnowledgeAssetsV10.publish` / `publishDirect`
     *      can call the facade (stable interface) instead of reaching into
     *      storage directly. `onlyContracts`-gated at the facade layer so the
     *      entry point has one canonical caller — the KA contract — and no
     *      direct EOA call path.
     */
    function registerKnowledgeAsset(
        uint256 contextGraphId,
        uint256 kaId
    ) external onlyContracts {
        contextGraphStorage.registerKnowledgeAssetToContextGraph(contextGraphId, kaId);
    }

    // --- Internal: PCA coherence validation ---

    /**
     * @notice WRITE-TIME sanity check that a claimed (authority, accountId)
     *         pair is initially coherent for a PCA-mode CG.
     *
     * @dev IMPORTANT: this is a CREATE-TIME SANITY GATE, NOT a drift-
     *      prevention guarantee. The stored `publishAuthority` is a
     *      snapshot that this check validates ONCE at write time so the
     *      initial config is internally consistent — "you claimed authority
     *      X owns account Y; we verified X == ownerOf(Y) right now."
     *
     *      Drift AFTER write (e.g. Alice creates a CG in PCA mode, then
     *      transfers the PCA NFT to Bob) is handled by LIVE RESOLVE at
     *      read time in `isAuthorizedPublisher` and `_isOwnerOrAuthority`,
     *      which IGNORE the stored snapshot in PCA mode and dereference
     *      `ownerOf(accountId)` on every call. The stored snapshot is
     *      retained only as a write-time audit trail and is NOT used for
     *      authorization. (Codex HIGH: PCA auth drift on NFT transfer.)
     *
     *      Historical rationale (still valid): the pre-live-resolve design
     *      ORed an EOA/Safe direct-authority branch with a PCA-agent
     *      branch, so a mismatched pair — e.g. `publishAuthority = Alice`,
     *      `accountId = 42` where account 42 is owned by Bob — would have
     *      silently granted TWO curators to the same CG: Alice via the EOA
     *      branch, Bob's agents via the PCA branch. The live-resolve fix
     *      collapses the EOA branch out of PCA mode entirely, but the
     *      write-time coherence check is still valuable because it catches
     *      misconfigurations where the caller passes an authority that
     *      does not match the NFT they claim. Without it, Alice could
     *      create a CG with `(authority = Alice, accountId = Bob's)` and
     *      the initial authorization surface would silently be "whoever
     *      owns Bob's NFT now" rather than the more obvious "Alice". A
     *      clear write-time revert keeps storage honest.
     *
     *      Fail-closed write-path behavior (stricter than read-path):
     *        - If the NFT contract is not resolvable via Hub (not registered,
     *          zero address, or Hub reverts), revert with `PCANotResolvable`.
     *          Unlike `isAuthorizedPublisher`, which gracefully degrades on a
     *          missing NFT, a write path that fails to resolve the NFT must
     *          revert — otherwise it lets a PCA config land without validation.
     *          Callers who want a non-PCA CG must pass accountId == 0 and use
     *          EOA/Safe mode instead.
     *        - If `ownerOf(accountId)` reverts (OZ's ERC721NonexistentToken),
     *          revert with `PCAAccountDoesNotExist`.
     *        - If the ownership check succeeds but the owner doesn't match the
     *          claimed authority, revert with `PCAAuthorityMismatch`.
     *
     *      `accountId == 0` (non-PCA / EOA / Safe / open) skips the check
     *      entirely — EOA/Safe modes use the stored authority verbatim at
     *      read time and there is no PCA lookup to reconcile.
     *
     *      `authority == address(0)` also skips: it represents either the
     *      open-policy state (where non-zero accountId is structurally
     *      rejected by storage with a clear "open policy" message — we
     *      don't want to shadow that with a PCA-specific error) or a
     *      malformed curated state that storage's own zero-authority
     *      guard will reject downstream. Either way, deferring to storage
     *      gives the caller the clearer diagnostic.
     */
    function _validatePCACoherence(
        address authority,
        uint256 accountId
    ) internal view {
        if (accountId == 0 || authority == address(0)) return;

        // Fresh Hub lookup each call (same pattern as isAuthorizedPublisher).
        // Write paths fail closed: if we can't resolve the NFT, we refuse to
        // store an un-validatable PCA config.
        address nftAddr;
        try hub.getContractAddress("DKGPublishingConvictionNFT") returns (address addr) {
            nftAddr = addr;
        } catch {
            revert KnowledgeAssetsLib.PCANotResolvable(accountId);
        }
        if (nftAddr == address(0)) {
            revert KnowledgeAssetsLib.PCANotResolvable(accountId);
        }

        // ownerOf reverts for never-minted tokens (OZ ERC721NonexistentToken).
        // Wrap in try/catch so we can distinguish "no such account" from
        // a live ownership mismatch.
        address actualOwner;
        try IDKGPublishingConvictionNFT(nftAddr).ownerOf(accountId) returns (address owner_) {
            actualOwner = owner_;
        } catch {
            revert KnowledgeAssetsLib.PCAAccountDoesNotExist(accountId);
        }

        if (actualOwner != authority) {
            revert KnowledgeAssetsLib.PCAAuthorityMismatch(accountId, authority, actualOwner);
        }
    }
}

contracts/DKGPublishingConvictionNFT.sol.content:
// SPDX-License-Identifier: Apache-2.0

pragma solidity ^0.8.20;

import {INamed} from "./interfaces/INamed.sol";
import {IVersioned} from "./interfaces/IVersioned.sol";
import {IInitializable} from "./interfaces/IInitializable.sol";
import {HubDependent} from "./abstract/HubDependent.sol";
import {PublishingMathLib} from "./libraries/PublishingMathLib.sol";
import {PublishingConviction} from "./PublishingConviction.sol";
import {PublishingConvictionStorage} from "./storage/PublishingConvictionStorage.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {ERC721} from "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import {ERC721Enumerable} from "@openzeppelin/contracts/token/ERC721/extensions/ERC721Enumerable.sol";

/**
 * @title DKGPublishingConvictionNFT
 * @notice Thin ERC-721 wrapper over publisher conviction accounts.
 *
 * V10 split-contract architecture (mirrors the staking-side
 * `DKGStakingConvictionNFT` / `StakingV10` / `ConvictionStakingStorage`
 * trio):
 *   - This wrapper is a dumb ERC-721 ownership receipt: it mints/burns
 *     tokens, validates ownership on mutating calls, drives the
 *     publisher-facing TRAC `transferFrom`s, and forwards every
 *     business action to `PublishingConviction`.
 *   - All account / window / agent state lives on
 *     `PublishingConvictionStorage`.
 *   - All business logic (account creation, lazy passive-sink
 *     settlement, post-expiry final sweep, active-sink epoch
 *     distribution, agent management, transfer-hook agent clear)
 *     lives on `PublishingConviction`. The logic address is resolved
 *     lazily from Hub so it can be re-registered without touching this
 *     wrapper.
 *
 * Wrapper-level state (intentional):
 *   - `_nextAccountId`: monotonic mint counter, tightly coupled to
 *     ERC-721 mint ordering. Mirrors `DKGStakingConvictionNFT.nextTokenId`.
 *   - Hub-resolved contract refs (storage, token, vault) are loaded
 *     once at `initialize()`; they are metadata, not application state.
 *
 * TRAC custody:
 *   - The wrapper NEVER holds TRAC. `createAccount` / `topUp` move TRAC
 *     directly from the publisher into the V10 vault
 *     (`ConvictionStakingStorage`) via `transferFrom`. The publisher
 *     therefore approves THIS wrapper as the spender (matching the
 *     legacy v2.x UX so existing integrations keep working).
 *   - `coverPublishingCost` does NOT physically move TRAC; it only
 *     updates `EpochStorage` accounting. The escrowed TRAC is already
 *     in the vault from `createAccount` / `topUp`.
 *
 * Public surface stability (selector-compatible with v2.x):
 *   - The legacy `accounts(uint256)` auto-getter is preserved as an
 *     explicit forwarder over the storage contract's auto-generated
 *     `accounts` mapping getter — INCLUDING the legacy zero-tuple
 *     return for an unknown `accountId` (it does NOT revert; use
 *     `getAccount` for the fail-closed variant). See the function
 *     NatSpec on `accounts(uint256)` below.
 *   - `agentToAccountId(address)`, `topUpBalance(uint256)`,
 *     `windowSpent(uint256, uint40)`, `maxAgentsPerAccount()` are kept
 *     on the wrapper as forwarders so `IDKGPublishingConvictionNFT`,
 *     `KnowledgeAssetsV10`, and `ContextGraphs` need no changes.
 *
 * Deliberate breaks in the v2.x → v3.0.0 wrapper bump:
 *   - PCA state-change events (`AccountCreated`, `ToppedUp`,
 *     `CostCovered`, `WindowSettled`, `AccountFinalSwept`,
 *     `AgentRegistered`, `AgentDeregistered`) are emitted by
 *     `PublishingConviction` (the logic contract), NOT by this
 *     wrapper. Off-chain consumers that subscribe to PCA state
 *     changes MUST listen to the `PublishingConviction` address
 *     (resolved from Hub at `getContractAddress("PublishingConviction")`),
 *     not this contract's address. This is the architectural
 *     invariant of the V10 split: the logic contract owns business
 *     semantics, including events. The 3.0.0 major version bump is
 *     the deliberate signal of this break — do NOT add wrapper-side
 *     re-emission to "preserve compatibility"; the canonical
 *     listening address is the logic contract.
 *   - The wrapper still emits ERC-721 events (`Transfer`,
 *     `Approval`, `ApprovalForAll`) from its own address, exactly
 *     as a normal NFT does — those are NOT moved.
 */
contract DKGPublishingConvictionNFT is INamed, IVersioned, HubDependent, IInitializable, ERC721Enumerable {
    string private constant _NAME = "DKGPublishingConvictionNFT";
    // Version history:
    //   2.0.0 — legacy stateful NFT (state + logic on this contract).
    //   3.0.0 — V10 storage/logic split. State migrates to
    //           `PublishingConvictionStorage`; business logic moves to
    //           `PublishingConviction`. The wrapper is now ERC-721 +
    //           mint counter + TRAC-pull only. Public selectors are
    //           preserved so `IDKGPublishingConvictionNFT` consumers
    //           (`KnowledgeAssetsV10`, `ContextGraphs`) need no changes.
    //   10.0.3 — OT-RFC-51 "Publishing Allocation": `createAccount` gains a
    //           `primaryNode` argument forwarded to the logic contract, and a
    //           new owner-gated `setPrimaryNode` forwarder is added.
    string private constant _VERSION = "10.0.3";

    uint256 public constant BPS_DENOMINATOR = 10_000;

    // ============================================================
    //                  Hub-wired dependencies
    // ============================================================

    /// @dev Reserved slot from the first v3 split draft where the logic
    ///      reference was cached. The public `publishingConviction()`
    ///      getter below now resolves Hub lazily.
    PublishingConviction private __reservedPublishingConviction;

    /// @notice V10 application-state store. Read directly for the
    ///         selector-stable public view forwarders below.
    PublishingConvictionStorage public publishingConvictionStorage;

    /// @notice TRAC ERC-20 reference; the publisher approves this
    ///         wrapper to pull TRAC into the vault on
    ///         `createAccount` / `topUp`.
    IERC20 public tokenContract;

    /// @notice V10 TRAC vault target. Resolves to
    ///         `ConvictionStakingStorage`, the post-v4.0.0
    ///         consolidation custodian. Field name retained for
    ///         storage layout stability across the legacy
    ///         `stakingStorageAddress` slot.
    address public stakingStorageAddress;

    // ============================================================
    //                       Mint counter
    // ============================================================

    /// @notice Monotonic account-id counter. The first mint produces
    ///         accountId 1 — accountId 0 is reserved as the "not
    ///         registered" sentinel for `agentToAccountId`. Initialized
    ///         to 1 on first `initialize()`; persists across redeploys
    ///         of the wrapper because Hub re-registration runs
    ///         `initialize()` and the `_nextAccountId == 0` guard
    ///         short-circuits.
    uint256 private _nextAccountId;

    // ============================================================
    //                          Errors
    // ============================================================

    error ZeroAddressDependency(string name);
    error OnlyKnowledgeAssetsV10(address caller);
    error NotAccountOwner(uint256 accountId, address caller);
    /// @notice OT-RFC-51 defense-in-depth: `setPrimaryNode` called with `newNode == 0`.
    error ZeroPrimaryNode();
    error InvalidAmount();
    error TokenTransferFailed();

    constructor(
        address hubAddress
    ) HubDependent(hubAddress) ERC721("DKG Publishing Conviction", "DKGPC") {}

    function initialize() public onlyHub {
        address store = hub.getContractAddress("PublishingConvictionStorage");
        if (store == address(0)) revert ZeroAddressDependency("PublishingConvictionStorage");
        publishingConvictionStorage = PublishingConvictionStorage(store);

        address token = hub.getContractAddress("Token");
        if (token == address(0)) revert ZeroAddressDependency("Token");
        tokenContract = IERC20(token);

        address vault = hub.getContractAddress("ConvictionStakingStorage");
        if (vault == address(0)) revert ZeroAddressDependency("ConvictionStakingStorage");
        stakingStorageAddress = vault;

        if (_nextAccountId == 0) _nextAccountId = 1;
    }

    function name() public pure virtual override(INamed, ERC721) returns (string memory) {
        return _NAME;
    }

    function version() external pure virtual returns (string memory) {
        return _VERSION;
    }

    /// @notice Current Hub-registered publishing-conviction logic.
    /// @dev    Kept as a selector-stable getter, but intentionally does a
    ///         lazy Hub lookup so logic-only upgrades do not require
    ///         reinitializing this wrapper.
    function publishingConviction() public view returns (PublishingConviction) {
        return _publishingConviction();
    }

    // ========================================================================
    //                  Account lifecycle entry points
    // ========================================================================

    /**
     * @notice Mint a new conviction-account NFT to the caller and
     *         transfer `committedTRAC` into the V10 vault.
     *
     * @dev    CEI ordering with `_mint` last:
     *           1. Allocate `accountId` from the wrapper's mint counter.
     *           2. Forward to `PublishingConviction.createAccount` which
     *              persists the `Account` record on PCS and emits
     *              `AccountCreated`. Logic-side parameter validation
     *              runs here, BEFORE any funds move.
     *           3. Pull TRAC from publisher to the V10 vault. The
     *              wrapper holds NO TRAC — this is a direct
     *              `transferFrom(publisher, ConvictionStakingStorage,
     *              committedTRAC)`.
     *           4. `_mint(msg.sender, accountId)` LAST. The wrapper
     *              never observes a half-built (NFT-without-Account
     *              -or-funding) state.
     *
     *         `_mint` (not `_safeMint`) is intentional: contract
     *         publishers without `IERC721Receiver` (DAO treasuries,
     *         relayer/factory wrappers, etc.) are part of the
     *         supported caller set.
     *
     *         The forward-before-pull order means a logic-side revert
     *         does not move funds. The whole tx reverts atomically on
     *         any failure path — the NFT is never minted without TRAC
     *         backing it and a recorded `Account` row.
     */
    function createAccount(uint96 committedTRAC, uint72 primaryNode) external returns (uint256 accountId) {
        if (committedTRAC == 0) revert InvalidAmount();

        accountId = _nextAccountId++;

        _publishingConviction().createAccount(msg.sender, accountId, committedTRAC, primaryNode);

        // Direct publisher -> CSS vault transfer. Contract never holds TRAC.
        // The TRAC sits in escrow against this account's billing windows and
        // is accounted to the staker pool lazily via active/passive sinks.
        if (!tokenContract.transferFrom(msg.sender, stakingStorageAddress, committedTRAC)) {
            revert TokenTransferFailed();
        }

        _mint(msg.sender, accountId);
    }

    /**
     * @notice Add TRAC to an existing account's persistent top-up
     *         buffer.
     *
     * @dev    The wrapper owns ownership validation and the TRAC pull;
     *         the logic contract enforces "amount > 0" and "not
     *         expired", and triggers lazy settlement before crediting
     *         the buffer. Order of operations matches `createAccount`:
     *         logic update first, TRAC pull last so a logic-side
     *         revert does not move funds.
     */
    function topUp(uint256 accountId, uint96 amount) external {
        _requireOwner(accountId);

        _publishingConviction().topUp(msg.sender, accountId, amount);

        if (!tokenContract.transferFrom(msg.sender, stakingStorageAddress, amount)) {
            revert TokenTransferFailed();
        }
    }

    /**
     * @notice OT-RFC-51: re-designate the primary node that this account's
     *         committed publishing allocation is credited to. Owner-gated
     *         here; the logic contract enforces the once-per-epoch rate
     *         limit and `nodeExists` validation for the new node, and moves
     *         future-epoch allocation net-zero on K_total.
     */
    function setPrimaryNode(uint256 accountId, uint72 newNode) external {
        _requireOwner(accountId);
        // OT-RFC-51 defense-in-depth: there is no clear-designation semantic.
        // The logic contract also rejects this; guard here so a 0 can never
        // reach it (see PublishingConviction.ZeroPrimaryNode).
        if (newNode == 0) revert ZeroPrimaryNode();
        _publishingConviction().setPrimaryNode(accountId, newNode);
    }

    // ========================================================================
    //                  KAV10-driven cost coverage
    // ========================================================================

    /**
     * @notice Charge a publishing agent's allowance for `baseCost` and
     *         distribute `discountedCost` over the published KA's
     *         epoch range. Callable ONLY by `KnowledgeAssetsV10`.
     *
     * @dev    The KAV10 gate lives here (not on the logic contract) so
     *         the logic contract's caller gate can stay
     *         `onlyConvictionNFT` and consistent with every other
     *         NFT-driven entry point. KAV10 calls THIS contract; we
     *         validate and forward.
     */
    function coverPublishingCost(
        address publishingAgent,
        uint96 baseCost,
        uint40 kaStartEpoch,
        uint40 kaEpochs
    ) external returns (uint96 discountedCost) {
        address kav10 = hub.getContractAddress("KnowledgeAssetsLifecycle");
        if (msg.sender != kav10) revert OnlyKnowledgeAssetsV10(msg.sender);

        return _publishingConviction().coverPublishingCost(publishingAgent, baseCost, kaStartEpoch, kaEpochs);
    }

    /// @notice Permissionless lazy-settlement entry point.
    /// @dev    Pure forwarder — the logic contract handles existence
    ///         and `fullySwept` short-circuit checks.
    function settle(uint256 accountId) external {
        _publishingConviction().settle(accountId);
    }

    // ========================================================================
    //                  Agent management entry points
    // ========================================================================

    function registerAgent(uint256 accountId, address agent) external {
        _requireOwner(accountId);
        _publishingConviction().registerAgent(msg.sender, accountId, agent);
    }

    function deregisterAgent(uint256 accountId, address agent) external {
        _requireOwner(accountId);
        _publishingConviction().deregisterAgent(msg.sender, accountId, agent);
    }

    // ========================================================================
    //                  Governance forwarders
    // ========================================================================

    /// @notice Tune the per-account agent registration cap.
    /// @dev    Selector-stable forwarder for `setMaxAgentsPerAccount`.
    ///         The `onlyHubOwner` gate is enforced HERE because PCS's
    ///         own `setMaxAgentsPerAccount` is gated `onlyContracts`
    ///         (so this forwarder, a Hub-registered contract, may
    ///         drive the write). Without the gate on the wrapper, any
    ///         externally-owned account could re-tune the cap.
    function setMaxAgentsPerAccount(uint256 cap) external onlyHubOwner {
        publishingConvictionStorage.setMaxAgentsPerAccount(cap);
    }

    // ========================================================================
    //              Selector-stable view forwarders
    // ========================================================================
    //
    // These functions preserve the public selectors that v2.x exposed via
    // public mappings / variables. `IDKGPublishingConvictionNFT` callers
    // (`KnowledgeAssetsV10`, `ContextGraphs`, off-chain indexers) keep
    // working unchanged. Each forwarder is a pure read against PCS.

    /// @notice Conviction-account record by id. Selector-compatible
    ///         with the legacy v2.x `accounts` public mapping AND
    ///         behavior-compatible with it: returns the all-zero
    ///         tuple for an unknown / unminted `accountId` instead
    ///         of reverting. Indexers and existence-probe callers
    ///         that read the legacy mapping continue to work
    ///         unchanged. Use `getAccount(accountId)` (forwarded
    ///         from `PublishingConvictionStorage`) for the
    ///         fail-closed variant that reverts `UnknownAccount`.
    ///
    ///         Implemented by forwarding to the storage contract's
    ///         auto-generated `accounts(accountId)` mapping getter,
    ///         not `getAccount(accountId)`, precisely so the unknown-
    ///         id branch keeps the legacy zero-tuple semantic. Codex
    ///         round 3 review on PR #650 flagged the prior
    ///         `getAccount(...)` forwarder as an observable behavior
    ///         break vs the legacy public mapping; this regression
    ///         is locked in by `accounts(unknown id) returns zero
    ///         tuple` in `DKGPublishingConvictionNFT.test.ts`.
    function accounts(uint256 accountId) external view returns (
        uint96 committedTRAC,
        uint40 createdAtEpoch,
        uint40 expiresAtEpoch,
        uint40 createdAtTimestamp,
        uint40 expiresAtTimestamp,
        uint16 lockDurationEpochs,
        uint16 discountBps,
        uint16 lastSettledWindow,
        bool fullySwept,
        uint72 primaryNode,
        uint40 lastPrimaryNodeChangeEpoch
    ) {
        return publishingConvictionStorage.accounts(accountId);
    }

    /// @notice Per-billing-window TRAC drawn against the base
    ///         allowance. Selector-compatible with the legacy
    ///         `windowSpent` public mapping.
    function windowSpent(uint256 accountId, uint40 w) external view returns (uint96) {
        return publishingConvictionStorage.windowSpent(accountId, w);
    }

    /// @notice Persistent top-up buffer for `accountId`.
    function topUpBalance(uint256 accountId) external view returns (uint96) {
        return publishingConvictionStorage.topUpBalance(accountId);
    }

    /// @notice Reverse map: account id paying for a given agent (0 if
    ///         not registered). Selector-compatible.
    function agentToAccountId(address agent) external view returns (uint256) {
        return publishingConvictionStorage.agentToAccountId(agent);
    }

    /// @notice Governance-tunable cap on registered agents per account.
    function maxAgentsPerAccount() external view returns (uint256) {
        return publishingConvictionStorage.maxAgentsPerAccount();
    }

    /// @notice Enumerate every registered agent for `accountId`.
    function getRegisteredAgents(uint256 accountId) external view returns (address[] memory) {
        return publishingConvictionStorage.getRegisteredAgents(accountId);
    }

    /// @notice Membership check used by off-chain integrations.
    function isAgent(uint256 accountId, address agent) external view returns (bool) {
        return publishingConvictionStorage.isRegisteredAgent(accountId, agent);
    }

    /// @notice Discrete 6-tier discount ladder. Selector-compatible
    ///         wrapper read over the shared publishing math helper.
    function getDiscountBps(uint96 committedTRAC) public pure returns (uint256) {
        return PublishingMathLib.discountBps(committedTRAC);
    }

    /// @notice Discount basis points fixed at creation for `accountId`.
    function getDiscount(uint256 accountId) external view returns (uint256) {
        return publishingConvictionStorage.getAccount(accountId).discountBps;
    }

    /// @notice Discounted cost preview for a given account + base cost.
    function getDiscountedCost(uint256 accountId, uint96 baseCost) external view returns (uint96) {
        uint256 bps = publishingConvictionStorage.getAccount(accountId).discountBps;
        return uint96((uint256(baseCost) * (BPS_DENOMINATOR - bps)) / BPS_DENOMINATOR);
    }

    /// @notice Aggregate read combining account fields, top-up balance,
    ///         and agent count into one tuple. Selector-stable.
    function getAccountInfo(uint256 accountId) external view returns (
        address owner_,
        uint96 committedTRAC,
        uint96 baseEpochAllowance,
        uint40 createdAtEpoch,
        uint40 expiresAtEpoch,
        uint40 createdAtTimestamp,
        uint40 expiresAtTimestamp,
        uint16 discountBps,
        uint96 topUpBuffer,
        uint256 agentCount,
        uint16 lastSettledWindow,
        bool fullySwept
    ) {
        PublishingConvictionStorage.Account memory a =
            publishingConvictionStorage.getAccount(accountId);
        return (
            ownerOf(accountId),
            a.committedTRAC,
            a.committedTRAC / uint96(a.lockDurationEpochs),
            a.createdAtEpoch,
            a.expiresAtEpoch,
            a.createdAtTimestamp,
            a.expiresAtTimestamp,
            a.discountBps,
            publishingConvictionStorage.topUpBalance(accountId),
            publishingConvictionStorage.agentCount(accountId),
            a.lastSettledWindow,
            a.fullySwept
        );
    }

    /// @notice Remaining base + topUp allowance for `accountId` in
    ///         chain `epoch`. Forwards to the logic contract's view.
    function getRemainingAllowance(uint256 accountId, uint40 epoch) external view returns (uint96) {
        return _publishingConviction().getRemainingAllowance(accountId, epoch);
    }

    /// @notice Current billing-window index for `accountId`.
    function getCurrentBillingWindow(uint256 accountId) external view returns (uint40) {
        return _publishingConviction().getCurrentBillingWindow(accountId);
    }

    /// @notice Chain-epoch range for billing window `w`.
    function getWindowChainEpochRange(uint256 accountId, uint40 w)
        external
        view
        returns (uint40 startEp, uint40 endEp)
    {
        return _publishingConviction().getWindowChainEpochRange(accountId, w);
    }

    // ========================================================================
    //                  ERC-721 overrides
    // ========================================================================

    function supportsInterface(
        bytes4 interfaceId
    ) public view virtual override(ERC721Enumerable) returns (bool) {
        return super.supportsInterface(interfaceId);
    }

    function _increaseBalance(
        address account,
        uint128 value
    ) internal virtual override(ERC721Enumerable) {
        super._increaseBalance(account, value);
    }

    /// @dev Owner-to-owner transfer hook: forward to the logic contract
    ///      so it can flush pending lazy settlement and clear every
    ///      agent registration. Skipped on mint/burn (`from == 0` or
    ///      `to == 0`). Mint case: the storage record is populated AFTER
    ///      `_mint` returns by `createAccount`, so the hook would have
    ///      no Account to settle anyway.
    function _update(
        address to,
        uint256 tokenId,
        address auth
    ) internal virtual override(ERC721Enumerable) returns (address) {
        address from = super._update(to, tokenId, auth);

        if (from != address(0) && to != address(0) && from != to) {
            _publishingConviction().onTransfer(tokenId, from, to);
        }

        return from;
    }

    // ========================================================================
    //                  Internal
    // ========================================================================

    function _publishingConviction() internal view returns (PublishingConviction) {
        address logic = hub.getContractAddress("PublishingConviction");
        if (logic == address(0)) revert ZeroAddressDependency("PublishingConviction");
        return PublishingConviction(logic);
    }

    function _requireOwner(uint256 accountId) internal view {
        if (_ownerOf(accountId) == address(0)) {
            // Match OZ's `ERC721NonexistentToken` revert by relying on
            // `_requireOwned` so callers see the same surface across
            // legacy and split implementations.
            _requireOwned(accountId);
        }
        if (ownerOf(accountId) != msg.sender) {
            revert NotAccountOwner(accountId, msg.sender);
        }
    }
}

contracts/DKGStakingConvictionNFT.sol.content:
// SPDX-License-Identifier: Apache-2.0

pragma solidity ^0.8.20;

import {IVersioned} from "./interfaces/IVersioned.sol";
import {IInitializable} from "./interfaces/IInitializable.sol";
import {ContractStatus} from "./abstract/ContractStatus.sol";
import {Ask} from "./Ask.sol";
import {ShardingTable} from "./ShardingTable.sol";
import {StakingV10} from "./StakingV10.sol";
import {ShardingTableStorage} from "./storage/ShardingTableStorage.sol";
import {ConvictionStakingStorage} from "./storage/ConvictionStakingStorage.sol";
import {ParametersStorage} from "./storage/ParametersStorage.sol";
import {ProfileStorage} from "./storage/ProfileStorage.sol";
import {RandomSamplingStorage} from "./storage/RandomSamplingStorage.sol";
import {Chronos} from "./storage/Chronos.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {ERC721} from "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import {ERC721Enumerable} from "@openzeppelin/contracts/token/ERC721/extensions/ERC721Enumerable.sol";
import {ICustodian} from "./interfaces/ICustodian.sol";
import {HubLib} from "./libraries/HubLib.sol";

/**
 * @title DKGStakingConvictionNFT
 * @notice Wraps V10 DKG staking positions as transferable ERC-721 NFTs.
 *
 * Each NFT represents a staking position on a specific node with a discrete
 * conviction lock tier ({0, 1, 3, 6, 12} months → 1.0x / 1.5x / 2.0x / 3.5x /
 * 6.0x boost, D20 hardcoded tier ladder). The position can be transferred to
 * another address (accrued-interest transfer model — the new owner inherits
 * both the raw stake and any unclaimed rewards; see `_update` below).
 *
 * @dev V10 split-contract architecture. This contract is a dumb ERC-721
 *      ownership receipt: it mints/burns tokens, validates ownership on
 *      mutating calls, and forwards every business action to `StakingV10`.
 *      All stake / withdrawal / reward / migration logic lives in
 *      `StakingV10`, gated by `onlyConvictionNFT` so only this wrapper can
 *      invoke it. TRAC never touches this contract: users approve
 *      `StakingV10` directly and `StakingV10.stake` pulls TRAC via
 *      `token.transferFrom(staker, convictionStorage, amount)` — CSS is
 *      the V10 vault as of v4.0.0. The wrapper never calls
 *      `ConvictionStakingStorage.*` directly for mutations — the only
 *      storage read it does is `convictionStakingStorage.getPosition(tokenId)`
 *      in `redelegate`, to capture the pre-call `identityId` for the
 *      wrapper-layer event.
 *
 *      User-facing entry points:
 *        - `createConviction`                             — mint path, fresh V10 stake
 *        - `allocate`                                     — mint path, spends migration credit
 *        - `selfMigrate` / `selfMigrateOperatorFee`       — self-service drain into credit (straggler backstop; no mint)
 *        - `finalizeMigrationBatch`                       — DAO closer (D11), sets `v10LaunchEpoch`
 *        - `relock`                                       — D21 burn-and-mint tier re-commit
 *        - `redelegate`                                   — D25 in-place node swap (stable tokenId)
 *        - `withdraw`                                     — D14 atomic burn-and-payout
 *        - `claim`
 *      Admin entry points (admin-push drain into credit; no mint):
 *        - `adminDrainBatch` / `adminMigrateToCredit`     — delegator stake (+pending) → credit
 *        - `adminDrainOperatorFeesBatch`                  — operator fees → credit
 *
 *      NFT lifecycle:
 *        - `createConviction` / `allocate`:
 *          fresh mints. Monotonic `nextTokenId`.
 *        - `relock` (D21): burns `oldTokenId` and mints `newTokenId`.
 *          CSS-level position state migrates via the D23
 *          `createNewPositionFromExisting` primitive, preserving
 *          `cumulativeRewardsClaimed`, `lastClaimedEpoch`, and
 *          `migrationEpoch` into the new tokenId so off-chain reward
 *          accounting stays intact across the burn-mint.
 *        - `redelegate` (D25): tokenId is STABLE — no mint, no burn,
 *          only `pos.identityId` mutates on CSS via `updateOnRedelegate`.
 *          `expiryTimestamp` is preserved: the lock clock keeps ticking.
 *        - `withdraw` (D14): atomic. Burns `tokenId` after CSS deletes
 *          the position and TRAC is released to the owner.
 */
/// @dev M5 — this contract does NOT implement `INamed`. ERC-721's `name()`
///      already occupies that function selector with a different contract —
///      the collection display name returned to wallets — so an `INamed`
///      implementation would collide. Use `contractName()` below for the
///      dev-facing contract id (matches other V10 contracts' INamed value).
contract DKGStakingConvictionNFT is IVersioned, ContractStatus, IInitializable, ERC721Enumerable {
    string private constant _CONTRACT_NAME = "DKGStakingConvictionNFT";
    // 1.1.0 — initial V10 NFT wrapper.
    // 1.2.0 — D26 code-review follow-ups:
    //         * M5 — `name()` now returns the ERC-721 collection name
    //           (`"DKG Staker Conviction"`) as ERC-721 consumers expect;
    //           the dev-facing contract id is exposed via `contractName()`.
    //           `INamed` inheritance removed to avoid the selector collision.
    //         * L1 — stale `expiryEpoch` references scrubbed from NatSpec.
    //         * L2 — `nextTokenId` starts at 1 so `tokenId == 0` is a
    //           guaranteed sentinel ("no position").
    //         * L3 — `lockTier` widened to `uint40` across all entry
    //           points and events.
    //         * L8 — `identityId != 0` guard added on mint paths so
    //           ambiguous "zero-node" mints fail fast at the wrapper.
    //         * 10.0.3 — operator-fee migration: added
    //           `adminDrainOperatorFeesBatch` + `OperatorFeeMigrated`; bumped so
    //           the breaking migration ABI is detectable via `version()`.
    string private constant _VERSION = "10.0.3";

    // ========================================================================
    // Constants
    // ========================================================================

    /// @notice 1e18 fixed-point scale shared with `ConvictionStakingStorage`.
    ///         Tier table and reward math all use this scale.
    uint256 public constant SCALE18 = 1e18;

    // ========================================================================
    // Hub-wired dependencies
    // ========================================================================

    StakingV10 public stakingV10;
    ConvictionStakingStorage public convictionStakingStorage;
    Chronos public chronos;
    RandomSamplingStorage public randomSamplingStorage;
    ShardingTableStorage public shardingTableStorage;
    ShardingTable public shardingTableContract;
    Ask public askContract;
    ParametersStorage public parametersStorage;
    ProfileStorage public profileStorage;
    IERC20 public tokenContract;

    // ========================================================================
    // Storage
    // ========================================================================

    /// @notice Monotonic token id counter. The first mint produces tokenId 1
    ///         (L2 — tokenId 0 is reserved as a sentinel so `ownerOf(0)` is
    ///         always "unambiguously nothing"). `++nextTokenId` bumps the
    ///         counter before use, so `nextTokenId == N` means "N positions
    ///         have been minted (ever)".
    uint256 public nextTokenId;

    // ========================================================================
    // Events
    // ========================================================================

    /// @notice Emitted by `createConviction` and `convertToNFT` after the
    ///         NFT is minted. The authoritative position-created event (with
    ///         raw / expiryTimestamp / multiplier18) is emitted by
    ///         `ConvictionStakingStorage.createPosition` via `StakingV10.stake`;
    ///         this wrapper-layer event is kept so off-chain indexers that
    ///         watch the NFT contract alone still see the mint.
    event PositionCreated(
        address indexed owner,
        uint256 indexed tokenId,
        uint72 indexed identityId,
        uint96 amount,
        uint40 lockTier
    );

    /// @notice Emitted by `relock` after the old NFT is burned and a fresh
    ///         one is minted under a new lock tier. D21 — NFTs are ephemeral;
    ///         off-chain indexers follow `oldTokenId → newTokenId` via this
    ///         event (and `PositionReplaced` on `ConvictionStakingStorage`,
    ///         which carries the full reward-stat continuity).
    event PositionRelocked(
        uint256 indexed oldTokenId,
        uint256 indexed newTokenId,
        uint40 newLockTier
    );

    /// @notice Emitted by `redelegate` after the position's identity is
    ///         mutated in place. D25 — tokenId, `expiryTimestamp`, lock tier,
    ///         multiplier, and reward cursor are all preserved; only the
    ///         node assignment changes. Global totals are invariant; only
    ///         per-node effective stake moves. Authoritative event (same
    ///         shape) is emitted by `ConvictionStakingStorage` via
    ///         `updateOnRedelegate`; this wrapper-layer event is kept so
    ///         off-chain indexers watching the NFT contract alone still
    ///         see the transition.
    event PositionRedelegated(
        uint256 indexed tokenId,
        uint72 indexed oldIdentityId,
        uint72 indexed newIdentityId
    );

    /// @notice Emitted by `withdraw` after CSS deletes the position and TRAC
    ///         is released from the vault to the owner. The NFT is burned
    ///         immediately after. Authoritative event (with `staker`) is
    ///         emitted by `StakingV10.withdraw`; this wrapper-layer event
    ///         is kept so off-chain indexers watching the NFT contract
    ///         alone still see the exit.
    event PositionWithdrawn(uint256 indexed tokenId, uint96 amount);

    /// @notice Emitted when a delegator's V8 stake is drained into migration
    ///         credit by the admin sweep. `credited` is the total
    ///         moved into that delegator's credit by this event.
    event MigrationStarted(address indexed delegator, uint96 credited);

    /// @notice Emitted when a node's V8 operator fee (resting balance + any open
    ///         fee-withdrawal request) is drained into the operator's migration
    ///         credit by the admin sweep. Keyed by `identityId` so
    ///         per-node fee migration reconciles against the V8 vault; `operator`
    ///         is the validated current ADMIN_KEY holder that was credited.
    /// @dev    Reconciliation: total migration credit issued = Σ `MigrationStarted`
    ///         (delegator stake) + Σ `OperatorFeeMigrated` (operator fees). An
    ///         indexer must sum BOTH events or it undercounts operators.
    event OperatorFeeMigrated(uint72 indexed identityId, address indexed operator, uint96 credited);

    /// @notice Emitted when migration credit is allocated into a fresh V10
    ///         conviction position. `creditApplied` is true when the tier-6/12
    ///         conviction lock-credit was applied (any 6/12 migration allocation;
    ///         universal).
    event Allocated(
        address indexed delegator,
        uint256 indexed tokenId,
        uint72 indexed targetNode,
        uint96 amount,
        uint40 lockTier,
        bool creditApplied
    );

    /// @notice Emitted by `finalizeMigrationBatch` when the DAO closes the
    ///         V10 migration window by setting the `v10LaunchEpoch` marker
    ///         on CSS. Retroactive-attribution analyses use this epoch.
    event MigrationBatchFinalized(uint256 v10LaunchEpoch);

    // ========================================================================
    // Errors
    // ========================================================================

    // Only errors thrown at the NFT wrapper layer are declared here. Every
    // position-lifecycle check (lock expiry, withdrawal state, same-identity,
    // profile existence, max-stake, rewards/raw sufficiency, etc.) is the
    // responsibility of `StakingV10` and reverts with the matching error
    // declared there. Keeping the NFT layer's error surface minimal avoids
    // dead code at the wrapper and prevents the wrapper layer from drifting
    // into business-rule decisions.
    error InvalidLockTier();
    error NotPositionOwner();
    error ZeroAmount();
    /// @notice Thrown by `adminMigrateToCredit` when the delegator
    ///         has no V8 stake across the given source nodes (nothing drained,
    ///         so no credit would be created). `adminDrainBatch` SKIPS such
    ///         entries instead of reverting.
    error NothingToMigrate();
    /// @notice L8 — rejected at the wrapper layer when a mint-path or
    ///         redelegate call would otherwise forward a zero identity to
    ///         StakingV10 (which uses `identityId == 0` internally as the
    ///         "no position" sentinel).
    error InvalidIdentityId();

    // ========================================================================
    // Constructor + initialize
    // ========================================================================

    // solhint-disable-next-line no-empty-blocks
    constructor(
        address hubAddress
    ) ContractStatus(hubAddress) ERC721("DKG Staker Conviction", "DKGSC") {}

    function initialize() public onlyHub {
        stakingV10 = StakingV10(hub.getContractAddress("StakingV10"));
        convictionStakingStorage = ConvictionStakingStorage(hub.getContractAddress("ConvictionStakingStorage"));
        chronos = Chronos(hub.getContractAddress("Chronos"));
        randomSamplingStorage = RandomSamplingStorage(hub.getContractAddress("RandomSamplingStorage"));
        shardingTableStorage = ShardingTableStorage(hub.getContractAddress("ShardingTableStorage"));
        shardingTableContract = ShardingTable(hub.getContractAddress("ShardingTable"));
        askContract = Ask(hub.getContractAddress("Ask"));
        parametersStorage = ParametersStorage(hub.getContractAddress("ParametersStorage"));
        profileStorage = ProfileStorage(hub.getContractAddress("ProfileStorage"));
        tokenContract = IERC20(hub.getContractAddress("Token"));
    }

    // M5 — `name()` (ERC-721) is deliberately NOT overridden; it returns the
    //      constructor-supplied collection name ("DKG Staker Conviction")
    //      that wallets display. The dev-facing contract id lives on
    //      `contractName()`.
    function contractName() external pure returns (string memory) {
        return _CONTRACT_NAME;
    }

    function version() external pure virtual returns (string memory) {
        return _VERSION;
    }

    // ========================================================================
    // Admin gate — used by the admin drains (`adminDrainBatch` /
    // `adminMigrateToCredit` / `adminDrainOperatorFeesBatch`) and `finalizeMigrationBatch`
    // ========================================================================

    /// @dev Matches the ownership + multisig pattern used by other admin
    ///      entry points on V10 contracts (e.g. `RandomSampling`).
    modifier onlyOwnerOrMultiSigOwner() {
        address hubOwner = hub.owner();
        if (msg.sender != hubOwner && !_isMultiSigOwner(hubOwner)) {
            revert HubLib.UnauthorizedAccess("Only Hub Owner or Multisig Owner");
        }
        _;
    }

    function _isMultiSigOwner(address multiSigAddress) internal view returns (bool) {
        try ICustodian(multiSigAddress).getOwners() returns (address[] memory owners) {
            for (uint256 i = 0; i < owners.length; i++) {
                if (msg.sender == owners[i]) return true;
            }
        } catch {
            // Not a multisig or call reverted; treat as not an owner.
        }
        return false;
    }

    // ========================================================================
    // Conviction multiplier tier ladder — delegates to CSS (v2.1.0)
    // ========================================================================
    //
    // Source of truth is `ConvictionStakingStorage._tiers`. The baseline
    // ladder seeded at `CSS.initialize()` is {0, 1, 3, 6, 12} mapping to
    // {1x, 1.5x, 2x, 3.5x, 6x} and {0, 30d, 90d, 180d, 360d} wall-clock
    // lock durations.
    // New tiers can be appended by the HubOwner via `CSS.addTier`; this
    // helper picks them up automatically via the storage read.
    //
    // Discrete, exact-match semantics — no snap-down. An unregistered
    // `lockTier` reverts `InvalidLockTier()`.
    //
    // Tier 0 → 1x is a first-class tier, not an edge case:
    //   V10 policy is that every staking position is an NFT, including
    //   no-lock liquid stake. Tier 0 is valid on every entry point that
    //   takes a lockTier:
    //     - createConviction(_, _, 0): fresh mint at rest state.
    //     - relock(_, 0)             : post-expiry opt-out to permanent 1x.
    //     - _convertToNFT(_, _, 0)   : V8 migrants landing at rest state.
    //     - any caller reading a live position's current tier after its
    //       lock has expired back to the rest state.
    //   Semantics: 1.0x multiplier, `expiryTimestamp == 0` (permanent, no
    //   boost decay ever fires), TRAC withdrawable at any time via the
    //   atomic `withdraw` path (D14 — no delay, the lock IS the delay
    //   and tier 0 has no lock).
    //
    //   `createConviction` still rejects DEACTIVATED tiers at the CSS
    //   layer: `CSS.createPosition` requires `active == true` whenever
    //   `migrationEpoch == 0`. Tier 0 is seeded active at
    //   `CSS.initialize()` and a HubOwner could deactivate it via
    //   `deactivateTier(0)` if the no-lock product is ever retired;
    //   relock and V8→V10 migration paths bypass the `active` check
    //   (existence only) so users can renew under a tier they
    //   originally committed to.
    //
    // @param lockTier Tier id; must exist in `CSS._tiers`. Maps to the
    //                 wall-clock duration registered there. NOT a Chronos
    //                 epoch count.
    // @return multiplier18 1e18-scaled tier multiplier.
    function _convictionMultiplier(uint256 lockTier) internal view returns (uint256) {
        ConvictionStakingStorage.TierConfig memory tc =
            convictionStakingStorage.getTier(uint40(lockTier));
        if (!tc.exists) revert InvalidLockTier();
        return uint256(tc.multiplier18);
    }

    // ========================================================================
    // Entry points — thin wrappers that forward to `StakingV10`
    // ========================================================================
    //
    // The NFT contract is a dumb ownership receipt. All position business
    // logic (stake bookkeeping, conviction math, reward accrual, withdrawal
    // state machine, V8 migration) lives in `StakingV10`, which is gated by
    // `onlyConvictionNFT` so only this contract can invoke it. Each wrapper:
    //
    //   1. Validates ownership (`ownerOf == msg.sender`) on mutating calls.
    //   2. For mint paths, fails fast on `lockTier` via `_convictionMultiplier`.
    //   3. Mints / burns the ERC-721 token as needed.
    //   4. Forwards to the matching `StakingV10` method with `msg.sender`
    //      passed explicitly as the `staker` argument (StakingV10 never
    //      trusts `tx.origin`).
    //   5. Emits a wrapper-layer mirror event for NFT-contract watchers —
    //      the authoritative event for off-chain accounting comes from the
    //      `StakingV10` / `ConvictionStakingStorage` layer.
    //
    // TRAC never touches this contract: at `createConviction` the user has
    // approved `StakingV10` directly, and `StakingV10.stake` pulls TRAC via
    // `token.transferFrom(staker, convictionStorage, amount)` — CSS is
    // the v4.0.0 TRAC vault. The NFT layer only mints/burns ERC-721 tokens.

    /// @notice Mint a fresh NFT-backed staking position on `identityId` with
    ///         `amount` TRAC under the `lockTier` tier. Valid tiers are
    ///         whatever `CSS.getTier(lockTier).active == true`; the seeded
    ///         baseline is tier 0 (rest state, 1x, no lock) plus 1/3/6/12
    ///         (30d/90d/180d/366d → 1.5x/2x/3.5x/6x). All tiers — including
    ///         tier 0 — produce an NFT; every V10 staking position is an NFT.
    function createConviction(
        uint72 identityId,
        uint96 amount,
        uint40 lockTier
    ) external returns (uint256 tokenId) {
        if (identityId == 0) revert InvalidIdentityId();
        if (amount == 0) revert ZeroAmount();
        // Fail-fast on tiers that don't exist in `CSS._tiers` (e.g. 2, 4,
        // 7, 13): `_convictionMultiplier` reverts `InvalidLockTier()` when
        // the tier is unregistered. Tier 0 (rest state, 1x) is a valid
        // registered tier — V10 policy is that no-lock stake is a first-
        // class NFT position, not a blocked state. Deactivated tiers are
        // rejected further downstream by `CSS.createPosition` via
        // `_requireActiveTier` (fresh stakes only — migrationEpoch == 0).
        _convictionMultiplier(lockTier);

        tokenId = ++nextTokenId;
        // CEI ordering: settle CSS state and pull TRAC FIRST, then `_mint`
        // last so the wrapper never observes a half-built (NFT-without-
        // position) state. `_mint` (not `_safeMint`) is intentional:
        // contract callers without `IERC721Receiver` are part of the
        // supported caller set (multisigs, treasuries, AA wallets, etc.).
        stakingV10.stake(msg.sender, tokenId, identityId, amount, lockTier);
        _mint(msg.sender, tokenId);

        emit PositionCreated(msg.sender, tokenId, identityId, amount, lockTier);
    }

    /// @notice Post-expiry re-commit of an existing position to a new lock
    ///         tier. Raw stake unchanged; multiplier + expiry shift.
    ///
    /// @dev D21 — NFTs are ephemeral. Relock burns the old NFT and mints a
    ///      fresh one at `newTokenId = ++nextTokenId`. `StakingV10.relock`
    ///      drives the D23 `createNewPositionFromExisting` primitive on CSS,
    ///      which preserves `cumulativeRewardsClaimed`, `lastClaimedEpoch`,
    ///      and `migrationEpoch` on the new tokenId; indexers that need to
    ///      track a delegator's history across relocks follow the
    ///      `PositionRelocked(oldTokenId, newTokenId, ...)` event surfaced
    ///      here (and the CSS-level `PositionReplaced` with the full reward
    ///      stat continuity).
    ///
    ///      CEI ordering — state changes first, NFT mint last:
    ///        1. `stakingV10.relock` — drives CSS's `createNewPositionFromExisting`
    ///           which itself asserts the new slot is empty
    ///           (`positions[newTokenId].identityId == 0`). That assertion is
    ///           a CSS-state check, not an NFT-existence check, so the new
    ///           NFT does NOT need to exist yet.
    ///        2. `_burn(oldTokenId)` — removes the old NFT after CSS has
    ///           moved the position. A mid-call revert leaves BOTH NFT and
    ///           position state intact at the old tokenId.
    ///        3. `_mint(msg.sender, newTokenId)` — last, so the wrapper
    ///           never observes a half-built burn-mint state. `_mint`
    ///           (not `_safeMint`) is intentional: contract callers
    ///           without `IERC721Receiver` are part of the supported
    ///           caller set, including any contract holding an existing
    ///           position from a prior `_mint`-era relock.
    function relock(uint256 oldTokenId, uint40 newLockTier) external returns (uint256 newTokenId) {
        if (ownerOf(oldTokenId) != msg.sender) revert NotPositionOwner();
        // Fail-fast on unregistered tiers (e.g. 2, 4, 7). Tier 0 is valid:
        // relock to the rest state is a legitimate post-expiry opt-out to
        // permanent 1x with no new lock. Deactivated tiers are allowed on
        // the relock path (existence-only check in CSS) so users can
        // renew under a tier they originally committed to even if it has
        // since been retired.
        _convictionMultiplier(newLockTier);

        newTokenId = ++nextTokenId;
        stakingV10.relock(msg.sender, oldTokenId, newTokenId, newLockTier);
        _burn(oldTokenId);
        _mint(msg.sender, newTokenId);

        emit PositionRelocked(oldTokenId, newTokenId, newLockTier);
    }

    /// @notice Move a position from its current node to `newIdentityId`.
    ///         Per-node effective stake moves; global totals invariant.
    ///         The tokenId is STABLE — the caller's NFT asset identity is
    ///         preserved across the redelegation, only the node it points
    ///         at changes.
    ///
    /// @dev D25 — in-place node swap. Unlike `relock` (which burns and
    ///      mints because tier / multiplier / expiry all change), a
    ///      redelegation is a routing decision: the lock clock keeps
    ///      ticking on the same `expiryTimestamp`, the reward cursor
    ///      (`lastClaimedEpoch`, `cumulativeRewardsClaimed`,
    ///      `migrationEpoch`) carries through unchanged, and the tokenId
    ///      itself persists so wallets and marketplaces see a stable
    ///      asset. StakingV10 drives the CSS `updateOnRedelegate`
    ///      primitive which moves per-node effective-stake contributions
    ///      and pending expiry deltas across at `currentEpoch`.
    function redelegate(uint256 tokenId, uint72 newIdentityId) external {
        if (ownerOf(tokenId) != msg.sender) revert NotPositionOwner();
        if (newIdentityId == 0) revert InvalidIdentityId();
        // Capture the pre-call `identityId` so the wrapper-layer event can
        // surface both endpoints.
        uint72 oldIdentityId = convictionStakingStorage.getPosition(tokenId).identityId;

        stakingV10.redelegate(msg.sender, tokenId, newIdentityId);

        emit PositionRedelegated(tokenId, oldIdentityId, newIdentityId);
    }

    /// @notice Atomic full withdrawal. Pays out the position's entire `raw`
    ///         balance (post-auto-claim) to the owner and burns the NFT in
    ///         a single transaction. Caller must own the NFT.
    ///
    /// @dev D14 — no request/cancel/finalize dance, no address-timer
    ///      delay. Pre-expiry reverts `LockStillActive` at StakingV10.
    ///      Q3 — rewards are auto-claimed inside `StakingV10.withdraw`
    ///      before the final drain, so the user sees a single button in
    ///      the UI. Full-only by design (Q1) — a user wanting to keep
    ///      some TRAC staked should withdraw and re-stake the remainder
    ///      (tier 0 with 1x is effectively liquid).
    function withdraw(uint256 tokenId) external returns (uint96 amount) {
        if (ownerOf(tokenId) != msg.sender) revert NotPositionOwner();

        // CEI ordering — the receipt NFT is dropped BEFORE the CSS
        // teardown + TRAC payout run, so the on-chain ownership claim
        // ends before any external token movement. ownerOf-gated
        // re-entry paths on this contract (claim / withdraw / relock /
        // redelegate) revert at the entry ownership check.
        // StakingV10.withdraw gates on the CSS position (`pos.identityId
        // == 0`), not NFT existence, so the teardown is unaffected.
        _burn(tokenId);

        amount = stakingV10.withdraw(msg.sender, tokenId);

        emit PositionWithdrawn(tokenId, amount);
    }

    /// @notice Walk unclaimed epochs for the position, accumulate reward,
    ///         and bank it into the `ConvictionStakingStorage` rewards
    ///         bucket. Updates `lastClaimedEpoch`.
    function claim(uint256 tokenId) external {
        if (ownerOf(tokenId) != msg.sender) revert NotPositionOwner();
        stakingV10.claim(msg.sender, tokenId);
        // No wrapper-layer event — `StakingV10.claim` emits `RewardsClaimed`
        // with the amount already. The NFT layer does not duplicate reward
        // accounting events.
    }

    // ========================================================================
    // V8 → V10 "pool & allocate" migration
    // ========================================================================
    //
    // Admin-push: the protocol drains EVERY wallet's V8 stake across
    // its source nodes into that wallet's in-protocol migration credit, via
    // `adminDrainBatch` (bulk) / `adminMigrateToCredit` (single delegator) —
    // both onlyOwnerOrMultiSigOwner. Users never drain themselves; they only
    // call `allocate` to spend their pre-populated credit into V10 conviction
    // positions (node + amount + tier), repeatably. A tier-6/12 allocation earns
    // the conviction lock-credit (universal — no eligibility registry).
    // Credit is non-withdrawable as credit; `allocate` is its only sink — but a
    // tier-0 allocation carries no lock and is immediately withdrawable, so
    // drained funds are always recoverable to the wallet in two txs. The credit
    // ledger + drain/allocate workers live on CSS / StakingV10
    // (onlyConvictionNFT); this wrapper owns the tokenId counter + ERC-721 mint
    // and the owner gating.
    //
    // There is intentionally NO self-service drain: the off-chain sweep is the
    // only path that empties V8, so its completeness (per-chain
    // StakingStorage.getTotalStake() == 0) is a release gate before the V8
    // `Staking` contract is unregistered.

    /// @notice Single-delegator admin drain — move `delegator`'s V8 stake across
    ///         `sourceNodes` into THEIR migration credit (no allocation). See
    ///         `adminDrainBatch` for the bulk sweep. Gate:
    ///         `onlyOwnerOrMultiSigOwner`. Reverts `NothingToMigrate` if nothing
    ///         was drained (caller-error guard on an intentional single call).
    function adminMigrateToCredit(
        address delegator,
        uint72[] calldata sourceNodes
    ) external onlyOwnerOrMultiSigOwner returns (uint96 credited) {
        // Benign: _drainAll calls only the onlyConvictionNFT worker over trusted
        // storage (no callback); the event after it carries no reentrancy risk.
        // slither-disable-next-line reentrancy-events
        credited = _drainAll(delegator, sourceNodes);
        if (credited == 0) revert NothingToMigrate();
        emit MigrationStarted(delegator, credited);
    }

    /// @notice Bulk admin-push drain. Each index `i` is ONE (delegator, node)
    ///         pair — the flattened form matches the V8 storage key and the
    ///         off-chain DelegatorsInfo enumeration, giving even per-pair gas so
    ///         the driver packs uniform chunks. Pairs with nothing to drain are
    ///         SKIPPED (not reverted), so a chunk mixing already-drained and
    ///         fresh pairs still lands and re-running a chunk after a partial
    ///         failure is safe (`drainV8ToCredit` is idempotent — a zeroed slot
    ///         yields 0). Amounts are NOT passed in — they are read on-chain from
    ///         V8 state, so the credit is exactly what was drained. Gate:
    ///         `onlyOwnerOrMultiSigOwner`. Emits one `MigrationStarted` per pair
    ///         that moved credit.
    function adminDrainBatch(
        address[] calldata delegators,
        uint72[] calldata identityIds
    ) external onlyOwnerOrMultiSigOwner {
        uint256 n = delegators.length;
        require(n == identityIds.length, "length mismatch");
        for (uint256 i = 0; i < n; i++) {
            // Benign: owner-only batch; the callee is onlyConvictionNFT over
            // trusted protocol storage, moves plain ERC20 TRAC (no callback),
            // and is idempotent — no value-reentrancy vector, event-after-call ok.
            // slither-disable-next-line calls-loop,reentrancy-events
            uint96 t = stakingV10.drainV8ToCredit(delegators[i], identityIds[i]);
            if (t > 0) emit MigrationStarted(delegators[i], t);
        }
    }

    /// @notice Bulk operator-fee drain — companion to `adminDrainBatch` for the
    ///         node side. Each index `i` is ONE (node, operator) pair: the V8
    ///         operator fee on `identityIds[i]` (resting balance + open
    ///         withdrawal request) is moved into `operators[i]`'s migration
    ///         credit (the SAME bucket as delegator
    ///         stake). `operators[i]` MUST currently hold ADMIN_KEY on the node
    ///         (validated in `StakingV10.drainOperatorFeeToCredit`, which
    ///         REVERTS a stale/wrong address) — so a mis-resolved operator
    ///         reverts the whole batch rather than crediting wrongly; the
    ///         off-chain sweep re-resolves and retries. Nodes with no fee are
    ///         SKIPPED (idempotent: a re-drained node yields 0). Amounts are
    ///         read on-chain, never passed in. Gate: `onlyOwnerOrMultiSigOwner`.
    ///         Emits one `OperatorFeeMigrated` per node that moved credit.
    function adminDrainOperatorFeesBatch(
        uint72[] calldata identityIds,
        address[] calldata operators
    ) external onlyOwnerOrMultiSigOwner {
        uint256 n = identityIds.length;
        require(n == operators.length, "length mismatch");
        for (uint256 i = 0; i < n; i++) {
            // Benign: owner-only batch; the callee is onlyConvictionNFT over
            // trusted protocol storage, moves plain ERC20 TRAC (no callback),
            // and is idempotent — no value-reentrancy vector, event-after-call ok.
            // slither-disable-next-line calls-loop,reentrancy-events
            uint96 t = stakingV10.drainOperatorFeeToCredit(identityIds[i], operators[i]);
            if (t > 0) emit OperatorFeeMigrated(identityIds[i], operators[i], t);
        }
    }

    /// @notice Self-service straggler backstop. The connected wallet drains ITS
    ///         OWN V8 stake (keyed by `keccak256(msg.sender)`) across `sourceNodes`
    ///         into its own migration credit. Admin-push (`adminDrainBatch`) is the
    ///         primary path; this exists so any delegator the off-chain sweep
    ///         missed can never be stranded. Permissionless and self-validating —
    ///         you can only ever drain the V8 key that hashes from your own
    ///         address, into your own credit. Works after V8 Staking is
    ///         unregistered (the drain goes through StakingStorage directly); the
    ///         worker's freeze gate means it is only callable once V8 Staking is
    ///         frozen (so it cannot race live V8 reward/sharding accounting).
    function selfMigrate(uint72[] calldata sourceNodes) external returns (uint96 credited) {
        credited = _drainAll(msg.sender, sourceNodes);
        if (credited == 0) revert NothingToMigrate();
        emit MigrationStarted(msg.sender, credited);
    }

    /// @notice Self-service operator-fee backstop: the node admin (msg.sender,
    ///         validated against ADMIN_KEY inside `drainOperatorFeeToCredit`)
    ///         drains the node's V8 operator fee into its own migration credit.
    ///         Same freeze-gated, post-unregister-safe properties as `selfMigrate`.
    function selfMigrateOperatorFee(uint72 identityId) external returns (uint96 credited) {
        credited = stakingV10.drainOperatorFeeToCredit(identityId, msg.sender);
        if (credited == 0) revert NothingToMigrate();
        emit OperatorFeeMigrated(identityId, msg.sender, credited);
    }

    /// @notice Spend `amount` of the caller's migration credit into a fresh V10
    ///         conviction position on `targetNode` at `lockTier`. Repeatable
    ///         until the credit is spent. Any tier-6/12 allocation receives the
    ///         conviction lock-credit (universal).
    function allocate(
        uint72 targetNode,
        uint96 amount,
        uint40 lockTier
    ) external returns (uint256 tokenId) {
        if (targetNode == 0) revert InvalidIdentityId();
        if (amount == 0) revert ZeroAmount();
        tokenId = ++nextTokenId;
        // CEI: settle CSS state (credit debit + position) first, mint last.
        // `_mint` (not `_safeMint`) — same supported-caller rationale as
        // `createConviction`.
        bool creditApplied = stakingV10.allocateFromCredit(msg.sender, tokenId, targetNode, amount, lockTier);
        _mint(msg.sender, tokenId);
        emit Allocated(msg.sender, tokenId, targetNode, amount, lockTier, creditApplied);
    }

    /// @dev Drain `delegator`'s V8 stake across `sourceNodes` into credit,
    ///      summing the total. A node with no V8 stake contributes 0;
    ///      idempotent (a re-drained node yields 0).
    function _drainAll(
        address delegator,
        uint72[] calldata sourceNodes
    ) internal returns (uint96 total) {
        uint256 n = sourceNodes.length;
        for (uint256 i = 0; i < n; i++) {
            // Benign: onlyConvictionNFT callee over trusted storage, plain ERC20,
            // idempotent (see adminDrainBatch).
            // slither-disable-next-line calls-loop
            total += stakingV10.drainV8ToCredit(delegator, sourceNodes[i]);
        }
    }

    /// @notice Set the V8→V10 conviction lock-credit (seconds). Owner-settable;
    ///         set it before running the admin sweep. CSS caps it below the
    ///         tier-6 lock duration so a position's expiry cannot underflow.
    function setConvictionCreditSeconds(uint40 secondsValue) external onlyOwnerOrMultiSigOwner {
        stakingV10.setConvictionCreditSeconds(secondsValue);
    }

    // ---- Migration credit views (forward to the CSS ledger) ----

    function migrationCredit(address user) external view returns (uint96) {
        return convictionStakingStorage.migrationCredit(user);
    }

    function convictionCreditSeconds() external view returns (uint40) {
        return convictionStakingStorage.convictionCreditSeconds();
    }

    /// @notice DAO closer — D11. Sets the `v10LaunchEpoch` marker on
    ///         `ConvictionStakingStorage` to formally close the V10
    ///         migration window. After this, late drains are still possible via
    ///         `adminDrainBatch` / `adminMigrateToCredit`, but the launch-epoch
    ///         field is the canonical off-chain cut-off for retroactive
    ///         reward / analytics windows.
    function finalizeMigrationBatch(uint256 v10LaunchEpoch) external onlyOwnerOrMultiSigOwner {
        stakingV10.setV10LaunchEpoch(v10LaunchEpoch);
        emit MigrationBatchFinalized(v10LaunchEpoch);
    }

    // ========================================================================
    // ERC-721 overrides — accrued-interest transfer model (Phase 5 Q8)
    // ========================================================================
    //
    // Mint/burn/transfer all flow through `_update`. For transfers, we do
    // NOT settle rewards, reset `lastClaimedEpoch`, or touch the position —
    // the NFT carries its unclaimed rewards like a bond with accrued
    // coupon (the accrued-interest NFT transfer model).
    //
    // The body is a pure `super._update` pass-through; this explicit
    // override exists to (a) document the intent and (b) satisfy the
    // compiler override requirement for `ERC721Enumerable`.

    function supportsInterface(
        bytes4 interfaceId
    ) public view virtual override(ERC721Enumerable) returns (bool) {
        return super.supportsInterface(interfaceId);
    }

    function _increaseBalance(
        address account,
        uint128 value
    ) internal virtual override(ERC721Enumerable) {
        super._increaseBalance(account, value);
    }

    function _update(
        address to,
        uint256 tokenId,
        address auth
    ) internal virtual override(ERC721Enumerable) returns (address) {
        return super._update(to, tokenId, auth);
    }
}

contracts/Guardian.sol.content:
// SPDX-License-Identifier: Apache-2.0

pragma solidity ^0.8.20;

import {HubDependent} from "./abstract/HubDependent.sol";
import {ICustodian} from "./interfaces/ICustodian.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";

contract Guardian is HubDependent {
    event TokenTransferred(address indexed custodian, uint256 amount);
    event MisplacedEtherWithdrawn(address indexed custodian, uint256 amount);
    event MisplacedERC20Withdrawn(address indexed custodian, address tokenContract, uint256 amount);

    error ZeroAddressCustodian();
    error CustodianNotAContract(address custodian);
    error CustodianWithoutOwnersFunction(address custodian);
    error CustodianHasNoOwners(address custodian);
    error TokenTransferFailed();
    error EtherTransferFailed();
    error InvalidTokenContract(address tokenContractAddress);

    IERC20 public tokenContract;

    // solhint-disable-next-line no-empty-blocks
    constructor(address hubAddress) HubDependent(hubAddress) {}

    function initialize() public virtual onlyHub {
        tokenContract = IERC20(hub.getContractAddress("Token"));
    }

    function transferTokens(address payable custodian) external onlyHub {
        if (custodian == address(0)) {
            revert ZeroAddressCustodian();
        }

        uint256 contractSize;
        assembly {
            contractSize := extcodesize(custodian)
        }
        if (contractSize == 0) {
            revert CustodianNotAContract(custodian);
        }

        ICustodian custodianContract = ICustodian(custodian);
        bool hasOwnersFunction = false;
        try custodianContract.getOwners() returns (address[] memory owners) {
            hasOwnersFunction = true;
            if (owners.length == 0) {
                revert CustodianHasNoOwners(custodian);
            }
        } catch {
            // getOwners reverted (e.g. not ICustodian); hasOwnersFunction stays false.
        }
        if (!hasOwnersFunction) {
            revert CustodianWithoutOwnersFunction(custodian);
        }

        uint256 balanceTransferred = tokenContract.balanceOf(address(this));
        bool transactionResult = tokenContract.transfer(custodian, balanceTransferred);

        if (!transactionResult) {
            revert TokenTransferFailed();
        }

        emit TokenTransferred(custodian, balanceTransferred);
    }

    function withdrawMisplacedEther() external onlyHub {
        uint256 balance = address(this).balance;
        if (balance > 0) {
            (bool success, ) = msg.sender.call{value: balance}("");
            if (!success) {
                revert EtherTransferFailed();
            }
        }
        emit MisplacedEtherWithdrawn(msg.sender, balance);
    }

    function withdrawMisplacedTokens(address tokenContractAddress) external onlyHub {
        if (tokenContractAddress == address(tokenContract)) {
            revert InvalidTokenContract(tokenContractAddress);
        }
        IERC20 misplacedTokensContract = IERC20(tokenContractAddress);

        uint256 balance = misplacedTokensContract.balanceOf(address(this));
        if (balance > 0) {
            bool transactionResult = misplacedTokensContract.transfer(msg.sender, balance);
            if (!transactionResult) {
                revert TokenTransferFailed();
            }
        }
        emit MisplacedERC20Withdrawn(msg.sender, tokenContractAddress, balance);
    }
}

contracts/Identity.sol.content:
// SPDX-License-Identifier: Apache-2.0

pragma solidity ^0.8.20;

import {IdentityStorage} from "./storage/IdentityStorage.sol";
import {ContractStatus} from "./abstract/ContractStatus.sol";
import {IInitializable} from "./interfaces/IInitializable.sol";
import {INamed} from "./interfaces/INamed.sol";
import {IVersioned} from "./interfaces/IVersioned.sol";
import {IdentityLib} from "./libraries/IdentityLib.sol";

contract Identity is INamed, IVersioned, ContractStatus, IInitializable {
    event IdentityCreated(uint72 indexed identityId, bytes32 indexed operationalKey, bytes32 indexed adminKey);
    event IdentityDeleted(uint72 indexed identityId);

    string private constant _NAME = "Identity";
    // Version history:
    //   1.0.0 — initial release.
    //   1.1.0 — `addOperationalWallets` now disambiguates same-identity
    //           collisions (primary added by `createIdentity` OR intra-
    //           array duplicate within the same call) from cross-identity
    //           collisions via the new `OperationalWalletDuplicate(wallet)`
    //           error. `OperationalKeyTaken(key)` remains reserved for
    //           the cross-identity case. Dropped the dead `KeyIsEmpty()`
    //           pre-check (impossible after the zero-address check).
    string private constant _VERSION = "10.0.2";

    IdentityStorage public identityStorage;

    // solhint-disable-next-line no-empty-blocks
    constructor(address hubAddress) ContractStatus(hubAddress) {}

    modifier onlyAdmin(uint72 identityId) {
        _checkAdmin(identityId);
        _;
    }

    function initialize() public onlyHub {
        identityStorage = IdentityStorage(hub.getContractAddress("IdentityStorage"));
    }

    function name() external pure virtual override returns (string memory) {
        return _NAME;
    }

    function version() external pure virtual override returns (string memory) {
        return _VERSION;
    }

    function createIdentity(address operational, address admin) external onlyContracts returns (uint72) {
        if (operational == address(0)) {
            revert IdentityLib.OperationalAddressZero();
        }
        if (admin == address(0)) {
            revert IdentityLib.AdminAddressZero();
        }
        if (admin == operational) {
            revert IdentityLib.AdminEqualsOperational();
        }

        IdentityStorage ids = identityStorage;

        uint72 identityId = ids.generateIdentityId();

        bytes32 adminKey = keccak256(abi.encodePacked(admin));
        ids.addKey(identityId, adminKey, IdentityLib.ADMIN_KEY, IdentityLib.ECDSA);

        bytes32 operationalKey = keccak256(abi.encodePacked(operational));
        ids.addKey(identityId, operationalKey, IdentityLib.OPERATIONAL_KEY, IdentityLib.ECDSA);

        ids.setOperationalKeyIdentityId(operationalKey, identityId);

        emit IdentityCreated(identityId, operationalKey, adminKey);

        return identityId;
    }

    function deleteIdentity(uint72 identityId) external onlyContracts {
        identityStorage.deleteIdentity(identityId);

        emit IdentityDeleted(identityId);
    }

    function addKey(
        uint72 identityId,
        bytes32 key,
        uint256 keyPurpose,
        uint256 keyType
    ) external onlyAdmin(identityId) {
        if (key == bytes32(0)) {
            revert IdentityLib.KeyIsEmpty();
        }

        IdentityStorage ids = identityStorage;

        if (keyPurpose == IdentityLib.OPERATIONAL_KEY) {
            if (ids.identityIds(key) != 0) {
                revert IdentityLib.OperationalKeyTaken(key);
            }
            ids.setOperationalKeyIdentityId(key, identityId);
        }

        bytes32 attachedKey;
        (, , attachedKey) = ids.getKey(identityId, key);
        if (attachedKey == key) {
            revert IdentityLib.KeyAlreadyAttached(key);
        }

        ids.addKey(identityId, key, keyPurpose, keyType);
    }

    function removeKey(uint72 identityId, bytes32 key) external onlyAdmin(identityId) {
        if (key == bytes32(0)) {
            revert IdentityLib.KeyIsEmpty();
        }

        IdentityStorage ids = identityStorage;

        uint256 purpose;
        bytes32 attachedKey;
        (purpose, , attachedKey) = ids.getKey(identityId, key);
        if (attachedKey != key) {
            revert IdentityLib.KeyNotAttached(key);
        }

        if (
            ids.getKeysByPurpose(identityId, IdentityLib.ADMIN_KEY).length == 1 &&
            ids.keyHasPurpose(identityId, key, IdentityLib.ADMIN_KEY)
        ) {
            revert IdentityLib.CannotDeleteOnlyAdminKey(identityId);
        }

        if (
            ids.getKeysByPurpose(identityId, IdentityLib.OPERATIONAL_KEY).length == 1 &&
            ids.keyHasPurpose(identityId, key, IdentityLib.OPERATIONAL_KEY)
        ) {
            revert IdentityLib.CannotDeleteOnlyOperationalKey(identityId);
        }

        ids.removeKey(identityId, key);

        if (purpose == IdentityLib.OPERATIONAL_KEY) {
            ids.removeOperationalKeyIdentityId(key);
        }
    }

    function addOperationalWallets(uint72 identityId, address[] calldata operationalWallets) external onlyContracts {
        IdentityStorage ids = identityStorage;

        bytes32 operationalKey;
        bytes32 attachedKey;
        uint72 existingId;

        for (uint256 i; i < operationalWallets.length; ) {
            if (operationalWallets[i] == address(0)) {
                revert IdentityLib.OperationalAddressZero();
            }

            operationalKey = keccak256(abi.encodePacked(operationalWallets[i]));

            existingId = ids.identityIds(operationalKey);
            // Same-identity collision: either the wallet was attached as
            // the primary op key by `createIdentity` (the createProfile
            // entrypoint passes `msg.sender` to that, then the same
            // address inside `operationalWallets` reaches us here), or
            // it was added by an earlier iteration of this same loop
            // (intra-array duplicate). Both surface as
            // `OperationalWalletDuplicate(wallet)` so callers don't
            // confuse them with the cross-identity collision below.
            if (existingId == identityId) {
                revert IdentityLib.OperationalWalletDuplicate(operationalWallets[i]);
            }
            if (existingId != 0) {
                revert IdentityLib.OperationalKeyTaken(operationalKey);
            }

            ids.setOperationalKeyIdentityId(operationalKey, identityId);

            (, , attachedKey) = ids.getKey(identityId, operationalKey);
            // Defensive: the key is already attached with some purpose
            // (admin OR operational). On the createProfile path this
            // fires when an op-wallet entry equals `adminWallet` — the
            // key was attached as `ADMIN_KEY` by `createIdentity` and
            // would now be attached again as `OPERATIONAL_KEY`. The
            // surfaced error is `KeyAlreadyAttached(key)`; admin/
            // operational wallet reuse is a deliberate operator choice
            // and stays un-policed beyond this attachment check.
            if (attachedKey == operationalKey) {
                revert IdentityLib.KeyAlreadyAttached(operationalKey);
            }

            ids.addKey(identityId, operationalKey, IdentityLib.OPERATIONAL_KEY, IdentityLib.ECDSA);

            unchecked {
                i++;
            }
        }
    }

    function _checkAdmin(uint72 identityId) internal view virtual {
        if (
            !identityStorage.keyHasPurpose(identityId, keccak256(abi.encodePacked(msg.sender)), IdentityLib.ADMIN_KEY)
        ) {
            revert IdentityLib.AdminFunctionOnly(identityId, msg.sender);
        }
    }
}

