contracts/libraries/PublishingMathLib.so.content:
// SPDX-License-Identifier: Apache-2.0

pragma solidity ^0.8.20;

library PublishingMathLib {
    struct ActiveSinkRange {
        uint40 startEpoch;
        uint40 endEpoch;
        uint96 tokenAmount;
    }

    function discountBps(uint96 committedTRAC) internal pure returns (uint256) {
        if (committedTRAC >= 1_000_000 ether) return 7500;
        if (committedTRAC >= 500_000 ether)   return 5000;
        if (committedTRAC >= 250_000 ether)   return 4000;
        if (committedTRAC >= 100_000 ether)   return 3000;
        if (committedTRAC >= 50_000 ether)    return 2000;
        if (committedTRAC >= 25_000 ether)    return 1000;
        return 0;
    }

    function prorateActiveSink(
        uint96 tokenAmount,
        uint40 currentEpoch,
        uint256 epochs,
        uint256 epochLengthInSeconds,
        uint256 timeRemainingInCurrentEpoch
    ) internal pure returns (ActiveSinkRange[3] memory ranges) {
        uint256 baseTokensPerFullEpoch = tokenAmount / epochs;
        uint256 currentEpochAllocation = (baseTokensPerFullEpoch * timeRemainingInCurrentEpoch) / epochLengthInSeconds;
        uint256 finalEpochAllocation = baseTokensPerFullEpoch - currentEpochAllocation;
        uint256 numberOfFullEpochs = epochs - 1;
        uint256 totalTokensForFullEpochs = baseTokensPerFullEpoch * numberOfFullEpochs;
        uint256 totalAllocated = currentEpochAllocation + totalTokensForFullEpochs + finalEpochAllocation;
        if (totalAllocated < tokenAmount) {
            finalEpochAllocation += tokenAmount - totalAllocated;
        }

        if (currentEpochAllocation > 0) {
            ranges[0] = ActiveSinkRange({
                startEpoch: currentEpoch,
                endEpoch: currentEpoch,
                tokenAmount: uint96(currentEpochAllocation)
            });
        }
        if (numberOfFullEpochs > 0 && totalTokensForFullEpochs > 0) {
            ranges[1] = ActiveSinkRange({
                startEpoch: currentEpoch + 1,
                endEpoch: currentEpoch + uint40(numberOfFullEpochs),
                tokenAmount: uint96(totalTokensForFullEpochs)
            });
        }
        if (finalEpochAllocation > 0) {
            ranges[2] = ActiveSinkRange({
                startEpoch: currentEpoch + uint40(epochs),
                endEpoch: currentEpoch + uint40(epochs),
                tokenAmount: uint96(finalEpochAllocation)
            });
        }
    }
}

contracts/libraries/RandomSamplingLib.so.content:
// SPDX-License-Identifier: Apache-2.0

pragma solidity ^0.8.20;

library RandomSamplingLib {
    struct Challenge {
        uint256 knowledgeAssetId;
        uint256 chunkId; // TODO:Smaller data structure
        address knowledgeAssetStorageContract;
        uint256 epoch;
        uint256 activeProofPeriodStartBlock;
        uint256 proofingPeriodDurationInBlocks;
        bool solved;
        // OT-RFC-43 / R3 — curation classification PINNED at issuance. Recorded
        // here (alongside `knowledgeAssetStorageContract`) so `submitProof`
        // verifies against the SAME (root, count) branch the challenge was drawn
        // against, instead of re-deriving it from the live `ContextGraphStorage`
        // singleton — which a generation cutover could re-point, misclassifying
        // an older curated challenge as public. Packs into the `solved` slot.
        bool isCurated;
        // OT-RFC-49 / WS-B Trap 1 (proof-race) — the (leafCount, root) pair PINNED
        // at issuance. `submitProof` verifies against THESE snapshotted values
        // instead of re-reading `getLatest*Root`/`get*Count` live, so a KA update
        // landing between `createChallenge` and `submitProof` can no longer rotate
        // the challenge surface out from under an honest prover (which would lose
        // stake). `challengeLeafCount` (uint32) packs into the `solved`/`isCurated`
        // slot's remaining 30 bytes; `challengeRoot` takes a fresh slot. Resolved
        // from the SAME curated/public branch the draw used:
        // curated → (getCatalogLeafCount, getCatalogRoot);
        // public  → (getMerkleLeafCount, getLatestMerkleRoot).
        uint32 challengeLeafCount;
        bytes32 challengeRoot;
    }

    struct ProofPeriodStatus {
        uint256 activeProofPeriodStartBlock;
        bool isValid;
    }

    struct ProofingPeriodDuration {
        uint16 durationInBlocks;
        uint256 effectiveEpoch;
    }
}

