            if (i >= len) break;
            uint256 ka = contextGraphStorage.getSamplingKaAt(cgId, i);
            if (knowledgeAssetStorage.getEndEpoch(ka) < currentEpoch) {
                // swap-pops the last element into i, so re-check i (do not advance).
                contextGraphStorage.swapRemoveSamplingKnowledgeAssetAt(cgId, i, ka);
                removed++;
            } else {
                i++;
            }
        }
    }

    // slither-disable-end weak-prng,uninitialized-local,cyclomatic-complexity,incorrect-equality,calls-loop,timestamp

    // NOTE: the legacy `_isInExhaustedList` / `_isCGEligible` helpers were removed with the
    // BIT integration. Exhaustion is now the in-memory `exhausted` set passed to
    // CGWeightTreeStorage.findStrictGtExcluding; eligibility is verified on the DRAWN CG in
    // `_pickKa` (1 SLOAD, not the O(N) scan) — a deactivated CG is treated as a miss.

    /**
     * @dev Calculates the node score based on stake, publishing activity, and ask alignment
     * Implements anti-sybil multiplicative score formula (RFC-26 update)
     *
     * Formula: nodeScore(t) = S(t) * (c + 0.86 * P(t) + 0.60 * A(t) * P(t))
     *
     * Where:
     * - S(t) = sqrt(nodeEffectiveStake / STAKE_CAP) - sublinear conviction stake scaling
     * - P(t) = K_n / K_total - publishing share over 4 epochs (t-3, t-2, t-1, t)
     * - A(t) = 1 - |nodeAsk - networkPrice| / networkPrice - ask alignment factor
     * - c = 0.002 (STAKE_BASELINE_COEFFICIENT) - small baseline for staked non-publishers
     *
     * The multiplicative structure ensures stake amplifies contribution rather than
     * providing an unconditional reward floor. The small c coefficient preserves a
     * minimal incentive for staking even without publishing, preventing a hard cliff
     * while making sybil extraction economically unattractive.
     *
     * All calculations use 18-decimal precision for accuracy
     * @param identityId The node identity to calculate score for
     * @return score18 The calculated node score scaled by 18-decimal for precision
     */
    function calculateNodeScore(uint72 identityId) public view returns (uint256) {
        return _calculateNodeScore(identityId, convictionStakingStorage.getNodeEffectiveStake(identityId));
    }

    // Slither: score math uses fixed-point integer ratios deliberately; epoch
    // storage reads are over a bounded four-epoch window.
    // slither-disable-start divide-before-multiply,calls-loop
    function _calculateNodeScore(uint72 identityId, uint256 nodeEffectiveStake) internal view returns (uint256) {
        uint256 currentEpoch = chronos.getCurrentEpoch();

        // 1. Stake factor S(t) = sqrt(nodeEffectiveStake / stakeCap)
        // Using sublinear scaling to reduce stake dominance (RFC-26 Section 4.1)
        //
        // D15/D26 — post-migration the node's scoring stake is V10 effective
        // stake: raw TRAC multiplied by active conviction multipliers and
        // timestamp-adjusted for expired boosts. Migration is mandatory (user
        // directive), so V8 `StakingStorage.nodes[id].stake` is legacy-only.
        uint256 stakeCap = uint256(parametersStorage.maximumStake());
        nodeEffectiveStake = nodeEffectiveStake > stakeCap ? stakeCap : nodeEffectiveStake;
        // S18 = sqrt((nodeEffectiveStake / stakeCap) * SCALE18) * sqrt(SCALE18)
        uint256 stakeRatio18 = (nodeEffectiveStake * SCALE18) / stakeCap;
        uint256 stakeFactor18 = Math.sqrt(stakeRatio18 * SCALE18);

        // 2. Publishing factor P(t) = K_n / K_total (RFC-26 Section 4.2,
        //    re-based by OT-RFC-51 "Publishing Allocation").
        //
        //    OT-RFC-51: the publishing factor is now fed by COMMITTED PCA
        //    "publishing allocation" rather than realized publishing, over a
        //    single (current-epoch) window instead of the prior 4-epoch sum.
        //    `K_n` = the current epoch's allocation seeded to this node by
        //    its designated PCAs; `K_total` = the network-wide current-epoch
        //    allocation. Coefficients / S(t) / A(t) below are unchanged.
        uint256 nodeKV = epochStorage.getNodeEpochPublishingAllocation(identityId, currentEpoch);
        uint256 totalKV = epochStorage.getEpochPublishingAllocation(currentEpoch);
        uint256 publishingFactor18 = totalKV > 0 ? (nodeKV * SCALE18) / totalKV : 0;

        // 3. Ask alignment factor A(t) = 1 - |nodeAsk - networkPrice| / networkPrice (RFC-26 Section 4.3)
        // Rewards nodes whose ask is close to the network reference price:
        // - Perfect alignment (deviation = 0): A(t) = 1.0 (maximum bonus)
        // - 50% deviation: A(t) = 0.5
        // - 100%+ deviation: A(t) = 0.0 (no bonus, capped to avoid negative values)
        uint256 nodeAsk = uint256(profileStorage.getAsk(identityId));
        uint256 networkPrice = askStorage.getPricePerKbEpoch();
        uint256 askAlignmentFactor18 = 0;
        if (networkPrice > 0) {
            uint256 deviation = nodeAsk > networkPrice ? nodeAsk - networkPrice : networkPrice - nodeAsk;
            uint256 deviationRatio18 = (deviation * SCALE18) / networkPrice;
            askAlignmentFactor18 = deviationRatio18 >= SCALE18 ? 0 : SCALE18 - deviationRatio18;
        }

        // nodeScore(t) = S(t) * (c + 0.86 * P(t) + 0.60 * A(t) * P(t))
        // c = 0.002 = 2/1000 (STAKE_BASELINE_COEFFICIENT)
        // Coefficients: 0.86 = 86/100, 0.60 = 60/100
        uint256 baselineComponent18 = (2 * SCALE18) / 1000;
        uint256 publishingComponent18 = (86 * publishingFactor18) / 100;
        uint256 askPublishingComponent18 = (60 * askAlignmentFactor18 * publishingFactor18) / (100 * SCALE18);

        uint256 innerScore18 = baselineComponent18 + publishingComponent18 + askPublishingComponent18;
        return (stakeFactor18 * innerScore18) / SCALE18;
    }
    // slither-disable-end divide-before-multiply,calls-loop

    /**
     * @dev Updates and returns the current active proof period start block
     * Automatically advances to the next period if the current one has ended
     * @return Current active proof period start block number
     */
    // Slither: divide-then-multiply intentionally floors to the latest complete
    // proof period boundary.
    // slither-disable-next-line divide-before-multiply
    function updateAndGetActiveProofPeriodStartBlock() public returns (uint256) {
        uint256 activeProofingPeriodDurationInBlocks = getActiveProofingPeriodDurationInBlocks();

        if (activeProofingPeriodDurationInBlocks == 0) {
            revert("Active proofing period duration in blocks should not be 0");
        }

        uint256 activeProofPeriodStartBlock = randomSamplingStorage.getActiveProofPeriodStartBlock();

        if (block.number > activeProofPeriodStartBlock + activeProofingPeriodDurationInBlocks - 1) {
            // Calculate how many complete periods have passed since the last active period started
            uint256 blocksSinceLastStart = block.number - activeProofPeriodStartBlock;
            uint256 completePeriodsPassed = blocksSinceLastStart / activeProofingPeriodDurationInBlocks;

            uint256 newActiveProofPeriodStartBlock = activeProofPeriodStartBlock +
                completePeriodsPassed *
                activeProofingPeriodDurationInBlocks;

            randomSamplingStorage.setActiveProofPeriodStartBlock(newActiveProofPeriodStartBlock);

            return newActiveProofPeriodStartBlock;
        }

        return activeProofPeriodStartBlock;
    }

    /**
     * @dev Returns the status of the current active proof period including start block and whether it's still active
     * @return ProofPeriodStatus struct containing start block and active status
     */
    function getActiveProofPeriodStatus() external view returns (RandomSamplingLib.ProofPeriodStatus memory) {
        uint256 activeProofPeriodStartBlock = randomSamplingStorage.getActiveProofPeriodStartBlock();
        return
            RandomSamplingLib.ProofPeriodStatus(
                activeProofPeriodStartBlock,
                block.number < activeProofPeriodStartBlock + getActiveProofingPeriodDurationInBlocks()
            );
    }

    /**
     * @dev Calculates the start block of a historical proof period based on current period and offset
     * Used to determine proof periods from the past for validation purposes
     * @param proofPeriodStartBlock Start block of a valid proof period (must be > 0 and aligned to period boundaries)
     * @param offset Number of periods to go back (must be > 0)
     * @return Start block of the historical proof period
     */
    function getHistoricalProofPeriodStartBlock(
        uint256 proofPeriodStartBlock,
        uint256 offset
    ) external view returns (uint256) {
        require(proofPeriodStartBlock > 0, "Proof period start block must be greater than 0");
        require(
            proofPeriodStartBlock % getActiveProofingPeriodDurationInBlocks() == 0,
            "Proof period start block is not valid"
        );
        require(offset > 0, "Offset must be greater than 0");
        return proofPeriodStartBlock - offset * getActiveProofingPeriodDurationInBlocks();
    }

    /**
     * @dev Returns the currently active proofing period duration in blocks
     * Automatically selects the appropriate duration based on current epoch
     * @return Duration in blocks of the currently active proofing period
     */
    function getActiveProofingPeriodDurationInBlocks() public view returns (uint16) {
        return randomSamplingStorage.getEpochProofingPeriodDurationInBlocks(chronos.getCurrentEpoch());
    }

    /**
     * @dev Internal function to validate that a node profile exists
     * Used by modifiers and functions to ensure operations target valid nodes
     * Reverts with ProfileDoesntExist error if profile is not found
     * @param identityId Node identity to check existence for
     */
    function _checkProfileExists(uint72 identityId) internal view virtual {
        if (!profileStorage.profileExists(identityId)) {
            revert ProfileLib.ProfileDoesntExist(identityId);
        }
    }

    /**
     * @dev Internal function to validate that a node exists in the sharding table
     * Used by modifiers and functions to ensure operations target valid nodes
     * Reverts with NodeDoesntExist error if node is not found
     * @param identityId Node identity to check existence for
     */
    function _checkNodeExistsInShardingTable(uint72 identityId) internal view virtual {
        if (!shardingTableStorage.nodeExists(identityId)) {
            revert("Node does not exist in sharding table");
        }
    }

    function _isMultiSigOwner(address multiSigAddress) internal view returns (bool) {
        try ICustodian(multiSigAddress).getOwners() returns (address[] memory multiSigOwners) {
            for (uint256 i = 0; i < multiSigOwners.length; i++) {
                if (msg.sender == multiSigOwners[i]) {
                    return true;
                }
            }
        } catch {
            // Not a multisig or call reverted; treat as not owner.
        }

        return false;
    }

    function _checkOwnerOrMultiSigOwner() internal view virtual {
        address hubOwner = hub.owner();
        if (msg.sender != hubOwner && !_isMultiSigOwner(hubOwner)) {
            revert HubLib.UnauthorizedAccess("Only Hub Owner or Multisig Owner");
        }
    }
}

contracts/ShardingTable.sol.content:
// SPDX-License-Identifier: Apache-2.0

pragma solidity ^0.8.20;

import {ProfileStorage} from "./storage/ProfileStorage.sol";
import {ShardingTableStorage} from "./storage/ShardingTableStorage.sol";
import {ConvictionStakingStorage} from "./storage/ConvictionStakingStorage.sol";
import {ParametersStorage} from "./storage/ParametersStorage.sol";
import {ContractStatus} from "./abstract/ContractStatus.sol";
import {IInitializable} from "./interfaces/IInitializable.sol";
import {INamed} from "./interfaces/INamed.sol";
import {IVersioned} from "./interfaces/IVersioned.sol";
import {ShardingTableLib} from "./libraries/ShardingTableLib.sol";

contract ShardingTable is INamed, IVersioned, ContractStatus, IInitializable {
    string private constant _NAME = "ShardingTable";
    // v2.0.0 — ABI-breaking: dropped the V8→V9 `migrationPeriodEnd` field
    // and its constructor parameter, plus the matching public getter.
    // Original purpose: gate the `migrateOldShardingTable` Neuroweb-only
    // function set during the old ShardingTable migration window. That
    // function was removed during the V9→V10 consolidation, leaving the
    // field as dead state on a Logic contract — a violation of the
    // Storage/Logic separation pattern. The Neuroweb-only branch in
    // `019_deploy_sharding_table.ts` that referenced `migrateOldShardingTable`
    // is removed in the same PR (the function it called no longer exists,
    // so the branch was already unreachable on V10 deploys).
    string private constant _VERSION = "10.0.3";

    ProfileStorage public profileStorage;
    ShardingTableStorage public shardingTableStorage;
    /// @notice v4.0.0 — V10 canonical node stake source. Replaces the prior
    ///         `stakingStorage` reference; the V8 archive is unmaintained
    ///         post-migration so its `getNodeStake` is not a faithful read.
    ConvictionStakingStorage public convictionStakingStorage;

    /// @notice The sharding table is full: `nodesCount` has reached the
    ///         governance-configured `shardingTableSizeLimit`. The cap bounds
    ///         the O(n) re-index loops in `insertNode`/`removeNode` so they
    ///         cannot exceed the block gas limit.
    error ShardingTableIsFull(uint72 nodesCount, uint16 sizeLimit);

    // solhint-disable-next-line no-empty-blocks
    constructor(address hubAddress) ContractStatus(hubAddress) {}

    function initialize() public onlyHub {
        profileStorage = ProfileStorage(hub.getContractAddress("ProfileStorage"));
        shardingTableStorage = ShardingTableStorage(hub.getContractAddress("ShardingTableStorage"));
        convictionStakingStorage = ConvictionStakingStorage(hub.getContractAddress("ConvictionStakingStorage"));
    }

    function name() external pure virtual override returns (string memory) {
        return _NAME;
    }

    function version() external pure virtual override returns (string memory) {
        return _VERSION;
    }

    function getShardingTable(
        uint72 startingIdentityId,
        uint72 nodesNumber
    ) external view returns (ShardingTableLib.NodeInfo[] memory) {
        return _getShardingTable(startingIdentityId, nodesNumber);
    }

    function getShardingTable() external view returns (ShardingTableLib.NodeInfo[] memory) {
        ShardingTableStorage sts = shardingTableStorage;
        return _getShardingTable(sts.indexToIdentityId(0), sts.nodesCount());
    }

    function insertNode(uint72 identityId) external onlyContracts {
        uint256 newNodeHashRingPosition = uint256(sha256(profileStorage.getNodeId(identityId)));

        _insertNode(_binarySearchForIndex(newNodeHashRingPosition), identityId, newNodeHashRingPosition);
    }

    function insertNode(uint72 index, uint72 identityId) external onlyContracts {
        _insertNode(index, identityId, uint256(sha256(profileStorage.getNodeId(identityId))));
    }

    function removeNode(uint72 identityId) external onlyContracts {
        ShardingTableStorage sts = shardingTableStorage;

        ShardingTableLib.Node memory nodeToRemove = sts.getNode(identityId);

        // Decrement indexes of all nodes after removed one + add pointers to identityId for changed indexes
        uint72 index = nodeToRemove.index;
        uint72 nextIdentityId = sts.indexToIdentityId(nodeToRemove.index + 1);
        while (nextIdentityId != ShardingTableLib.NULL) {
            sts.decrementNodeIndex(nextIdentityId);
            sts.setIdentityId(index, nextIdentityId);

            unchecked {
                index += 1;
            }

            nextIdentityId = sts.indexToIdentityId(index + 1);
        }

        // Delete node object + set last index pointer to be ShardingTableLib.NULL + decrement total nodes count
        sts.deleteNodeObject(identityId);
        sts.setIdentityId(index, ShardingTableLib.NULL);
        sts.decrementNodesCount();
    }

    function _binarySearchForIndex(uint256 hashRingPosition) internal virtual returns (uint72) {
        ShardingTableStorage sts = shardingTableStorage;

        uint72 nodesCount = sts.nodesCount();

        if (nodesCount == 0) {
            return 0;
        }

        uint72 left;
        uint72 mid;
        uint72 right = nodesCount - 1;

        while (left <= right) {
            mid = (left + right) / 2;
            uint256 currentHashRingPosition = sts.getHashRingPositionByIndex(mid);

            if (hashRingPosition > currentHashRingPosition) {
                // Node is in the right half of the range, move left pointers
                left = mid + 1;
            } else if (hashRingPosition < currentHashRingPosition) {
                if (mid == 0) {
                    // The new element should be inserted at index 0
                    return 0;
                }
                // Node is in the left half of the range, move right pointers
                right = mid - 1;
            } else {
                // Exact match found
                return mid;
            }
        }

        return left;
    }

    function _insertNode(uint72 index, uint72 identityId, uint256 newNodeHashRingPosition) internal virtual {
        ShardingTableStorage sts = shardingTableStorage;
        ProfileStorage ps = profileStorage;

        // SECURITY FIX: enforce the configured size cap. `shardingTableSizeLimit`
        // (default 500) had a setter but was checked at NO insert site, so the
        // table could grow without bound — making the O(n) re-index loops in
        // insertNode/removeNode (both walk every node after the touched index)
        // exceed the block gas limit, which freezes unstake/redelegate/leave
        // and any other op that re-indexes the table. ParametersStorage is
        // resolved from the Hub at call time (it is deployed AFTER ShardingTable,
        // so it cannot be cached in initialize() without breaking deployment).
        uint72 nodesCount = sts.nodesCount();
        uint16 sizeLimit = ParametersStorage(hub.getContractAddress("ParametersStorage")).shardingTableSizeLimit();
        if (nodesCount >= sizeLimit) {
            revert ShardingTableIsFull(nodesCount, sizeLimit);
        }

        if (sts.nodeExists(identityId)) {
            revert ShardingTableLib.NodeAlreadyInTheShardingTable(identityId);
        }

        if (index != 0) {
            uint256 prevNodeHashRingPosition = sts.getHashRingPositionByIndex(index - 1);

            // Check that the new Node is indeed on the right from the prevNode
            // Also allows new Head insertion as prevNode.hashRingPosition will be 0 in such case
            if (newNodeHashRingPosition < prevNodeHashRingPosition) {
                revert ShardingTableLib.InvalidIndexWithRespectToPreviousNode(
                    identityId,
                    newNodeHashRingPosition,
                    prevNodeHashRingPosition
                );
            }
        }

        ShardingTableLib.Node memory nextNode = sts.getNodeByIndex(index);

        // Check that the new Node is indeed on the left from the nextNode
        // Check is skipped when inserting new Tail
        if (nextNode.identityId != ShardingTableLib.NULL && newNodeHashRingPosition > nextNode.hashRingPosition) {
            revert ShardingTableLib.InvalidIndexWithRespectToNextNode(
                identityId,
                newNodeHashRingPosition,
                nextNode.hashRingPosition
            );
        }
        // Create node object + set index pointer to new identityId + increment total nodes count
        sts.createNodeObject(newNodeHashRingPosition, ps.getNodeId(identityId), identityId, index);
        sts.setIdentityId(index, identityId);
        sts.incrementNodesCount();

        // Increment indexes of all nodes after inserted one + add pointers to identityId for changed indexes
        uint72 currentIdentityId;
        uint72 nextIdentityId = nextNode.identityId;
        while (nextIdentityId != ShardingTableLib.NULL) {
            unchecked {
                index += 1;
            }

            currentIdentityId = nextIdentityId;
            nextIdentityId = sts.indexToIdentityId(index);

            sts.incrementNodeIndex(currentIdentityId);
            sts.setIdentityId(index, currentIdentityId);
        }
    }

    function _getShardingTable(
        uint72 startingIdentityId,
        uint72 nodesNumber
    ) internal view virtual returns (ShardingTableLib.NodeInfo[] memory) {
        ShardingTableLib.NodeInfo[] memory nodesPage;
        ShardingTableStorage sts = shardingTableStorage;

        if ((sts.nodesCount() == 0) || (nodesNumber == 0)) {
            return nodesPage;
        }
        ShardingTableLib.Node memory startingNode = sts.getNode(startingIdentityId);

        if (startingIdentityId == ShardingTableLib.NULL || startingNode.identityId == ShardingTableLib.NULL) {
            revert ShardingTableLib.InvalidStartingIdentityId(startingIdentityId);
        }

        nodesPage = new ShardingTableLib.NodeInfo[](nodesNumber);

        ProfileStorage ps = profileStorage;
        ConvictionStakingStorage cs = convictionStakingStorage;

        uint72 nextIdentityId = startingIdentityId;
        uint72 index;
        while ((index < nodesNumber) && (nextIdentityId != ShardingTableLib.NULL)) {
            // v4.0.0 — V10 canonical node stake. Down-cast to uint96 is safe
            // under protocol invariants: `StakingV10.stake` enforces
            // `nodeStakeV10 <= parametersStorage.maximumStake()` (uint96), and
            // the V10 raw stake field cannot exceed the cap.
            uint256 stake256 = cs.getNodeStakeV10(nextIdentityId);
            uint96 stakeView = stake256 > type(uint96).max ? type(uint96).max : uint96(stake256);
            nodesPage[index] = ShardingTableLib.NodeInfo({
                nodeId: ps.getNodeId(nextIdentityId),
                identityId: nextIdentityId,
                ask: ps.getAsk(nextIdentityId),
                stake: stakeView
            });

            unchecked {
                index += 1;
            }
            nextIdentityId = sts.indexToIdentityId(index + startingNode.index);
        }

        return nodesPage;
    }
}

contracts/StakingKPI.sol.content:
// SPDX-License-Identifier: Apache-2.0

pragma solidity ^0.8.20;

import {IdentityStorage} from "./storage/IdentityStorage.sol";
import {ProfileStorage} from "./storage/ProfileStorage.sol";
import {StakingStorage} from "./storage/StakingStorage.sol";
import {ConvictionStakingStorage} from "./storage/ConvictionStakingStorage.sol";
import {Chronos} from "./storage/Chronos.sol";
import {ContractStatus} from "./abstract/ContractStatus.sol";
import {IInitializable} from "./interfaces/IInitializable.sol";
import {INamed} from "./interfaces/INamed.sol";
import {IVersioned} from "./interfaces/IVersioned.sol";
import {ProfileLib} from "./libraries/ProfileLib.sol";
import {IdentityLib} from "./libraries/IdentityLib.sol";
import {EpochStorage} from "./storage/EpochStorage.sol";
import {RandomSamplingStorage} from "./storage/RandomSamplingStorage.sol";
import {ParametersStorage} from "./storage/ParametersStorage.sol";

contract StakingKPI is INamed, IVersioned, ContractStatus, IInitializable {
    string private constant _NAME = "StakingKPI";
    // Version history:
    //   1.0.0 — initial KPI surface (V8 stake-base + node aggregates).
    //   2.0.0 — v4.0.0 storage consolidation: node-level reads
    //           (`getNodeStats`, `getOperatorFeeStats`) switched to CSS
    //           (`getNodeStakeV10`, `getOperatorFeeBalance`) so V10 nodes
    //           report non-zero stake and fee balance. Per-delegator
    //           reads (`getOperatorStats`, `getDelegatorStats`, the reward
    //           simulator) remain V8 stake-base keyed; they are accurate for
    //           V8 archive queries but return 0 for V10 nodes. A V10
    //           tokenId-keyed equivalent is a separate follow-up PR.
    string private constant _VERSION = "10.0.2";
    uint256 public constant SCALE18 = 1e18;

    IdentityStorage public identityStorage;
    ProfileStorage public profileStorage;
    /// @notice V8 archive accessor. Retained ONLY for V8-stake-base-keyed
    ///         per-delegator KPI reads (`getOperatorStats`,
    ///         `getDelegatorStats`, `_simulatePrepareForStakeChange`).
    ///         These are accurate for V8 archive queries but return 0 for
    ///         V10 nodes (mandatory migration → V8 stake base unmaintained).
    ///         A V10 tokenId-keyed per-delegator KPI is deferred to a
    ///         follow-up PR.
    StakingStorage public stakingStorage;
    /// @notice v4.0.0 — V10 canonical aggregates (node stake, operator-fee
    ///         balance, per-epoch reward flags). Source of truth for the
    ///         node-level KPI surface.
    ConvictionStakingStorage public convictionStakingStorage;
    Chronos public chronos;
    RandomSamplingStorage public randomSamplingStorage;
    EpochStorage public epochStorage;
    ParametersStorage public parametersStorage;

    /**
     * @dev Initializes the StakingKPI contract with the Hub address for access control
     * Only called once during deployment
     * @param hubAddress Address of the Hub contract for access control and contract dependencies
     */
    constructor(address hubAddress) ContractStatus(hubAddress) {}

    modifier profileExists(uint72 identityId) {
        _checkProfileExists(identityId);
        _;
    }

    /**
     * @dev Initializes the contract by connecting to all required Hub storage dependencies
     * Called once during deployment to set up contract references for staking calculations
     * Only the Hub can call this function
     */
    function initialize() external onlyHub {
        identityStorage = IdentityStorage(hub.getContractAddress("IdentityStorage"));
        profileStorage = ProfileStorage(hub.getContractAddress("ProfileStorage"));
        stakingStorage = StakingStorage(hub.getContractAddress("StakingStorage"));
        convictionStakingStorage = ConvictionStakingStorage(hub.getContractAddress("ConvictionStakingStorage"));
        chronos = Chronos(hub.getContractAddress("Chronos"));
        randomSamplingStorage = RandomSamplingStorage(hub.getContractAddress("RandomSamplingStorage"));
        epochStorage = EpochStorage(hub.getContractAddress("EpochStorageV8"));
        parametersStorage = ParametersStorage(hub.getContractAddress("ParametersStorage"));
    }

    /**
     * @dev Returns the name of this contract for identification purposes
     * @return Contract name as a string
     */
    function name() external pure virtual override returns (string memory) {
        return _NAME;
    }

    /**
     * @dev Returns the version of this contract for compatibility tracking
     * @return Contract version as a string
     */
    function version() external pure virtual override returns (string memory) {
        return _VERSION;
    }

    /**
     * @dev Returns the total stake of all admin keys for a node.
     *
     * @notice DEPRECATED in V10 (v2.0.0): reads V8 stake base which is
     *         unmaintained for V10 nodes (mandatory migration). Returns 0
     *         for V10-only nodes. A V10 tokenId-keyed equivalent is deferred
     *         to a follow-up PR.
     * @param identityId Node's identity ID to get total stake for
     * @return Total stake of all admin keys for the node (V8 archive only)
     */
    function getOperatorStats(uint72 identityId) external view returns (uint96) {
        bytes32[] memory adminKeys = identityStorage.getKeysByPurpose(identityId, IdentityLib.ADMIN_KEY);

        uint96 totalStake;
        for (uint256 i; i < adminKeys.length; i++) {
            uint96 delegatorStakeBase = stakingStorage.getDelegatorStakeBase(identityId, adminKeys[i]);
            totalStake += delegatorStakeBase;
        }

        return totalStake;
    }

    /**
     * @dev Returns the total node stake (v4.0.0 — V10 canonical raw TRAC
     *      sum from `ConvictionStakingStorage.nodeStakeV10`).
     * @param identityId Node's identity ID to get total stake for
     * @return Total stake of the node (V10 canonical, uint96-clamped)
     */
    function getNodeStats(uint72 identityId) external view returns (uint96) {
        // Down-cast safe under protocol invariants: `StakingV10.stake`
        // enforces `nodeStakeV10 <= maximumStake` (uint96), and the V10
        // raw stake field cannot exceed the cap.
        uint256 stake256 = convictionStakingStorage.getNodeStakeV10(identityId);
        return stake256 > type(uint96).max ? type(uint96).max : uint96(stake256);
    }

    /**
     * @dev Returns the total node operator fee balance (v4.0.0 — read from
     *      `ConvictionStakingStorage`; V8 SS balance is no longer written
     *      by the V10 claim path).
     * @param identityId Node's identity ID to get total operator fee balance for
     * @return Total node operator fee balance
     */
    function getOperatorFeeStats(uint72 identityId) external view returns (uint96) {
        return convictionStakingStorage.getOperatorFeeBalance(identityId);
    }

    /**
     * @dev Returns the total stake of a node's delegator.
     *
     * @notice DEPRECATED in V10 (v2.0.0): V8 stake base is per-(identity,address)
     *         keyed, unmaintained for V10 nodes. Returns 0 for V10-only
     *         delegators. V10 stake is per-tokenId (NFT-keyed); a V10
     *         tokenId-keyed equivalent is deferred to a follow-up PR.
     * @param identityId Node's identity ID to get total stake for
     * @param delegator Delegator's address to get stake for
     * @return Total stake of the node's delegator (V8 archive only)
     */
    function getDelegatorStats(uint72 identityId, address delegator) external view returns (uint96) {
        bytes32 delegatorKey = keccak256(abi.encodePacked(delegator));
        return stakingStorage.getDelegatorStakeBase(identityId, delegatorKey);
    }

    /**
     * @dev Calculate the reward for a delegator in an epoch (correct only for the finalized epochs).
     *
     * @notice DEPRECATED in V10 (v2.0.0): the inner `_simulatePrepareForStakeChange`
     *         reads V8 stake base which is unmaintained for V10 nodes
     *         (mandatory migration). Returns 0 for V10 delegators because
     *         `stakeBase == 0` short-circuits the reward simulator. The
     *         V10 reward path lives on `StakingV10._claim` (compound-into-raw,
     *         per-NFT). A V10 tokenId-keyed reward KPI is deferred to a
     *         follow-up PR.
     *
     * @param identityId Node's identity ID that the delegator is delegating to
     * @param epoch Epoch number to calculate rewards for (must be finalized)
     * @param delegator Delegator's address to calculate rewards for
     * @return Reward amount for the delegator in the specified epoch (V8 archive only)
     */
    function getDelegatorReward(
        uint72 identityId,
        uint256 epoch,
        address delegator
    ) external view profileExists(identityId) returns (uint256) {
        // D13 — `DelegatorsInfo.isNodeDelegator` is V8 address-keyed and
        // unregistered in V10. Dropped here: KPI still returns 0 for a
        // non-delegator through `_simulatePrepareForStakeChange` (stakeBase
        // == 0 → early return 0), so the guard is redundant under the
        // frozen-V8 archive model. V10 per-NFT KPI lives elsewhere.

        bytes32 delegatorKey = keccak256(abi.encodePacked(delegator));

        uint256 delegatorScore18 = _simulatePrepareForStakeChange(epoch, identityId, delegatorKey);
        if (delegatorScore18 == 0) return 0;

        uint256 nodeScore18 = randomSamplingStorage.getNodeEpochScore(epoch, identityId);
        if (nodeScore18 == 0) return 0;

        // Calculate the final delegators rewards pool
        uint256 netNodeRewards = getNetNodeRewards(identityId, epoch);

        if (netNodeRewards == 0) return 0;

        return (delegatorScore18 * netNodeRewards) / nodeScore18;
    }

    /**
     * @dev Fetch the net rewards for all node's delegators in an epoch (rewards of node's delegators - operator fee)
     * Calculates the total rewards available to node's delegators after operator fees are deducted
     * Handles both cases: when operator fee has been claimed and when it hasn't
     * @param identityId Node's identity ID to get net rewards for
     * @param epoch Epoch number to calculate net rewards for
     * @return Net rewards available for distribution to the node's delegators in the epoch
     */
    function getNetNodeRewards(
        uint72 identityId,
        uint256 epoch
    ) public view profileExists(identityId) returns (uint256) {
        // D3+D13 — post-V10 these flags live on ConvictionStakingStorage.
        if (convictionStakingStorage.isOperatorFeeClaimedForEpoch(identityId, epoch)) {
            return convictionStakingStorage.netNodeEpochRewards(identityId, epoch);
        }

        uint256 nodeScore18 = randomSamplingStorage.getNodeEpochScore(epoch, identityId);
        if (nodeScore18 == 0) return 0;

        uint256 allNodesScore18 = randomSamplingStorage.getAllNodesEpochScore(epoch);
        if (allNodesScore18 == 0) return 0;

        uint256 epocRewardsPool = epochStorage.getEpochPool(1, epoch);
        if (epocRewardsPool == 0) return 0;

        uint256 totalNodeRewards = (epocRewardsPool * nodeScore18) / allNodesScore18;

        uint256 feePercentageForEpoch = profileStorage.getOperatorFeePercentageByTimestampReverse(
            identityId,
            chronos.timestampForEpoch(epoch + 1) - 1
        );
        uint96 operatorFeeAmount = uint96(
            (totalNodeRewards * feePercentageForEpoch) / parametersStorage.maxOperatorFee()
        );

        return totalNodeRewards - operatorFeeAmount;
    }

    /**
     * @dev Internal function to simulate preparing for stake change and calculate delegator score
     * Calculates what the delegator's score would be after settling all pending score changes
     * Used for reward calculations without actually updating storage state
     * @param epoch The epoch to simulate the stake change for
     * @param identityId The node identity ID the delegator is delegating to
     * @param delegatorKey The unique key identifying the delegator
     * @return delegatorScore18 The simulated delegator score after settling, scaled by 10^18
     */
    function _simulatePrepareForStakeChange(
        uint256 epoch,
        uint72 identityId,
        bytes32 delegatorKey
    ) internal view returns (uint256 delegatorScore18) {
        // 1. Current "score-per-stake"
        uint256 nodeScorePerStake36 = randomSamplingStorage.getNodeEpochScorePerStake(epoch, identityId);

        uint256 currentDelegatorScore18 = randomSamplingStorage.getEpochNodeDelegatorScore(
            epoch,
            identityId,
            delegatorKey
        );

        // 2. Last index at which this delegator was settled
        uint256 delegatorLastSettledNodeEpochScorePerStake36 = randomSamplingStorage
            .getDelegatorLastSettledNodeEpochScorePerStake(epoch, identityId, delegatorKey);

        // Nothing new to settle
        if (nodeScorePerStake36 == delegatorLastSettledNodeEpochScorePerStake36) {
            return currentDelegatorScore18;
        }

        uint96 stakeBase = stakingStorage.getDelegatorStakeBase(identityId, delegatorKey);

        // If the delegator has no stake, just bump the index and exit
        if (stakeBase == 0) {
            return currentDelegatorScore18;
        }
        // 4. Newly earned score for this delegator in the epoch
        uint256 diff36 = nodeScorePerStake36 - delegatorLastSettledNodeEpochScorePerStake36; // scaled 1e36
        uint256 scoreEarned18 = (uint256(stakeBase) * diff36) / SCALE18;

        return currentDelegatorScore18 + scoreEarned18;
    }

    /**
     * @dev Internal function to validate that a node profile exists
     * Used by modifiers and functions to ensure operations target valid nodes
     * Reverts with ProfileDoesntExist error if profile is not found
     * @param identityId Node identity ID to check existence for
     */
    function _checkProfileExists(uint72 identityId) internal view virtual {
        if (!profileStorage.profileExists(identityId)) {
            revert ProfileLib.ProfileDoesntExist(identityId);
        }
    }
}

contracts/StakingV10.sol.content:
// SPDX-License-Identifier: Apache-2.0

pragma solidity ^0.8.20;

import {ShardingTable} from "./ShardingTable.sol";
import {Ask} from "./Ask.sol";
import {ParametersStorage} from "./storage/ParametersStorage.sol";
import {ProfileStorage} from "./storage/ProfileStorage.sol";
import {ShardingTableStorage} from "./storage/ShardingTableStorage.sol";
import {StakingStorage} from "./storage/StakingStorage.sol";
import {ConvictionStakingStorage} from "./storage/ConvictionStakingStorage.sol";
import {IdentityStorage} from "./storage/IdentityStorage.sol";
import {RandomSamplingStorage} from "./storage/RandomSamplingStorage.sol";
import {EpochStorage} from "./storage/EpochStorage.sol";
import {Chronos} from "./storage/Chronos.sol";
import {ContractStatus} from "./abstract/ContractStatus.sol";
import {IInitializable} from "./interfaces/IInitializable.sol";
import {INamed} from "./interfaces/INamed.sol";
import {IVersioned} from "./interfaces/IVersioned.sol";
import {IdentityLib} from "./libraries/IdentityLib.sol";
import {Permissions} from "./libraries/Permissions.sol";
import {StakingLib} from "./libraries/StakingLib.sol";
import {TokenLib} from "./libraries/TokenLib.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/**
 * @title StakingV10
 * @notice V10 NFT-backed staking orchestrator. Canonical staking entry point
 *         post-migration.
 *
 * V10 architecture (post-consolidation, v3.0.0 / CSS v4.0.0):
 *   - All V10 delegator state, the TRAC vault, AND operator-fee accounting
 *     live in `ConvictionStakingStorage` (CSS). CSS extends `Guardian`, holds
 *     `tokenContract`, and exposes `transferStake` for outflows. Deposits
 *     route TRAC into the CSS address; withdrawals call `cs.transferStake`.
 *   - `StakingStorage` is dead weight in the V10 hot path. It is read ONLY
 *     by `_convertToNFT` (V8→V10 drain at cutover). Operator-fee balances,
 *     operator-fee withdrawal requests, and the TRAC vault role moved into
 *     CSS in v4.0.0.
 *   - DelegatorsInfo is unregistered (D13). The two per-node-per-epoch
 *     flags it used to hold (`isOperatorFeeClaimedForEpoch`,
 *     `netNodeEpochRewards`) were absorbed into ConvictionStakingStorage.
 *   - The V8 Staking contract is unregistered. The V8-side score
 *     settlement helper (`Staking.prepareForStakeChange`) is no longer
 *     reachable from V10 (D17); the V10-native `_prepareForStakeChangeV10`
 *     handles all V10 settlement. Operator-fee request/finalize/cancel
 *     was V8-only — v3.0.0 ports it to V10 (CSS-backed) so post-consolidation
 *     deploys can fully drain operator fees without the V8 contract.
 *
 * Rewards model (D19 — compound into raw):
 *   - `claim()` walks the unclaimed window, sums TRAC rewards, and compounds
 *     them directly into the position's `raw` via `cs.increaseRaw`. The
 *     compounded TRAC therefore earns the position's current multiplier
 *     going forward. A parallel statistic-only counter
 *     `cs.cumulativeRewardsClaimed` tracks lifetime reward compounding for
 *     UI/indexer consumption.
 *   - There is no separate `rewards` bucket, no `increaseRewards` /
 *     `decreaseRewards`.
 *
 * Withdraw model (D14 — atomic):
 *   - `withdraw()` is a single transaction. Pre-expiry is disallowed (lock
 *     still active). Post-expiry (or tier-0 rest state) it auto-claims any
 *     outstanding rewards into `raw`, pays out the full `raw` balance from
 *     the `StakingStorage` TRAC vault to the owner, and deletes the CSS
 *     position. The NFT wrapper burns the token on the back half. There is
 *     no request/cancel/finalize dance and no address-timer delay — the
 *     lock IS the delay, and partial withdrawals are not a first-class
 *     feature (re-stake the remainder for the same economic result).
 *
 * Redelegate model (D25 — in-place):
 *   - `redelegate()` is a single transaction that mutates `pos.identityId`
 *     in place on CSS via `updateOnRedelegate`. Same tokenId, same
 *     `expiryEpoch`, same rewards cursor — only the node assignment
 *     changes. `relock` continues to use the D21/D23 burn-and-mint path
 *     because relock materially changes tier / multiplier / expiry.
 */
contract StakingV10 is INamed, IVersioned, ContractStatus, IInitializable {
    using SafeERC20 for IERC20;

    // ========================================================================
    // Metadata
    // ========================================================================

    string private constant _NAME = "StakingV10";
    // Version history:
    //   2.0.0 — initial V10 orchestrator (post-migration).
    //   2.1.0 — atomic `withdraw` + in-place `redelegate`.
    //   2.2.0 — aligned with CSS v2.2.0: `PendingWithdrawal` storage gone,
    //           `redelegate` goes through `updateOnRedelegate` (tokenId +
    //           expiryEpoch preserved), `withdraw` is a single-tx exit
    //           with auto-claim.
    //   2.3.0 — D26 code-review follow-ups:
    //           * H1 — `_claim` dormancy bomb fixed: rewardless epochs
    //             early-continue (no fee-flag SSTORE, no per-epoch SLOAD
    //             storm).
    //           * H2 — expiry-split reward math extracted into a shared
    //             `_delegatorIncrementForEpoch` helper; `_claim` and
    //             `_prepareForStakeChangeV10` share one code path.
    //           * L3 — `lockTier` widened from `uint8` to `uint40` across
    //             the public surface so admins can add tier ids above 255.
    //           * L11 — `createPosition` no longer takes `multiplier18`;
    //             CSS reads it from the tier table.
    //   3.0.0 — Storage consolidation (CSS v4.0.0):
    //           * `stake` deposits TRAC into `convictionStorage` (CSS) instead
    //             of `stakingStorage` (SS). CSS extends Guardian and is the
    //             V10 TRAC vault.
    //           * `withdraw` outflow uses `convictionStorage.transferStake`.
    //           * `_claim` operator-fee accrual writes to
    //             `convictionStorage.increaseOperatorFeeBalance`.
    //           * NEW: `requestOperatorFeeWithdrawal`,
    //             `finalizeOperatorFeeWithdrawal`, `cancelOperatorFeeWithdrawal`
    //             — V10-native operator-fee withdrawal API (was V8-only). Uses
    //             `parametersStorage.stakeWithdrawalDelay` cooldown.
    //           * `stakingStorage` is retained ONLY for `_convertToNFT`'s
    //             V8→V10 drain at cutover.
    //   3.1.0 — V8→V10 migration conviction credit (CSS v4.1.0):
    //           * `allocateFromCredit`, for migrants picking lockTier 6 or 12,
    //             shortens the V10 NFT's default `expiryTimestamp` by
    //             `convictionCreditSeconds` (universal — no eligibility
    //             registry; every 6/12 migration allocation earns it).
    //           * `convictionStorage.createPosition(...)` calls now pass the
    //             new `expiryShortenedBy` arg (CSS v4.1.0). `stake` always
    //             passes 0; `_convertToNFT` passes 0 except for eligible
    //             6m/12m migrants.
    //   10.0.3 — Audit fix: mid-epoch `redelegate`/`relock` orphaned the
    //           current epoch's settled delegator score (the old
    //           (epoch, node, key) RSS slot was never read again after the
    //           identity flip / tokenId re-key).
    //           * `redelegate` / `relock` record a `RewardCarry` pointer in
    //             CSS when the settled score is non-zero.
    //           * `_claim` integrates matured carries (epoch closed) via the
    //             extracted `_nodeEpochReward` helper, then clears them.
    //   10.0.5 — Permissionless claim WITHOUT a wrapper redeploy: adds the
    //           public `claimFor(tokenId)` settlement entry point (anyone may
    //           trigger; rewards compound to the tokenId-keyed NFT owner). The
    //           `onlyConvictionNFT` `claim` keeps its 2-arg `(staker, tokenId)`
    //           signature so the deployed 10.0.3 wrapper still works post-
    //           redeploy — superseding #1302's wrapper-side change, which could
    //           not ship to mainnet without orphaning existing position NFTs.
    //           Also carries the #1297 boost-expiry reward-boundary fix (which
    //           had landed under the unchanged 10.0.4 string).
    string private constant _VERSION = "10.0.5";

    /// @notice Emitted when a node crosses `minimumStake` during a
    /// stake / redelegate / claim but the sharding table is full, so its
    /// admission is deferred. Admission is best-effort housekeeping: the node
    /// stays out of the ring (earning no score, which is correct) and is
    /// re-attempted on the next stake/claim once a slot frees. The caller's
    /// stake / claim / withdraw / redelegate is never blocked by a full table. #1286
    event NodeAdmissionDeferred(uint72 indexed identityId, uint256 nodeStakeV10);

    // ========================================================================
    // Constants
    // ========================================================================

    /// @notice 1e18 fixed-point scale shared with `ConvictionStakingStorage`.
    uint256 public constant SCALE18 = 1e18;

    /// @notice EpochStorage shard ID for the reward pool.
    uint256 private constant EPOCH_POOL_INDEX = 1;

    // ========================================================================
    // Hub-wired dependencies
    // ========================================================================

    /// @notice V8 archive accessor — present ONLY for `_convertToNFT`'s V8→V10
    ///         drain. The V10 hot path (stake/withdraw/claim/operator-fee
    ///         accrual + withdrawal) reads and writes `convictionStorage`
    ///         exclusively (v4.0.0 consolidation).
    StakingStorage public stakingStorage;
    ConvictionStakingStorage public convictionStorage;
    Chronos public chronos;
    RandomSamplingStorage public randomSamplingStorage;
    ShardingTableStorage public shardingTableStorage;
    ShardingTable public shardingTable;
    Ask public ask;
    ParametersStorage public parametersStorage;
    ProfileStorage public profileStorage;
    /// @notice IdentityStorage for `onlyAdmin(identityId)` admin-key checks
    ///         (operator-fee withdrawal request / finalize / cancel).
    IdentityStorage public identityStorage;
    IERC20 public token;
    EpochStorage public epochStorage;

    // ========================================================================
    // Events
    // ========================================================================

    event Staked(
        uint256 indexed tokenId,
        address indexed staker,
        uint72 indexed identityId,
        uint96 amount,
        uint40 lockTier
    );
    event Relocked(uint256 indexed tokenId, uint40 newLockTier, uint64 newExpiryTimestamp);
    event Redelegated(uint256 indexed tokenId, uint72 indexed oldIdentityId, uint72 indexed newIdentityId);
    /// @notice Authoritative atomic-withdraw event. `amount` is the total
    ///         TRAC paid out to `staker` (post-auto-claim `raw`). The NFT
    ///         wrapper burns `tokenId` on the back half.
    event Withdrawn(uint256 indexed tokenId, address indexed staker, uint96 amount);
    event RewardsClaimed(uint256 indexed tokenId, uint96 amount);

    // ========================================================================
    // Errors
    // ========================================================================

    error InvalidLockTier();
    error LockStillActive();
    error NotPositionOwner();
    error ZeroAmount();
    error MaxStakeExceeded();
    error SameIdentity();
    error ProfileDoesNotExist();
    error RewardOverflow();
    error PositionNotFound();
    error UnclaimedEpochs();
    error V8StakingStillLive();
    error NodeAlreadyInShardingTable(uint72 identityId);
    error NodeBelowMinimumStake(uint72 identityId);

    // ========================================================================
    // Constructor + initialize
    // ========================================================================

    // solhint-disable-next-line no-empty-blocks
    constructor(address hubAddress) ContractStatus(hubAddress) {}

    /**
     * @dev Wires Hub-registered dependencies. DelegatorsInfo and the V8
     *      `Staking` contract are NOT looked up here (D3 + D17 + D13):
     *      DelegatorsInfo is unregistered by deploy script 021, V8 Staking
     *      is unregistered by deploy script 998 as part of the migration
     *      cutover.
     */
    function initialize() external onlyHub {
        stakingStorage = StakingStorage(hub.getContractAddress("StakingStorage"));
        convictionStorage = ConvictionStakingStorage(hub.getContractAddress("ConvictionStakingStorage"));
        chronos = Chronos(hub.getContractAddress("Chronos"));
        randomSamplingStorage = RandomSamplingStorage(hub.getContractAddress("RandomSamplingStorage"));
        shardingTableStorage = ShardingTableStorage(hub.getContractAddress("ShardingTableStorage"));
        shardingTable = ShardingTable(hub.getContractAddress("ShardingTable"));
        ask = Ask(hub.getContractAddress("Ask"));
        parametersStorage = ParametersStorage(hub.getContractAddress("ParametersStorage"));
        profileStorage = ProfileStorage(hub.getContractAddress("ProfileStorage"));
        identityStorage = IdentityStorage(hub.getContractAddress("IdentityStorage"));
        token = IERC20(hub.getContractAddress("Token"));
        epochStorage = EpochStorage(hub.getContractAddress("EpochStorageV8"));
    }

    function name() external pure virtual override returns (string memory) {
        return _NAME;
    }

    function version() external pure virtual override returns (string memory) {
        return _VERSION;
    }

    // ========================================================================
    // Caller gate
    // ========================================================================

    modifier onlyConvictionNFT() {
        if (msg.sender != hub.getContractAddress("DKGStakingConvictionNFT")) {
            revert StakingLib.OnlyConvictionNFT();
        }
        _;
    }

    /// @notice Operator-fee admin gate. Mirrors V8 `Staking.onlyAdmin` —
    ///         the caller's address (hashed) must hold ADMIN_KEY purpose
    ///         on `identityId` per `IdentityStorage`.
    modifier onlyAdmin(uint72 identityId) {
        if (
            !identityStorage.keyHasPurpose(
                identityId,
                keccak256(abi.encodePacked(msg.sender)),
                IdentityLib.ADMIN_KEY
            )
        ) {
            revert Permissions.OnlyProfileAdminFunction(msg.sender);
        }
        _;
    }

    // ========================================================================
    // Internal guards
    // ========================================================================

    /**
     * @dev Reverts `UnclaimedEpochs` if the position has not been claimed up
     *      to `currentEpoch - 1`.  Called at the top of every stake-changing
     *      entry point so that reward history is settled before any
     *      structural mutation. NOT called in `stake` (no prior position) or
     *      `convertToNFT` (the V10 position is being seeded fresh; the V8-
     *      side rolling rewards no longer gate migration per D7/D8).
     */
    function _requireFullyClaimed(ConvictionStakingStorage.Position memory pos) internal view {
        uint256 currentEpoch = chronos.getCurrentEpoch();
        if (currentEpoch <= 1) return;
        if (uint256(pos.lastClaimedEpoch) < currentEpoch - 1) revert UnclaimedEpochs();
    }

    // ========================================================================
    // External entry points
    // ========================================================================

    /**
     * @notice Mint a fresh NFT-backed staking position on `identityId` with
     *         `amount` TRAC locked for `lockTier` epochs.
     *
     * @dev V10 flow (D15 — CSS-only accounting):
     *        1. Amount + tier validation.
     *        2. Destination profile existence.
     *        3. maxStake cap on the DESTINATION V10 node stake
     *           (`cs.nodeStakeV10`, NOT `ss.nodeStake`). StakingStorage's
     *           node stake is V8 legacy and stale post-migration.
     *        4. V10 settlement baseline (zero stake, bumps the
     *           node-epoch-score-per-stake cursor for this token).
     *        5. TRAC transfer into the StakingStorage vault (still the
     *           protocol-wide TRAC custody).
     *        6. CSS position creation (migrationEpoch = 0 — fresh stake).
     *        7. Sharding-table insert threshold, Ask recalc.
     */
    function stake(
        address staker,
        uint256 tokenId,
        uint72 identityId,
        uint96 amount,
        uint40 lockTier
    ) external onlyConvictionNFT {
        if (amount == 0) revert ZeroAmount();
        if (!profileStorage.profileExists(identityId)) revert ProfileDoesNotExist();

        // Tier-existence / activeness is checked by CSS.createPosition.

        uint256 maxStake = uint256(parametersStorage.maximumStake());
        uint256 totalNodeStakeAfter = convictionStorage.getNodeStakeV10(identityId) + uint256(amount);
        if (totalNodeStakeAfter > maxStake) revert MaxStakeExceeded();

        if (token.allowance(staker, address(this)) < amount) {
            revert TokenLib.TooLowAllowance(address(token), token.allowance(staker, address(this)), amount);
        }

        if (token.balanceOf(staker) < amount) {
            revert TokenLib.TooLowBalance(address(token), token.balanceOf(staker), amount);
        }

        _prepareForStakeChangeV10(chronos.getCurrentEpoch(), tokenId, identityId);

        // v4.0.0 — TRAC flows into the CSS vault. CSS extends Guardian and
        // exposes `transferStake` for the withdraw outflow side. The NFT
        // wrapper never holds funds; the V8 StakingStorage is no longer in
        // the deposit path.
        //
        // Slither flags this site twice:
        //   - `arbitrary-send-erc20`: `staker` is the `from` argument. NOT
        //     arbitrary — the `onlyConvictionNFT` modifier restricts callers
        //     to the convictionNFT contract, which only invokes `stake()`
        //     for the NFT holder whose token is being created. The allowance
        //     check at line 340 above proves the `staker` authorised this
        //     specific transfer (or the call reverts before reaching here).
        //   - `unchecked-transfer`: `safeTransferFrom` (SafeERC20) reverts
        //     on failure; the false-return path Slither warns about does
        //     not apply.
        // slither-disable-next-line arbitrary-send-erc20,unchecked-transfer
        token.safeTransferFrom(staker, address(convictionStorage), amount);

        // L11 — multiplier18 is no longer passed in; CSS reads it from the
        //       tier table (single source of truth).
        // v4.1.0 — fresh V10 stakes never receive the V8 migration credit;
        //          `expiryShortenedBy` is therefore always 0 here.
        convictionStorage.createPosition(
            tokenId,
            identityId,
            amount,
            lockTier,
            0, // fresh V10 stake: no migrationEpoch
            0 // fresh V10 stake: no expiry credit
        );

        // Sharding-table maintenance gates on the V10 canonical node stake.
        ParametersStorage ps = parametersStorage;
        ShardingTableStorage sts = shardingTableStorage;
        if (!sts.nodeExists(identityId) && totalNodeStakeAfter >= uint256(ps.minimumStake())) {
            _tryAdmitNode(identityId);
        }

        ask.recalculateActiveSet();

        emit Staked(tokenId, staker, identityId, amount, lockTier);
    }

    /**
     * @notice Post-expiry re-commit of an existing position to a new lock
     *         tier. Raw stake unchanged; multiplier + expiry shift. Under
     *         D21 this is a burn-and-mint: `oldTokenId` is burned by the
     *         NFT wrapper, `newTokenId` is a freshly-minted NFT the wrapper
     *         has already allocated, and the on-chain position state moves
     *         over via the D23 `createNewPositionFromExisting` primitive.
     *
     * @dev Continuity preserved across the burn-mint:
     *        - `raw` (principal unchanged — no TRAC moves).
     *        - `cumulativeRewardsClaimed` (lifetime reward stat).
     *        - `lastClaimedEpoch` (reward cursor — prevents double-claim).
     *        - `migrationEpoch` (D6 retroactive-claim marker).
     *      Re-initialized on the new tokenId:
     *        - `lockTier`, `multiplier18`, `expiryEpoch` (the whole point
     *          of relock).
     *      `identityId` is held constant — this is relock, not redelegate.
     */
    function relock(
        address staker,
        uint256 oldTokenId,
        uint256 newTokenId,
        uint40 newLockTier
    ) external onlyConvictionNFT {
        staker; // unused — see file-header rationale.

        ConvictionStakingStorage.Position memory pos = convictionStorage.getPosition(oldTokenId);
        if (pos.identityId == 0) revert PositionNotFound();
        _requireFullyClaimed(pos);

        // D26 — timestamp-accurate lock gate. Tier-0 (expiryTimestamp == 0)
        // is already in rest state; any non-zero expiry must have elapsed.
        if (pos.expiryTimestamp != 0 && block.timestamp < uint256(pos.expiryTimestamp)) revert LockStillActive();

        uint256 currentEpoch = chronos.getCurrentEpoch();
        uint256 settledEpochScore18 = _prepareForStakeChangeV10(currentEpoch, oldTokenId, pos.identityId);

        // v10.0.3 — baseline the NEW tokenId's settlement cursor at the
        // current score-per-stake BEFORE the position exists under it
        // (cursor-bump-only branch: `positions[newTokenId].identityId == 0`).
        // Without this the new key re-integrates the epoch's score from 0
        // at the NEW multiplier — over-crediting the delegator and
        // overdrawing the node's epoch pool. Mirrors the `stake` baseline.
        _prepareForStakeChangeV10(currentEpoch, newTokenId, pos.identityId);

        // M1 + L11 — same-identity relock. CSS reads the multiplier from the
        //            tier table; no need to pass it in. Migrates any existing
        //            reward carries from oldTokenId to newTokenId (v10.0.3).
        convictionStorage.createNewPositionFromExisting(
            oldTokenId,
            newTokenId,
            pos.identityId,
            newLockTier
        );

        // v10.0.3 — the score settled this epoch lives in RSS under the OLD
        // tokenId's delegator key, which `_claim(newTokenId)` would never
        // read. Carry the pointer across the burn-mint.
        if (settledEpochScore18 > 0) {
            convictionStorage.addRewardCarry(
                newTokenId,
                pos.identityId,
                uint32(currentEpoch),
                bytes32(oldTokenId)
            );
        }

        ConvictionStakingStorage.Position memory posAfter = convictionStorage.getPosition(newTokenId);
        emit Relocked(newTokenId, newLockTier, uint64(posAfter.expiryTimestamp));
    }

    /**
     * @notice Move a position from its current node to `newIdentityId`.
     *         Same tokenId persists; only `pos.identityId` mutates.
     *         Per-node raw / effective stake moves across at `currentEpoch`;
     *         global totals invariant.
     *
     * @dev D25 — in-place redelegate. The tokenId, `expiryEpoch`,
     *      `lockTier`, `multiplier18`, `lastClaimedEpoch`, `migrationEpoch`
     *      and `cumulativeRewardsClaimed` are ALL preserved. The lock
     *      clock does NOT reset: a redelegation is a routing decision,
     *      not a new commitment. CSS's `updateOnRedelegate` moves the
     *      per-node effective-stake contribution at `currentEpoch` and
     *      reassigns the pending expiry drop from the old node to the
     *      new node at the same `expiryEpoch`.
     *
     *      Fresh stakes still gate on the destination's `maxStake` —
     *      redelegating INTO a near-capped node can still revert. The
     *      min-stake boundary on the OLD node may trigger a sharding-
     *      table removal; the new node may cross back in. Ask recalc
     *      runs once at the end.
     */
    function redelegate(
        address staker,
        uint256 tokenId,
        uint72 newIdentityId
    ) external onlyConvictionNFT {
        staker;

        ConvictionStakingStorage.Position memory pos = convictionStorage.getPosition(tokenId);
        if (pos.identityId == 0) revert PositionNotFound();
        _requireFullyClaimed(pos);
        uint72 oldIdentityId = pos.identityId;

        if (oldIdentityId == newIdentityId) revert SameIdentity();
        if (!profileStorage.profileExists(newIdentityId)) revert ProfileDoesNotExist();

        uint96 raw = pos.raw;
        require(raw > 0, "No raw");

        // Destination maxStake cap gates on V10 canonical node stake.
        uint256 newNodeStakeAfter = convictionStorage.getNodeStakeV10(newIdentityId) + uint256(raw);
        uint256 maxStake = uint256(parametersStorage.maximumStake());
        if (newNodeStakeAfter > maxStake) revert MaxStakeExceeded();

        // Settle score-per-stake indices on BOTH nodes before CSS mutates
        // effective stake (which shifts the delegator's contribution
        // between the two nodes at `currentEpoch`).
        uint256 currentEpoch = chronos.getCurrentEpoch();
        uint256 oldNodeEpochScore18 = _prepareForStakeChangeV10(currentEpoch, tokenId, oldIdentityId);
        _prepareForStakeChangeV10(currentEpoch, tokenId, newIdentityId);

        // v10.0.3 — the score settled on the OLD node for the in-progress
        // epoch becomes unreachable once `pos.identityId` flips (later
        // claims read only the current node). Record a carry pointer so
        // the next claim integrates it against the old node's pool.
        if (oldNodeEpochScore18 > 0) {
            convictionStorage.addRewardCarry(
                tokenId,
                oldIdentityId,
                uint32(currentEpoch),
                bytes32(tokenId)
            );
        }

        // D25 — in-place node swap. tokenId + expiryEpoch + reward cursor
        // preserved; per-node diffs + per-node raw + pending expiry
        // subtraction all move from oldIdentityId to newIdentityId.
        convictionStorage.updateOnRedelegate(tokenId, newIdentityId);

        // Sharding-table maintenance on BOTH nodes gates on V10 canonical stake.
        ShardingTableStorage sts = shardingTableStorage;
        uint256 minStake = uint256(parametersStorage.minimumStake());

        uint256 oldNodeStakeAfter = convictionStorage.getNodeStakeV10(oldIdentityId);
        if (sts.nodeExists(oldIdentityId) && oldNodeStakeAfter < minStake) {
            shardingTable.removeNode(oldIdentityId);
        }
        if (!sts.nodeExists(newIdentityId) && newNodeStakeAfter >= minStake) {
            _tryAdmitNode(newIdentityId);
        }

        ask.recalculateActiveSet();

        emit Redelegated(tokenId, oldIdentityId, newIdentityId);
    }

    /**
     * @notice Atomic full withdrawal. Post-expiry (or tier-0 rest state)
     *         only. Auto-claims any outstanding rewards into `raw`, pays
     *         out the full `raw` balance from the `StakingStorage` TRAC
     *         vault to `staker`, and deletes the CSS position. The NFT
     *         wrapper burns the token on return.
     *
     * @dev D14 — atomic withdraw. No request / cancel / finalize dance,
     *      no address-timer delay: the lock IS the delay. Partial
     *      withdrawals are NOT a first-class feature — a user wanting
     *      partial liquidity should withdraw the whole position and
     *      re-stake the remainder, which gives the same economic
     *      result (tier-0 with 1x multiplier is effectively liquid
     *      stake). Q3 — rewards are auto-claimed inside this call so
     *      the user sees a single button in the UI.
     */
    function withdraw(
        address staker,
        uint256 tokenId
    ) external onlyConvictionNFT returns (uint96 amount) {
        ConvictionStakingStorage.Position memory pos = convictionStorage.getPosition(tokenId);
        if (pos.identityId == 0) revert PositionNotFound();

        // Lock gate: pre-expiry withdrawals are disallowed. Tier-0
        // positions (`expiryTimestamp == 0`) always pass — they are the
        // rest state with no lock. D26 — timestamp-accurate.
        bool unlocked = pos.expiryTimestamp == 0 || block.timestamp >= uint256(pos.expiryTimestamp);
        if (!unlocked) revert LockStillActive();

        // Auto-claim any outstanding rewards (compounds into `raw`). Must
        // happen BEFORE reading the final raw, because compounding grows
        // it. No-op when `currentEpoch <= 1` or nothing is unclaimed.
        _claim(tokenId);

        // Re-read after auto-claim — raw may have grown via compounding.
        pos = convictionStorage.getPosition(tokenId);
        amount = pos.raw;
        require(amount > 0, "No raw");
        uint72 identityId = pos.identityId;

        // Delete the position: CSS handles effective-stake diff teardown,
        // pending-expiry delta cancel, per-node enumeration pop, per-node
        // raw aggregate decrement, global total decrement, finalization.
        convictionStorage.deletePosition(tokenId);

        // v4.0.0 — TRAC flows from the CSS vault to the NFT owner.
        convictionStorage.transferStake(staker, amount);

        // Sharding-table maintenance: node may have dropped below minStake.
        uint256 newNodeStake = convictionStorage.getNodeStakeV10(identityId);
        if (
            shardingTableStorage.nodeExists(identityId) &&
            newNodeStake < uint256(parametersStorage.minimumStake())
        ) {
            shardingTable.removeNode(identityId);
        }

        ask.recalculateActiveSet();

        emit Withdrawn(tokenId, staker, amount);
    }

    // ========================================================================
    // Operator-fee withdrawal (v4.0.0)
    //
    // Operators accrue fees inside `_claim` (the gross-vs-net split). The
    // accrued balance lives on CSS (`nodeOperatorFeeBalance`); withdrawing
    // it back to the operator's wallet is a request → cooldown → finalize
    // dance, mirroring V8 `Staking.{request,finalize,cancel}OperatorFeeWithdrawal`
    // exactly. The cooldown reuses `parametersStorage.stakeWithdrawalDelay`
    // (no separate operator-fee delay parameter).
    //
    // Restake-fee-as-stake is handled by the existing 2-step path
    // (`finalizeOperatorFeeWithdrawal` → `DKGStakingConvictionNFT.createConviction`)
    // — no dedicated `restakeOperatorFee` primitive exists in V10 because
    // V10 stake is NFT-keyed and lock-tiered; the operator picks tier on
    // re-stake.
    //
    // ── Deprecated V8 lifetime statistics ─────────────────────────────────
    // V8 `StakingStorage` tracked `operatorFeeCumulative{Earned,PaidOut}Rewards`
    // (with paired events) so off-chain dashboards could compute lifetime
    // operator-fee throughput per node. V10 deliberately drops these counters:
    // the on-chain working set is `nodeOperatorFeeBalance` + queued
    // `operatorFeeWithdrawals` only. Lifetime analytics for V10 are computed
    // off-chain by replaying the existing `OperatorFeeBalanceUpdated`,
    // `OperatorFeeWithdrawalRequestCreated`, and `OperatorFeeWithdrawalRequestDeleted`
    // events (or via the per-epoch `IsOperatorFeeClaimedForEpoch` flag), and
    // are not part of the staking-storage surface. Any consumer that needs the
    // legacy cumulative reads must be ported to event replay; CSS will not be
    // extended with the V8 fields. Documented here so the omission is
    // intentional rather than an oversight in the V8→V10 consolidation.
    // ========================================================================

    /// @notice Initiate an operator-fee withdrawal. Caller must hold ADMIN_KEY
    ///         on `identityId`. Subsequent calls before finalize/cancel
    ///         augment the existing request (combined amount = old + new).
    function requestOperatorFeeWithdrawal(uint72 identityId, uint96 withdrawalAmount) external onlyAdmin(identityId) {
        if (withdrawalAmount == 0) revert TokenLib.ZeroTokenAmount();

        ConvictionStakingStorage cs = convictionStorage;

        uint96 existingRequestAmount = cs.getOperatorFeeWithdrawalRequestAmount(identityId);
        uint96 currentOperatorFeeBalance = cs.getOperatorFeeBalance(identityId);

        // If a request already exists, the requested funds were already
        // moved out of the balance into the queue — restore them before we
        // re-check the cap so the totalRequestAmount comparison is honest.
        if (existingRequestAmount > 0) {
            currentOperatorFeeBalance += existingRequestAmount;
        }

        uint96 totalRequestAmount = existingRequestAmount + withdrawalAmount;
        if (totalRequestAmount > currentOperatorFeeBalance) {
            revert StakingLib.AmountExceedsOperatorFeeBalance(currentOperatorFeeBalance, totalRequestAmount);
        }

        uint256 withdrawalReleaseTimestamp = block.timestamp + parametersStorage.stakeWithdrawalDelay();
        cs.setOperatorFeeBalance(identityId, currentOperatorFeeBalance - totalRequestAmount);
        cs.createOperatorFeeWithdrawalRequest(identityId, totalRequestAmount, /*indexed*/ 0, withdrawalReleaseTimestamp);
    }

    /// @notice Complete an operator-fee withdrawal after the cooldown has
    ///         elapsed. Pays out from the CSS TRAC vault.
    function finalizeOperatorFeeWithdrawal(uint72 identityId) external onlyAdmin(identityId) {
        ConvictionStakingStorage cs = convictionStorage;

        (uint96 operatorFeeWithdrawalAmount, , uint256 withdrawalReleaseTimestamp) = cs.getOperatorFeeWithdrawalRequest(
            identityId
        );
        if (operatorFeeWithdrawalAmount == 0) revert StakingLib.WithdrawalWasntInitiated();
        if (block.timestamp < withdrawalReleaseTimestamp) {
            revert StakingLib.WithdrawalPeriodPending(block.timestamp, withdrawalReleaseTimestamp);
        }

        cs.deleteOperatorFeeWithdrawalRequest(identityId);
        cs.transferStake(msg.sender, operatorFeeWithdrawalAmount);
    }

    /// @notice Cancel a pending operator-fee withdrawal and return the queued
    ///         amount to the operator-fee balance. No cooldown applies.
    function cancelOperatorFeeWithdrawal(uint72 identityId) external onlyAdmin(identityId) {
        ConvictionStakingStorage cs = convictionStorage;

        uint96 operatorFeeWithdrawalAmount = cs.getOperatorFeeWithdrawalRequestAmount(identityId);
        if (operatorFeeWithdrawalAmount == 0) revert StakingLib.WithdrawalWasntInitiated();

        cs.deleteOperatorFeeWithdrawalRequest(identityId);
        cs.increaseOperatorFeeBalance(identityId, operatorFeeWithdrawalAmount);
    }

    /**
     * @notice Walk unclaimed epochs, accumulate reward, and compound it into
     *         the position's `raw` (D19). `cumulativeRewardsClaimed` tracks
     *         lifetime compounding as a statistic.
     *
     * @dev D6 — retroactive claim for migrated positions. If
     *      `pos.migrationEpoch != 0` AND `pos.migrationEpoch > pos.lastClaimedEpoch + 1`,
     *      the claim window starts from `pos.migrationEpoch` instead of
     *      `pos.lastClaimedEpoch + 1`. For a fresh V8→V10 migration where
     *      the user never claimed pre-migration, this collapses to "start
     *      the claim at the migration epoch". For a later-life migration
     *      (shouldn't happen in the mandatory-migration model but kept
     *      behavior-defined), the `max(lastClaimedEpoch+1, migrationEpoch)`
     *      semantics prevent double-claiming.
     *
     *      D19 — reward handling:
     *        1. Sum per-epoch rewards across the window (V10 math —
     *           CSS per-epoch operator fee + net-node rewards).
     *        2. `cs.increaseRaw(tokenId, rewardTotal)` — raw grows; the
     *           compounded TRAC earns the position's current multiplier
     *           going forward; per-epoch effective-stake diff updated.
     *        3. `cs.addCumulativeRewardsClaimed(tokenId, rewardTotal)` —
     *           statistic-only lifetime counter.
     *        4. `cs.setLastClaimedEpoch(tokenId, toEpoch)` — advance cursor.
     *      No StakingStorage writes.
     */
    // The first arg (the staker address) is intentionally UNNAMED: it is
    // retained only for ABI compatibility with the DEPLOYED DKGStakingConvictionNFT
    // wrapper (10.0.3), whose owner-gated `claim` calls
    // `stakingV10.claim(msg.sender, tokenId)`. Keeping this 2-arg signature means
    // the existing wrapper keeps working after StakingV10 is redeployed — so no
    // wrapper redeploy (which would orphan position NFTs) is needed. Settlement is
    // tokenId-keyed (the NFT owner is the beneficiary), so the address is unused.
    function claim(address, uint256 tokenId) external onlyConvictionNFT {
        _claim(tokenId);
    }

    /// @notice Permissionless settlement: ANY caller may trigger a claim for
    ///         `tokenId`. Rewards compound into the tokenId-keyed position, so
    ///         the current NFT owner benefits regardless of caller — no funds
    ///         are routed to `msg.sender`. This is the wrapper-independent
    ///         permissionless-claim entry point: keepers can settle rewards (and
    ///         the per-epoch operator fee) without touching the stateful ERC-721
    ///         wrapper. `_claim` reverts `PositionNotFound` for a nonexistent or
    ///         already-withdrawn position, so no extra guard is required.
    function claimFor(uint256 tokenId) external {
        _claim(tokenId);
    }

    /**
     * @dev Internal claim body shared between the external `claim` entry
     *      point and the atomic `withdraw` path. Advances the position's
     *      reward cursor and compounds any outstanding rewards into `raw`.
     *      No-op when the position has no unclaimed window (early epochs
     *      or `lastClaimedEpoch == currentEpoch - 1`).
     */
    /// @dev Best-effort sharding-table admission. Callers gate on eligibility
    /// (node not in table AND stake >= minimumStake) before calling. A full
    /// table (`ShardingTableIsFull`) MUST NOT revert the caller's
    /// stake/claim/withdraw/redelegate — admission is opportunistic housekeeping.
    /// On failure the node stays out of the ring (earning no score, which is the
    /// correct incentive) and is re-attempted by the next stake/claim once a slot
    /// frees. Fixes #1286 (a full table previously blocked claim — and via
    /// `withdraw`'s auto-claim, raw-stake withdrawal too).
    ///
    /// NB: a node deferred while OUT of the ring earns no reward, so a later
    /// zero-reward `_claim` returns before its inline admission and will NOT
    /// re-admit it. `admitNode` below is the permissionless recovery for that.
    function _tryAdmitNode(uint72 identityId) internal {
        try shardingTable.insertNode(identityId) {
            // admitted
        } catch (bytes memory reason) {
            // Only a full table (ShardingTableIsFull) is an expected, benign
            // deferral. Any other revert (a Hub-wiring / index-invariant / future
            // check failure) is a real error we must NOT mask while the caller's
            // staking state is already mutated — rethrow the original revert.
            bytes4 selector;
            if (reason.length >= 4) {
                // solhint-disable-next-line no-inline-assembly
                assembly {
                    selector := mload(add(reason, 0x20))
                }
            }
            if (selector == ShardingTable.ShardingTableIsFull.selector) {
                // ShardingTable rolled back its own state on the full-table revert;
                // it is a trusted Hub-registered contract, so emitting after the
                // call is safe (slither reentrancy-events false positive).
                // slither-disable-next-line reentrancy-events
                emit NodeAdmissionDeferred(identityId, convictionStorage.getNodeStakeV10(identityId));
            } else {
                // solhint-disable-next-line no-inline-assembly
                assembly {
                    revert(add(reason, 0x20), mload(reason))
                }
            }
        }
    }

    /// @notice Permissionless maintenance: admit a node that is eligible for the
    /// sharding table (V10 stake >= `minimumStake`) but not currently in it —
    /// e.g. one whose opportunistic admission was deferred because the table was
    /// full (`_tryAdmitNode` / #1286). Anyone may bring an eligible node into the
    /// ring once a slot frees, without the node's staker needing to add stake or
    /// trigger a reward claim (a zero-reward `_claim` returns before its inline
    /// admission). Reverts `ShardingTableIsFull` if the table is still full (so
    /// the caller learns), or `NodeAlreadyInShardingTable` / `NodeBelowMinimumStake`
    /// if the node is not eligible.
    function admitNode(uint72 identityId) external {
        if (shardingTableStorage.nodeExists(identityId)) {
            revert NodeAlreadyInShardingTable(identityId);
        }
        if (convictionStorage.getNodeStakeV10(identityId) < uint256(parametersStorage.minimumStake())) {
            revert NodeBelowMinimumStake(identityId);
        }
        shardingTable.insertNode(identityId);
        ask.recalculateActiveSet();
    }

    function _claim(uint256 tokenId) internal {
        ConvictionStakingStorage.Position memory pos = convictionStorage.getPosition(tokenId);
        if (pos.identityId == 0) revert PositionNotFound();

        uint256 currentEpoch = chronos.getCurrentEpoch();
        if (currentEpoch <= 1) return;

        // D6 — retroactive claim on migrationEpoch.
        uint256 lastClaimed = uint256(pos.lastClaimedEpoch);
        uint256 migrationEpoch = uint256(pos.migrationEpoch);
        uint256 claimFromEpoch = lastClaimed + 1;
        if (migrationEpoch != 0 && migrationEpoch > claimFromEpoch) {
            claimFromEpoch = migrationEpoch;
        }
        uint256 claimToEpoch = currentEpoch - 1;
        if (claimFromEpoch > claimToEpoch) return;

        _prepareForStakeChangeV10(currentEpoch, tokenId, pos.identityId);

        // Local cache.
        uint256 rawU = uint256(pos.raw);
        uint256 mult18 = uint256(pos.multiplier18);
        uint256 expiryTs = uint256(pos.expiryTimestamp);
        // D26 — wall-clock → epoch projection of the position's expiry.
        // 0 for tier-0 (no boost, no expiry).
        uint256 expiryEpoch = expiryTs == 0 ? 0 : chronos.epochAtTimestamp(expiryTs);
        uint72 identityId = pos.identityId;
        bytes32 delegatorKey = bytes32(tokenId);

        uint256 effBoosted = (rawU * mult18) / SCALE18;
        uint256 effBase = rawU;

        uint256 rewardTotal = 0;
        for (uint256 e = claimFromEpoch; e <= claimToEpoch; e++) {
            // H1 — fast path for rewardless epochs. `getEpochLastScorePerStake`
            // is 0 iff no proof was ever submitted on this node in epoch `e`.
            // When that is the case: no node score, no delegator score, no
            // operator-fee math, nothing to settle. Skipping here collapses a
            // dormant-epoch iteration from ~25k gas (4 SLOADs + 1 SSTORE for
            // the fee flag) to ~2k gas (single SLOAD + continue). This is
            // what keeps long-dormant tier-0 positions claimable.
            uint256 scorePerStake36 = randomSamplingStorage.getEpochLastScorePerStake(identityId, e);
            if (scorePerStake36 == 0) continue;

            uint256 settledDelegatorScore18 = randomSamplingStorage.getEpochNodeDelegatorScore(
                e,
                identityId,
                delegatorKey
            );
            uint256 lastSettledIndex36 = randomSamplingStorage
                .getDelegatorLastSettledNodeEpochScorePerStake(e, identityId, delegatorKey);

            // H2 — expiry-split reward integration shared with
            //      `_prepareForStakeChangeV10`.
            uint256 unsettledDelegatorScore18 = _delegatorIncrementForEpoch(
                e,
                identityId,
                scorePerStake36,
                lastSettledIndex36,
                effBoosted,
                effBase,
                expiryTs,
                expiryEpoch
            );
            uint256 delegatorScore18 = settledDelegatorScore18 + unsettledDelegatorScore18;

            rewardTotal += _nodeEpochReward(e, identityId, delegatorScore18);
        }

        // v10.0.3 — integrate matured reward carries (pointers to RSS score
        // slots recorded by mid-epoch `redelegate`/`relock`; see CSS struct
        // docs). A carry matures once its epoch is <= `claimToEpoch`.
        {
            ConvictionStakingStorage.RewardCarry[] memory carries =
                convictionStorage.getRewardCarries(tokenId);
            bool carriesMatured = false;
            for (uint256 i = 0; i < carries.length; i++) {
                if (uint256(carries[i].epoch) > claimToEpoch) continue;
                carriesMatured = true;
                // The main loop above already integrated the position's
                // CURRENT (node, key) slot for every epoch in the window —
                // skip a carry that points at it (e.g. A→B→A round-trip).
                if (carries[i].identityId == identityId && carries[i].delegatorKey == delegatorKey) {
                    continue;
                }
                uint256 carryScore18 = randomSamplingStorage.getEpochNodeDelegatorScore(
                    uint256(carries[i].epoch),
                    carries[i].identityId,
                    carries[i].delegatorKey
                );
                if (carryScore18 == 0) continue;
                rewardTotal += _nodeEpochReward(
                    uint256(carries[i].epoch),
                    carries[i].identityId,
                    carryScore18
                );
            }
            if (carriesMatured) {
                convictionStorage.clearRewardCarries(tokenId, uint32(claimToEpoch));
            }
        }

        if (rewardTotal == 0) {
            // No-reward window: just advance the claim cursor.
            convictionStorage.setLastClaimedEpoch(tokenId, uint32(claimToEpoch));
            return;
        }

        if (rewardTotal > type(uint96).max) revert RewardOverflow();
        uint96 rewardU96 = uint96(rewardTotal);

        // D19 — compound into raw. CSS writes the per-epoch effective-stake
        // diff and bumps nodeStakeV10 / totalStakeV10 in lockstep. The
        // compounded TRAC earns the position's current multiplier.
        convictionStorage.increaseRaw(tokenId, rewardU96);
        convictionStorage.addCumulativeRewardsClaimed(tokenId, rewardU96);

        // Sharding-table + Ask housekeeping — the reward compound grew
        // node stake; a node previously under `minimumStake` may now be
        // eligible for the sharding table. Reward is always an increase,
        // so only the cross-above-minimum insert is needed.
        {
            uint256 newNodeStake = convictionStorage.getNodeStakeV10(identityId);
            if (
                !shardingTableStorage.nodeExists(identityId) &&
                newNodeStake >= uint256(parametersStorage.minimumStake())
            ) {
                _tryAdmitNode(identityId);
            }
        }
        ask.recalculateActiveSet();

        convictionStorage.setLastClaimedEpoch(tokenId, uint32(claimToEpoch));

        emit RewardsClaimed(tokenId, rewardU96);
    }

    // ========================================================================
    // V8→V10 "pool & allocate" migration workers
    // ========================================================================
    //
    // The NFT wrapper (DKGStakingConvictionNFT) is the only caller
    // (onlyConvictionNFT). It owns the tokenId counter + ERC-721 mint and the
    // owner gating; these workers do the privileged StakingStorage/CSS
    // mutations. `drainV8ToCredit` is the drain half of the old `_convertToNFT`
    // (now per-node, mints nothing, credits CSS); `allocateFromCredit` is the
    // V10-seed half (now funded from migration credit, not a fresh transfer).

    /// @notice Drain ALL of `delegator`'s V8 stake on `identityId` (active
    ///         stakeBase + any pending withdrawal, D8) into their migration
    ///         credit on CSS. Returns the drained `total` so the wrapper can
    ///         aggregate across nodes and revert if the grand total is zero;
    ///         a node with no V8 stake contributes 0 (no revert here).
    /// @dev    no per-source eligibility: the full drained amount is
    ///         credited to the delegator; the tier-6/12 lock-credit is decided
    ///         later in `allocateFromCredit` from the chosen tier.
    function drainV8ToCredit(
        address delegator,
        uint72 identityId
    ) external onlyConvictionNFT returns (uint96 total) {
        // Freeze-first invariant (on-chain): the V8 `Staking` logic must be
        // unregistered before ANY drain (admin sweep OR self-migrate). A drain
        // zeroes stakeBase without settling the reward cursor; if V8 `Staking`
        // is still live it keeps computing rewards/sharding off StakingStorage,
        // so draining against live state corrupts it. Gating here covers every
        // drain path through one chokepoint; selfMigrate auto-opens at freeze.
        if (hub.isContract("Staking")) revert V8StakingStillLive();
        bytes32 v8Key = keccak256(abi.encodePacked(delegator));
        StakingStorage ss = stakingStorage;
        uint96 stakeBase = ss.getDelegatorStakeBase(identityId, v8Key);
        uint96 pending = ss.getDelegatorWithdrawalRequestAmount(identityId, v8Key);
        total = stakeBase + pending;
        if (total == 0) return 0;

        // V8 drain. Pending was already excluded from node/total stake at
        // request time, so only the active base is decremented.
        if (stakeBase > 0) {
            ss.setDelegatorStakeBase(identityId, v8Key, 0);
            ss.decreaseNodeStake(identityId, stakeBase);
            ss.decreaseTotalStake(stakeBase);
        }
        if (pending > 0) {
            ss.deleteDelegatorWithdrawalRequest(identityId, v8Key);
        }
        // Move the migrated TRAC SS -> CSS so the credit stays collateralized.
        ss.transferStake(address(convictionStorage), total);

        convictionStorage.addMigrationCredit(delegator, total);
    }

    /// @notice Drain node `identityId`'s V8 operator fee (the resting
    ///         `operatorFeeBalance` PLUS any open fee-withdrawal request) into
    ///         `operator`'s migration credit on CSS. Returns the drained
    ///         `total`; a node with no fee contributes 0 (no revert here), so
    ///         the wrapper can sweep in bulk.
    /// @dev    "one credit": the operator fee folds
    ///         into the SAME `migrationCredit` bucket as delegator stake, so
    ///         the operator recovers it exactly like a delegator — `allocate`
    ///         at tier 0 (immediately withdrawable) or 6/12 (conviction).
    ///
    ///         Operator addresses are NOT recoverable on-chain — IdentityStorage
    ///         holds key *hashes*, not addresses — so the off-chain sweep
    ///         supplies `operator` and this function validates it currently
    ///         holds ADMIN_KEY on the node (mirroring who V8
    ///         `finalizeOperatorFeeWithdrawal` would have paid). A stale/wrong
    ///         address REVERTS rather than crediting silently, so a
    ///         mis-resolved operator can never be paid; the sweep hard-fails
    ///         and re-resolves. The check is skipped only when there is nothing
    ///         to drain (`total == 0`), keeping re-runs idempotent and cheap.
    function drainOperatorFeeToCredit(
        uint72 identityId,
        address operator
    ) external onlyConvictionNFT returns (uint96 total) {
        // Freeze-first invariant (see drainV8ToCredit) — no fee drain while V8
        // Staking is still live and could finalize/restake the same balance.
        if (hub.isContract("Staking")) revert V8StakingStillLive();
        StakingStorage ss = stakingStorage;
        uint96 feeBalance = ss.getOperatorFeeBalance(identityId);
        uint96 feeRequest = ss.getOperatorFeeWithdrawalRequestAmount(identityId);
        total = feeBalance + feeRequest;
        if (total == 0) return 0;

        // Credit only an address that currently controls the node.
        if (
            !identityStorage.keyHasPurpose(
                identityId,
                keccak256(abi.encodePacked(operator)),
                IdentityLib.ADMIN_KEY
            )
        ) {
            revert Permissions.OnlyProfileAdminFunction(operator);
        }

        // Zero the V8 fee slots (idempotent: a re-drain reads 0, returns 0).
        // The open-request amount stayed in the SS vault at request time (no
        // token moved), so deleting it here releases it for the SS->CSS move.
        if (feeBalance > 0) {
            ss.setOperatorFeeBalance(identityId, 0);
        }
        if (feeRequest > 0) {
            ss.deleteOperatorFeeWithdrawalRequest(identityId);
        }
        // Move the migrated TRAC SS -> CSS so the credit stays collateralized.
        ss.transferStake(address(convictionStorage), total);

        convictionStorage.addMigrationCredit(operator, total);
    }

    /// @notice Spend `amount` of `staker`'s migration credit into a fresh V10
    ///         conviction position on `targetNode` at `lockTier`. Runs the full
    ///         stake tail (score-cursor baseline → createPosition → sharding
    ///         insert → ask recalc). Any tier-6/12 allocation applies the
    ///         `convictionCreditSeconds` lock-shortening (universal). The
    ///         wrapper supplies `tokenId` and mints after.
    function allocateFromCredit(
        address staker,
        uint256 tokenId,
        uint72 targetNode,
        uint96 amount,
        uint40 lockTier
    ) external onlyConvictionNFT returns (bool creditApplied) {
        if (!profileStorage.profileExists(targetNode)) revert ProfileDoesNotExist();
        ConvictionStakingStorage cs = convictionStorage;
        // Active-tier check: createPosition skips _requireActiveTier on the
        // migration path (migrationEpoch > 0), and this is a NEW tier choice
        // (not honoring a prior V8 commitment), so reject deactivated tiers —
        // EXCEPT tier 0. Tier 0 is the no-lock recovery sink that guarantees
        // admin-drained credit is always withdrawable in two txs (allocate
        // tier-0 -> withdraw); exempting it keeps that safety net independent of
        // whether the owner has retired the no-lock product.
        require(lockTier == 0 || cs.getTier(lockTier).active, "Inactive tier");

        // maxStake cap on the destination node (post-allocation aggregate).
        if (cs.getNodeStakeV10(targetNode) + uint256(amount) > uint256(parametersStorage.maximumStake())) {
            revert MaxStakeExceeded();
        }

        // Debit credit (reverts if amount == 0 or > migrationCredit). The
        // tier-6/12 conviction lock-credit is universal — any 6/12
        // migration allocation earns it (no per-staker eligibility).
        cs.spendMigrationCredit(staker, amount);
        // `creditApplied` must reflect shortening that was ACTUALLY applied:
        // a tier-6/12 allocation while `convictionCreditSeconds == 0` (credit
        // not yet configured) shortens by 0, so the flag/event would otherwise
        // claim a credit that wasn't granted. Gate it on a non-zero duration.
        uint40 creditSeconds = cs.convictionCreditSeconds();
        creditApplied = (lockTier == 6 || lockTier == 12) && creditSeconds > 0;
        uint40 expiryShortenedBy = creditApplied ? creditSeconds : 0;

        uint256 currentEpoch = chronos.getCurrentEpoch();
        // Baseline the V10 score cursor BEFORE createPosition so the creation
        // epoch is not retroactively over-credited.
        _prepareForStakeChangeV10(currentEpoch, tokenId, targetNode);

        cs.createPosition(tokenId, targetNode, amount, lockTier, uint32(currentEpoch), expiryShortenedBy);

        if (
            !shardingTableStorage.nodeExists(targetNode) &&
            cs.getNodeStakeV10(targetNode) >= uint256(parametersStorage.minimumStake())
        ) {
            _tryAdmitNode(targetNode);
        }
        ask.recalculateActiveSet();
    }

    /// @notice Set the V8→V10 conviction lock-credit (seconds) on CSS. Driven
    ///         by the owner-gated `setConvictionCreditSeconds` entrypoint on the
    ///         NFT wrapper (no freeze gate; settable any time pre-sweep).
    function setConvictionCreditSeconds(uint40 secondsValue) external onlyConvictionNFT {
        convictionStorage.setConvictionCreditSeconds(secondsValue);
    }

    /**
     * @notice Admin: set the V10 launch epoch marker on CSS. This is the
     *         retroactive-attribution boundary used by the admin migration
     *         bookkeeping and off-chain analytics. Expected to be called
     *         exactly once, in the deploy-script migration cutover. Gate
     *         enforced at the NFT wrapper (`onlyOwnerOrMultiSigOwner`).
     *
     * @dev D7 — the V10 launch epoch is the cutoff past which V8-era
     *      state should not continue to accrue rewards; anything the
     *      migration process hasn't swept by this epoch is treated as a
     *      straggler and drained via `adminDrainBatch` / `adminMigrateToCredit`.
     */
    function setV10LaunchEpoch(uint256 epoch) external onlyConvictionNFT {
        convictionStorage.setV10LaunchEpoch(epoch);
    }


    // ========================================================================
    // Internal helpers — V10 score-per-stake settlement
    // ========================================================================

    /**
     * @dev Convert a delegator's epoch score on `identityId` into TRAC,
     *      lazily materializing the node's operator-fee split for `(e,
     *      identityId)` on first touch. Extracted from the `_claim` epoch
     *      loop (v10.0.3) so reward carries share the exact same math.
     *
     *      H1 note — on epochs with `scorePerStake36 > 0 && nodeScore18 ==
     *      0` this returns 0. That combination is essentially impossible in
     *      production (score-per-stake can only be advanced by submitProof,
     *      which also adds to node score), but defensive: there is no fee
     *      to collect and no reward.
     */
    function _nodeEpochReward(
        uint256 e,
        uint72 identityId,
        uint256 delegatorScore18
    ) internal returns (uint256 epochReward) {
        uint256 nodeScore18 = randomSamplingStorage.getNodeEpochScore(e, identityId);
        if (nodeScore18 == 0) return 0;

        uint256 netNodeRewards;
        if (!convictionStorage.isOperatorFeeClaimedForEpoch(identityId, e)) {
            uint256 allNodesScore18 = randomSamplingStorage.getAllNodesEpochScore(e);
            if (allNodesScore18 > 0) {
                uint256 grossNodeRewards = (epochStorage.getEpochPool(EPOCH_POOL_INDEX, e)
                    * nodeScore18) / allNodesScore18;
                uint96 operatorFeeAmount = uint96(
                    (grossNodeRewards
                        * profileStorage.getOperatorFeePercentageByTimestampReverse(identityId, chronos.timestampForEpoch(e + 1) - 1))
                        / parametersStorage.maxOperatorFee()
                );
                netNodeRewards = grossNodeRewards - operatorFeeAmount;
                convictionStorage.setIsOperatorFeeClaimedForEpoch(identityId, e, true);
                convictionStorage.setNetNodeEpochRewards(identityId, e, netNodeRewards);
                // v4.0.0 — operator-fee balance lives on CSS now.
                convictionStorage.increaseOperatorFeeBalance(identityId, operatorFeeAmount);
            }
        } else {
            netNodeRewards = convictionStorage.getNetNodeEpochRewards(identityId, e);
        }

        if (delegatorScore18 > 0) {
            epochReward = (delegatorScore18 * netNodeRewards) / nodeScore18;
        }
    }

    /**
     * @dev D26 — settle the delegator's score accumulator for `epoch` up to
     *      the latest on-chain proof. If the position lives on `identityId`,
     *      integrate using its current effective stake, splitting at
     *      `expiryTimestamp` when the boost transition lands inside `epoch`.
     *      Otherwise (redelegate to a different node, or migration baseline)
     *      just bump the delegator's cursor to the current last-value.
     */
    function _prepareForStakeChangeV10(
        uint256 epoch,
        uint256 tokenId,
        uint72 identityId
    ) internal returns (uint256 delegatorScore) {
        bytes32 delegatorKey = bytes32(tokenId);
        ConvictionStakingStorage.Position memory pos = convictionStorage.getPosition(tokenId);

        uint256 nodeScorePerStake36 = randomSamplingStorage.getEpochLastScorePerStake(identityId, epoch);
        uint256 currentDelegatorScore18 = randomSamplingStorage.getEpochNodeDelegatorScore(
            epoch,
            identityId,
            delegatorKey
        );
        uint256 lastSettled = randomSamplingStorage.getDelegatorLastSettledNodeEpochScorePerStake(
            epoch,
            identityId,
            delegatorKey
        );

        if (nodeScorePerStake36 == lastSettled) {
            return currentDelegatorScore18;
        }

        uint256 scoreEarned18 = 0;
        if (pos.identityId == identityId) {
            uint256 rawU = uint256(pos.raw);
            uint256 mult18 = uint256(pos.multiplier18);
            uint256 expiryTs = uint256(pos.expiryTimestamp);
            uint256 expiryEpoch = expiryTs == 0 ? 0 : chronos.epochAtTimestamp(expiryTs);
            uint256 effBoosted = (rawU * mult18) / SCALE18;
            uint256 effBase = rawU;

            scoreEarned18 = _delegatorIncrementForEpoch(
                epoch,
                identityId,
                nodeScorePerStake36,
                lastSettled,
                effBoosted,
                effBase,
                expiryTs,
                expiryEpoch
            );
        }

        if (scoreEarned18 > 0) {
            randomSamplingStorage.addToEpochNodeDelegatorScore(epoch, identityId, delegatorKey, scoreEarned18);
        }
        randomSamplingStorage.setDelegatorLastSettledNodeEpochScorePerStake(
            epoch,
            identityId,
            delegatorKey,
            nodeScorePerStake36
        );

        return currentDelegatorScore18 + scoreEarned18;
    }

    /**
     * @dev H2 — shared D26 expiry-split reward integration. Returns the
     *      delegator's earned score increment (18-decimals) across the
     *      settlement window `(lastSettled, current]` in epoch `epoch`,
     *      honoring the position's boost transition at `expiryTs`.
     *
     * Cases, in order:
     *   * `current <= lastSettled`       → nothing to integrate.
     *   * `expiryTs == 0`                → tier-0 rest state; no boost
     *                                      transition ever. Use `effBase`.
     *   * `epoch < expiryEpoch`          → boost fully active in epoch.
     *                                      Use `effBoosted`.
     *   * `epoch > expiryEpoch`          → boost already dropped for the
     *                                      whole epoch. Use `effBase`.
     *   * `epoch == expiryEpoch` with
     *     `effBoosted == effBase`        → M4: boost delta is zero (1x
     *                                      "locked" tier). Skip the
     *                                      binary search, integrate with
     *                                      `effBase`.
     *   * `epoch == expiryEpoch` with
     *     `effBoosted > effBase`         → one binary search into the
     *                                      epoch's checkpoint array gives
     *                                      scorePerStake strictly before the
     *                                      expiry second; integrate the
     *                                      left half at boosted rate and
     *                                      the right half at base rate.
     *                                      `scoreBeforeExpiry` below the
     *                                      delegator cursor collapses
     *                                      back to the base-rate path.
     */
    function _delegatorIncrementForEpoch(
        uint256 epoch,
        uint72 identityId,
        uint256 current,
        uint256 lastSettled,
        uint256 effBoosted,
        uint256 effBase,
        uint256 expiryTs,
        uint256 expiryEpoch
    ) internal view returns (uint256) {
        if (current <= lastSettled) return 0;

        if (expiryTs == 0 || epoch < expiryEpoch) {
            uint256 eff = expiryTs == 0 ? effBase : effBoosted;
            return (eff * (current - lastSettled)) / SCALE18;
        }
        if (epoch > expiryEpoch) {
            return (effBase * (current - lastSettled)) / SCALE18;
        }
        // epoch == expiryEpoch.
        if (effBoosted == effBase) {
            // M4 — degenerate tier (duration>0, mult==1x). No boost delta at
            //      expiry, so no split is needed and we skip the binary
            //      search.
            return (effBase * (current - lastSettled)) / SCALE18;
        }
        uint256 scoreBeforeExpiry = randomSamplingStorage.findScorePerStakeAt(
            identityId,
            epoch,
            uint40(expiryTs - 1)
        );
        if (scoreBeforeExpiry > lastSettled) {
            return
                (effBoosted * (scoreBeforeExpiry - lastSettled)) / SCALE18 +
                (effBase * (current - scoreBeforeExpiry)) / SCALE18;
        }
        return (effBase * (current - lastSettled)) / SCALE18;
    }
}

contracts/storage/AskStorage.sol.content:
// SPDX-License-Identifier: Apache-2.0

pragma solidity ^0.8.20;

import {ParametersStorage} from "../storage/ParametersStorage.sol";
import {INamed} from "../interfaces/INamed.sol";
import {IVersioned} from "../interfaces/IVersioned.sol";
import {IInitializable} from "../interfaces/IInitializable.sol";
import {ContractStatus} from "../abstract/ContractStatus.sol";

contract AskStorage is INamed, IVersioned, ContractStatus, IInitializable {
    string private constant _NAME = "AskStorage";
    string private constant _VERSION = "10.0.2";

    ParametersStorage public parametersStorage;

    uint256 public prevWeightedActiveAskSum;
    uint256 public weightedActiveAskSum;

    uint96 public prevTotalActiveStake;
    uint96 public totalActiveStake;

    // solhint-disable-next-line no-empty-blocks
    constructor(address hubAddress) ContractStatus(hubAddress) {}

    function initialize() public onlyHub {
        parametersStorage = ParametersStorage(hub.getContractAddress("ParametersStorage"));
    }

    function name() public pure virtual returns (string memory) {
        return _NAME;
    }

    function version() external pure virtual returns (string memory) {
        return _VERSION;
    }

    function getPricePerKbEpoch() external view returns (uint256) {
        return getStakeWeightedAverageAsk();
    }

    function getPrevPricePerKbEpoch() external view returns (uint256) {
        return getPrevStakeWeightedAverageAsk();
    }

    function getStakeWeightedAverageAsk() public view returns (uint256) {
        return totalActiveStake > 0 ? weightedActiveAskSum / totalActiveStake : 0;
    }

    function getPrevStakeWeightedAverageAsk() public view returns (uint256) {
        return prevTotalActiveStake > 0 ? prevWeightedActiveAskSum / prevTotalActiveStake : 0;
    }

    function getAskLowerBound() external view returns (uint256) {
        return (prevWeightedActiveAskSum * parametersStorage.askLowerBoundFactor()) / prevTotalActiveStake;
    }

    function getAskUpperBound() external view returns (uint256) {
        return (prevWeightedActiveAskSum * parametersStorage.askUpperBoundFactor()) / prevTotalActiveStake;
    }

    function getAskBounds() external view returns (uint256, uint256) {
        ParametersStorage params = parametersStorage;

        return (
            (prevWeightedActiveAskSum * params.askLowerBoundFactor()) / prevTotalActiveStake,
            (prevWeightedActiveAskSum * params.askUpperBoundFactor()) / prevTotalActiveStake
        );
    }

    function setWeightedActiveAskSum(uint256 _weightedActiveAskSum) external onlyContracts {
        weightedActiveAskSum = _weightedActiveAskSum;
    }

    function increaseWeightedActiveAskSum(uint256 amount) external onlyContracts {
        weightedActiveAskSum += amount;
    }

    function decreaseWeightedActiveAskSum(uint256 amount) external onlyContracts {
        weightedActiveAskSum -= amount;
    }

    function setPrevWeightedActiveAskSum(uint256 _prevWeightedActiveAskSum) external onlyContracts {
        prevWeightedActiveAskSum = _prevWeightedActiveAskSum;
    }

    function setTotalActiveStake(uint96 _totalActiveStake) external onlyContracts {
        totalActiveStake = _totalActiveStake;
    }

    function increaseTotalActiveStake(uint96 amount) external onlyContracts {
        totalActiveStake += amount;
    }

    function decreaseTotalActiveStake(uint96 amount) external onlyContracts {
        totalActiveStake -= amount;
    }

    function setPrevTotalActiveStake(uint96 _prevTotalActiveStake) external onlyContracts {
        prevTotalActiveStake = _prevTotalActiveStake;
    }
}

contracts/storage/CGWeightTreeStorage.so.content:
// SPDX-License-Identifier: Apache-2.0

pragma solidity ^0.8.20;

import {SafeCast} from "@openzeppelin/contracts/utils/math/SafeCast.sol";

import {Chronos} from "./Chronos.sol";
import {ContextGraphValueStorage} from "./ContextGraphValueStorage.sol";
import {HubDependent} from "../abstract/HubDependent.sol";
import {INamed} from "../interfaces/INamed.sol";
import {IVersioned} from "../interfaces/IVersioned.sol";
import {IInitializable} from "../interfaces/IInitializable.sol";

/**
 * @title CGWeightTreeStorage
 * @notice Fenwick / Binary-Indexed-Tree index over Context-Graph ids for O(log)
 *         value-weighted challenge selection in RandomSampling. See
 *         docs/rfcs/scalable-weighted-cg-sampling.md.
 *
 *         - `cgWeight[cg]` is the CG's approximate current-epoch weight (the Fenwick leaf).
 *         - `bit`         holds standard BIT partial range sums over a FIXED power-of-two capacity.
 *         - `bitTotal`    is the cached Σ cgWeight == prefixSum(BIT_CAPACITY).
 *
 *         `ContextGraphValueStorage` is the source of truth; this tree is an
 *         eventually-consistent fast index reconciled by `settle`. Challenge
 *         correctness never depends on weight freshness (RandomSampling's KA
 *         filter drops expired KAs after the draw), so leaves may be approximate.
 *
 * @dev CAPACITY IS FIXED AT DEPLOY — never grow it. A mapping-backed Fenwick whose
 *      logical size grows is silently wrong: when the live id count crosses a 2^k
 *      boundary, the newly-relevant internal node bit[2^k] must cover (0, 2^k] but
 *      never received the point updates written to lower leaves before it "existed",
 *      so prefixSum past that boundary is permanently short — no revert, bitTotal
 *      stays self-consistent, only the draw distribution is wrong. Fixing capacity up
 *      front makes every leaf's update path reach all its ancestors from the start;
 *      the mapping is sparse so unused leaves cost nothing. Because RandomSampling is
 *      a fresh-deploy contract, capacity is (re)chosen per deploy via the constructor.
 */
contract CGWeightTreeStorage is INamed, IVersioned, IInitializable, HubDependent {
    using SafeCast for uint256;
    using SafeCast for int256;

    string private constant _NAME = "CGWeightTreeStorage";
    string private constant _VERSION = "1.0.0";

    /// @dev Thrown by _bitUpdate when an id is 0 (Fenwick is 1-based; lowbit(0)==0 loops
    ///      forever) or >= BIT_CAPACITY (the update loop would no-op yet bitTotal would
    ///      still move — silently breaking the Σ-consistency invariant). Real guard, not
    ///      just "size capacity big enough": defense-in-depth vs the monotonic CG counter.
    error CgIdOutOfBitCapacity(uint256 cg, uint256 capacity);
    error CapacityNotPowerOfTwo(uint256 capacity);
    error NotBackfilling();

    event WeightSet(uint256 indexed cg, uint256 oldWeight, uint256 newWeight);
    event BackfillFinalized(uint256 bitTotal);

    Chronos public chronos;
    ContextGraphValueStorage public contextGraphValueStorage;

    /// @notice Fixed power-of-two capacity; valid CG ids are 1..BIT_CAPACITY-1.
    uint256 public immutable BIT_CAPACITY;

    mapping(uint256 index => uint256) internal bit; // Fenwick partial range sums
    mapping(uint256 cg => uint256) public cgWeight; // explicit per-CG leaf (O(1) reads)
    uint256 public bitTotal; // cached Σ cgWeight == prefixSum(BIT_CAPACITY)
    mapping(uint256 cg => uint256) public cgSettledEpoch; // epoch the leaf was last reconciled to
    bool public backfillLocked; // true during migration seeding; gates `seed`

    constructor(address hubAddress, uint256 bitCapacity) HubDependent(hubAddress) {
        // Power-of-two so the descent's top step is exactly BIT_CAPACITY and lowbit math is clean.
        if (bitCapacity == 0 || (bitCapacity & (bitCapacity - 1)) != 0) {
            revert CapacityNotPowerOfTwo(bitCapacity);
        }
        BIT_CAPACITY = bitCapacity;
        backfillLocked = true; // released by finishBackfill() once seeding completes
    }

    function initialize() public virtual override onlyHub {
        chronos = Chronos(hub.getContractAddress("Chronos"));
        contextGraphValueStorage = ContextGraphValueStorage(hub.getContractAddress("ContextGraphValueStorage"));
    }

    function name() external pure virtual override returns (string memory) {
        return _NAME;
    }

    function version() external pure virtual override returns (string memory) {
        return _VERSION;
    }

    // -------------------------------------------------------------------------
    // Fenwick primitives
    // -------------------------------------------------------------------------

    /// @dev Standard Fenwick point update by a signed delta; keeps bitTotal in sync.
    function _bitUpdate(uint256 i, int256 delta) internal {
        // Guard first (unconditional): an out-of-range/zero id must revert even on a no-op delta,
        // matching the docstring's defense-in-depth intent against the monotonic CG counter.
        if (i == 0 || i >= BIT_CAPACITY) revert CgIdOutOfBitCapacity(i, BIT_CAPACITY);
        if (delta == 0) return;
        for (uint256 x = i; x <= BIT_CAPACITY; x += (x & (~x + 1))) {
            bit[x] = (bit[x].toInt256() + delta).toUint256(); // never underflows: see invariants
        }
        // Slither flags this cached-total SSTORE as "costly op in a loop" via the settleMany/
        // seedMany batch call stacks; updating bitTotal once per leaf change is required and is
        // the whole point of the cached total (O(1) reads).
        // slither-disable-next-line costly-loop
        bitTotal = (bitTotal.toInt256() + delta).toUint256();
    }

    /// @notice Smallest index whose prefix sum is STRICTLY greater than `r` (mirrors the
    ///         legacy `running > r` straddle). Capacity is a fixed power of two, so the top
    ///         step is BIT_CAPACITY — no highest-bit computation needed. Caller guarantees
    ///         `r < bitTotal`.
    function findStrictGt(uint256 r) public view returns (uint256 idx) {
        uint256 cum = 0;
        idx = 0;
        for (uint256 step = BIT_CAPACITY; step != 0; step >>= 1) {
            uint256 next = idx + step;
            if (next <= BIT_CAPACITY && cum + bit[next] <= r) {
                // <= r ⇒ still go right
                idx = next;
                cum += bit[next];
            }
        }
        idx += 1; // first index that pushes the running sum strictly past r
    }

    /// @notice Renormalized strict-gt search over (all weighted CGs \ `excluded`).
    ///         Subtracts each excluded leaf's contribution DURING the descent, which
    ///         reproduces the legacy "re-summed adjustedTotal" distribution exactly —
    ///         do NOT replace with an "advance to next nonzero leaf" walk (that skews the
    ///         distribution and starves the tail). Caller guarantees `r < workingTotal`.
    ///         O(excluded.length · log).
    function findStrictGtExcluding(uint256 r, uint256[] memory excluded) public view returns (uint256 idx) {
        uint256 cum = 0;
        idx = 0;
        for (uint256 step = BIT_CAPACITY; step != 0; step >>= 1) {
            uint256 next = idx + step;
            if (next > BIT_CAPACITY) continue;
            // bit[next] covers ids (idx, next]; net out any excluded leaves in that span.
            // Cannot underflow: excluded leaves in (idx, next] are a subset of bit[next]'s sum.
            uint256 nodeSum = bit[next] - _excludedInRange(idx + 1, next, excluded);
            if (cum + nodeSum <= r) {
                idx = next;
                cum += nodeSum;
            }
        }
        idx += 1;
        // idx can never be an excluded CG: its leaf was netted out of every enclosing nodeSum.
    }

    /// @notice Working total for a renormalized draw = bitTotal − Σ current weight of excluded ids.
    ///         Recompute per attempt (a prior settle may have moved bitTotal).
    function workingTotal(uint256[] memory excluded) public view returns (uint256) {
        return bitTotal - _excludedSum(excluded);
    }

    function _excludedInRange(uint256 lo, uint256 hi, uint256[] memory excluded) internal view returns (uint256 s) {
        uint256 n = excluded.length;
        for (uint256 j = 0; j < n; j++) {
            uint256 e = excluded[j];
            if (e >= lo && e <= hi) s += cgWeight[e];
        }
    }

    function _excludedSum(uint256[] memory excluded) internal view returns (uint256 s) {
        uint256 n = excluded.length;
        for (uint256 j = 0; j < n; j++) s += cgWeight[excluded[j]];
    }

    // -------------------------------------------------------------------------
    // Migration seeding (permissioned, only while backfill-locked)
    // -------------------------------------------------------------------------

    /// @notice Set a CG's leaf to `weight` during the one-time migration backfill.
    ///         Restricted to the locked window so weights can only be injected during
    ///         seeding; post-unlock the only writer is `settle` (reconcile to truth).
    function seed(uint256 cg, uint256 weight) external onlyContracts {
        if (!backfillLocked) revert NotBackfilling();
        _setWeight(cg, weight);
    }

    function seedMany(uint256[] calldata cgs, uint256[] calldata weights) external onlyContracts {
        if (!backfillLocked) revert NotBackfilling();
        uint256 n = cgs.length;
        require(n == weights.length, "len mismatch");
        for (uint256 k = 0; k < n; k++) _setWeight(cgs[k], weights[k]);
    }

    /// @notice End the migration backfill; enables the prod draw/settle path in RandomSampling.
    ///         One-way and not re-callable, so an accidental double-call reverts loudly rather than
    ///         silently re-emitting. Recovery from a premature call is a fresh redeploy (capacity is
    ///         immutable and chosen per deploy anyway).
    function finishBackfill() external onlyContracts {
        if (!backfillLocked) revert NotBackfilling();
        backfillLocked = false;
        emit BackfillFinalized(bitTotal);
    }

    // -------------------------------------------------------------------------
    // Lazy settlement (the only place truth meets the index)
    // -------------------------------------------------------------------------

    /// @notice Reconcile a CG's leaf to its true current-epoch weight in the ledger, and
    ///         finalize the ledger so subsequent reads of this CG are O(1). Permissionless
    ///         by design (settle-on-spend, settle-on-miss, keeper): finalizeCGValueUpTo is
    ///         onlyContracts but the call originates from this Hub-registered contract.
    // Slither: the "reentrancy" detectors flag the state writes after finalizeCGValueUpTo/
    // getCGValueAtEpoch, but those callees are TRUSTED Hub-registered storage contracts that do
    // pure storage math — no ETH/token transfer, no low-level call, no untrusted callback — so
    // there is no reentrancy surface. State-after-call ordering is required (finalize must run
    // before the value read).
    // slither-disable-next-line reentrancy-no-eth,reentrancy-benign,reentrancy-events
    function settle(uint256 cg) public {
        uint256 currentEpoch = chronos.getCurrentEpoch();
        if (currentEpoch > 0) contextGraphValueStorage.finalizeCGValueUpTo(cg, currentEpoch - 1);
        uint256 truth = contextGraphValueStorage.getCGValueAtEpoch(cg, currentEpoch);
        _setWeight(cg, truth);
        cgSettledEpoch[cg] = currentEpoch;
    }

    /// @notice Permissionless batch settle (keeper backstop for dormant / under-stated CGs).
    // Slither: external calls inside the loop are unavoidable for a batch settle; each callee is
    // a trusted Hub storage contract (see settle). The batch is caller-bounded.
    // slither-disable-next-line calls-loop
    function settleMany(uint256[] calldata cgs) external {
        uint256 n = cgs.length;
        for (uint256 k = 0; k < n; k++) settle(cgs[k]);
    }

    function _setWeight(uint256 cg, uint256 weight) internal {
        uint256 cached = cgWeight[cg];
        if (weight != cached) {
            _bitUpdate(cg, weight.toInt256() - cached.toInt256());
            cgWeight[cg] = weight;
            emit WeightSet(cg, cached, weight);
        }
    }
}

contracts/storage/Chronos.sol.content:
// SPDX-License-Identifier: Apache-2.0

pragma solidity ^0.8.20;

contract Chronos {
    uint256 public immutable START_TIME;
    uint256 public immutable EPOCH_LENGTH;

    error InvalidStartTime();
    error InvalidEpochLength();

    constructor(uint256 _startTime, uint256 _epochLength) {
        if (_startTime <= 0) {
            revert InvalidStartTime();
        }
        if (_epochLength <= 0) {
            revert InvalidEpochLength();
        }

        START_TIME = _startTime;
        EPOCH_LENGTH = _epochLength;
    }

    function startTime() external view returns (uint256) {
        return START_TIME;
    }

    function epochLength() external view returns (uint256) {
        return EPOCH_LENGTH;
    }

    function getCurrentEpoch() external view returns (uint256) {
        if (block.timestamp < START_TIME) {
            return 1;
        }
        return ((block.timestamp - START_TIME) / EPOCH_LENGTH) + 1;
    }

    function epochAtTimestamp(uint256 timestamp) external view returns (uint256) {
        if (timestamp < START_TIME) {
            return 1;
        }
        return ((timestamp - START_TIME) / EPOCH_LENGTH) + 1;
    }

    function timeUntilNextEpoch() external view returns (uint256) {
        if (block.timestamp < START_TIME) {
            return START_TIME + EPOCH_LENGTH - block.timestamp;
        }
        // Slither: `block.timestamp % EPOCH_LENGTH` is flagged as weak-PRNG
        // because miners can nudge `block.timestamp` within a small window.
        // This is deterministic time math, NOT randomness — the modulo
        // computes "seconds elapsed since the start of the current epoch",
        // which has the same minor miner-influence as `block.timestamp`
        // itself does (already trusted protocol-wide for epoch advancement).
        // No randomness derivation, no PRNG semantics.
        // slither-disable-next-line weak-prng
        uint256 elapsed = (block.timestamp - START_TIME) % EPOCH_LENGTH;
        return EPOCH_LENGTH - elapsed;
    }

    function hasEpochElapsed(uint256 epochNumber) external view returns (bool) {
        return block.timestamp >= (START_TIME + (epochNumber - 1) * EPOCH_LENGTH);
    }

    function timestampForEpoch(uint256 epochNumber) external view returns (uint256) {
        if (epochNumber == 0) {
            return 0;
        }
        return START_TIME + (epochNumber - 1) * EPOCH_LENGTH;
    }

    function elapsedTimeInCurrentEpoch() external view returns (uint256) {
        if (block.timestamp < START_TIME) {
            return 0;
        }
        // Slither weak-prng — deterministic time math, not randomness.
        // See `timeUntilNextEpoch` above for the long-form rationale.
        // slither-disable-next-line weak-prng
        return (block.timestamp - START_TIME) % EPOCH_LENGTH;
    }

    function totalElapsedTime() external view returns (uint256) {
        if (block.timestamp < START_TIME) {
            return 0;
        }
        return block.timestamp - START_TIME;
    }

    function isChronosActive() external view returns (bool) {
        return block.timestamp >= START_TIME;
    }
}

contracts/storage/ContextGraphStorage.so.content:
// SPDX-License-Identifier: Apache-2.0

pragma solidity ^0.8.20;

import {Guardian} from "../Guardian.sol";
import {KnowledgeAssetsLib} from "../libraries/KnowledgeAssetsLib.sol";
import {INamed} from "../interfaces/INamed.sol";
import {IVersioned} from "../interfaces/IVersioned.sol";
import {ERC721} from "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import {ERC721Enumerable} from "@openzeppelin/contracts/token/ERC721/extensions/ERC721Enumerable.sol";

/**
 * @title ContextGraphStorage
 * @notice ERC-721 registry for Context Graphs. Each CG is an NFT — the token holder
 *         has management authority (publish policy, participants).
 *
 * Inherits Guardian for Hub-based access control and ERC721Enumerable for
 * transferable governance tokens. The logic facade (ContextGraphs.sol) remains
 * stateless and replaceable; all state lives here.
 *
 * Design notes:
 *   - Per-CG hosting committees and per-CG quorum were removed in
 *     SPEC_CG_MEMORY_MODEL. Every CG is hosted by the network's sharding
 *     table at publish time, and the ACK quorum is the system parameter
 *     `parametersStorage.minimumRequiredSignatures()`. The CG records only
 *     the participant-agent allow-list (addresses used for curated / PCA
 *     flows).
 *   - 3 curator types are supported via (publishAuthority, publishAuthorityAccountId):
 *       EOA      -> publishAuthority = wallet, accountId = 0
 *       Safe     -> publishAuthority = multisig contract, accountId = 0
 *       PCA      -> publishAuthority = account-owner address (read-only marker),
 *                   accountId = DKGPublishingConvictionNFT account ID
 *     The facade is responsible for resolving curator type at publish time.
 *   - `kaToContextGraph` reverse lookup and `_contextGraphKAList` forward list
 *     are written via `registerKnowledgeAssetToContextGraph` (called from the publish flow
 *     in Phase 8) and read by Phase 10 random sampling.
 *   - The legacy `addBatchToContextGraph` / `_contextGraphBatches` /
 *     `_attestedRoots` / `verifyTripleInclusion` surface is REMOVED. The
 *     deleted Merkle-inclusion path closes audit finding H2 (forged inclusion
 *     proofs via caller-supplied storage address).
 */
contract ContextGraphStorage is INamed, IVersioned, Guardian, ERC721Enumerable {
    string private constant _NAME = "ContextGraphStorage";
    // 10.0.3 — KC→KA terminology: public getters renamed getContextGraphKCCount/At/List →
    //          getContextGraphKaCount/At/List (ABI selector change; no behavior change).
    // 10.0.4 — OT-RFC-53: per-CG registration-escrow accounting (get/set/decrease/
    //          clear) consumed by the deposit pull + admin sweep. ABI surface addition.
    // 10.0.6 — Decoupled sampling list: a SECOND per-CG array (`_samplingKAList`)
    //          drives random sampling and is the one the keeper compacts, while
    //          `_contextGraphKAList` stays strictly append-only as the
    //          registration-ordinal source the off-chain chain-reconciler reads
    //          (`getContextGraphKaCount/At`). Pruning expired KAs from sampling no
    //          longer mutates that ordinal, so the reconciler's [watermark, head)
    //          cursor can never skip a later publish. Adds getSamplingKaCount/At;
    //          swapRemoveSamplingKnowledgeAssetAt now targets the sampling list.
    string private constant _VERSION = "10.0.6";

    // -----------------------------------------------------------------------
    // Bounds on participant list — anti-griefing cap.
    //
    // MAX_PARTICIPANT_AGENTS bounds both the O(n^2) creation-time dedup and
    // the O(n) shift-left in `removeParticipantAgent` to ~1.3M gas worst case.
    // -----------------------------------------------------------------------
    uint256 public constant MAX_PARTICIPANT_AGENTS = 256;

    // -----------------------------------------------------------------------
    // Storage layout — fresh design (no prior deployments to preserve).
    // -----------------------------------------------------------------------

    uint256 private _contextGraphCounter;

    // Core context graph metadata (no participant list; that lives in its
    // own mapping to avoid struct↔dynamic-array mutability constraints).
    mapping(uint256 contextGraphId => KnowledgeAssetsLib.ContextGraph) private _contextGraphs;

    // Participant agents: EOA addresses authorised to publish into a curated
    // CG (used as an allow-list for Safe / PCA-agent flows). Insertion order
    // preserved; duplicates rejected.
    // Slither: mappings are zero-initialized by the language (no slot is
    // written until first key insertion). The "uninitialized-state" rule
    // fires on declaration-without-initializer, but there is no
    // initializer syntax for mappings — Solidity rejects it. False
    // positive for every public/private mapping in the codebase.
    // slither-disable-next-line uninitialized-state
    mapping(uint256 contextGraphId => address[]) private _participantAgents;

    // Non-zero when curator type is PCA: the DKGPublishingConvictionNFT
    // account ID whose registered agents are authorised to publish.
    mapping(uint256 contextGraphId => uint256) private _publishAuthorityAccountId;

    // OT-RFC-38 / LU-6 Phase B — opt-in stable identifier the curator
    // commits to at create time. Set to `keccak256(bytes(cleartextId))`
    // by the agent layer so the wire form of SWM gossip (topic,
    // envelope `contextGraphId`, signing payload, host-mode store key)
    // is chain-derivable and privacy-preserving (cleartext never leaves
    // the local node). Hosting cores that hear `ContextGraphCreated`
    // read this and auto-subscribe to `dkg/context-graph/{nameHash}/
    // shared-memory` in host mode — no off-chain discovery channel
    // required for registered CGs. Zero indicates a CG that didn't
    // commit to a name hash (curator chose not to opt in, or it pre-
    // dates this surface); host-mode auto-subscribe is then governed
    // by the discovery beacon path instead.
    mapping(uint256 contextGraphId => bytes32) private _contextGraphNameHash;

    // KA -> CG reverse lookup (Phase 10 random sampling).
    // Public for convenience; zero means "not registered".
    mapping(uint256 kaId => uint256 contextGraphId) public kaToContextGraph;

    // CG -> [KA IDs] APPEND-ONLY registration list. This is the per-CG
    // registration-ordinal source the off-chain chain-reconciler walks as
    // `[watermark, head)` (head = getContextGraphKaCount) — so it MUST stay
    // append-only: never reorder, never shrink. Sampling pruning happens on
    // `_samplingKAList` below, never here.
    mapping(uint256 contextGraphId => uint256[]) private _contextGraphKAList;

    // CG -> [live KA IDs] COMPACTED list that drives within-CG random sampling.
    // Written alongside `_contextGraphKAList` on registration, but the keeper
    // (`RandomSampling.pruneExpiredKnowledgeAssets` → `swapRemoveSamplingKnowledgeAssetAt`)
    // swap-pops EXPIRED KAs out of THIS list only. Decoupling the sampling
    // enumeration from the append-only registration ordinal lets the draw shed
    // dead slots without corrupting the reconciler cursor. Read via
    // getSamplingKaCount/At; the two lists diverge over time by design.
    //
    // POPULATION INVARIANT: `registerKnowledgeAssetToContextGraph` is the SOLE
    // writer of both arrays and always appends to them together — there is no
    // setter or migration that writes `_contextGraphKAList` alone. So a CG can
    // never hold registrations in the append-only list without the matching
    // sampling entries (the "pre-existing KAs invisible to sampling" state is
    // unreachable). This is a fresh-design, non-proxy contract deployed empty for
    // V10 (both lists populate from genesis); should a future deployment ever
    // need to preserve CG state, the migration MUST seed both arrays together.
    mapping(uint256 contextGraphId => uint256[]) private _samplingKAList;

    // OT-RFC-53 — per-CG registration-deposit escrow (anti-spam). Accounting
    // only: the TRAC itself is custodied in the CSS vault (mirrors
    // PublishingConviction's committed-TRAC model). Set at on-chain CG
    // creation, decremented as the owner spends it on publishing into the CG,
    // cleared on an admin sweep to the staker reward pool.
    mapping(uint256 contextGraphId => uint96) private _cgRegistrationEscrow;

    // -----------------------------------------------------------------------
    // Events
    // -----------------------------------------------------------------------

    event ContextGraphCreated(
        uint256 indexed contextGraphId,
        address indexed owner,
        bytes32 indexed nameHash,
        address[] participantAgents,
        uint256 metadataBatchId,
        uint8 accessPolicy,
        uint8 publishPolicy,
        address publishAuthority,
        uint256 publishAuthorityAccountId
    );

    event ContextGraphDeactivated(
        uint256 indexed contextGraphId
    );

    event PublishPolicyUpdated(
        uint256 indexed contextGraphId,
        uint8 publishPolicy,
        address publishAuthority,
        uint256 publishAuthorityAccountId
    );

    event PublishAuthorityUpdated(
        uint256 indexed contextGraphId,
        address newAuthority,
        uint256 newAuthorityAccountId
    );

    event AgentParticipantAdded(
        uint256 indexed contextGraphId,
        address indexed agent
    );

    event AgentParticipantRemoved(
        uint256 indexed contextGraphId,
        address indexed agent
    );

    event KnowledgeAssetRegisteredToContextGraph(
        uint256 indexed contextGraphId,
        uint256 indexed kaId
    );

    constructor(
        address hubAddress
    ) Guardian(hubAddress) ERC721("DKG Context Graph", "DKGCG") {}

    function name() public pure virtual override(INamed, ERC721) returns (string memory) {
        return _NAME;
    }

    function version() external pure virtual returns (string memory) {
        return _VERSION;
    }

    // -----------------------------------------------------------------------
    // Creation
    // -----------------------------------------------------------------------

    /**
     * @notice Create a new context graph and mint its governance NFT.
     * @param owner_                       Recipient of the ERC-721 (token holder == manager).
     * @param participantAgents            EOA allow-list (no zeros, no duplicates).
     * @param metadataBatchId              Batch ID describing the CG metadata (0 if none).
     * @param accessPolicy                 0 = public/discoverable, 1 = private/curated.
     * @param publishPolicy                0 = curated, 1 = open.
     * @param publishAuthority             Curator address. Required when curated; ignored
     *                                     (and forced to address(0)) when open.
     * @param publishAuthorityAccountId    Non-zero for PCA curator type. Requires curated.
     *                                     Forced to 0 when open.
     * @param nameHash                     OT-RFC-38 / LU-6 Phase B — opt-in stable wire
     *                                     identifier the curator commits to (intended to
     *                                     be `keccak256(bytes(cleartextId))`, but the
     *                                     contract is agnostic to the derivation; ANY
     *                                     unique non-zero `bytes32` works). Hosting
     *                                     cores in the sharding table use this to
     *                                     auto-subscribe to the SWM gossip topic on
     *                                     receipt of the `ContextGraphCreated` event.
     *                                     Pass `bytes32(0)` to opt out — host-mode
     *                                     auto-discovery for the CG then relies on the
     *                                     gossip-beacon path (Option β).
     *
     * @dev Hosts and ACK quorum are network-level concerns: the sharding table
     *      supplies hosts at publish time and `parametersStorage.minimumRequiredSignatures()`
     *      sets the quorum. CGs do not declare a per-CG hosting committee.
     */
    function createContextGraph(
        address owner_,
        address[] calldata participantAgents,
        uint256 metadataBatchId,
        uint8 accessPolicy,
        uint8 publishPolicy,
        address publishAuthority,
        uint256 publishAuthorityAccountId,
        bytes32 nameHash
    ) external onlyContracts returns (uint256 contextGraphId) {
        if (owner_ == address(0)) {
            revert KnowledgeAssetsLib.InvalidContextGraphConfig("zero address owner");
        }
        if (participantAgents.length > MAX_PARTICIPANT_AGENTS) {
            revert KnowledgeAssetsLib.InvalidContextGraphConfig("agents cap");
        }
        if (accessPolicy > 1) {
            revert KnowledgeAssetsLib.InvalidContextGraphConfig("invalid accessPolicy");
        }
        if (publishPolicy > 1) {
            revert KnowledgeAssetsLib.InvalidContextGraphConfig("invalid publishPolicy");
        }

        // Curator config is policy-dependent.
        address normalizedAuthority;
        uint256 normalizedAccountId;
        if (publishPolicy == 0) {
            // Curated: authority required; accountId optional (non-zero -> PCA).
            if (publishAuthority == address(0)) {
                revert KnowledgeAssetsLib.InvalidContextGraphConfig("curated requires publishAuthority");
            }
            normalizedAuthority = publishAuthority;
            normalizedAccountId = publishAuthorityAccountId;
        } else {
            // Open: authority + accountId must be empty.
            if (publishAuthority != address(0)) {
                revert KnowledgeAssetsLib.InvalidContextGraphConfig("open policy: zero authority required");
            }
            if (publishAuthorityAccountId != 0) {
                revert KnowledgeAssetsLib.InvalidContextGraphConfig("open policy: zero accountId required");
            }
            normalizedAuthority = address(0);
            normalizedAccountId = 0;
        }

        contextGraphId = ++_contextGraphCounter;

        // CEI ordering: populate ALL CG state below first; `_mint` happens
        // last so the wrapper never observes a half-built (NFT-without-
        // metadata-or-participants) state. `_mint` (not `_safeMint`) is
        // intentional: `owner_` is forwarded from `ContextGraphs.create
        // ContextGraph` as the upstream `msg.sender`, and contract owners
        // without `IERC721Receiver` (DAO timelocks, custom multisigs,
        // factory wrappers) are part of the supported caller set.
        KnowledgeAssetsLib.ContextGraph storage cg = _contextGraphs[contextGraphId];
        cg.metadataBatchId = metadataBatchId;
        cg.active = true;
        cg.createdAt = uint40(block.timestamp);
        cg.accessPolicy = accessPolicy;
        cg.publishPolicy = publishPolicy;
        cg.publishAuthority = normalizedAuthority;

        address[] storage storedAgents = _participantAgents[contextGraphId];
        for (uint256 i; i < participantAgents.length; i++) {
            address agent = participantAgents[i];
            if (agent == address(0)) {
                revert KnowledgeAssetsLib.InvalidContextGraphConfig("zero participant agent");
            }
            // Linear dedup; small lists in practice.
            for (uint256 j; j < i; j++) {
                if (participantAgents[j] == agent) {
                    revert KnowledgeAssetsLib.AgentParticipantAlreadyExists(contextGraphId, agent);
                }
            }
            storedAgents.push(agent);
        }

        if (normalizedAccountId != 0) {
            _publishAuthorityAccountId[contextGraphId] = normalizedAccountId;
        }

        if (nameHash != bytes32(0)) {
            _contextGraphNameHash[contextGraphId] = nameHash;
        }

        _mint(owner_, contextGraphId);

        emit ContextGraphCreated(
            contextGraphId,
            owner_,
            nameHash,
            participantAgents,
            metadataBatchId,
            accessPolicy,
            publishPolicy,
            normalizedAuthority,
            normalizedAccountId
        );
    }

    // -----------------------------------------------------------------------
    // KA <-> CG registration (Phase 8 publish flow + Phase 10 sampling)
    // -----------------------------------------------------------------------

    /**
     * @notice Bind a Knowledge Asset to a Context Graph.
     * @dev Records the reverse lookup (`kaToContextGraph[kaId] = cgId`) and
     *      appends to BOTH per-CG lists: `_contextGraphKAList` (the append-only
     *      registration ordinal the reconciler reads) and `_samplingKAList` (the
     *      compactable sampling enumeration). They start identical; the keeper
     *      later prunes expired entries from the sampling list only.
     *      Reverts on double registration.
     */
    function registerKnowledgeAssetToContextGraph(
        uint256 contextGraphId,
        uint256 kaId
    ) external onlyContracts {
        if (kaId == 0) {
            revert KnowledgeAssetsLib.InvalidContextGraphConfig("zero kaId");
        }
        if (!_contextGraphs[contextGraphId].active) {
            revert KnowledgeAssetsLib.ContextGraphNotActive(contextGraphId);
        }
        uint256 existing = kaToContextGraph[kaId];
        if (existing != 0) {
            revert KnowledgeAssetsLib.KnowledgeAssetAlreadyRegisteredToContextGraph(kaId, existing);
        }
        kaToContextGraph[kaId] = contextGraphId;
        _contextGraphKAList[contextGraphId].push(kaId);
        _samplingKAList[contextGraphId].push(kaId);
        emit KnowledgeAssetRegisteredToContextGraph(contextGraphId, kaId);
    }

    event KnowledgeAssetPrunedFromSamplingList(uint256 indexed contextGraphId, uint256 indexed kaId);

    /// @dev The generic swap-pop below can desync the sampling list from
    ///      `kaToContextGraph`, so it is restricted to the RandomSampling
    ///      contract (the sole component that prunes the list, and only for
    ///      EXPIRED KAs — it checks `endEpoch` before calling). This is stricter
    ///      than `onlyContracts`: it stops a future/buggy Hub contract from
    ///      removing a LIVE KA from sampling while it still reports as registered.
    error OnlyRandomSampling(address caller);

    /**
     * @notice Remove a Knowledge Asset from a Context Graph's SAMPLING list by
     *         swap-and-pop.
     * @dev Called only by `RandomSampling.pruneExpiredKnowledgeAssets` (the
     *      permissionless keeper) to prune EXPIRED KAs, so the sampling
     *      enumeration cannot accumulate dead slots into a within-CG sampling DoS.
     *      Removes ONLY from `_samplingKAList` — the append-only
     *      `_contextGraphKAList` (the reconciler's registration ordinal) is NOT
     *      touched, so a later publish can never be skipped by the reconciler's
     *      cursor. The `kaToContextGraph[kaId]` reverse binding is also left
     *      intact: readers (`getKAContextGraphId`) must still resolve the KA, and
     *      an expired KA can never be re-registered (it cannot be re-published
     *      with the same id), so the double-registration guard stays correct.
     *      `expectedKaId` makes the call a no-op when the slot no longer holds it
     *      (a prior swap-pop moved a different KA into `index`) — robust to stale
     *      indices.
     */
    function swapRemoveSamplingKnowledgeAssetAt(
        uint256 contextGraphId,
        uint256 index,
        uint256 expectedKaId
    ) external {
        if (msg.sender != hub.getContractAddress("RandomSampling")) {
            revert OnlyRandomSampling(msg.sender);
        }
        uint256[] storage list = _samplingKAList[contextGraphId];
        uint256 len = list.length;
        if (index >= len || list[index] != expectedKaId) {
            return; // stale / already moved — skip; pruned on a later draw
        }
        uint256 last = len - 1;
        if (index != last) {
            list[index] = list[last];
        }
        list.pop();
        emit KnowledgeAssetPrunedFromSamplingList(contextGraphId, expectedKaId);
    }

    /**
     * @notice Return the entire KA list for a context graph as a memory array.
     * @dev WARNING — ON-CHAIN CALLERS MUST NOT USE THIS GETTER. Gas cost is
     *      O(n) in the list length and the ABI decode copies the full array
     *      into memory. Phase 10 random sampling and any other on-chain
     *      consumer MUST use `getContextGraphKaAt(cgId, index)` together
     *      with `getContextGraphKaCount(cgId)` to fetch a single element at
     *      a bounded cost. This full-array getter is retained for off-chain
     *      indexers (eth_call) where the gas cost is not charged.
     */
    function getContextGraphKaList(
        uint256 contextGraphId
    ) external view returns (uint256[] memory) {
        return _contextGraphKAList[contextGraphId];
    }

    function getContextGraphKaCount(
        uint256 contextGraphId
    ) external view returns (uint256) {
        return _contextGraphKAList[contextGraphId].length;
    }

    /**
     * @notice Return a single KA id at a given index within a CG's KA list.
     * @dev O(1) indexed accessor for on-chain consumers (Phase 10 random
     *      sampling). Reverts with `InvalidContextGraphConfig("kaIndex oob")`
     *      on out-of-bounds access — empty list rejects all indices.
     */
    function getContextGraphKaAt(
        uint256 contextGraphId,
        uint256 index
    ) external view returns (uint256 kaId) {
        uint256[] storage list = _contextGraphKAList[contextGraphId];
        if (index >= list.length) {
            revert KnowledgeAssetsLib.InvalidContextGraphConfig("kaIndex oob");
        }
        return list[index];
    }

    /**
     * @notice Length of the COMPACTED sampling list (live + not-yet-pruned KAs).
     * @dev This is the count the within-CG random-sampling draw bounds against
     *      (`RandomSampling._pickKa`) and the keeper scans. It shrinks as the
     *      keeper prunes expired KAs — unlike `getContextGraphKaCount`, which is
     *      the monotonic append-only registration count.
     */
    function getSamplingKaCount(
        uint256 contextGraphId
    ) external view returns (uint256) {
        return _samplingKAList[contextGraphId].length;
    }

    /**
     * @notice Single KA id at an index within a CG's compacted sampling list.
     * @dev O(1) accessor for the within-CG draw + the keeper. Reverts
     *      `InvalidContextGraphConfig("samplingIndex oob")` out of bounds.
     */
    function getSamplingKaAt(
        uint256 contextGraphId,
        uint256 index
    ) external view returns (uint256 kaId) {
        uint256[] storage list = _samplingKAList[contextGraphId];
        if (index >= list.length) {
            revert KnowledgeAssetsLib.InvalidContextGraphConfig("samplingIndex oob");
        }
        return list[index];
    }

    // -----------------------------------------------------------------------
    // Deactivation
    // -----------------------------------------------------------------------

    function deactivateContextGraph(
        uint256 contextGraphId
    ) external onlyContracts {
        _requireExists(contextGraphId);
        _contextGraphs[contextGraphId].active = false;
        emit ContextGraphDeactivated(contextGraphId);
    }

    // -----------------------------------------------------------------------
    // OT-RFC-53 — registration-deposit escrow accounting (onlyContracts).
    //
    // `ContextGraphs` writes the balance at on-chain creation and clears it on
    // an admin sweep; `KnowledgeAssetsLifecycle` decrements it as the CG owner
    // funds publishing from the escrow. The underlying TRAC lives in the CSS
    // vault throughout — these functions only move the per-CG accounting.
    // -----------------------------------------------------------------------

    function getRegistrationEscrow(uint256 contextGraphId) external view returns (uint96) {
        return _cgRegistrationEscrow[contextGraphId];
    }

    function setRegistrationEscrow(uint256 contextGraphId, uint96 amount) external onlyContracts {
        _requireExists(contextGraphId);
        _cgRegistrationEscrow[contextGraphId] = amount;
    }

    function decreaseRegistrationEscrow(uint256 contextGraphId, uint96 amount) external onlyContracts {
        _requireExists(contextGraphId);
        uint96 current = _cgRegistrationEscrow[contextGraphId];
        if (amount > current) {
            revert KnowledgeAssetsLib.InvalidContextGraphConfig("escrow underflow");
        }
        _cgRegistrationEscrow[contextGraphId] = current - amount;
    }

    function clearRegistrationEscrow(uint256 contextGraphId) external onlyContracts returns (uint96 cleared) {
        _requireExists(contextGraphId);
        cleared = _cgRegistrationEscrow[contextGraphId];
        if (cleared != 0) {
            _cgRegistrationEscrow[contextGraphId] = 0;
        }
    }

    // -----------------------------------------------------------------------
    // Publish policy & authority
    // -----------------------------------------------------------------------

    /**
     * @notice Replace the publish policy + curator config in a single call.
     * @dev When `publishPolicy == 1` (open), the new authority and accountId
     *      MUST both be zero — open CGs have no curator.
     */
    function updatePublishPolicy(
        uint256 contextGraphId,
        uint8 publishPolicy,
        address publishAuthority,
        uint256 publishAuthorityAccountId
    ) external onlyContracts {
        _requireExists(contextGraphId);
        if (publishPolicy > 1) {
            revert KnowledgeAssetsLib.InvalidContextGraphConfig("invalid publishPolicy");
        }
        if (publishPolicy == 0) {
            if (publishAuthority == address(0)) {
                revert KnowledgeAssetsLib.InvalidContextGraphConfig("curated requires publishAuthority");
            }
        } else {
            if (publishAuthority != address(0)) {
                revert KnowledgeAssetsLib.InvalidContextGraphConfig("open policy: zero authority required");
            }
            if (publishAuthorityAccountId != 0) {
                revert KnowledgeAssetsLib.InvalidContextGraphConfig("open policy: zero accountId required");
            }
        }

        KnowledgeAssetsLib.ContextGraph storage cg = _contextGraphs[contextGraphId];
        cg.publishPolicy = publishPolicy;
        cg.publishAuthority = publishAuthority;
        _publishAuthorityAccountId[contextGraphId] = publishAuthorityAccountId;

        emit PublishPolicyUpdated(
            contextGraphId,
            publishPolicy,
            publishAuthority,
            publishAuthorityAccountId
        );
    }

    /**
     * @notice Update only the curator (authority + accountId), keeping policy.
     * @dev Convenience for rotating an EOA / Safe / PCA without touching the
     *      open/curated bit. Caller is the facade — it is responsible for
     *      gating to the NFT owner.
     */
    function updatePublishAuthority(
        uint256 contextGraphId,
        address newAuthority,
        uint256 newAuthorityAccountId
    ) external onlyContracts {
        _requireExists(contextGraphId);
        KnowledgeAssetsLib.ContextGraph storage cg = _contextGraphs[contextGraphId];
        if (cg.publishPolicy == 0) {
            // Curated: authority required.
            if (newAuthority == address(0)) {
                revert KnowledgeAssetsLib.InvalidContextGraphConfig("curated requires publishAuthority");
            }
        } else {
            // Open: authority + accountId must remain empty.
            if (newAuthority != address(0) || newAuthorityAccountId != 0) {
                revert KnowledgeAssetsLib.InvalidContextGraphConfig("open policy: clear authority/accountId");
            }
        }
        cg.publishAuthority = newAuthority;
        _publishAuthorityAccountId[contextGraphId] = newAuthorityAccountId;

        emit PublishAuthorityUpdated(contextGraphId, newAuthority, newAuthorityAccountId);
    }

    // -----------------------------------------------------------------------
    // Participant agent governance
    // -----------------------------------------------------------------------

    function addParticipantAgent(
        uint256 contextGraphId,
        address agent
    ) external onlyContracts {
        _requireExists(contextGraphId);
        if (agent == address(0)) {
            revert KnowledgeAssetsLib.InvalidContextGraphConfig("zero participant agent");
        }
        address[] storage agents = _participantAgents[contextGraphId];
        uint256 len = agents.length;
        if (len >= MAX_PARTICIPANT_AGENTS) {
            revert KnowledgeAssetsLib.InvalidContextGraphConfig("agents cap");
        }
        for (uint256 i; i < len; i++) {
            if (agents[i] == agent) {
                revert KnowledgeAssetsLib.AgentParticipantAlreadyExists(contextGraphId, agent);
            }
        }
        agents.push(agent);
        emit AgentParticipantAdded(contextGraphId, agent);
    }

    /// @notice Remove an agent from the participant allow-list.
    /// @dev Shift-left preserves insertion order for deterministic off-chain
    ///      iteration. Gas cost is bounded by MAX_PARTICIPANT_AGENTS
    ///      (~1.3M gas worst case at the 256-entry cap).
    function removeParticipantAgent(
        uint256 contextGraphId,
        address agent
    ) external onlyContracts {
        _requireExists(contextGraphId);
        address[] storage agents = _participantAgents[contextGraphId];
        uint256 len = agents.length;

        for (uint256 i; i < len; i++) {
            if (agents[i] == agent) {
                // Shift left to preserve insertion order (no swap-pop).
                for (uint256 j = i; j < len - 1; j++) {
                    agents[j] = agents[j + 1];
                }
                agents.pop();
                emit AgentParticipantRemoved(contextGraphId, agent);
                return;
            }
        }
        revert KnowledgeAssetsLib.AgentParticipantNotFound(contextGraphId, agent);
    }

    // -----------------------------------------------------------------------
    // Read APIs
    // -----------------------------------------------------------------------

    function getContextGraph(
        uint256 contextGraphId
    ) external view returns (
        address owner_,
        address[] memory participantAgents,
        uint256 metadataBatchId,
        bool active,
        uint256 createdAt,
        uint8 accessPolicy,
        uint8 publishPolicy,
        address publishAuthority,
        uint256 publishAuthorityAccountId
    ) {
        _requireExists(contextGraphId);
        KnowledgeAssetsLib.ContextGraph storage cg = _contextGraphs[contextGraphId];
        return (
            ownerOf(contextGraphId),
            _participantAgents[contextGraphId],
            cg.metadataBatchId,
            cg.active,
            cg.createdAt,
            cg.accessPolicy,
            cg.publishPolicy,
            cg.publishAuthority,
            _publishAuthorityAccountId[contextGraphId]
        );
    }

    function getParticipantAgents(
        uint256 contextGraphId
    ) external view returns (address[] memory) {
        return _participantAgents[contextGraphId];
    }

    function isParticipantAgent(
        uint256 contextGraphId,
        address agent
    ) external view returns (bool) {
        address[] storage agents = _participantAgents[contextGraphId];
        for (uint256 i; i < agents.length; i++) {
            if (agents[i] == agent) return true;
        }
        return false;
    }

    function getContextGraphOwner(
        uint256 contextGraphId
    ) external view returns (address) {
        return ownerOf(contextGraphId);
    }

    function isContextGraphActive(
        uint256 contextGraphId
    ) external view returns (bool) {
        return _contextGraphs[contextGraphId].active;
    }

    function getPublishPolicy(
        uint256 contextGraphId
    ) external view returns (uint8 publishPolicy, address publishAuthority) {
        KnowledgeAssetsLib.ContextGraph storage cg = _contextGraphs[contextGraphId];
        return (cg.publishPolicy, cg.publishAuthority);
    }

    function getAccessPolicy(
        uint256 contextGraphId
    ) external view returns (uint8) {
        return _contextGraphs[contextGraphId].accessPolicy;
    }

    function getPublishAuthorityAccountId(
        uint256 contextGraphId
    ) external view returns (uint256) {
        return _publishAuthorityAccountId[contextGraphId];
    }

    /**
     * @notice OT-RFC-38 / LU-6 Phase B — committed name hash for the CG.
     *         Returns `bytes32(0)` when the curator opted out at create
     *         time (rare; expected only for CGs that pre-date the
     *         Phase B surface or want to rely on the discovery-beacon
     *         path exclusively).
     */
    function getNameHash(
        uint256 contextGraphId
    ) external view returns (bytes32) {
        return _contextGraphNameHash[contextGraphId];
    }

    /**
     * @notice True iff the CG carries curated (encrypted) payloads — i.e.,
     *         the ACCESS policy is curated, regardless of publish policy.
     *
     * Originally this checked `publishPolicy == 0`, but that conflated two
     * orthogonal axes: "who can read" (access) vs. "who can publish".
     * The ciphertext-commitment branch on the KAv10 publish path needs
     * to know whether the payload is ENCRYPTED, which is an access-policy
     * question. The "curated access + open publish" combo (anyone in the
     * allowlist may publish, but readers must still decrypt) is a valid
     * configuration and must accept ciphertext commitments.
     *
     * Used by `RandomSampling._pickWeightedChallenge` step 2 to decide
     * whether the per-KA ciphertext-commitment filter applies (RFC-39
     * Phase A.5). Both call sites converge on this access-policy check.
     */
    function getIsCurated(
        uint256 contextGraphId
    ) external view returns (bool) {
        return _contextGraphs[contextGraphId].accessPolicy != 0;
    }

    function getLatestContextGraphId() external view returns (uint256) {
        return _contextGraphCounter;
    }

    // -----------------------------------------------------------------------
    // Internal
    // -----------------------------------------------------------------------

    function _requireExists(uint256 contextGraphId) internal view {
        _requireOwned(contextGraphId);
    }

    /**
     * @dev Override required by Solidity for ERC721Enumerable.
     */
    function supportsInterface(
        bytes4 interfaceId
    ) public view virtual override(ERC721Enumerable) returns (bool) {
        return super.supportsInterface(interfaceId);
    }

    function _increaseBalance(
        address account,
        uint128 value
    ) internal virtual override(ERC721Enumerable) {
        super._increaseBalance(account, value);
    }

    function _update(
        address to,
        uint256 tokenId,
        address auth
    ) internal virtual override(ERC721Enumerable) returns (address) {
        address from = super._update(to, tokenId, auth);

        // On transfer (not mint/burn, not self-transfer): if the curated
        // publishAuthority was the previous owner, auto-rotate it to the new
        // owner so governance follows the NFT and the old owner can't keep
        // publishing. Always clear the PCA accountId — the new owner is
        // unlikely to be the same PCA, and they must explicitly opt back into
        // PCA mode if desired.
        //
        // Self-transfers (`from == to`) are no-ops for governance: without the
        // `from != to` guard the branch below would trivially evaluate true
        // (publishAuthority == from == to) and silently clear the accountId.
        if (from != address(0) && to != address(0) && from != to) {
            KnowledgeAssetsLib.ContextGraph storage cg = _contextGraphs[tokenId];
            if (cg.publishAuthority == from) {
                cg.publishAuthority = to;
                _publishAuthorityAccountId[tokenId] = 0;
                emit PublishAuthorityUpdated(tokenId, to, 0);
            }
        }

        return from;
    }
}

contracts/storage/ContextGraphValueStora.content:
// SPDX-License-Identifier: Apache-2.0

pragma solidity ^0.8.20;

import {SafeCast} from "@openzeppelin/contracts/utils/math/SafeCast.sol";

import {Chronos} from "./Chronos.sol";
import {HubDependent} from "../abstract/HubDependent.sol";
import {INamed} from "../interfaces/INamed.sol";
import {IVersioned} from "../interfaces/IVersioned.sol";

/**
 * @title ContextGraphValueStorage
 * @notice Lightweight per-CG and global per-epoch TRAC value tracker for V10
 *         value-weighted challenges. Mirrors `EpochStorage.sol` diff/cumulative
 *         finalize pattern at lines 149-174 / 279-310 exactly, but scaled to
 *         int256/uint256 because publish values are wei-of-TRAC and exceed uint96.
 *
 * Design rationale (see V10_CONTRACTS_REDESIGN_v2.md §"Data in
 * ContextGraphValueStorage"): a KA published with value `V` for `lifetime`
 * epochs contributes `V / lifetime` per epoch during its active window
 * [startEpoch, startEpoch + lifetime - 1]. Expiry is handled implicitly by the
 * negative diff written at `startEpoch + lifetime`. No cleanup, no keeper.
 *
 * `addCGValueForEpochRange` uses plain integer division per the spec. A couple
 * wei of rounding dust per publish is acceptable — this mapping is used for
 * challenge weighting, not reward distribution.
 *
 * The dormant shard mappings (`cgShard`, `shardKnowledgeValue`) are reserved
 * storage slots for future V11 sharding. Setters will be added alongside the
 * V11 logic contracts; no API exists today.
 */
contract ContextGraphValueStorage is INamed, IVersioned, HubDependent {
    string private constant _NAME = "ContextGraphValueStorage";
    string private constant _VERSION = "10.0.2";

    event CGValueAddedForEpochRange(
        uint256 indexed cgId,
        uint256 startEpoch,
        uint256 endEpoch,
        uint256 lifetime,
        uint256 value,
        uint256 perEpoch
    );
    event CGValueFinalized(uint256 indexed cgId, uint256 startEpoch, uint256 endEpoch);
    event GlobalValueFinalized(uint256 startEpoch, uint256 endEpoch);

    error ZeroLifetime();
    error ZeroValue();
    error NegativeCumulative();
    error BackfillForbidden();
    error FutureOrCurrentEpoch();

    Chronos public chronos;

    // Per-CG diff/cumulative ledgers.
    mapping(uint256 cgId => mapping(uint256 epoch => int256)) public cgValueDiff;
    mapping(uint256 cgId => mapping(uint256 epoch => uint256)) public cgValueCumulative;
    mapping(uint256 cgId => uint256) public cgLastFinalizedEpoch;

    // Global diff/cumulative ledgers (sum across all CGs).
    mapping(uint256 epoch => int256) public totalValueDiff;
    mapping(uint256 epoch => uint256) public totalValueCumulative;
    uint256 public globalLastFinalizedEpoch;

    /// @dev Reserved storage slots for future V11 sharding. Setters will be
    ///      added alongside the V11 logic contracts; no API exists today.
    mapping(uint256 cgId => uint256) public cgShard;
    mapping(uint256 shardId => mapping(uint256 epoch => uint256)) public shardKnowledgeValue;

    constructor(address hubAddress) HubDependent(hubAddress) {}

    function initialize() public onlyHub {
        chronos = Chronos(hub.getContractAddress("Chronos"));
    }

    function name() external pure virtual override returns (string memory) {
        return _NAME;
    }

    function version() external pure virtual override returns (string memory) {
        return _VERSION;
    }

    // -------------------------------------------------------------------------
    // State mutators
    // -------------------------------------------------------------------------

    /**
     * @notice Record that `value` TRAC will be paid for `cgId` spread evenly
     *         across `lifetime` epochs starting at `startEpoch`. Each epoch in
     *         [startEpoch, startEpoch + lifetime - 1] receives `value/lifetime`.
     * @dev Mirrors `EpochStorage.addTokensToEpochRange`. Finalizes per-CG and
     *      global ledgers up to `currentEpoch - 1` after the diff writes so
     *      stale epochs are crystallized before the next read. Rounding dust is
     *      discarded per the spec (challenge weighting, not reward payout).
     *
     *      Invariant: `startEpoch >= currentEpoch`. Backfilling into an
     *      already-finalized epoch would corrupt `cgValueCumulative` silently
     *      because the cumulative at that epoch has already been crystallized
     *      and subsequent reads hit the fast path. Reverts `BackfillForbidden`
     *      if the caller tries.
     *
     *      Retraction / expiry is automatic via the paired negative diff
     *      written at `startEpoch + lifetime`. There is no removal function
     *      by design: Phase 8 value-changing ops (CREATE, byte-size-grow
     *      UPDATE, lifetime extension) are all positive deltas, and natural
     *      expiry is handled by the diff ledger itself.
     */
    function addCGValueForEpochRange(
        uint256 cgId,
        uint256 startEpoch,
        uint256 lifetime,
        uint256 value
    ) external onlyContracts {
        if (lifetime == 0) {
            revert ZeroLifetime();
        }
        if (value == 0) {
            revert ZeroValue();
        }

        uint256 currentEpoch = chronos.getCurrentEpoch();
        if (startEpoch < currentEpoch) {
            revert BackfillForbidden();
        }

        uint256 perEpoch = value / lifetime;
        int256 perEpochSigned = SafeCast.toInt256(perEpoch);

        cgValueDiff[cgId][startEpoch] += perEpochSigned;
        cgValueDiff[cgId][startEpoch + lifetime] -= perEpochSigned;

        totalValueDiff[startEpoch] += perEpochSigned;
        totalValueDiff[startEpoch + lifetime] -= perEpochSigned;

        if (currentEpoch > 1) {
            _finalizeCGValueUpTo(cgId, currentEpoch - 1);
            _finalizeGlobalValueUpTo(currentEpoch - 1);
        }

        emit CGValueAddedForEpochRange(
            cgId,
            startEpoch,
            startEpoch + lifetime - 1,
            lifetime,
            value,
            perEpoch
        );
    }

    /**
     * @notice Crystallizes `cgValueCumulative[cgId]` up to `epoch` so
     *         subsequent reads at or below `epoch` become O(1). Safe to call
     *         repeatedly: a call with `epoch <= cgLastFinalizedEpoch[cgId]`
     *         is a no-op.
     * @dev Intended to be called by RandomSampling before a challenge draw
     *      (see V10_CONTRACTS_REDESIGN_v2 "On challenge generation"), but any
     *      Hub-registered contract may call it. Reads stay pure `view`; this
     *      is the state-changing half of the "finalize then read" pattern.
     * @dev Reverts FutureOrCurrentEpoch if `epoch` is at or beyond the current
     *      epoch. Only past epochs may be finalized; current-epoch reads always
     *      take the simulation path to reflect in-flight diff writes.
     */
    function finalizeCGValueUpTo(uint256 cgId, uint256 epoch) external onlyContracts {
        if (epoch >= chronos.getCurrentEpoch()) {
            revert FutureOrCurrentEpoch();
        }
        if (epoch <= cgLastFinalizedEpoch[cgId]) {
            return;
        }
        _finalizeCGValueUpTo(cgId, epoch);
    }

    /**
     * @notice Crystallizes `totalValueCumulative` up to `epoch`. See
     *         {finalizeCGValueUpTo} for semantics.
     * @dev Reverts FutureOrCurrentEpoch if `epoch` is at or beyond the current
     *      epoch. Only past epochs may be finalized; current-epoch reads always
     *      take the simulation path to reflect in-flight diff writes.
     */
    function finalizeGlobalValueUpTo(uint256 epoch) external onlyContracts {
        if (epoch >= chronos.getCurrentEpoch()) {
            revert FutureOrCurrentEpoch();
        }
        if (epoch <= globalLastFinalizedEpoch) {
            return;
        }
        _finalizeGlobalValueUpTo(epoch);
    }

    // -------------------------------------------------------------------------
    // Read helpers
    // -------------------------------------------------------------------------

    /// @notice Active per-epoch contribution of `cgId` at `epoch` (sum of all
    ///         active KAs' per-epoch values at that epoch). Returns the
    ///         simulated value if the epoch has not been finalized yet.
    function getCGValueAtEpoch(uint256 cgId, uint256 epoch) public view returns (uint256) {
        if (epoch <= cgLastFinalizedEpoch[cgId]) {
            return cgValueCumulative[cgId][epoch];
        }
        return _simulateCGValueFinalization(cgId, epoch);
    }

    /// @notice Global sum across all CGs of active per-epoch contributions at `epoch`.
    function getTotalValueAtEpoch(uint256 epoch) public view returns (uint256) {
        if (epoch <= globalLastFinalizedEpoch) {
            return totalValueCumulative[epoch];
        }
        return _simulateGlobalValueFinalization(epoch);
    }

    function getCurrentCGValue(uint256 cgId) external view returns (uint256) {
        return getCGValueAtEpoch(cgId, chronos.getCurrentEpoch());
    }

    function getCurrentTotalValue() external view returns (uint256) {
        return getTotalValueAtEpoch(chronos.getCurrentEpoch());
    }

    // -------------------------------------------------------------------------
    // Internal finalization
    // -------------------------------------------------------------------------

    function _finalizeCGValueUpTo(uint256 cgId, uint256 epoch) internal {
        uint256 lastFinalized = cgLastFinalizedEpoch[cgId];
        if (epoch <= lastFinalized) {
            return;
        }

        uint256 startEpoch = lastFinalized + 1;
        int256 running;
        if (lastFinalized > 0) {
            running = int256(cgValueCumulative[cgId][lastFinalized]);
        }

        for (uint256 e = startEpoch; e <= epoch; e++) {
            running += cgValueDiff[cgId][e];
            // Cumulative values are non-negative by construction (positive diffs
            // at startEpoch are always matched by negative diffs at
            // startEpoch+lifetime). Revert defensively on underflow.
            if (running < 0) {
                revert NegativeCumulative();
            }
            cgValueCumulative[cgId][e] = uint256(running);
        }

        cgLastFinalizedEpoch[cgId] = epoch;

        emit CGValueFinalized(cgId, startEpoch, epoch);
    }

    function _finalizeGlobalValueUpTo(uint256 epoch) internal {
        uint256 lastFinalized = globalLastFinalizedEpoch;
        if (epoch <= lastFinalized) {
            return;
        }

        uint256 startEpoch = lastFinalized + 1;
        int256 running;
        if (lastFinalized > 0) {
            running = int256(totalValueCumulative[lastFinalized]);
        }

        for (uint256 e = startEpoch; e <= epoch; e++) {
            running += totalValueDiff[e];
            if (running < 0) {
                revert NegativeCumulative();
            }
            totalValueCumulative[e] = uint256(running);
        }

        globalLastFinalizedEpoch = epoch;

        emit GlobalValueFinalized(startEpoch, epoch);
    }

    function _simulateCGValueFinalization(uint256 cgId, uint256 epoch) internal view returns (uint256) {
        uint256 lastFinalized = cgLastFinalizedEpoch[cgId];
        if (epoch <= lastFinalized) {
            return cgValueCumulative[cgId][epoch];
        }

        int256 running;
        if (lastFinalized > 0) {
            running = int256(cgValueCumulative[cgId][lastFinalized]);
        }

        for (uint256 e = lastFinalized + 1; e <= epoch; e++) {
            running += cgValueDiff[cgId][e];
            // Unify policy with the mutate path (`_finalizeCGValueUpTo`): a
            // negative running total would signal ledger corruption and is an
            // unrecoverable invariant break. Reverting here — even from a view
            // function — gives RPC clients immediate visibility instead of
            // silently clamping to zero.
            if (running < 0) {
                revert NegativeCumulative();
            }
        }

        return uint256(running);
    }

    function _simulateGlobalValueFinalization(uint256 epoch) internal view returns (uint256) {
        uint256 lastFinalized = globalLastFinalizedEpoch;
        if (epoch <= lastFinalized) {
            return totalValueCumulative[epoch];
        }

        int256 running;
        if (lastFinalized > 0) {
            running = int256(totalValueCumulative[lastFinalized]);
        }

        for (uint256 e = lastFinalized + 1; e <= epoch; e++) {
            running += totalValueDiff[e];
            if (running < 0) {
                revert NegativeCumulative();
            }
        }

        return uint256(running);
    }
}

contracts/storage/ConvictionStakingStora.content:
// SPDX-License-Identifier: Apache-2.0

pragma solidity ^0.8.20;

import {Chronos} from "./Chronos.sol";
import {Guardian} from "../Guardian.sol";
import {ICustodian} from "../interfaces/ICustodian.sol";
import {INamed} from "../interfaces/INamed.sol";
import {IVersioned} from "../interfaces/IVersioned.sol";
import {HubLib} from "../libraries/HubLib.sol";
import {StakingLib} from "../libraries/StakingLib.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/**
 * @title ConvictionStakingStorage
 * @notice Primary accounting store AND TRAC vault for V10 staking.
 *
 * V10 architecture (post-consolidation, v4.0.0):
 *   - CSS is the single source of truth for V10 staking: NFT-keyed positions,
 *     per-node stake aggregates, per-epoch operator-fee/net-rewards flags,
 *     per-node operator-fee balances + withdrawal queue, AND the TRAC vault.
 *     There is no separate `StakingStorage` in the V10 hot path.
 *   - The TRAC custody role moved here from V8 `StakingStorage` in v4.0.0:
 *     CSS now extends `Guardian`, so its `tokenContract` reference and
 *     `transferStake` outflow function come from the same base every V10
 *     publish/payment contract uses for vault-routed deposits. Vault-target
 *     consumers (`KnowledgeAssetsLifecycle`, `DKGKnowledgeAssets`, `Paymaster`,
 *     `PublishingConvictionAccount`, `DKGPublishingConvictionNFT`,
 *     `DKGStakingConvictionNFT`) resolve `hub.getContractAddress("ConvictionStakingStorage")`
 *     for both deposits (TRAC `transferFrom` to CSS) and withdrawals
 *     (`StakingV10` calls `cs.transferStake`).
 *   - Migration to V10 is MANDATORY: every V8 delegator becomes a V10 NFT
 *     position. `RandomSampling.calculateNodeScore` therefore reads the
 *     timestamp-accurate effective stake here (raw TRAC × active conviction
 *     multipliers), while raw stake gates still read `nodeStakeV10`. V8
 *     `StakingStorage` is deployed-but-unused dead code post-consolidation;
 *     only `StakingV10._convertToNFT` reads it (V8→V10 drain at cutover).
 *
 * Rewards model (D19 — compound-into-raw):
 *   - The previous split-bucket model (separate `rewards` sidecar that
 *     always earned 1x) has been removed. Claimed rewards compound into
 *     `raw`, so they take on the position's current lock multiplier.
 *   - `cumulativeRewardsClaimed` is now a statistic-only counter for
 *     UI/indexer consumption; it never enters effective-stake math.
 *
 * Tier model (D20 — mutable wall-clock tier ladder):
 *   - Tier durations and multipliers are stored in `_tiers` (keyed by
 *     `lockTier` id). The baseline ladder seeded at `initialize()` is
 *     {0→(0s, 1x), 1→(30d, 1.5x), 3→(90d, 2x), 6→(180d, 3.5x), 12→(366d, 6x)}.
 *   - `expiryTimestamp = block.timestamp + duration`, rounded UP to the
 *     next 12-hour expiry bucket. The upward rounding keeps the promised
 *     minimum lock duration while coalescing per-block dust stakes into
 *     one queue slot per half-day.
 *   - New tiers can be appended via `addTier` (HubOwner or multisig owner).
 *     Existing tiers can be deactivated via `deactivateTier` to stop
 *     accepting NEW fresh stakes, but relock / migration paths still
 *     honor the original commitment (existence-only check). The model is
 *     additive-only: once added a tier id cannot be removed.
 *
 * Effective-stake accounting (D26 — timestamp-accurate):
 *   - Each node carries a `runningNodeEffectiveStake[id]` settled at
 *     `nodeLastSettledAt[id]`, plus a sorted queue of pending boost-
 *     expiry drops (`nodeExpiryTimes[id]` / `nodeExpiryDrop[id][ts]`)
 *     with a monotonic head cursor `nodeExpiryHead[id]`.
 *   - `settleNodeTo(id, ts)` advances the running stake to `ts` by
 *     draining all expiry entries whose timestamp is <= ts. Called by
 *     every CSS mutator before applying its own delta, and by
 *     `RandomSampling.submitProof` before integrating score.
 *   - This replaces the v2.x epoch-diff accumulator (effectiveStakeDiff,
 *     nodeEffectiveStakeDiff, lastFinalizedEpoch, finalize*). Past-epoch
 *     effective-stake snapshots are no longer reconstructable from CSS;
 *     consumers that need them should settle and read "current" state.
 */
contract ConvictionStakingStorage is INamed, IVersioned, Guardian {
    using SafeERC20 for IERC20;

    string private constant _NAME = "ConvictionStakingStorage";
    // Version history:
    //   1.1.0 — split-bucket rewards, discrete tier ladder.
    //   1.2.0 — V10-native pending-withdrawal storage (create/delete/get).
    //   2.0.0 — V10 canonical store (positions + per-node aggregates +
    //           absorbed DelegatorsInfo + tier constants).
    //   2.1.0 — Mutable D20 tier ladder (lockTier rename, _tiers mapping).
    //   2.2.0 — D14/D25 atomic-withdraw & in-place redelegate (removed
    //           PendingWithdrawal).
    //   3.0.0 — D26 timestamp-accurate effective-stake accounting:
    //           * `Position.expiryEpoch` → `Position.expiryTimestamp`
    //             (uint40 seconds-since-unix-epoch, NOT a Chronos epoch).
    //           * Per-node running effective-stake with a sorted pending-
    //             expiry queue. Epoch-diff accumulator, finalize helpers
    //             and their dirty cursors removed.
    //           * `BLOCK_DRIFT_BUFFER` removed (no longer meaningful).
    //   3.1.0 — D26 code-review follow-ups:
    //           * M1 — `updateOnRelock` removed; `createNewPositionFromExisting`
    //             simplified to same-identity-only (cross-identity branch was
    //             unreachable — `redelegate` goes through `updateOnRedelegate`).
    //           * M2 — `nodeExpiryPresent` mapping added so a cancel→reschedule
    //             at the same `ts` doesn't duplicate the queue slot.
    //           * M3/M4 — `addTier` rejects degenerate tier configs
    //             (tier 0 must be rest state; non-zero tier needs both a
    //             positive duration and a >1x multiplier).
    //           * L4 — `createPosition` guards against `currentEpoch == 0`.
    //           * L5 — `_cancelNodeExpiry` `delete`s the slot when the
    //             remaining drop hits zero (refunds SSTORE).
    //           * L7 — `getNodeEffectiveStakeAtEpoch` tolerates Chronos
    //             returning 0 for unanchored epochs.
    //           * L9 — `setV10LaunchEpoch` is one-shot (anchor cannot be
    //             silently rebound).
    //           * L11 — `createPosition` no longer takes `multiplier18`;
    //             it reads the multiplier from the tier table.
    //   4.0.0 — Storage consolidation: CSS absorbs the TRAC vault role and
    //           operator-fee accounting from V8 `StakingStorage`.
    //           * Base contract switched from `HubDependent` → `Guardian`
    //             (CSS now holds `tokenContract`, exposes `transferStake`,
    //             and inherits the misplaced-token rescue helpers).
    //           * Added `nodeOperatorFeeBalance` (per-node fee accrual the
    //             `StakingV10._claim` operator split previously wrote to
    //             `StakingStorage.nodes[id].operatorFeeBalance`).
    //           * Added `operatorFeeWithdrawals` (per-node request queue
    //             with the V8 `StakeWithdrawalRequest` struct shape so the
    //             `StakingV10` admin surface can be added without further
    //             struct churn).
    //           * Vault deposits across V10 (`KnowledgeAssetsV10`,
    //             `DKGKnowledgeAssets`, `Paymaster`, etc.) now route TRAC
    //             into the CSS address. `StakingStorage` is no longer in
    //             the V10 hot path; only `StakingV10._convertToNFT` reads
    //             it (V8→V10 drain at cutover).
    //   4.1.0 — V8→V10 migration conviction credit.
    //           * `createPosition` gains a sixth parameter
    //             `expiryShortenedBy` (seconds). Subtracted from the
    //             tier-default `expiryTimestamp` after the standard
    //             computation so callers (presently
    //             `StakingV10._convertToNFT`) can grant a one-time time
    //             credit to V8 delegators who held continuous stake for
    //             the 60 days preceding V10 launch. Validated against
    //             `_tierDuration(lockTier)` and the current block
    //             timestamp; tier-0 callers MUST pass 0.
    //   10.0.3 — Reward carries (audit fix: mid-epoch redelegate/relock
    //           orphaned the current epoch's settled delegator score).
    //           * NEW `RewardCarry` struct + `rewardCarries` mapping:
    //             pointers to RSS (epoch, identityId, delegatorKey) score
    //             slots that the position's CURRENT node/key no longer
    //             reaches. Written by `StakingV10.redelegate` / `relock`,
    //             drained by `StakingV10._claim`.
    //           * `createNewPositionFromExisting` migrates carries across
    //             the relock burn-mint; `deletePosition` deletes them.
    //   10.0.5 — Expiry-queue DoS hardening:
    //           * Boost expiries are rounded up to 12-hour buckets so
    //             per-block dust stakes coalesce into one queue slot per
    //             half-day.
    //           * New distinct expiry slots are capped per node; same-bucket
    //             stakes keep coalescing even when the cap is reached.
    //   10.0.6 — Audit G-6: increaseRaw/decreaseRaw install a position's running-
    //             stake / boost contribution as the ONE-SHOT delta from its raw
    //             (floor(newRaw*m) - floor(oldRaw*m)), so a reward-compounded
    //             position's contribution always equals the one-shot value the
    //             unwind paths remove. This eliminates the incremental-vs-one-shot
    //             floor asymmetry that bricked redelegate/relock/exit/decreaseRaw,
    //             with the strict cancel/stake-delta invariants kept intact.
    string private constant _VERSION = "10.0.6";

    // Multiplier scale, matches DKGStakingConvictionNFT._convictionMultiplier
    // (returns 1e18-scaled values so fractional tiers like 1.5x and 3.5x
    // are representable).
    uint256 internal constant SCALE18 = 1e18;
    uint40 public constant EXPIRY_BUCKET_SECONDS = 12 hours;
    uint256 public constant MAX_NODE_PENDING_EXPIRIES = 1024;
    /// @notice Maximum boosted lock-tier duration. Bounded so the distinct future
    ///         buckets a node can ever hold stays STRICTLY below the slot cap.
    ///         Because `_computeExpiryTimestamp` rounds UP to the next bucket, a
    ///         tier of `k` buckets created just after a boundary expires `k + 1`
    ///         buckets out — so a node staking once per bucket can reach `k + 1`
    ///         distinct pending slots. To keep that `<= MAX_NODE_PENDING_EXPIRIES`,
    ///         a tier must be at most `MAX_NODE_PENDING_EXPIRIES - 1` buckets
    ///         (`1023 * 12h = 511.5 days`). With this enforced in `addTier`,
    ///         `MAX_NODE_PENDING_EXPIRIES` can never be reached by valid stakes —
    ///         it stays a pure backstop and never blocks a legitimate stake/relock
    ///         (and the tombstone-vs-live slot distinction can never bite). The
    ///         baseline ladder tops out at 366 days, well under this.
    uint256 public constant MAX_TIER_DURATION =
        (MAX_NODE_PENDING_EXPIRIES - 1) * uint256(EXPIRY_BUCKET_SECONDS);

    // ============================================================
    //                 D20 — Mutable tier ladder
    // ============================================================

    // Tier definition. `duration` is the committed wall-clock lock
    // (seconds) passed to `_computeExpiryTimestamp`. `multiplier18` is the
    // 1e18-scaled effective-stake multiplier applied pre-expiry.
    //
    // `active` gates NEW fresh stakes (createPosition with migrationEpoch==0).
    // Relock and migration paths take the existence-only path so the user's
    // original commitment is honored even if a tier has since been retired.
    //
    // `exists` distinguishes a never-added tier id from a deactivated one.
    struct TierConfig {
        uint256 duration;
        uint64 multiplier18;
        bool active;
        bool exists;
    }

    // Position layout (two storage slots — V10 compound-into-raw model):
    //   slot 1: raw(96) + lockTier(40) + expiryTimestamp(40) + identityId(72) = 248 bits
    //   slot 2: cumulativeRewardsClaimed(96) + multiplier18(64)
    //           + lastClaimedEpoch(32) + migrationEpoch(32)                 = 224 bits
    //
    // Field semantics:
    //   raw                        — principal (+ compounded rewards). Earns
    //                                `multiplier18` while `block.timestamp <
    //                                expiryTimestamp`, drops back to 1x
    //                                thereafter. Claim compounds TRAC into
    //                                this field.
    //   lockTier                   — tier identifier from the mutable ladder
    //                                in `_tiers`. Baseline set is
    //                                {0, 1, 3, 6, 12} (30d / 90d / 180d /
    //                                366d wall-clock locks).
    //   expiryTimestamp            — Unix timestamp (seconds) at which the
    //                                boost drops. 0 iff lockTier == 0 (rest
    //                                state). uint40 holds ~34k years.
    //   identityId                 — the node this position delegates to.
    //   cumulativeRewardsClaimed   — D19 statistic: total TRAC ever compounded
    //                                into `raw` via claim for this NFT.
    //   multiplier18               — materialized copy of `_tierMultiplier(lockTier)`.
    //   lastClaimedEpoch           — Chronos epoch of the last successful claim.
    //   migrationEpoch             — D6: V8→V10 retroactive-claim boundary.
    //                                0 means "fresh V10 stake".
    struct Position {
        uint96 raw;
        uint40 lockTier;
        uint40 expiryTimestamp;
        uint72 identityId;
        // slot 2
        uint96 cumulativeRewardsClaimed;
        uint64 multiplier18;
        uint32 lastClaimedEpoch;
        uint32 migrationEpoch;
    }

    event PositionCreated(
        uint256 indexed tokenId,
        uint72 indexed identityId,
        uint96 raw,
        uint40 lockTier,
        uint40 expiryTimestamp,
        uint64 multiplier18,
        uint32 migrationEpoch
    );
    event PositionRedelegated(
        uint256 indexed tokenId,
        uint72 indexed oldIdentityId,
        uint72 indexed newIdentityId
    );
    event PositionDeleted(uint256 indexed tokenId);
    // D21+D23 — ephemeral NFT for `relock` only. The old tokenId is burned
    // and a fresh one is minted under a new tier. Off-chain indexers trace a
    // position's history across the burn-mint via the (oldTokenId, newTokenId)
    // link in this event.
    event PositionReplaced(
        uint256 indexed oldTokenId,
        uint256 indexed newTokenId,
        uint72 indexed newIdentityId,
        uint96 raw,
        uint40 newLockTier,
        uint40 newExpiryTimestamp,
        uint64 newMultiplier18
    );
    event LastClaimedEpochUpdated(uint256 indexed tokenId, uint32 epoch);
    event MigrationEpochSet(uint256 indexed tokenId, uint32 epoch);
    // D19 — compound-into-raw model.
    event RawIncreased(uint256 indexed tokenId, uint96 amount, uint96 newRaw);
    event RawDecreased(uint256 indexed tokenId, uint96 amount, uint96 newRaw);
    event CumulativeRewardsClaimedUpdated(uint256 indexed tokenId, uint96 added, uint96 newTotal);
    // D26 — running-effective-stake settlement.
    event NodeEffectiveStakeSettled(
        uint72 indexed identityId,
        uint40 fromTimestamp,
        uint40 toTimestamp,
        uint256 newRunningEffectiveStake
    );
    event NodeEffectiveStakeDelta(uint72 indexed identityId, int256 delta, uint256 newRunningEffectiveStake);
    event NodeExpiryScheduled(uint72 indexed identityId, uint40 timestamp, uint256 dropAdded, uint256 newTotalDrop);
    event NodeExpiryCancelled(uint72 indexed identityId, uint40 timestamp, uint256 dropRemoved, uint256 newTotalDrop);
    error NodeExpiryQueueFull(uint72 identityId, uint256 pending, uint256 maxPending);
    // D15 — V10 stake aggregate events.
    event NodeStakeV10Increased(uint72 indexed identityId, uint256 amount, uint256 newNodeStake, uint256 newTotal);
    event NodeStakeV10Decreased(uint72 indexed identityId, uint256 amount, uint256 newNodeStake, uint256 newTotal);
    // D7 — V10 launch marker.
    event V10LaunchEpochSet(uint256 epoch);
    // D3 — DelegatorsInfo-absorbed events.
    event IsOperatorFeeClaimedForEpochUpdated(uint72 indexed identityId, uint256 indexed epoch, bool isClaimed);
    event NetNodeEpochRewardsSet(uint72 indexed identityId, uint256 indexed epoch, uint256 amount);

    Chronos public chronos;

    mapping(uint256 => Position) public positions;

    // ============================================================
    //    D26 — Running effective-stake state per node
    // ============================================================
    //
    // Invariant: `runningNodeEffectiveStake[id]` is the node's effective
    // stake AT `nodeLastSettledAt[id]` (inclusive). All expiries whose
    // timestamp is <= nodeLastSettledAt[id] have already been applied
    // (dropped from the running stake). All entries in `nodeExpiryTimes[id]`
    // at indices >= nodeExpiryHead[id] have timestamps strictly greater
    // than nodeLastSettledAt[id].
    // Slither: mappings are zero-initialized by the language — see
    // ContextGraphStorage._participantAgents for the long-form rationale.
    // slither-disable-next-line uninitialized-state
    mapping(uint72 => uint256) public runningNodeEffectiveStake;
    // slither-disable-next-line uninitialized-state
    mapping(uint72 => uint40) public nodeLastSettledAt;

    // Sorted-ascending queue of pending boost-expiry timestamps per node.
    // We only append past index `nodeExpiryHead[id]`; partially-cancelled
    // entries stay physically present at their sorted position and drain
    // with whatever drop remains. Fully-cancelled entries (drop back to 0
    // before drain) are kept as "zero-drop" slots so that when a fresh
    // expiry lands at the same `ts`, `nodeExpiryPresent` prevents us from
    // pushing a duplicate (M2).
    mapping(uint72 => uint40[]) internal nodeExpiryTimes;
    // Aggregate boost drop scheduled at exactly `ts` for `id`. Multiple
    // positions sharing an `expiryTimestamp` are coalesced here.
    mapping(uint72 => mapping(uint40 => uint256)) internal nodeExpiryDrop;
    // Drain cursor into `nodeExpiryTimes[id]`. Entries below the head
    // are fully drained and MUST NOT be read again.
    mapping(uint72 => uint256) internal nodeExpiryHead;
    // M2 — tracks whether `ts` has a live slot in `nodeExpiryTimes[id]`
    //      at or past `nodeExpiryHead[id]`. Set on first schedule, cleared
    //      when the drain cursor walks past the slot. Without this, a
    //      cancel-to-zero followed by a fresh schedule at the same `ts`
    //      would push a second entry (functionally harmless, but doubles
    //      the SSTOREs and weakens the "at most one entry per `ts`"
    //      invariant on `nodeExpiryTimes[id]`).
    mapping(uint72 => mapping(uint40 => bool)) internal nodeExpiryPresent;

    // ============================================================
    //                D5 — Per-node tokenId enumeration
    // ============================================================
    mapping(uint72 => uint256[]) public nodeTokens;
    mapping(uint72 => mapping(uint256 => uint256)) public nodeTokenIndex;

    // ============================================================
    //           D15 — V10 stake aggregates (raw TRAC principal)
    // ============================================================
    mapping(uint72 => uint256) public nodeStakeV10;
    uint256 public totalStakeV10;

    // ============================================================
    //            D3 — Absorbed DelegatorsInfo fields (V10)
    // ============================================================
    mapping(uint72 => mapping(uint256 => bool)) public isOperatorFeeClaimedForEpoch;
    mapping(uint72 => mapping(uint256 => uint256)) public netNodeEpochRewards;

    // ============================================================
    //   v4.0.0 — Operator-fee balance + withdrawal queue (absorbed
    //            from V8 StakingStorage)
    //
    // `nodeOperatorFeeBalance` accrues each time `StakingV10._claim`
    // splits gross node rewards by `Profile.getLatestOperatorFeePercentage`
    // (operator-fee-percentage cut, drained when the operator finalises a
    // `requestOperatorFeeWithdrawal` / `cancelOperatorFeeWithdrawal` against
    // their identity).
    //
    // `operatorFeeWithdrawals` is the per-identity request queue. The struct
    // shape is reused from `StakingLib.StakeWithdrawalRequest` so the
    // operator-side admin functions can be added on `StakingV10` (or on a
    // future thin admin contract) without further struct churn. V10 never
    // populates `indexedOutAmount`; it stays 0 for every entry.
    // ============================================================
    mapping(uint72 => uint96) public nodeOperatorFeeBalance;
    mapping(uint72 => StakingLib.StakeWithdrawalRequest) public operatorFeeWithdrawals;

    // ============================================================
    //                 D7 — V10 launch epoch marker
    // ============================================================
    uint256 public v10LaunchEpoch;

    // ============================================================
    //   V8→V10 "pool & allocate" migration credit ledger
    // ============================================================
    // Migrated-but-unallocated TRAC, per delegator. Backed 1:1 by TRAC
    // physically held in THIS contract (moved here by the drain worker via
    // StakingStorage.transferStake). The only sink is `spendMigrationCredit`
    // (driven by DKGStakingConvictionNFT.allocate) — credit is NEVER
    // withdrawable to a wallet. Lives here (durable storage), not on the
    // wrapper (logic), so a wrapper redeploy mid-migration cannot strand the
    // already-moved TRAC.
    mapping(address => uint96) public migrationCredit;
    // Lock-shortening (seconds) applied to ANY tier-6/12 migration allocation
    // (universal — no per-staker eligibility distinction). Set
    // at cutover via `setConvictionCreditSeconds`, capped below the shortest
    // credited-tier (tier 6) duration so a position's expiry cannot underflow.
    // 0 until set (no credit).
    uint40 public convictionCreditSeconds;

    // ============================================================
    //           D20 (v2.1.0) — Mutable tier-ladder storage
    // ============================================================
    mapping(uint40 => TierConfig) internal _tiers;
    uint40[] public tierIds;

    // ============================================================
    //   v10.0.3 — Reward carries (mid-epoch redelegate / relock)
    // ============================================================
    //
    // A mid-epoch `redelegate` flips `pos.identityId`, and a `relock`
    // re-keys the position under a fresh tokenId. In both cases the
    // delegator score already settled in RandomSamplingStorage under the
    // OLD (epoch, identityId, delegatorKey) slot becomes unreachable from
    // `StakingV10._claim`, which reads only the position's CURRENT node +
    // key — silently forfeiting up to one epoch's rewards. Each carry is
    // a POINTER to such a slot; the score value itself stays in RSS.
    // `StakingV10._claim` integrates matured carries (epoch closed) and
    // clears them.
    struct RewardCarry {
        uint72 identityId;
        uint32 epoch;
        bytes32 delegatorKey;
    }

    // Bounded so a position's claim/withdraw can never be self-bricked by
    // an excessive number of same-epoch redelegations (carries from past
    // epochs are flushed on every claim).
    uint256 public constant MAX_REWARD_CARRIES = 32;

    mapping(uint256 => RewardCarry[]) internal rewardCarries;

    event RewardCarryAdded(
        uint256 indexed tokenId,
        uint72 indexed identityId,
        uint32 epoch,
        bytes32 delegatorKey
    );
    event RewardCarriesCleared(uint256 indexed tokenId, uint32 maxEpoch, uint256 removed);

    // ============================================================
    //          Tier admin events (v2.1.0)
    // ============================================================
    event TierAdded(uint40 indexed lockTier, uint256 duration, uint64 multiplier18);
    event TierDeactivated(uint40 indexed lockTier);
    event ConvictionCreditSecondsSet(uint40 secondsValue);

    // ============================================================
    //   v4.0.0 — Vault + operator-fee events (absorbed from V8 SS)
    // ============================================================
    event OperatorFeeBalanceUpdated(uint72 indexed identityId, uint96 feeBalance);
    event OperatorFeeWithdrawalRequestCreated(
        uint72 indexed identityId,
        uint96 amount,
        uint96 indexedOutAmount,
        uint256 timestamp
    );
    event OperatorFeeWithdrawalRequestDeleted(uint72 indexed identityId);
    event StakedTokensTransferred(address indexed receiver, uint96 amount);
    /// @notice OT-RFC-53: emitted when the protocol treasury fee owed on an
    ///         escrow-funded publish/update/extend is routed out of the vault to
    ///         the treasury. Distinct from {StakedTokensTransferred} so off-chain
    ///         accounting never mistakes a treasury-fee outflow for a stake move.
    event RegistrationDepositFeeTransferred(address indexed treasury, uint96 amount);

    constructor(address hubAddress) Guardian(hubAddress) {}

    /// @dev Overrides `Guardian.initialize()` so the CSS deploy step seeds
    ///      both Guardian's TRAC reference AND CSS's V10 staking state in
    ///      one call. Guardian only sets `tokenContract`; CSS additionally
    ///      wires Chronos and seeds the D20 baseline tier ladder. Callable
    ///      only by Hub; `_seedBaselineTiers` is idempotent across post-
    ///      upgrade redeploys (existing tier ids short-circuit).
    function initialize() public override onlyHub {
        tokenContract = IERC20(hub.getContractAddress("Token"));
        chronos = Chronos(hub.getContractAddress("Chronos"));

        // Seed the baseline D20 ladder on the first call. Idempotent across
        // re-invocations (post-upgrade redeploys) because `_addTierInternal`
        // short-circuits when the tier id already exists.
        _seedBaselineTiers();
    }

    /// @dev Baseline durations are exact wall-clock commitments. Timestamp-
    ///      accurate accounting (D26) removes the v2.x BLOCK_DRIFT_BUFFER
    ///      padding: a 30-day lock means exactly 30 * 86400 seconds of boost.
    ///      Lock 12 uses 366 days so it absorbs a leap year.
    function _seedBaselineTiers() internal {
        if (!_tiers[0].exists) {
            _addTierInternal(0, 0, uint64(SCALE18)); // rest state (1x)
        }
        if (!_tiers[1].exists) {
            _addTierInternal(1, 30 days, uint64((15 * SCALE18) / 10));
        }
        if (!_tiers[3].exists) {
            _addTierInternal(3, 90 days, uint64(2 * SCALE18));
        }
        if (!_tiers[6].exists) {
            _addTierInternal(6, 180 days, uint64((35 * SCALE18) / 10));
        }
        if (!_tiers[12].exists) {
            _addTierInternal(12, 366 days, uint64(6 * SCALE18));
        }
    }

    function name() external pure virtual override returns (string memory) {
        return _NAME;
    }

    function version() external pure virtual override returns (string memory) {
        return _VERSION;
    }

    // ============================================================
    //                 D20 — Tier helpers (storage-backed)
    // ============================================================

    function _tierDuration(uint40 lockTier) internal view returns (uint256) {
        TierConfig memory tc = _tiers[lockTier];
        require(tc.exists, "Invalid tier");
        return tc.duration;
    }

    function _tierMultiplier(uint40 lockTier) internal view returns (uint64) {
        TierConfig memory tc = _tiers[lockTier];
        require(tc.exists, "Invalid tier");
        return tc.multiplier18;
    }

    function _requireActiveTier(uint40 lockTier) internal view {
        TierConfig memory tc = _tiers[lockTier];
        require(tc.exists, "Invalid tier");
        require(tc.active, "Tier inactive");
    }

    function expectedMultiplier18(uint40 lockTier) public view returns (uint64) {
        return _tierMultiplier(lockTier);
    }

    function tierDuration(uint40 lockTier) external view returns (uint256) {
        return _tierDuration(lockTier);
    }

    function getTier(uint40 lockTier) external view returns (TierConfig memory) {
        return _tiers[lockTier];
    }

    function allTierIds() external view returns (uint40[] memory) {
        return tierIds;
    }

    function tierCount() external view returns (uint256) {
        return tierIds.length;
    }

    // ============================================================
    //         D20 — Tier admin (v2.1.0, Q4=B multisig gate)
    // ============================================================

    /// @notice Add a new lock tier to the ladder (D20 governance).
    /// @dev    M3/M4 — rejects degenerate configurations that would either
    ///         brick `createPosition` (zero-duration + non-1x multiplier:
    ///         the would-be expiry lands at `block.timestamp`, the
    ///         `_scheduleNodeExpiry` "Expiry in past" check fires, every
    ///         mint reverts) or create "locked-but-boost-free" positions
    ///         that trip the `expiryEpoch` split branch in claim math for
    ///         no economic purpose (gas noise).
    ///
    ///         The tier ladder is:
    ///             * id 0 — rest state: `duration == 0`, `mult == 1e18`.
    ///             * id N>0 — real locked tier: `duration > 0` AND
    ///                        `mult > 1e18`.
    function addTier(
        uint40 lockTier,
        uint256 duration,
        uint64 multiplier18
    ) external onlyOwnerOrMultiSigOwner {
        require(!_tiers[lockTier].exists, "Tier exists");
        if (lockTier == 0) {
            require(duration == 0 && multiplier18 == uint64(SCALE18), "Tier 0 must be rest");
        } else {
            require(duration > 0, "Non-zero tier needs duration");
            // Keep MAX_NODE_PENDING_EXPIRIES an unreachable backstop: a single
            // tier's expiry window must fit within that many 12h buckets, so the
            // per-node slot cap can never block a legitimate stake/relock.
            require(duration <= MAX_TIER_DURATION, "Tier duration too long");
            require(multiplier18 > uint64(SCALE18), "Non-zero tier needs boost");
        }
        _addTierInternal(lockTier, duration, multiplier18);
    }

    function deactivateTier(uint40 lockTier) external onlyOwnerOrMultiSigOwner {
        TierConfig storage tc = _tiers[lockTier];
        require(tc.exists, "Invalid tier");
        require(tc.active, "Already inactive");
        tc.active = false;
        emit TierDeactivated(lockTier);
    }

    function _addTierInternal(
        uint40 lockTier,
        uint256 duration,
        uint64 multiplier18
    ) internal {
        _tiers[lockTier] = TierConfig({
            duration: duration,
            multiplier18: multiplier18,
            active: true,
            exists: true
        });
        tierIds.push(lockTier);
        emit TierAdded(lockTier, duration, multiplier18);
    }

    // --- Admin access control (mirrors DKGStakingConvictionNFT) ---

    modifier onlyOwnerOrMultiSigOwner() {
        address hubOwner = hub.owner();
        if (msg.sender != hubOwner && !_isMultiSigOwner(hubOwner)) {
            revert HubLib.UnauthorizedAccess("Only Hub Owner or Multisig Owner");
        }
        _;
    }

    function _isMultiSigOwner(address multiSigAddress) internal view returns (bool) {
        try ICustodian(multiSigAddress).getOwners() returns (address[] memory owners) {
            for (uint256 i = 0; i < owners.length; i++) {
                if (msg.sender == owners[i]) return true;
            }
        } catch {
            // Not a multisig or call reverted; treat as not an owner.
        }
        return false;
    }

    // ============================================================
    //          D26 — Running-effective-stake settlement
    // ============================================================
    //
    // WHAT THIS SECTION DOES
    // ----------------------
    // V10 tracks a node's *effective* stake (raw TRAC × active lock
    // multiplier) as a continuous quantity that changes at exact
    // timestamps — never at epoch boundaries. Two things make it move:
    //
    //   (1) Instantaneous deltas: someone stakes / unstakes / migrates /
    //       redelegates. These are applied via `_applyNodeStakeDelta`.
    //   (2) Time passing: a boost expires at its precise wall-clock
    //       `expiryTimestamp`, and from that second onward the position
    //       contributes `raw × 1x` instead of `raw × multiplier`. The
    //       difference is called the *drop*. Drops are pre-scheduled
    //       into a per-node sorted queue and drained by `_settleNodeTo`.
    //
    // `runningNodeEffectiveStake[id]` holds the node's effective stake
    // AS OF `nodeLastSettledAt[id]` (inclusive). To compute the value
    // "now", callers first bring the clock forward with `settleNodeTo`,
    // which walks the expiry queue up to `now` and subtracts all the
    // matured drops.
    //
    // WHO CALLS SETTLE AND WHY
    // ------------------------
    //   * `RandomSampling.submitProof` — before integrating score into
    //     `scorePerStake`, so the denominator reflects the node's
    //     effective stake at the proof's block timestamp (not at the
    //     last mutator call).
    //   * Every mutator in this file (createPosition, updateOnRelock,
    //     updateOnRedelegate, createNewPositionFromExisting,
    //     deletePosition, increaseRaw, decreaseRaw) — before touching
    //     `runningNodeEffectiveStake[id]`, so all deltas compose against
    //     a correctly-aged baseline.
    //   * Views that need a fresh instantaneous snapshot
    //     (`_simulateNodeEffectiveStakeAt` is the const-time counterpart
    //     used by `getNodeEffectiveStakeAtEpoch`).
    //
    // WHY THE STATE IS SHAPED LIKE THIS
    // ---------------------------------
    // We need sub-epoch accuracy but cannot loop over positions on every
    // read (thousands of delegators per popular node). The running
    // stake + pre-scheduled drop queue reduces every CSS mutation and
    // every proof to O(matured-drops-since-last-settle), which in
    // steady state is near-zero (see "LOOP BOUND" on `_settleNodeTo`).

    /// @notice Advance `runningNodeEffectiveStake[id]` to an explicit
    ///         target timestamp `ts`. Idempotent for past/current `ts`.
    /// @dev Exposed so `RandomSampling.submitProof` can settle to
    ///      `block.timestamp` before integrating `scorePerStake`. Also
    ///      used by views that need to simulate at an arbitrary `ts`
    ///      (though they call `_simulateNodeEffectiveStakeAt` instead,
    ///      which does not mutate state).
    /// @param identityId Canonical node id (matches StakingStorage).
    /// @param ts         Target wall-clock seconds. Treated as the
    ///                   inclusive upper bound: all expiries with
    ///                   `expiryTimestamp <= ts` are realized.
    function settleNodeTo(uint72 identityId, uint40 ts) public onlyContracts {
        _settleNodeTo(identityId, ts);
    }

    /// @notice Convenience wrapper settling to `block.timestamp`. This
    ///         is what every CSS mutator uses before applying its delta,
    ///         because `block.timestamp` is the authoritative "now" on
    ///         EVM chains.
    function settleNode(uint72 identityId) external onlyContracts {
        _settleNodeTo(identityId, uint40(block.timestamp));
    }

    /// @dev   Drain matured expiries up to `ts` and advance the node's
    ///        running effective stake and last-settled watermark.
    ///
    /// VARIABLES (in the context of the wider system):
    ///
    ///   `from`  — the node's previous last-settled watermark. Anything
    ///             with `expiryTimestamp <= from` was already applied in
    ///             a prior settle; anything > from has NOT yet been
    ///             applied and is still sitting in the queue.
    ///
    ///   `head`  — drain cursor into `nodeExpiryTimes[id]`. Entries at
    ///             indices < head are fully processed and MUST NOT be
    ///             read again. `head` only moves forward; we never pop
    ///             or rewrite the array, so the per-entry work is
    ///             strictly once-in-forever.
    ///
    ///   `times` — pointer to the per-node sorted-ascending array of
    ///             distinct `expiryTimestamp` values. Same-`ts` expiries
    ///             from multiple positions are coalesced at schedule
    ///             time (see `_scheduleNodeExpiry`) into one array slot.
    ///
    ///   `len`   — current array length. May grow (new expiries scheduled
    ///             mid-tx) but entries past `len` at call start are
    ///             irrelevant for *this* settle — they were added after
    ///             `from` and cannot have `ts <= ts` AND be sorted ahead
    ///             of the current head without violating the invariant.
    ///
    ///   `stake` — local copy of `runningNodeEffectiveStake[id]`, edited
    ///             in a scratch variable to avoid SSTORE per iteration.
    ///             Flushed back once at the end.
    ///
    ///   `t`     — the timestamp of the queue entry currently under
    ///             consideration. The loop breaks as soon as `t > ts`
    ///             because the array is sorted and all later entries
    ///             are strictly greater.
    ///
    ///   `drop`  — aggregate boost amount scheduled to expire at `t`
    ///             (summed across all positions sharing that `t`). The
    ///             drop equals `raw × (multiplier18 - 1e18) / 1e18` per
    ///             position at the moment it was scheduled, summed.
    ///             A zero drop means the entry was fully cancelled by
    ///             prior `_cancelNodeExpiry` calls (redelegate-away,
    ///             withdraw, relock) and is simply skipped.
    ///
    /// LOOP BOUND (why this cannot explode the block gas limit)
    /// --------------------------------------------------------
    /// The `while` terminates as soon as `t > ts` or `head == len`.
    /// Entries are only added through `_scheduleNodeExpiry`, and fresh
    /// lock expiries are rounded UP to 12-hour buckets before they reach
    /// the queue. A per-block dust-stake stream therefore coalesces into
    /// one slot per half-day, not one slot per block.
    ///
    /// `_scheduleNodeExpiry` also refuses to create a new distinct slot
    /// once `MAX_NODE_PENDING_EXPIRIES` pending slots are live for a node.
    /// Same-bucket stakes keep accumulating into the existing slot, so the
    /// cap bounds replay work without blocking aggregation inside an
    /// already-reserved bucket.
    ///
    /// Work is amortized once: each array slot is visited by exactly one
    /// `_settleNodeTo` call across the contract's lifetime. In steady state
    /// `submitProof` drains the queue continuously; after dormancy, the
    /// 12-hour bucket + pending-slot cap keeps the catch-up loop bounded.
    ///
    /// INVARIANTS MAINTAINED ON EXIT
    /// -----------------------------
    ///   I1. nodeLastSettledAt[id] == ts.
    ///   I2. For every `t` with `t <= ts`, `nodeExpiryDrop[id][t] == 0`.
    ///   I3. runningNodeEffectiveStake[id] equals the true effective
    ///       stake of the node at wall-clock second `ts`, assuming the
    ///       prior entry state was consistent (recursive invariant).
    function _settleNodeTo(uint72 identityId, uint40 ts) internal {
        // Idempotent replay: if we've already settled at or beyond `ts`,
        // the running stake is already correct for that moment.
        uint40 from = nodeLastSettledAt[identityId];
        if (ts <= from) {
            return;
        }

        // Load the drain cursor, the sorted expiry array, its length,
        // and the running stake into locals. `times` is a storage
        // pointer (not a copy): we index into it but never mutate it
        // here. `stake` is a scratch local so iteration does not
        // SSTORE; we flush once at the end.
        uint256 head = nodeExpiryHead[identityId];
        uint40[] storage times = nodeExpiryTimes[identityId];
        uint256 len = times.length;
        uint256 stake = runningNodeEffectiveStake[identityId];

        // Walk every queued expiry whose timestamp is <= `ts`, in order.
        // The queue is sorted ascending, so as soon as `times[head] > ts`
        // we are done — nothing later can satisfy the condition.
        while (head < len) {
            uint40 t = times[head];
            if (t > ts) break;

            // `drop` is the total boost (sum over all positions that
            // were coalesced at this `t`) that MUST come off the
            // running stake at exactly second `t`. Zero means the
            // entry was fully cancelled (e.g. all those positions were
            // relocked / redelegated-away / withdrawn before expiry) —
            // harmless no-op.
            uint256 drop = nodeExpiryDrop[identityId][t];
            if (drop != 0) {
                // Invariant (enforced at schedule time): drop values are
                // derived from raw × (multiplier - 1) portions of real
                // positions on this node, so their sum can never exceed
                // the running effective stake that was installed by the
                // same schedule call.
                stake -= drop;

                // Free the aggregate slot (gas refund + keeps state
                // compact). We never revisit drained `t` because `head`
                // only moves forward.
                delete nodeExpiryDrop[identityId][t];
            }
            // M2 — clear the "slot reserved" flag now that the head has
            // walked past this `ts`. A fresh schedule at the same `ts`
            // AFTER this point is impossible anyway (`_scheduleNodeExpiry`
            // requires `ts > nodeLastSettledAt[id]`); we still clear it
            // to claim the SSTORE refund and keep state compact.
            delete nodeExpiryPresent[identityId][t];
            // `head` is bounded above by `len`, both fit in uint256;
            // incrementing cannot overflow.
            unchecked {
                head++;
            }
        }

        // Flush all three pieces of state together so the invariants
        // above hold atomically.
        nodeExpiryHead[identityId] = head;
        runningNodeEffectiveStake[identityId] = stake;
        nodeLastSettledAt[identityId] = ts;
        emit NodeEffectiveStakeSettled(identityId, from, ts, stake);
    }

    /// @dev Simulated settle: computes effective stake at `ts` without
    ///      writing. `ts` must be >= nodeLastSettledAt[id] (we can't look
    ///      into the past; pre-settled history is not retained under D26).
    function _simulateNodeEffectiveStakeAt(uint72 identityId, uint40 ts) internal view returns (uint256) {
        if (ts < nodeLastSettledAt[identityId]) {
            // Caller asked for a past moment; we can't reconstruct. Return
            // 0 to match "no stake at that moment" semantics, matching
            // the pre-creation default for the running mapping.
            return 0;
        }
        uint256 head = nodeExpiryHead[identityId];
        uint40[] storage times = nodeExpiryTimes[identityId];
        uint256 len = times.length;
        uint256 stake = runningNodeEffectiveStake[identityId];
        while (head < len) {
            uint40 t = times[head];
            if (t > ts) break;
            stake -= nodeExpiryDrop[identityId][t];
            unchecked {
                head++;
            }
        }
        return stake;
    }

    // ============================================================
    //              D26 — Expiry queue helpers (internal)
    // ============================================================

    /// @dev Schedule a boost-expiry drop at `ts` for `id`. Maintains the
    ///      sorted-ascending invariant over `nodeExpiryTimes[id]` starting
    ///      at `nodeExpiryHead[id]`. Typical call pattern appends to the
    ///      tail (new lock later than all existing); cross-tier inserts
    ///      shift the tail one slot rightward until the correct position.
    /// @dev M2 — uses `nodeExpiryPresent[id][ts]` (not `drop != 0`) as the
    ///      "array slot already reserved" witness. This handles the
    ///      cancel→reschedule-at-same-ts case: after a full cancel the
    ///      drop aggregate is zero but the array slot is still live; we
    ///      must NOT push a duplicate.
    function _scheduleNodeExpiry(uint72 identityId, uint40 ts, uint256 drop) internal {
        require(drop != 0, "Zero drop");
        require(ts > nodeLastSettledAt[identityId], "Expiry in past");
        uint256 existing = nodeExpiryDrop[identityId][ts];
        nodeExpiryDrop[identityId][ts] = existing + drop;
        emit NodeExpiryScheduled(identityId, ts, drop, existing + drop);
        if (nodeExpiryPresent[identityId][ts]) {
            // ts already has a slot in the queue; just bumped the drop.
            return;
        }

        // Insert `ts` into the sorted queue.
        uint40[] storage arr = nodeExpiryTimes[identityId];
        uint256 head = nodeExpiryHead[identityId];
        uint256 len = arr.length;
        uint256 pending = len - head;
        if (pending >= MAX_NODE_PENDING_EXPIRIES) {
            revert NodeExpiryQueueFull(identityId, pending, MAX_NODE_PENDING_EXPIRIES);
        }
        nodeExpiryPresent[identityId][ts] = true;

        arr.push(ts); // temporarily at tail
        // Bubble left while the left neighbor is strictly greater AND we
        // haven't crossed the drain head.
        uint256 i = len;
        while (i > head && arr[i - 1] > ts) {
            arr[i] = arr[i - 1];
            unchecked {
                i--;
            }
        }
        arr[i] = ts;
    }

    /// @dev Cancel part (or all) of a previously scheduled boost drop. We
    ///      keep the array entry in place (M2: `nodeExpiryPresent[id][ts]`
    ///      stays `true`) so that a re-schedule at the same `ts` does not
    ///      push a duplicate slot; the drain cursor will clean both up
    ///      when it walks past. A zero-drop entry is harmlessly drained
    ///      as a no-op when settle reaches it.
    /// @dev L5 — `delete`s the aggregate slot when remaining hits zero so
    ///      the SSTORE gets its gas refund. The `nodeExpiryPresent` flag
    ///      is deliberately NOT cleared: M2's whole point is to remember
    ///      "this `ts` already has an array slot" until the cursor walks
    ///      past it.
    function _cancelNodeExpiry(uint72 identityId, uint40 ts, uint256 drop) internal {
        if (drop == 0) return;
        if (ts <= nodeLastSettledAt[identityId]) {
            // Already drained — nothing to cancel.
            return;
        }
        uint256 existing = nodeExpiryDrop[identityId][ts];
        // Strict invariant: a cancel can never exceed the scheduled drop. G-6 keeps
        // this strict (no saturation) because increaseRaw/decreaseRaw now install a
        // position's boost as the ONE-SHOT delta from its raw, so the scheduled slot
        // always holds exactly floor(curRaw*(m-S)) for the position and the one-shot
        // unwind removes exactly that — no incremental-vs-one-shot floor asymmetry.
        require(existing >= drop, "Cancel > scheduled");
        uint256 remaining = existing - drop;
        if (remaining == 0) {
            delete nodeExpiryDrop[identityId][ts];
        } else {
            nodeExpiryDrop[identityId][ts] = remaining;
        }
        emit NodeExpiryCancelled(identityId, ts, drop, remaining);
    }

    /// @dev Apply an instantaneous delta to `runningNodeEffectiveStake[id]`.
    ///      Must be called after the node has been settled to `block.timestamp`
    ///      (callers are responsible — all mutators below do so).
    function _applyNodeStakeDelta(uint72 identityId, int256 delta) internal {
        if (delta == 0) return;
        uint256 stake = runningNodeEffectiveStake[identityId];
        if (delta > 0) {
            stake += uint256(delta);
        } else {
            uint256 d = uint256(-delta);
            // Strict invariant: running stake can never go negative. G-6 keeps this
            // strict (no saturation) — increaseRaw/decreaseRaw install a position's
            // running-stake contribution as the ONE-SHOT delta from its raw, so the
            // aggregate always holds exactly floor(curRaw*m) for the position and the
            // one-shot unwind removes exactly that.
            require(stake >= d, "Neg running stake");
            stake -= d;
        }
        runningNodeEffectiveStake[identityId] = stake;
        emit NodeEffectiveStakeDelta(identityId, delta, stake);
    }

    // ============================================================
    //                        Mutators
    // ============================================================

    /**
     * @notice Create a fresh V10 position. Used by both the fresh-stake
     *         path (migrationEpoch = 0) and the V8→V10 migration path
     *         (migrationEpoch = migration epoch).
     */
    /// @notice Create a new V10 position under `lockTier` on `identityId`.
    /// @dev    L11 — `multiplier18` is no longer an argument; CSS reads it
    ///         from the tier table (single source of truth).
    ///         L4 — guards against pre-genesis bootstrap where
    ///         `chronos.getCurrentEpoch()` returns 0 (the `currentEpoch - 1`
    ///         arithmetic would otherwise panic).
    /// @param  expiryShortenedBy v4.1.0 — seconds to subtract from the
    ///         tier-default `expiryTimestamp`. Used by
    ///         `StakingV10._convertToNFT` to grant the V8→V10 migration
    ///         conviction credit (60 days for eligible delegators on
    ///         tiers 6/12, 0 otherwise). Caller MUST pass 0 for tier 0
    ///         and for fresh `stake()` calls.
    function createPosition(
        uint256 tokenId,
        uint72 identityId,
        uint96 raw,
        uint40 lockTier,
        uint32 migrationEpoch,
        uint40 expiryShortenedBy
    ) external onlyContracts {
        require(identityId != 0, "Zero node");
        require(positions[tokenId].identityId == 0, "Position exists");
        require(raw > 0, "Zero raw");
        if (migrationEpoch == 0) {
            _requireActiveTier(lockTier);
        }
        uint64 multiplier18 = _tierMultiplier(lockTier);

        uint256 currentEpoch = chronos.getCurrentEpoch();
        require(currentEpoch >= 1, "Pre-genesis create");
        uint40 tsNow = uint40(block.timestamp);
        uint40 expiryTimestamp = _computeExpiryTimestamp(lockTier);

        // v4.1.0 — apply the V8→V10 migration credit. The credit is in
        // seconds; we subtract from the freshly-computed default expiry.
        // Constraints:
        //   * The credit is V8→V10 migration-exclusive — fresh `stake()`
        //     calls (`migrationEpoch == 0`) MUST pass 0. Without this
        //     guard, any future Hub-registered caller could mint a
        //     fresh stake at a shortened lock just by remembering / not
        //     to pass the bonus. Tying the credit to a non-zero
        //     `migrationEpoch` keeps the bonus a closed eligibility set
        //     scoped to the V8→V10 drain path.
        //   * Tier 0 has no boost / no expiry, so any non-zero credit is
        //     a caller bug (guard catches it explicitly).
        //   * Credit must be strictly less than the tier duration —
        //     equal-or-greater would land the new expiry at or before
        //     `block.timestamp`, defeating the lock.
        //   * After applying, the resulting expiry must still be in the
        //     future. Belt-and-suspenders against off-by-one rounding
        //     in the tier table.
        if (expiryShortenedBy != 0) {
            require(migrationEpoch != 0, "Credit requires migrationEpoch");
            require(lockTier != 0, "Credit requires locked tier");
            uint256 dur = _tierDuration(lockTier);
            require(uint256(expiryShortenedBy) < dur, "Credit >= tier duration");
            // Subtract the migration credit AFTER bucketing and do NOT re-bucket.
            // `expiryShortenedBy` (convictionCreditSeconds) is a single global
            // offset, so `bucketedDefault - credit` still coalesces (same shifted
            // timestamp per creation bucket) and the queue stays bounded. Re-bucketing
            // here would silently round a non-bucket-aligned credit UP to the 12h grid
            // (e.g. `60d - 1h` -> a full `60d`), changing the configured credit. The
            // exact second is preserved on purpose — do not "tidy" this onto the grid.
            expiryTimestamp = uint40(uint256(expiryTimestamp) - uint256(expiryShortenedBy));
            require(expiryTimestamp > tsNow, "Credit leaves no remaining lock");
        }

        positions[tokenId] = Position({
            raw: raw,
            lockTier: lockTier,
            expiryTimestamp: expiryTimestamp,
            identityId: identityId,
            cumulativeRewardsClaimed: 0,
            multiplier18: multiplier18,
            lastClaimedEpoch: uint32(currentEpoch - 1),
            migrationEpoch: migrationEpoch
        });

        _pushNodeToken(identityId, tokenId);
        _increaseNodeStakeV10(identityId, uint256(raw));

        _settleNodeTo(identityId, tsNow);

        // Effective contribution right now = raw * multiplier18 / 1e18.
        uint256 effNow = (uint256(raw) * uint256(multiplier18)) / SCALE18;
        _applyNodeStakeDelta(identityId, int256(effNow));

        // Schedule the boost drop at expiry (if there is any boost).
        if (lockTier > 0 && multiplier18 > SCALE18) {
            uint256 boost = (uint256(raw) * (uint256(multiplier18) - SCALE18)) / SCALE18;
            _scheduleNodeExpiry(identityId, expiryTimestamp, boost);
        }

        emit PositionCreated(tokenId, identityId, raw, lockTier, expiryTimestamp, multiplier18, migrationEpoch);
    }

    // M1 — `updateOnRelock` was never reached from production contracts
    //      (StakingV10.relock goes through `createNewPositionFromExisting`,
    //      which preserves reward continuity under the D21 "NFTs are
    //      ephemeral across tier changes" narrative). Removing eliminates
    //      a silent dead-code path and clarifies that relock is a
    //      burn-and-mint, not an in-place tier swap.

    function updateOnRedelegate(uint256 tokenId, uint72 newIdentityId) external onlyContracts {
        require(newIdentityId != 0, "Zero node");
        Position storage pos = positions[tokenId];
        require(pos.identityId != 0, "No position");
        uint72 oldIdentityId = pos.identityId;
        require(oldIdentityId != newIdentityId, "Same node");

        uint40 tsNow = uint40(block.timestamp);
        uint96 raw = pos.raw;
        uint40 expiryTs = pos.expiryTimestamp;
        uint64 multiplier18 = pos.multiplier18;
        bool stillBoosted = expiryTs != 0 && tsNow < expiryTs;

        uint256 effectiveNow = stillBoosted
            ? (uint256(raw) * uint256(multiplier18)) / SCALE18
            : uint256(raw);
        uint256 boost = (stillBoosted && multiplier18 > SCALE18)
            ? (uint256(raw) * (uint256(multiplier18) - SCALE18)) / SCALE18
            : 0;

        // Settle both sides so running stake is timestamp-current.
        _settleNodeTo(oldIdentityId, tsNow);
        _settleNodeTo(newIdentityId, tsNow);

        // Unwind full contribution from old node; cancel its pending boost drop.
        _applyNodeStakeDelta(oldIdentityId, -int256(effectiveNow));
        if (boost != 0) {
            _cancelNodeExpiry(oldIdentityId, expiryTs, boost);
        }

        // Install full contribution on new node; schedule its pending boost drop.
        _applyNodeStakeDelta(newIdentityId, int256(effectiveNow));
        if (boost != 0) {
            _scheduleNodeExpiry(newIdentityId, expiryTs, boost);
        }

        pos.identityId = newIdentityId;

        // D5 — per-node enumeration.
        _popNodeToken(oldIdentityId, tokenId);
        _pushNodeToken(newIdentityId, tokenId);

        // D15 — raw aggregates (total unchanged).
        uint256 rawU = uint256(raw);
        nodeStakeV10[oldIdentityId] -= rawU;
        nodeStakeV10[newIdentityId] += rawU;
        emit NodeStakeV10Decreased(oldIdentityId, rawU, nodeStakeV10[oldIdentityId], totalStakeV10);
        emit NodeStakeV10Increased(newIdentityId, rawU, nodeStakeV10[newIdentityId], totalStakeV10);

        emit PositionRedelegated(tokenId, oldIdentityId, newIdentityId);
    }

    /**
     * @notice D23 primitive — atomically replace a live position at
     *         `oldTokenId` with a fresh one at `newTokenId` on the SAME
     *         node. Preserves `cumulativeRewardsClaimed`,
     *         `lastClaimedEpoch`, and `migrationEpoch`; the new position's
     *         lock clock starts at `block.timestamp` under the caller-
     *         supplied tier.
     *
     * @dev M1 + L11 — post-review:
     *        * Cross-identity branch removed. `StakingV10.redelegate`
     *          goes through `updateOnRedelegate`; the only live caller
     *          of this helper is `StakingV10.relock`, which stays on
     *          the same node.
     *        * `multiplier18` is no longer an argument; CSS reads it
     *          from the tier table to avoid round-tripping data the
     *          contract can derive on its own.
     */
    function createNewPositionFromExisting(
        uint256 oldTokenId,
        uint256 newTokenId,
        uint72 identityId,
        uint40 newLockTier
    ) external onlyContracts {
        require(identityId != 0, "Zero node");
        require(positions[newTokenId].identityId == 0, "New token used");
        require(oldTokenId != newTokenId, "Same tokenId");

        Position memory old = positions[oldTokenId];
        require(old.identityId != 0, "No position");
        require(old.identityId == identityId, "Identity mismatch");
        uint96 raw = old.raw;
        require(raw > 0, "Zero raw");

        uint64 newMultiplier18 = _tierMultiplier(newLockTier);

        uint40 oldExpiryTs = old.expiryTimestamp;
        uint64 oldMultiplier18 = old.multiplier18;
        uint40 tsNow = uint40(block.timestamp);

        _settleNodeTo(identityId, tsNow);

        // --- Unwind old contribution ---
        bool oldStillBoosted = oldExpiryTs != 0 && tsNow < oldExpiryTs;
        uint256 effectiveNowOld = oldStillBoosted
            ? (uint256(raw) * uint256(oldMultiplier18)) / SCALE18
            : uint256(raw);
        _applyNodeStakeDelta(identityId, -int256(effectiveNowOld));
        if (oldStillBoosted && oldMultiplier18 > SCALE18) {
            uint256 oldBoost = (uint256(raw) * (uint256(oldMultiplier18) - SCALE18)) / SCALE18;
            _cancelNodeExpiry(identityId, oldExpiryTs, oldBoost);
        }

        // --- Install new contribution (fresh lock starts now) ---
        uint40 newExpiryTs = _computeExpiryTimestamp(newLockTier);
        uint256 effectiveNowNew = (uint256(raw) * uint256(newMultiplier18)) / SCALE18;
        _applyNodeStakeDelta(identityId, int256(effectiveNowNew));
        if (newLockTier > 0 && newMultiplier18 > SCALE18) {
            uint256 newBoost = (uint256(raw) * (uint256(newMultiplier18) - SCALE18)) / SCALE18;
            _scheduleNodeExpiry(identityId, newExpiryTs, newBoost);
        }

        // --- Write new position preserving stats; delete old ---
        positions[newTokenId] = Position({
            raw: raw,
            lockTier: newLockTier,
            expiryTimestamp: newExpiryTs,
            identityId: identityId,
            cumulativeRewardsClaimed: old.cumulativeRewardsClaimed,
            multiplier18: newMultiplier18,
            lastClaimedEpoch: old.lastClaimedEpoch,
            migrationEpoch: old.migrationEpoch
        });
        delete positions[oldTokenId];

        // --- Per-node enumeration ---
        _popNodeToken(identityId, oldTokenId);
        _pushNodeToken(identityId, newTokenId);

        // v10.0.3 — carries follow the position across the burn-mint so
        // same-epoch redelegate→relock sequences keep their pointers.
        // `newTokenId` is freshly minted (monotonic counter, "New token
        // used" guard above) so its carry list starts empty.
        RewardCarry[] storage oldCarries = rewardCarries[oldTokenId];
        uint256 carryCount = oldCarries.length;
        if (carryCount > 0) {
            RewardCarry[] storage newCarries = rewardCarries[newTokenId];
            for (uint256 i; i < carryCount; i++) {
                newCarries.push(oldCarries[i]);
            }
            delete rewardCarries[oldTokenId];
        }

        // nodeStakeV10 is invariant — same identity, same raw. No emit.

        emit PositionReplaced(
            oldTokenId,
            newTokenId,
            identityId,
            raw,
            newLockTier,
            newExpiryTs,
            newMultiplier18
        );
    }

    function setLastClaimedEpoch(uint256 tokenId, uint32 epoch) external onlyContracts {
        require(positions[tokenId].identityId != 0, "No position");
        positions[tokenId].lastClaimedEpoch = epoch;
        emit LastClaimedEpochUpdated(tokenId, epoch);
    }

    // ============================================================
    //        v10.0.3 — Reward-carry mutators (see struct docs)
    // ============================================================

    /// @notice Record a pointer to an RSS delegator-score slot the
    ///         position's current node/key no longer reaches. Idempotent
    ///         per (identityId, epoch, delegatorKey): the RSS slot
    ///         accumulates across repeat visits (e.g. A→B→A→C in one
    ///         epoch), so a single pointer integrates all of them.
    function addRewardCarry(
        uint256 tokenId,
        uint72 identityId,
        uint32 epoch,
        bytes32 delegatorKey
    ) external onlyContracts {
        require(positions[tokenId].identityId != 0, "No position");
        RewardCarry[] storage list = rewardCarries[tokenId];
        uint256 len = list.length;
        for (uint256 i; i < len; i++) {
            RewardCarry storage c = list[i];
            if (c.identityId == identityId && c.epoch == epoch && c.delegatorKey == delegatorKey) {
                return;
            }
        }
        require(len < MAX_REWARD_CARRIES, "Carry limit");
        list.push(RewardCarry({identityId: identityId, epoch: epoch, delegatorKey: delegatorKey}));
        emit RewardCarryAdded(tokenId, identityId, epoch, delegatorKey);
    }

    /// @notice Drop every carry with `epoch <= maxEpoch` (already
    ///         integrated by the caller's claim pass). Swap-and-pop from
    ///         the tail so each swapped-in element was already visited.
    function clearRewardCarries(uint256 tokenId, uint32 maxEpoch) external onlyContracts {
        RewardCarry[] storage list = rewardCarries[tokenId];
        uint256 removed;
        uint256 i = list.length;
        while (i > 0) {
            i--;
            if (list[i].epoch <= maxEpoch) {
                list[i] = list[list.length - 1];
                list.pop();
                removed++;
            }
        }
        if (removed > 0) {
            emit RewardCarriesCleared(tokenId, maxEpoch, removed);
        }
    }

    function getRewardCarries(uint256 tokenId) external view returns (RewardCarry[] memory) {
        return rewardCarries[tokenId];
    }

    function setMigrationEpoch(uint256 tokenId, uint32 epoch) external onlyContracts {
        require(positions[tokenId].identityId != 0, "No position");
        positions[tokenId].migrationEpoch = epoch;
        emit MigrationEpochSet(tokenId, epoch);
    }

    /// @notice Set the V10 retroactive-claim anchor (D7). One-shot.
    /// @dev    L9 — reverts if already set. Prevents an admin (or a
    ///         compromised admin) from silently rebinding the reward-history
    ///         boundary mid-life.
    function setV10LaunchEpoch(uint256 epoch) external onlyContracts {
        require(v10LaunchEpoch == 0, "V10 launch already set");
        v10LaunchEpoch = epoch;
        emit V10LaunchEpochSet(epoch);
    }

    // ============================================================
    //   Migration credit ledger mutators (onlyContracts)
    // ============================================================

    /// @notice Credit `delegator` with migrated TRAC. Driven by StakingV10's
    ///         drain worker after the TRAC has been physically moved into this
    ///         contract.
    function addMigrationCredit(address delegator, uint96 total) external onlyContracts {
        migrationCredit[delegator] += total;
    }

    /// @notice Spend `amount` of `staker`'s migration credit for one allocation.
    ///         Whether the tier-6/12 lock-credit applies is decided by the caller
    ///         (StakingV10's allocate worker) from the chosen tier — there is no
    ///         per-staker eligibility, so the spend is a plain debit.
    function spendMigrationCredit(address staker, uint96 amount) external onlyContracts {
        require(amount > 0, "Zero amount");
        require(amount <= migrationCredit[staker], "Amount exceeds credit");
        migrationCredit[staker] -= amount;
    }

    /// @notice Set the V8→V10 conviction lock-credit (seconds). Capped strictly
    ///         below the tier-6 lock duration (the shortest credited tier) so
    ///         `expiryShortenedBy < duration` holds and a tier-6 allocation can
    ///         never underflow its expiry. The owner gate lives on the
    ///         DKGStakingConvictionNFT entrypoint that drives this.
    function setConvictionCreditSeconds(uint40 secondsValue) external onlyContracts {
        require(uint256(secondsValue) < _tierDuration(6), "credit >= tier-6 lock");
        convictionCreditSeconds = secondsValue;
        emit ConvictionCreditSecondsSet(secondsValue);
    }

    function deletePosition(uint256 tokenId) external onlyContracts {
        Position memory pos = positions[tokenId];
        require(pos.identityId != 0, "No position");

        uint40 tsNow = uint40(block.timestamp);
        uint96 raw = pos.raw;
        uint72 identityId = pos.identityId;
        uint40 expiryTs = pos.expiryTimestamp;
        uint64 multiplier18 = pos.multiplier18;
        bool stillBoosted = expiryTs != 0 && tsNow < expiryTs;

        _settleNodeTo(identityId, tsNow);

        uint256 effectiveNow = stillBoosted
            ? (uint256(raw) * uint256(multiplier18)) / SCALE18
            : uint256(raw);
        _applyNodeStakeDelta(identityId, -int256(effectiveNow));
        if (stillBoosted && multiplier18 > SCALE18) {
            uint256 boost = (uint256(raw) * (uint256(multiplier18) - SCALE18)) / SCALE18;
            _cancelNodeExpiry(identityId, expiryTs, boost);
        }

        _popNodeToken(identityId, tokenId);
        if (raw > 0) {
            _decreaseNodeStakeV10(identityId, uint256(raw));
        }

        delete positions[tokenId];
        // v10.0.3 — drop any leftover carries. `StakingV10.withdraw`
        // auto-claims first, so only current-epoch (immature) carries can
        // remain here — forfeited like all other current-epoch score.
        delete rewardCarries[tokenId];
        emit PositionDeleted(tokenId);
    }

    // ============================================================
    //       D19 — Raw-only mutators (compound-into-raw model)
    // ============================================================

    function decreaseRaw(uint256 tokenId, uint96 amount) external onlyContracts {
        Position storage pos = positions[tokenId];
        require(pos.identityId != 0, "No position");
        require(pos.raw >= amount, "Insufficient raw");
        if (amount == 0) {
            emit RawDecreased(tokenId, 0, pos.raw);
            return;
        }

        uint40 tsNow = uint40(block.timestamp);
        uint72 identityId = pos.identityId;
        uint40 expiryTs = pos.expiryTimestamp;
        uint64 multiplier18 = pos.multiplier18;
        bool stillBoosted = expiryTs != 0 && tsNow < expiryTs;

        _settleNodeTo(identityId, tsNow);

        // G-6: remove the position's contribution as the ONE-SHOT delta from its
        // current raw — floor(oldRaw*m) - floor(newRaw*m) — so the position's
        // running-stake / boost contribution always equals floor(curRaw*m), exactly
        // what the unwind paths (redelegate / relock / exit) later remove. No
        // incremental-vs-one-shot floor asymmetry, so the strict helper invariants
        // hold without saturation.
        uint256 oldRaw = uint256(pos.raw);
        uint256 newRaw = oldRaw - uint256(amount);
        uint256 effDelta = stillBoosted
            ? ((oldRaw * uint256(multiplier18)) / SCALE18) - ((newRaw * uint256(multiplier18)) / SCALE18)
            : uint256(amount);
        _applyNodeStakeDelta(identityId, -int256(effDelta));

        if (stillBoosted && multiplier18 > SCALE18) {
            uint256 boostDelta = ((oldRaw * (uint256(multiplier18) - SCALE18)) / SCALE18) -
                ((newRaw * (uint256(multiplier18) - SCALE18)) / SCALE18);
            _cancelNodeExpiry(identityId, expiryTs, boostDelta);
        }

        pos.raw = pos.raw - amount;
        _decreaseNodeStakeV10(identityId, uint256(amount));

        emit RawDecreased(tokenId, amount, pos.raw);
    }

    function increaseRaw(uint256 tokenId, uint96 amount) external onlyContracts {
        Position storage pos = positions[tokenId];
        require(pos.identityId != 0, "No position");
        if (amount == 0) {
            emit RawIncreased(tokenId, 0, pos.raw);
            return;
        }

        require(uint256(pos.raw) + uint256(amount) <= type(uint96).max, "Raw overflow");

        uint40 tsNow = uint40(block.timestamp);
        uint72 identityId = pos.identityId;
        uint40 expiryTs = pos.expiryTimestamp;
        uint64 multiplier18 = pos.multiplier18;
        bool stillBoosted = expiryTs != 0 && tsNow < expiryTs;

        _settleNodeTo(identityId, tsNow);

        // G-6: install the position's contribution as the ONE-SHOT delta from its
        // current raw — floor(newRaw*m) - floor(oldRaw*m) — so a reward-compounding
        // claim keeps the position's running-stake / boost contribution equal to
        // floor(curRaw*m), exactly what the unwind paths later remove. This replaces
        // the prior floor(amount*m) increment, whose independent floor caused the
        // incremental-vs-one-shot asymmetry that bricked redelegate/relock (audit
        // G-6); the strict helper invariants now hold without saturation.
        uint256 oldRaw = uint256(pos.raw);
        uint256 newRaw = oldRaw + uint256(amount);
        uint256 effDelta = stillBoosted
            ? ((newRaw * uint256(multiplier18)) / SCALE18) - ((oldRaw * uint256(multiplier18)) / SCALE18)
            : uint256(amount);
        _applyNodeStakeDelta(identityId, int256(effDelta));

        if (stillBoosted && multiplier18 > SCALE18) {
            uint256 boostDelta = ((newRaw * (uint256(multiplier18) - SCALE18)) / SCALE18) -
                ((oldRaw * (uint256(multiplier18) - SCALE18)) / SCALE18);
            // The one-shot delta can be 0 for a small compound (the floored boost
            // doesn't tip to the next wei); _scheduleNodeExpiry reverts on a zero
            // drop, so skip it — the contribution is already exact.
            if (boostDelta != 0) {
                _scheduleNodeExpiry(identityId, expiryTs, boostDelta);
            }
        }

        pos.raw = pos.raw + amount;
        _increaseNodeStakeV10(identityId, uint256(amount));

        emit RawIncreased(tokenId, amount, pos.raw);
    }

    function addCumulativeRewardsClaimed(uint256 tokenId, uint96 amount) external onlyContracts {
        Position storage pos = positions[tokenId];
        require(pos.identityId != 0, "No position");
        if (amount == 0) {
            emit CumulativeRewardsClaimedUpdated(tokenId, 0, pos.cumulativeRewardsClaimed);
            return;
        }

        uint96 newTotal = pos.cumulativeRewardsClaimed + amount;
        require(newTotal >= pos.cumulativeRewardsClaimed, "CRC overflow");
        pos.cumulativeRewardsClaimed = newTotal;
        emit CumulativeRewardsClaimedUpdated(tokenId, amount, newTotal);
    }

    // ============================================================
    //         D3 — Absorbed DelegatorsInfo mutators (V10)
    // ============================================================

    function setIsOperatorFeeClaimedForEpoch(uint72 identityId, uint256 epoch, bool isClaimed) external onlyContracts {
        isOperatorFeeClaimedForEpoch[identityId][epoch] = isClaimed;
        emit IsOperatorFeeClaimedForEpochUpdated(identityId, epoch, isClaimed);
    }

    function setNetNodeEpochRewards(uint72 identityId, uint256 epoch, uint256 amount) external onlyContracts {
        netNodeEpochRewards[identityId][epoch] = amount;
        emit NetNodeEpochRewardsSet(identityId, epoch, amount);
    }

    function getIsOperatorFeeClaimedForEpoch(uint72 identityId, uint256 epoch) external view returns (bool) {
        return isOperatorFeeClaimedForEpoch[identityId][epoch];
    }

    function getNetNodeEpochRewards(uint72 identityId, uint256 epoch) external view returns (uint256) {
        return netNodeEpochRewards[identityId][epoch];
    }

    // ============================================================
    //                          Reads
    // ============================================================

    function getPosition(uint256 tokenId) external view returns (Position memory) {
        return positions[tokenId];
    }

    /// @notice Effective stake for `id` right now (simulated settle to
    ///         `block.timestamp`).
    function getNodeEffectiveStake(uint72 identityId) external view returns (uint256) {
        return _simulateNodeEffectiveStakeAt(identityId, uint40(block.timestamp));
    }

    /// @notice Effective stake for `id` at an arbitrary future timestamp
    ///         `ts` (simulated settle). For `ts < nodeLastSettledAt[id]`
    ///         the function returns 0 — past-history snapshots are NOT
    ///         retained under D26.
    function getNodeEffectiveStakeAtTimestamp(uint72 identityId, uint40 ts) external view returns (uint256) {
        return _simulateNodeEffectiveStakeAt(identityId, ts);
    }

    /// @notice Deprecated adapter for the v2.x "effective stake at end of
    ///         epoch `e`" read surface. Returns the effective stake at
    ///         the LAST SECOND of `epoch` (computed via Chronos), or 0 if
    ///         the epoch is entirely in the pre-settled past. Consumers
    ///         should migrate to `getNodeEffectiveStakeAtTimestamp`.
    /// @dev    L7 — tolerates Chronos returning 0 for unanchored future
    ///         epochs (the naive `- 1` would underflow).
    function getNodeEffectiveStakeAtEpoch(uint72 identityId, uint256 epoch) external view returns (uint256) {
        uint256 nextAnchor = chronos.timestampForEpoch(epoch + 1);
        uint256 epochEnd = nextAnchor == 0 ? type(uint40).max : nextAnchor - 1;
        if (epochEnd > type(uint40).max) epochEnd = type(uint40).max;
        return _simulateNodeEffectiveStakeAt(identityId, uint40(epochEnd));
    }

    function getNodeLastSettledAt(uint72 identityId) external view returns (uint40) {
        return nodeLastSettledAt[identityId];
    }

    function getNodeRunningEffectiveStake(uint72 identityId) external view returns (uint256) {
        return runningNodeEffectiveStake[identityId];
    }

    function getNodeExpiryHead(uint72 identityId) external view returns (uint256) {
        return nodeExpiryHead[identityId];
    }

    function getNodeExpiryTimes(uint72 identityId) external view returns (uint40[] memory) {
        return nodeExpiryTimes[identityId];
    }

    function getNodeExpiryDrop(uint72 identityId, uint40 ts) external view returns (uint256) {
        return nodeExpiryDrop[identityId][ts];
    }

    function getNodePendingExpiryCount(uint72 identityId) external view returns (uint256) {
        return nodeExpiryTimes[identityId].length - nodeExpiryHead[identityId];
    }

    // D15 — V10 stake aggregate reads.
    function getNodeStakeV10(uint72 identityId) external view returns (uint256) {
        return nodeStakeV10[identityId];
    }

    function getTotalStakeV10() external view returns (uint256) {
        return totalStakeV10;
    }

    // D5 — per-node tokenId enumeration reads.
    function getNodeTokens(uint72 identityId) external view returns (uint256[] memory) {
        return nodeTokens[identityId];
    }

    function getNodeTokenCount(uint72 identityId) external view returns (uint256) {
        return nodeTokens[identityId].length;
    }

    function getNodeTokenAt(uint72 identityId, uint256 index) external view returns (uint256) {
        return nodeTokens[identityId][index];
    }

    // ============================================================
    //   v4.0.0 — Operator-fee balance accessors
    //
    // Mirrors the V8 `StakingStorage.{set,increase,decrease,get}OperatorFeeBalance`
    // surface so `StakingV10._claim` can be rewired by handle swap.
    // ============================================================

    function setOperatorFeeBalance(uint72 identityId, uint96 newBalance) external onlyContracts {
        nodeOperatorFeeBalance[identityId] = newBalance;
        emit OperatorFeeBalanceUpdated(identityId, newBalance);
    }

    function increaseOperatorFeeBalance(uint72 identityId, uint96 addedFee) external onlyContracts {
        nodeOperatorFeeBalance[identityId] += addedFee;
        emit OperatorFeeBalanceUpdated(identityId, nodeOperatorFeeBalance[identityId]);
    }

    function decreaseOperatorFeeBalance(uint72 identityId, uint96 removedFee) external onlyContracts {
        nodeOperatorFeeBalance[identityId] -= removedFee;
        emit OperatorFeeBalanceUpdated(identityId, nodeOperatorFeeBalance[identityId]);
    }

    function getOperatorFeeBalance(uint72 identityId) external view returns (uint96) {
        return nodeOperatorFeeBalance[identityId];
    }

    // ============================================================
    //   v4.0.0 — Operator-fee withdrawal request queue
    //
    // Mirrors the V8 `StakingStorage.{create,delete,get,...}OperatorFeeWithdrawalRequest`
    // surface; V10 never populates `indexedOutAmount` (always 0).
    // ============================================================

    function createOperatorFeeWithdrawalRequest(
        uint72 identityId,
        uint96 amount,
        uint96 indexedOutAmount,
        uint256 timestamp
    ) external onlyContracts {
        operatorFeeWithdrawals[identityId] = StakingLib.StakeWithdrawalRequest(amount, indexedOutAmount, timestamp);
        emit OperatorFeeWithdrawalRequestCreated(identityId, amount, indexedOutAmount, timestamp);
    }

    function deleteOperatorFeeWithdrawalRequest(uint72 identityId) external onlyContracts {
        delete operatorFeeWithdrawals[identityId];
        emit OperatorFeeWithdrawalRequestDeleted(identityId);
    }

    function getOperatorFeeWithdrawalRequest(uint72 identityId) external view returns (uint96, uint96, uint256) {
        StakingLib.StakeWithdrawalRequest memory wr = operatorFeeWithdrawals[identityId];
        return (wr.amount, wr.indexedOutAmount, wr.timestamp);
    }

    function getOperatorFeeWithdrawalRequestAmount(uint72 identityId) external view returns (uint96) {
        return operatorFeeWithdrawals[identityId].amount;
    }

    function getOperatorFeeWithdrawalRequestIndexedOutAmount(uint72 identityId) external view returns (uint96) {
        return operatorFeeWithdrawals[identityId].indexedOutAmount;
    }

    function getOperatorFeeWithdrawalRequestTimestamp(uint72 identityId) external view returns (uint256) {
        return operatorFeeWithdrawals[identityId].timestamp;
    }

    function operatorFeeWithdrawalRequestExists(uint72 identityId) external view returns (bool) {
        return operatorFeeWithdrawals[identityId].amount != 0;
    }

    // ============================================================
    //   v4.0.0 — TRAC vault outflow
    //
    // The CSS contract address is the V10 TRAC vault (deposits arrive via
    // `transferFrom(staker, address(this), amount)` from publish/staking
    // callers). `transferStake` (stake movement) and `transferRegistrationDepositFee`
    // (OT-RFC-53 escrow treasury fee) are the outflow paths; both gated to Hub-
    // registered contracts, mirroring V8 `StakingStorage.transferStake`.
    // ============================================================

    function transferStake(address receiver, uint96 stakeAmount) external onlyContracts {
        // Slither: `safeTransfer` (SafeERC20) reverts on failure rather than
        // returning false — the "unchecked-transfer" pattern Slither flags
        // applies to the bare ERC20 `.transfer()` return-value path. This
        // call site is the SAFE wrapper precisely BECAUSE the V10 design
        // upgraded V8's bare `.transfer()` (see StakingStorage.transferStake)
        // to SafeERC20. False positive — kept here as a directive for
        // future maintainers debugging the report.
        // slither-disable-next-line unchecked-transfer
        tokenContract.safeTransfer(receiver, stakeAmount);
        emit StakedTokensTransferred(receiver, stakeAmount);
    }

    /// @notice OT-RFC-53: routes the protocol treasury fee owed on an escrow-funded
    ///         publish/update/extend out of the vault to `treasury`. The SECOND
    ///         vault-outflow path; mirrors {transferStake} (gated to Hub contracts,
    ///         SafeERC20). The caller (KnowledgeAssetsLifecycle) computes `amount`
    ///         (bounded by the consumed escrow) and passes the configured
    ///         `protocolTreasury`; CSS performs only the gated transfer.
    function transferRegistrationDepositFee(address treasury, uint96 amount) external onlyContracts {
        // slither-disable-next-line unchecked-transfer
        tokenContract.safeTransfer(treasury, amount);
        emit RegistrationDepositFeeTransferred(treasury, amount);
    }

    // ============================================================
    //                       Internal helpers
    // ============================================================

    /**
     * @dev Wall-clock expiry computation (D26). Boosts last at least the tier
     *      duration and expire on the next 12-hour bucket. Returns 0 for tier-0
     *      (permanent rest state).
     */
    function _computeExpiryTimestamp(uint40 lockTier) internal view returns (uint40) {
        if (lockTier == 0) return 0;
        uint256 duration = _tierDuration(lockTier);
        uint256 exp = block.timestamp + duration;
        return _bucketExpiryTimestamp(exp);
    }

    function _bucketExpiryTimestamp(uint256 rawExpiry) internal pure returns (uint40) {
        uint256 bucket = uint256(EXPIRY_BUCKET_SECONDS);
        uint256 bucketed = ((rawExpiry + bucket - 1) / bucket) * bucket;
        require(bucketed <= type(uint40).max, "Expiry overflow");
        return uint40(bucketed);
    }

    function _pushNodeToken(uint72 identityId, uint256 tokenId) internal {
        nodeTokenIndex[identityId][tokenId] = nodeTokens[identityId].length;
        nodeTokens[identityId].push(tokenId);
    }

    function _popNodeToken(uint72 identityId, uint256 tokenId) internal {
        uint256[] storage arr = nodeTokens[identityId];
        uint256 idx = nodeTokenIndex[identityId][tokenId];
        uint256 last = arr.length - 1;
        if (idx != last) {
            uint256 movedToken = arr[last];
            arr[idx] = movedToken;
            nodeTokenIndex[identityId][movedToken] = idx;
        }
        arr.pop();
        delete nodeTokenIndex[identityId][tokenId];
    }

    function _increaseNodeStakeV10(uint72 identityId, uint256 amount) internal {
        nodeStakeV10[identityId] += amount;
        totalStakeV10 += amount;
        emit NodeStakeV10Increased(identityId, amount, nodeStakeV10[identityId], totalStakeV10);
    }

    function _decreaseNodeStakeV10(uint72 identityId, uint256 amount) internal {
        nodeStakeV10[identityId] -= amount;
        totalStakeV10 -= amount;
        emit NodeStakeV10Decreased(identityId, amount, nodeStakeV10[identityId], totalStakeV10);
    }
}

contracts/storage/DKGKnowledgeAssets.sol.content:
// SPDX-License-Identifier: Apache-2.0

pragma solidity ^0.8.20;

import {Guardian} from "../Guardian.sol";
import {ERC721} from "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import {KnowledgeAssetLib} from "../libraries/KnowledgeAssetLib.sol";
import {INamed} from "../interfaces/INamed.sol";
import {IVersioned} from "../interfaces/IVersioned.sol";
import {HubDependent} from "../abstract/HubDependent.sol";

/**
 * @title DKGKnowledgeAssets
 * @notice Greenfield KA storage: one ERC-721 per Knowledge Asset (`tokenId == kaId`),
 *         merkle-root history, economics, and ciphertext commitments. No ERC-1155.
 */
contract DKGKnowledgeAssets is INamed, IVersioned, HubDependent, ERC721, Guardian {

    /// @dev `author` is the verified agent identity from the V10.1+
    ///      author-attestation EIP-712 envelope, or `address(0)` for legacy
    ///      callers (`KnowledgeAsset (V10.1 active path)`) that do not perform author
    ///      attestation. Indexers SHOULD prefer this `indexed` field over
    ///      walking storage when filtering KAs by author.
    event KnowledgeAssetCreated(
        uint256 indexed id,
        address indexed author,
        string publishOperationId,
        bytes32 merkleRoot,
        uint88 byteSize,
        uint40 startEpoch,
        uint40 endEpoch,
        uint96 tokenAmount,
        bool isImmutable
    );
    event KnowledgeAssetUpdated(
        uint256 indexed id,
        address indexed author,
        string updateOperationId,
        bytes32 merkleRoot,
        uint256 byteSize,
        uint96 tokenAmount
    );
    event KnowledgeAssetsMinted(uint256 indexed id, address indexed to, uint256 startId, uint256 endId);
    event KnowledgeAssetsBurned(uint256 indexed id, address indexed from, uint256[] tokenIds);
    event KnowledgeAssetPublisherUpdated(uint256 indexed id, address publisher);
    event KnowledgeAssetMerkleRootsUpdated(uint256 indexed id, KnowledgeAssetLib.MerkleRoot[] merkleRoots);
    event KnowledgeAssetMerkleRootAdded(uint256 indexed id, bytes32 merkleRoot);
    event KnowledgeAssetMerkleRootRemoved(uint256 indexed id, bytes32 merkleRoot);
    event KnowledgeAssetMintedUpdated(uint256 indexed id, uint256 minted);
    event KnowledgeAssetBurnedUpdated(uint256 indexed id, uint256[] burned);
    event KnowledgeAssetByteSizeUpdated(uint256 indexed id, uint256 byteSize);
    event KnowledgeAssetChunksAmountUpdated(uint256 indexed id, uint256 chunksAmount);
    event KnowledgeAssetTokenAmountUpdated(uint256 indexed id, uint256 tokenAmount);
    event KnowledgeAssetStartEpochUpdated(uint256 indexed id, uint256 startEpoch);
    event KnowledgeAssetEndEpochUpdated(uint256 indexed id, uint256 endEpoch);
    event URIUpdate(string newURI);

    /// @notice OT-RFC-49 / WS-B: a per-KA PUBLIC `_catalog` commitment was set for
    ///         curated random sampling. Emitted by `setCatalogCommitment`, called by
    ///         `KnowledgeAssetsLifecycle._executePublishCore` immediately after
    ///         `createKnowledgeAsset` when the publish input carries a non-zero
    ///         `(catalogRoot, catalogLeafCount)` pair AND the owning CG is curated.
    ///         Off-chain indexers consume this to know which KAs participate in the
    ///         curated-CG sampling lottery (the picker treats missing commitments as
    ///         "skip this KA").
    event KnowledgeAssetCatalogCommitmentSet(
        uint256 indexed id,
        bytes32 catalogRoot,
        uint32 catalogLeafCount
    );

    // --- OT-RFC-43 Option 1 (variant 1a) errors ---
    /// @notice The supplied packed `kaId`'s high 160 bits (`kaId >> 96`) do not
    ///         equal the attested author. A wallet may only mint KAs within its
    ///         own namespace (OT-RFC-43 §4).
    error KaIdNamespaceMismatch(uint256 kaId, address author);
    /// @notice The supplied (author, number) packs to a `kaId` that is already
    ///         minted — a re-used reservation. Never a silent clobber.
    error KaIdAlreadyMinted(uint256 kaId);
    /// @notice `getLatestKnowledgeAssetId` is deprecated under Option 1 — ids
    ///         are packed (author<<96)|number and not globally sequential, so a
    ///         single "latest id" is meaningless.
    error GetLatestKnowledgeAssetIdDeprecated();

    string private constant _NAME = "DKGKnowledgeAssets";
    string private constant _VERSION = "10.1.0";

    string private _tokenURI;

    uint256 public immutable KNOWLEDGE_ASSET_BATCH_MAX_SIZE;

    // OT-RFC-43 Option 1 (variant 1a): the global auto-increment id counter is
    // retired — KA ids are now caller-supplied packed (author<<96)|number values
    // minted in `createKnowledgeAsset`. This storage SLOT is retained (renamed,
    // never written) so the layout of every field below is unchanged whether
    // this contract is freshly deployed OR upgraded in place (R3 — proxy-vs-
    // redeploy is unresolved; keeping the gap is safe under both). Do not
    // repurpose without resolving R3.
    // slither-disable-next-line unused-state,constable-states
    uint256 private _deprecatedKnowledgeAssetsCounter;
    uint256 private _totalMintedKnowledgeAssetsCounter;
    // V10 retired burn semantics — `burnKnowledgeAssetsTokens` is a
    // `pure` revert stub — so this counter is intentionally never
    // written. Solidity zero-initializes it, and `totalBurned()`
    // correctly returns 0 for legacy ABI consumers. The Slither
    // directive silences the rule WITHOUT changing storage layout;
    // making this `constant` would shift every slot declared below
    // and is out of scope for an ABI-only legacy field.
    // slither-disable-next-line uninitialized-state
    uint256 private _totalBurnedKnowledgeAssetsCounter;

    uint96 private _totalTokenAmount;

    mapping(uint256 => KnowledgeAssetLib.KnowledgeAsset) public knowledgeAssets;
    mapping(uint256 => bool) public isKnowledgeAssetBurned;

    /// @dev Parallel mapping for V10.1+ author attestation.
    ///
    /// Why a parallel map and not a struct field on `MerkleRoot`:
    /// `KnowledgeAsset.merkleRoots` is a dynamic array, so
    /// extending its element struct from 3 to 4 storage slots would
    /// shift the slot stride of every prior root entry — already-
    /// deployed KAs would decode their historical
    /// `publisher`/`merkleRoot`/`timestamp` from the wrong offsets.
    /// Layout-preserving fix: keep `MerkleRoot` at 3 slots and store
    /// the EIP-712-recovered author identity at
    /// `merkleRootAuthors[kaId][rootIndex]`. Both the publish AND the
    /// update path persist a verified EIP-712 author here (OT-RFC-45
    /// owner-only update). `address(0)` means the state change at
    /// `rootIndex` did not carry an attestation — i.e. legacy V8/V9
    /// mutations and admin paths (`setMerkleRoots` / `pushMerkleRoot`,
    /// which zero the slot by design).
    /// Indexers SHOULD prefer the indexed `author` topic on
    /// `KnowledgeAssetCreated` / `KnowledgeAssetUpdated`
    /// events; this on-chain mapping is the canonical lookup for
    /// `/api/knowledge-assets/:id/author` and SPARQL author-filter queries.
    mapping(uint256 => mapping(uint256 => address)) public merkleRootAuthors;

    /// @notice OT-RFC-49: DEAD — slot preserved for storage-layout stability.
    ///
    /// Formerly `ciphertextChunksRoots` (RFC-39 Phase A.5 curated ciphertext
    /// commitment). RFC-49 ("hosting follows access") strips private ciphertext
    /// from cores entirely, so cores can no longer prove a ciphertext chunk —
    /// the curated random-sampling commitment is now the PUBLIC `_catalog` root
    /// (`catalogRoots` below). This slot is intentionally retained (not deleted)
    /// so that removing it cannot shift the base slot of `_authorKaNumberHighWater`
    /// or any later mapping; same discipline as `_deprecatedKnowledgeAssetsCounter`.
    /// Never read or written after RFC-49.
    mapping(uint256 => bytes32) private _deprecatedCiphertextChunksRoots;

    /// @notice OT-RFC-49: DEAD — slot preserved. Formerly `ciphertextChunkCounts`.
    /// See `_deprecatedCiphertextChunksRoots`. Superseded by `catalogLeafCounts`.
    mapping(uint256 => uint32) private _deprecatedCiphertextChunkCounts;

    /// @notice OT-RFC-43 Option 1 (variant 1a): per-author high-water KA `number`
    ///         (the low 96 bits of the packed kaId), stored as `maxNumber + 1` so
    ///         the default `0` unambiguously means "this author has never minted".
    ///         Lets the off-chain allocator reconcile its cold-start floor with a
    ///         single O(1) `getMaxKaNumberForAuthor` view instead of an unbounded
    ///         `KnowledgeAssetCreated` log scan (which overflows the `eth_getLogs`
    ///         block-range cap on networks with deep history). Appended at the END
    ///         of storage to preserve the slot layout of every field above (see the
    ///         layout note on `_deprecatedKnowledgeAssetsCounter`).
    mapping(address => uint256) private _authorKaNumberHighWater;

    /// @notice OT-RFC-49 / WS-B: per-KA PUBLIC `_catalog` Merkle root — the curated
    ///         random-sampling commitment that replaces the stripped ciphertext one.
    ///
    /// Used by `RandomSampling._pickWeightedChallenge` (eligibility + leaf draw) and
    /// `RandomSampling.submitProof` for curated CGs in place of the ciphertext root.
    /// The root commits ONLY to the public `_catalog` leaves of the latest publish —
    /// the same plaintext triples cores host and serve under
    /// `did:dkg:context-graph:<cgId>/_catalog`. Computed off-chain by
    /// `computeCatalogRoot` (a dedicated `V10MerkleTree` over the catalog quads only;
    /// the private sub-roots stay in `merkleRoots[]` for proof-of-existence but are
    /// NEVER drawn). Set by `KnowledgeAssetsLifecycle._executePublishCore` for curated
    /// CGs. Default `bytes32(0)` is the "no catalog commitment" sentinel that
    /// `RandomSampling` uses to skip this KA in the curated draw (legacy KAs read 0 →
    /// grandfathered out until they re-publish post-RFC-49).
    ///
    /// Appended at the END of storage (after `_authorKaNumberHighWater`) to preserve
    /// every existing slot; new slot space cannot masquerade old ciphertext roots as
    /// catalog roots.
    mapping(uint256 => bytes32) public catalogRoots;

    /// @notice OT-RFC-49 / WS-B: per-KA PUBLIC `_catalog` leaf count (POST sort+dedupe,
    ///         == `V10MerkleTree.leafCount`, NOT the raw catalog-quad count).
    ///
    /// The leaf-count input for the `chunkId = uint256(seed) % count` draw in
    /// `RandomSampling._pickWeightedChallenge` step 3 for curated CGs, and the bounds
    /// check in `submitProof`. Must equal the off-chain tree's `leafCount` exactly or
    /// an honest prover cannot build a proof for a drawn `chunkId`.
    mapping(uint256 => uint32) public catalogLeafCounts;

    constructor(
        address hubAddress,
        uint256 _knowledgeAssetBatchMaxSize,
        string memory uri
    ) ERC721("DKG Knowledge Asset", "DKA") Guardian(hubAddress) {
        KNOWLEDGE_ASSET_BATCH_MAX_SIZE = _knowledgeAssetBatchMaxSize;
        _tokenURI = uri;
    }

    function name() public pure virtual override(INamed, ERC721) returns (string memory) {
        return _NAME;
    }

    function version() external pure virtual returns (string memory) {
        return _VERSION;
    }

    function knowledgeAssetBatchMaxSize() external view returns (uint256) {
        return KNOWLEDGE_ASSET_BATCH_MAX_SIZE;
    }

    function createKnowledgeAsset(
        address publisher,
        address author,
        uint256 kaId,
        string calldata publishOperationId,
        bytes32 merkleRoot,
        uint256 knowledgeAssetsAmount,
        uint88 byteSize,
        uint40 startEpoch,
        uint40 endEpoch,
        uint96 tokenAmount,
        bool isImmutable,
        uint32 merkleLeafCount
    ) external onlyContracts returns (uint256) {
        if (knowledgeAssetsAmount != 1) {
            revert KnowledgeAssetLib.ExceededKnowledgeAssetBatchSize(0, 0, knowledgeAssetsAmount, 1);
        }

        // OT-RFC-43 Option 1 (variant 1a): the KA id is supplied by the caller
        // (the off-chain allocator) as a deterministic packed value
        // kaId = (uint160(author) << 96) | uint96(number). The high 160 bits
        // MUST equal the attested author, so a wallet can only mint within its
        // own namespace. Unforgeable: `author` is proven by the EIP-712
        // attestation in `KnowledgeAssetsLifecycle._verifyAuthorAttestation`
        // before this call. NB: the namespace binds to the attested AUTHOR
        // (EIP-712 signer / initial NFT owner), a deliberate divergence from
        // OT-RFC-43 §7's `msg.sender`/publisher diagram — the two coincide in
        // the dominant self-publish case. The global `++_knowledgeAssetsCounter`
        // is removed under 1a (packed-only; no post-tx canonical id).
        if ((kaId >> 96) != uint256(uint160(author))) {
            revert KaIdNamespaceMismatch(kaId, author);
        }
        // Fail fast on a re-used (author, number): the id must not already be
        // minted. `_safeMint` below would also revert, but checking here keeps
        // checks-effects-interactions ordering (no state mutation before the
        // guard) and surfaces a precise error. `kaId` is guaranteed non-zero
        // because `author != address(0)` (enforced upstream), so the `0`
        // sentinel used by `getKnowledgeAssetId` / `isPartOfKnowledgeAsset` is
        // never produced here.
        if (_ownerOf(kaId) != address(0)) {
            revert KaIdAlreadyMinted(kaId);
        }
        // Defense-in-depth (audit hardening): assert the KA struct slot is
        // pristine, not merely unowned. `_ownerOf` proves the token was never
        // minted, but `onlyContracts` setters (`setMerkleRoots` / `pushMerkleRoot`)
        // could in principle pre-seed `knowledgeAssets[kaId]` for an unminted id,
        // which would make the index-0 `merkleRootAuthors` write below land at the
        // wrong index. Under the retired `++_knowledgeAssetsCounter` scheme a fresh
        // id was structurally never-touched; with caller-supplied ids we assert it.
        if (knowledgeAssets[kaId].merkleRoots.length != 0) {
            revert KaIdAlreadyMinted(kaId);
        }

        uint256 knowledgeAssetId = kaId;

        KnowledgeAssetLib.KnowledgeAsset storage ka = knowledgeAssets[knowledgeAssetId];

        ka.merkleRoots.push(
            KnowledgeAssetLib.MerkleRoot(publisher, merkleRoot, block.timestamp)
        );
        // First root of a fresh KA — index 0. `kaId` was just proven unminted
        // above (and `_safeMint` re-enforces it), so this parallel slot is
        // empty; the unconditional shape is kept for parity with
        // `updateKnowledgeAsset` below, where the index can have been
        // previously used (post-pop).
        merkleRootAuthors[knowledgeAssetId][ka.merkleRoots.length - 1] = author;
        ka.byteSize = byteSize;
        ka.startEpoch = startEpoch;
        ka.endEpoch = endEpoch;
        ka.tokenAmount = tokenAmount;
        ka.isImmutable = isImmutable;
        ka.merkleLeafCount = merkleLeafCount;

        unchecked {
            _totalTokenAmount += tokenAmount;
        }

        ka.minted = 1;
        _totalMintedKnowledgeAssetsCounter += 1;

        // OT-RFC-43 Option 1: record the per-author high-water `number` BEFORE the
        // `_safeMint` interaction (checks-effects-interactions — `_safeMint` calls
        // `onERC721Received` on a contract recipient). Stored as `number + 1` so the
        // default 0 means "never minted"; only ever raised, never lowered, so a
        // gap-filling mint of a lower number can never regress the floor. Backs the
        // O(1) `getMaxKaNumberForAuthor` allocator reconcile.
        uint256 mintedNumber = uint96(knowledgeAssetId); // low 96 bits = per-author number
        if (mintedNumber + 1 > _authorKaNumberHighWater[author]) {
            _authorKaNumberHighWater[author] = mintedNumber + 1;
        }

        _safeMint(author, knowledgeAssetId);

        emit KnowledgeAssetCreated(
            knowledgeAssetId,
            author,
            publishOperationId,
            merkleRoot,
            byteSize,
            startEpoch,
            endEpoch,
            tokenAmount,
            isImmutable
        );

        return knowledgeAssetId;
    }

    /// @notice OT-RFC-43 Option 1 (variant 1a): the highest KA `number` already
    ///         minted under `author` (the low 96 bits of its packed kaId), or `-1`
    ///         if `author` has never minted a KA.
    /// @dev    O(1) replacement for enumerating `KnowledgeAssetCreated(id, author)`
    ///         logs. The off-chain allocator's next number for `author` is
    ///         `getMaxKaNumberForAuthor(author) + 1`, so a brand-new author (result
    ///         `-1`) correctly starts at number 0. Returns `int256` so "never minted"
    ///         is a true sentinel rather than colliding with a legitimately-minted
    ///         number 0.
    ///
    ///         PRECONDITION — not backfilled across an in-place storage upgrade.
    ///         `_authorKaNumberHighWater` is only populated by `createKnowledgeAsset`
    ///         from this version (10.0.4) onward. On a fresh deploy or redeploy — the
    ///         expected path, where every KA is minted under this contract — it is
    ///         authoritative for ALL of an author's KAs. But if this storage is
    ///         upgraded IN PLACE over a pre-10.0.4 deployment that already minted KAs,
    ///         those historical authors read `-1` until their next mint. Such an
    ///         in-place upgrade is not supported unless the mapping is backfilled or
    ///         the allocator is explicitly configured to reconcile historical mints by
    ///         another source. The repository deployment flow is a fresh asset-storage
    ///         redeploy/Hub rotation, not bytecode replacement over existing storage.
    /// @param  author The attested author address (the high 160 bits of a packed kaId).
    /// @return The highest KA `number` already minted under `author`, or `-1` if none.
    function getMaxKaNumberForAuthor(address author) external view returns (int256) {
        uint256 highWater = _authorKaNumberHighWater[author];
        return highWater == 0 ? int256(-1) : int256(highWater) - 1;
    }

    function getKnowledgeAsset(
        uint256 id
    ) external view returns (KnowledgeAssetLib.KnowledgeAsset memory) {
        return knowledgeAssets[id];
    }

    /// @dev `author` is the verified author identity for this update. The
    ///      V10.1 update path attests the author (EIP-712) and enforces
    ///      owner-only in `KnowledgeAssetsLifecycle._executeUpdateCore`
    ///      (OT-RFC-45), so callers on that path pass a non-zero, verified
    ///      author. `address(0)` only on admin/legacy paths that carry no
    ///      attestation.
    function updateKnowledgeAsset(
        address publisher,
        address author,
        uint256 id,
        string calldata updateOperationId,
        bytes32 merkleRoot,
        uint256 mintKnowledgeAssetsAmount,
        uint256[] calldata knowledgeAssetsToBurn,
        uint88 byteSize,
        uint96 tokenAmount,
        uint32 merkleLeafCount
    ) external onlyContracts {
        KnowledgeAssetLib.KnowledgeAsset storage ka = knowledgeAssets[id];

        unchecked {
            _totalTokenAmount = _totalTokenAmount - ka.tokenAmount + tokenAmount;
        }

        ka.merkleRoots.push(
            KnowledgeAssetLib.MerkleRoot(publisher, merkleRoot, block.timestamp)
        );
        // Unconditional overwrite — this index may have been written by
        // a previous create/update and then popped via `popMerkleRoot`,
        // leaving the stale author in the parallel slot. Always write
        // the current `author` (the verified EIP-712 author the V10.1
        // lifecycle update path supplies; `address(0)` only on admin/legacy
        // paths) to make the canonical mapping monotonic with the
        // merkleRoots array.
        merkleRootAuthors[id][ka.merkleRoots.length - 1] = author;
        ka.byteSize = byteSize;
        ka.tokenAmount = tokenAmount;
        ka.merkleLeafCount = merkleLeafCount;

        // Burn with an empty list is a no-op (the inner for-loop over
        // tokenIds skips when length == 0). Mint with amount == 0 was
        // previously unconditionally dispatched to `_mintWithoutCheck`,
        // which reverts `MintZeroQuantity` on zero — blocking true
        // metadata-only updates (delta == 0, no mint, no burn) that the
        // KnowledgeAssetsV10 update flow explicitly documents as
        // supported. Guard the mint call so metadata-only rotations work
        // end-to-end. See Codex review round 2, finding 6.
        if (mintKnowledgeAssetsAmount != 0 || knowledgeAssetsToBurn.length != 0) {
            revert KnowledgeAssetLib.ExceededKnowledgeAssetBatchSize(
                id,
                ka.minted,
                mintKnowledgeAssetsAmount,
                0
            );
        }

        emit KnowledgeAssetUpdated(id, author, updateOperationId, merkleRoot, byteSize, tokenAmount);
    }

    /// @notice Lightweight update-path metadata — scalar fields only + the
    /// pre-update merkle-root count. Intended for callers (e.g.
    /// `KnowledgeAssetsV10._executeUpdateCore`) that need the state
    /// summary but NOT the full history arrays.
    ///
    /// Problem: `getKnowledgeAssetMetadata` performs a full
    /// storage → memory struct copy, which walks every entry of
    /// `merkleRoots[]` and `burned[]`. Because both arrays grow
    /// monotonically on every update, the memory cost (and thus gas
    /// cost) of calling that getter from the update path itself scales
    /// linearly — actually super-linearly due to EVM memory-expansion
    /// quadratic term — with the number of prior updates. A KA with
    /// thousands of historical entries eventually becomes un-updatable.
    ///
    /// This getter returns only the scalar slots and the merkle-root
    /// chain length (as a plain `uint256`), so the update path's gas
    /// cost is constant regardless of history.
    ///
    /// Codex review round 3 finding 1.
    function getKnowledgeAssetUpdateContext(
        uint256 id
    )
        external
        view
        returns (
            uint256 merkleRootsCount,
            uint256 minted,
            uint88 byteSize,
            uint40 endEpoch,
            uint96 tokenAmount,
            bool isImmutable,
            uint32 merkleLeafCount
        )
    {
        KnowledgeAssetLib.KnowledgeAsset storage ka = knowledgeAssets[id];
        return (
            ka.merkleRoots.length,
            ka.minted,
            ka.byteSize,
            ka.endEpoch,
            ka.tokenAmount,
            ka.isImmutable,
            ka.merkleLeafCount
        );
    }

    /// @notice Leaf count for the V10 flat-KA Merkle tree at latest root
    ///         (see `merkleLeafCount` on `KnowledgeAsset`).
    function getMerkleLeafCount(uint256 id) external view returns (uint32) {
        return knowledgeAssets[id].merkleLeafCount;
    }

    /// @notice OT-RFC-49 / WS-B: write the curated PUBLIC `_catalog` commitment for
    ///         a freshly-created (or updated) KA. Caller must enforce the curated-CG
    ///         gate — KAS does not look at `ContextGraphStorage` to keep the storage
    ///         layer policy-free.
    ///
    ///         Both fields must be non-zero — partial commitments (a non-zero root
    ///         with zero count, or vice versa) are forbidden because they would
    ///         silently de-rail the picker (zero count → divide-by-zero in the
    ///         catalog-leaf draw, zero root → proof verification against an empty
    ///         tree). `KnowledgeAssetsLifecycle` normalises "no commitment" to a
    ///         literal no-call (no event emitted, both slots stay at default zero).
    ///         Unlike the stripped ciphertext commitment, the catalog commitment is
    ///         re-set on every curated update so the random-sampling surface tracks
    ///         the latest published `_catalog`.
    function setCatalogCommitment(
        uint256 id,
        bytes32 catalogRoot,
        uint32 catalogLeafCount
    ) external onlyContracts {
        require(
            catalogRoot != bytes32(0) && catalogLeafCount > 0,
            "Invalid catalog commitment"
        );
        catalogRoots[id] = catalogRoot;
        catalogLeafCounts[id] = catalogLeafCount;

        emit KnowledgeAssetCatalogCommitmentSet(id, catalogRoot, catalogLeafCount);
    }

    /// @notice OT-RFC-49 / WS-B: latest PUBLIC `_catalog` Merkle root for a curated
    ///         KA, or `bytes32(0)` if no commitment was ever set (public KA, or a
    ///         legacy curated KA that has not re-published since RFC-49).
    ///         `RandomSampling` treats the zero sentinel as "skip this KA in the
    ///         curated draw".
    function getCatalogRoot(uint256 id) external view returns (bytes32) {
        return catalogRoots[id];
    }

    /// @notice OT-RFC-49 / WS-B: PUBLIC `_catalog` leaf count for a curated KA, or
    ///         `0` if no commitment was ever set. Used as the leaf-count input for
    ///         the curated picker's `chunkId = seed % count` draw and as the bounds
    ///         check in `submitProof`. Equals the off-chain `V10MerkleTree.leafCount`
    ///         (post sort+dedupe), never the raw catalog-quad count.
    function getCatalogLeafCount(uint256 id) external view returns (uint32) {
        return catalogLeafCounts[id];
    }

    function getKnowledgeAssetMetadata(
        uint256 id
    )
        external
        view
        returns (
            KnowledgeAssetLib.MerkleRoot[] memory,
            uint256[] memory,
            uint256,
            uint88,
            uint40,
            uint40,
            uint96,
            bool
        )
    {
        KnowledgeAssetLib.KnowledgeAsset memory ka = knowledgeAssets[id];

        return (
            ka.merkleRoots,
            ka.burned,
            ka.minted,
            ka.byteSize,
            ka.startEpoch,
            ka.endEpoch,
            ka.tokenAmount,
            ka.isImmutable
        );
    }

    /// @dev Greenfield: batch mint/burn removed. Updates rotate merkle state only.
    function mintKnowledgeAssetsTokens(uint256, address, uint256) public pure {
        revert KnowledgeAssetLib.ExceededKnowledgeAssetBatchSize(0, 0, 1, 0);
    }

    function burnKnowledgeAssetsTokens(uint256, address, uint256[] calldata) public pure {
        revert KnowledgeAssetLib.ExceededKnowledgeAssetBatchSize(0, 0, 1, 0);
    }

    function getMerkleRoots(uint256 id) external view returns (KnowledgeAssetLib.MerkleRoot[] memory) {
        return knowledgeAssets[id].merkleRoots;
    }

    function setMerkleRoots(
        uint256 id,
        KnowledgeAssetLib.MerkleRoot[] memory _merkleRoots
    ) external onlyContracts {
        // Wholesale replacement — clear the parallel author mapping for
        // the union of old and new index ranges so stale authors from
        // either side cannot leak through. The MerkleRoot struct itself
        // carries no author field (parallel-mapping design), so callers
        // of this admin path cannot supply authors here; effective
        // post-condition is "all entries unauthenticated until a
        // subsequent create/update writes them". Loop bounded by the
        // larger of the two lengths.
        uint256 oldLen = knowledgeAssets[id].merkleRoots.length;
        uint256 newLen = _merkleRoots.length;
        uint256 maxLen = oldLen > newLen ? oldLen : newLen;
        for (uint256 i = 0; i < maxLen; i++) {
            delete merkleRootAuthors[id][i];
        }
        knowledgeAssets[id].merkleRoots = _merkleRoots;

        emit KnowledgeAssetMerkleRootsUpdated(id, _merkleRoots);
    }

    function getMerkleRootObjectByIndex(
        uint256 id,
        uint256 index
    ) external view returns (KnowledgeAssetLib.MerkleRoot memory) {
        return knowledgeAssets[id].merkleRoots[index];
    }

    function getMerkleRootByIndex(uint256 id, uint256 index) external view returns (bytes32) {
        return knowledgeAssets[id].merkleRoots[index].merkleRoot;
    }

    function getMerkleRootPublisherByIndex(uint256 id, uint256 index) external view returns (address) {
        return knowledgeAssets[id].merkleRoots[index].publisher;
    }

    function getMerkleRootTimestampByIndex(uint256 id, uint256 index) external view returns (uint256) {
        return knowledgeAssets[id].merkleRoots[index].timestamp;
    }

    function getLatestMerkleRootObject(uint256 id) external view returns (KnowledgeAssetLib.MerkleRoot memory) {
        return _safeGetLatestMerkleRootObject(id);
    }

    function getLatestMerkleRoot(uint256 id) external view returns (bytes32) {
        return _safeGetLatestMerkleRootObject(id).merkleRoot;
    }

    function getLatestMerkleRootPublisher(uint256 id) external view returns (address) {
        return _safeGetLatestMerkleRootObject(id).publisher;
    }

    function getLatestMerkleRootTimestamp(uint256 id) external view returns (uint256) {
        return _safeGetLatestMerkleRootObject(id).timestamp;
    }

    function getMerkleRootAuthorByIndex(uint256 id, uint256 index) external view returns (address) {
        // Bounds-check via the canonical merkleRoots array so out-of-range
        // queries revert the same way as the other index-based getters,
        // rather than silently returning address(0) from the parallel
        // mapping (which has no concept of "valid index").
        require(index < knowledgeAssets[id].merkleRoots.length, "Index out of bounds");
        return merkleRootAuthors[id][index];
    }

    /// @notice Verified author identity for the latest merkle-root entry
    /// of `id`. Returns `address(0)` if the latest state change did not
    /// carry an author attestation (legacy/admin path only; both the publish
    /// and the V10.1 update path now attest the author — OT-RFC-45). Used by
    /// `/api/get` and other off-chain readers as the
    /// canonical "who authored this KA" lookup — chain wins over any
    /// off-chain `dkg:authoredBy` triple.
    function getLatestMerkleRootAuthor(uint256 id) external view returns (address) {
        uint256 len = knowledgeAssets[id].merkleRoots.length;
        if (len == 0) return address(0);
        return merkleRootAuthors[id][len - 1];
    }

    function pushMerkleRoot(address publisher, uint256 id, bytes32 merkleRoot) external onlyContracts {
        knowledgeAssets[id].merkleRoots.push(
            KnowledgeAssetLib.MerkleRoot(publisher, merkleRoot, block.timestamp)
        );
        // Defensive clear: this index may have been used by a previously
        // popped author entry (`merkleRoots.length` cycles via push/pop).
        // Without the explicit `delete`, an unauthenticated push after a
        // pop would inherit the popped entry's author and `getLatestMerkleRootAuthor`
        // would lie. Legacy `pushMerkleRoot` carries no author by design —
        // always zero the parallel slot.
        delete merkleRootAuthors[id][knowledgeAssets[id].merkleRoots.length - 1];

        emit KnowledgeAssetMerkleRootAdded(id, merkleRoot);
    }

    function popMerkleRoot(uint256 id) external onlyContracts {
        uint256 oldLen = knowledgeAssets[id].merkleRoots.length;
        bytes32 latestMerkleRoot = _safeGetLatestMerkleRootObject(id).merkleRoot;
        knowledgeAssets[id].merkleRoots.pop();
        // Clear the parallel author slot for the popped index. Without
        // this, the slot survives and a later push at the same index can
        // resurrect a stale author. `oldLen > 0` guards the empty-array
        // case (pop on empty would have reverted on the line above; the
        // `_safeGetLatestMerkleRootObject` returns a zero-tuple but the
        // pop itself reverts on length 0 — kept defensive).
        if (oldLen > 0) {
            delete merkleRootAuthors[id][oldLen - 1];
        }

        emit KnowledgeAssetMerkleRootRemoved(id, latestMerkleRoot);
    }

    function getMinted(uint256 id) external view returns (uint256) {
        return knowledgeAssets[id].minted;
    }

    function setMinted(uint256 id, uint256 _minted) external onlyContracts {
        knowledgeAssets[id].minted = _minted;

        emit KnowledgeAssetMintedUpdated(id, _minted);
    }

    function getBurned(uint256 id) external view returns (uint256[] memory) {
        return knowledgeAssets[id].burned;
    }

    function getBurnedAmount(uint256 id) external view returns (uint256) {
        return knowledgeAssets[id].burned.length;
    }

    function setBurned(uint256 id, uint256[] calldata _burned) external onlyContracts {
        knowledgeAssets[id].burned = _burned;

        emit KnowledgeAssetBurnedUpdated(id, _burned);
    }

    function getByteSize(uint256 id) external view returns (uint88) {
        return knowledgeAssets[id].byteSize;
    }

    function setByteSize(uint256 id, uint88 _byteSize) external onlyContracts {
        knowledgeAssets[id].byteSize = _byteSize;

        emit KnowledgeAssetByteSizeUpdated(id, _byteSize);
    }

    function getTokenAmount(uint256 id) external view returns (uint96) {
        return knowledgeAssets[id].tokenAmount;
    }

    function setTokenAmount(uint256 id, uint96 _tokenAmount) external onlyContracts {
        _totalTokenAmount = _totalTokenAmount - knowledgeAssets[id].tokenAmount + _tokenAmount;
        knowledgeAssets[id].tokenAmount = _tokenAmount;

        emit KnowledgeAssetTokenAmountUpdated(id, _tokenAmount);
    }

    function getStartEpoch(uint256 id) external view returns (uint40) {
        return knowledgeAssets[id].startEpoch;
    }

    function setStartEpoch(uint256 id, uint40 _startEpoch) external onlyContracts {
        knowledgeAssets[id].startEpoch = _startEpoch;

        emit KnowledgeAssetStartEpochUpdated(id, _startEpoch);
    }

    function getEndEpoch(uint256 id) external view returns (uint40) {
        return knowledgeAssets[id].endEpoch;
    }

    function setEndEpoch(uint256 id, uint40 _endEpoch) external onlyContracts {
        knowledgeAssets[id].endEpoch = _endEpoch;

        emit KnowledgeAssetEndEpochUpdated(id, _endEpoch);
    }

    /// @notice DEPRECATED under OT-RFC-43 Option 1 (variant 1a). KA ids are
    ///         packed (author<<96)|number values, not globally sequential, so a
    ///         single "latest id" is meaningless. Always reverts — enumerate
    ///         KAs via the `KnowledgeAssetCreated` event (or per-CG lists).
    function getLatestKnowledgeAssetId() external pure returns (uint256) {
        revert GetLatestKnowledgeAssetIdDeprecated();
    }

    function currentTotalSupply() external view returns (uint256) {
        return _totalMintedKnowledgeAssetsCounter - _totalBurnedKnowledgeAssetsCounter;
    }

    function totalMinted() external view returns (uint256) {
        return _totalMintedKnowledgeAssetsCounter;
    }

    function totalBurned() external view returns (uint256) {
        return _totalBurnedKnowledgeAssetsCounter;
    }

    function getTotalTokenAmount() external view returns (uint96) {
        return _totalTokenAmount;
    }

    function isPartOfKnowledgeAsset(uint256 id, uint256 tokenId) external view returns (bool) {
        return id == tokenId && _ownerOf(tokenId) != address(0);
    }

    function getKnowledgeAssetId(uint256 tokenId) external view returns (uint256) {
        if (_ownerOf(tokenId) == address(0)) {
            return 0;
        }
        return tokenId;
    }

    function getKnowledgeAssetsRange(uint256 id) external view returns (uint256, uint256, uint256[] memory) {
        KnowledgeAssetLib.KnowledgeAsset memory ka = knowledgeAssets[id];
        if (ka.minted == 0) {
            return (0, 0, ka.burned);
        }
        return (id, id, ka.burned);
    }

    function getKnowledgeAssetsAmount(uint256 id) external view returns (uint256) {
        KnowledgeAssetLib.KnowledgeAsset memory ka = knowledgeAssets[id];
        return ka.minted - ka.burned.length;
    }

    function isKnowledgeAssetOwner(address owner, uint256 id) external view returns (bool) {
        return ownerOf(id) == owner;
    }

    function setURI(string memory baseURI) external onlyHub {
        _tokenURI = baseURI;
        emit URIUpdate(baseURI);
    }

    function tokenURI(uint256 tokenId) public view override returns (string memory) {
        _requireOwned(tokenId);
        return _tokenURI;
    }

    function _safeGetLatestMerkleRootObject(
        uint256 id
    ) internal view returns (KnowledgeAssetLib.MerkleRoot memory) {
        KnowledgeAssetLib.KnowledgeAsset memory ka = knowledgeAssets[id];
        if (ka.merkleRoots.length == 0) {
            return KnowledgeAssetLib.MerkleRoot(address(0), bytes32(0), 0);
        }
        return ka.merkleRoots[ka.merkleRoots.length - 1];
    }

}

contracts/storage/EpochStorage.sol.content:
// SPDX-License-Identifier: Apache-2.0

pragma solidity ^0.8.20;

import {Chronos} from "./Chronos.sol";
import {HubDependent} from "../abstract/HubDependent.sol";
import {INamed} from "../interfaces/INamed.sol";
import {IVersioned} from "../interfaces/IVersioned.sol";

contract EpochStorage is INamed, IVersioned, HubDependent {
    string private constant _NAME = "EpochStorage";
    // 10.0.4 — OT-RFC-51 "Publishing Allocation": the per-node
    //          produced-knowledge-value accounting is repurposed as
    //          committed PCA "publishing allocation". The mappings,
    //          mutator, event, and getters are renamed
    //          (`*ProducedKnowledgeValue*` -> `*PublishingAllocation*`)
    //          and a net-zero `moveEpochPublishingAllocation` mutator is
    //          added so a PCA can re-designate its primary node without
    //          changing the epoch total (K_total).
    string private constant _VERSION = "10.0.4";

    event EpochPublishingAllocationAdded(uint72 indexed identityId, uint256 indexed epoch, uint96 amount);
    event TokensAddedToEpochRange(
        uint256 indexed shardId,
        uint256 startEpoch,
        uint256 endEpoch,
        uint96 tokenAmount,
        uint96 remainder
    );
    event EpochTokensPaidOut(uint256 indexed shardId, uint256 indexed epoch, uint72 indexed identityId, uint96 amount);
    event EpochsFinalized(uint256 indexed shardId, uint256 startEpoch, uint256 endEpoch);

    Chronos public chronos;

    mapping(uint256 => uint256) public lastFinalizedEpoch;
    mapping(uint256 => uint96) public accumulatedRemainder;

    mapping(uint256 => mapping(uint256 => int96)) public diff;
    mapping(uint256 => mapping(uint256 => uint96)) public cumulative;
    mapping(uint256 => mapping(uint256 => uint96)) public distributed;

    mapping(uint72 => mapping(uint256 => uint96)) public nodesEpochPublishingAllocation;
    mapping(uint256 => uint96) public epochPublishingAllocation;
    mapping(uint256 => uint96) public epochNodeMaxPublishingAllocation;

    mapping(uint72 => mapping(uint256 => mapping(uint256 => uint96))) public nodesPaidOut;

    constructor(address hubAddress) HubDependent(hubAddress) {}

    function initialize() public onlyHub {
        chronos = Chronos(hub.getContractAddress("Chronos"));
    }

    function name() external pure virtual override returns (string memory) {
        return _NAME;
    }

    function version() external pure virtual override returns (string memory) {
        return _VERSION;
    }

    function addEpochPublishingAllocation(
        uint72 identityId,
        uint256 epoch,
        uint96 amount
    ) external onlyContracts {
        nodesEpochPublishingAllocation[identityId][epoch] += amount;
        epochPublishingAllocation[epoch] += amount;

        // Maintain the per-epoch node max so its (public) getters stay
        // consistent. The OT-RFC-51 scoring path does NOT read it
        // (RandomSampling reads only getNodeEpochPublishingAllocation /
        // getEpochPublishingAllocation), but the mapping cannot be removed —
        // it precedes `nodesPaidOut` in this persistent (non-fresh-state)
        // storage layout — and leaving it written-nowhere/read-in-getters
        // trips Slither's uninitialized-state finding. The compare/SSTORE is
        // negligible against the surrounding accounting.
        if (nodesEpochPublishingAllocation[identityId][epoch] > epochNodeMaxPublishingAllocation[epoch]) {
            epochNodeMaxPublishingAllocation[epoch] = nodesEpochPublishingAllocation[identityId][epoch];
        }

        emit EpochPublishingAllocationAdded(identityId, epoch, amount);
    }

    /// @notice OT-RFC-51: move `amount` of publishing allocation from one
    ///         node to another within a single `epoch`. Used when a PCA
    ///         re-designates its primary node — the epoch total
    ///         (`epochPublishingAllocation`, i.e. K_total) is intentionally
    ///         NOT touched, so the move is net-zero on the denominator of
    ///         every node's publishing factor.
    /// @dev    `epochNodeMaxPublishingAllocation` is a per-epoch HIGH-WATER
    ///         MARK, maintained identically on the add and move paths: it is
    ///         only ever RAISED (when the destination's new value exceeds it),
    ///         never lowered by the `fromId` decrement — computing the true
    ///         current max after a decrement would need an O(nodes) scan.
    ///         Nothing on-chain reads it (scoring reads only
    ///         get(Node)EpochPublishingAllocation); it exists for off-chain
    ///         observability, for which the high-water-mark semantic is correct.
    function moveEpochPublishingAllocation(
        uint72 fromId,
        uint72 toId,
        uint256 epoch,
        uint96 amount
    ) external onlyContracts {
        nodesEpochPublishingAllocation[fromId][epoch] -= amount;
        nodesEpochPublishingAllocation[toId][epoch] += amount; // epoch total unchanged -> K_total net-zero

        if (nodesEpochPublishingAllocation[toId][epoch] > epochNodeMaxPublishingAllocation[epoch]) {
            epochNodeMaxPublishingAllocation[epoch] = nodesEpochPublishingAllocation[toId][epoch];
        }
    }

    function getEpochPublishingAllocation(uint256 epoch) external view returns (uint96) {
        return epochPublishingAllocation[epoch];
    }

    function getCurrentEpochPublishingAllocation() external view returns (uint96) {
        return epochPublishingAllocation[chronos.getCurrentEpoch()];
    }

    function getPreviousEpochPublishingAllocation() external view returns (uint96) {
        uint256 currentEpoch = chronos.getCurrentEpoch();
        if (currentEpoch <= 1) {
            return 0;
        }
        return epochPublishingAllocation[currentEpoch - 1];
    }

    function getNodeEpochPublishingAllocation(uint72 identityId, uint256 epoch) external view returns (uint96) {
        return nodesEpochPublishingAllocation[identityId][epoch];
    }

    function getNodeCurrentEpochPublishingAllocation(uint72 identityId) external view returns (uint96) {
        return nodesEpochPublishingAllocation[identityId][chronos.getCurrentEpoch()];
    }

    function getNodePreviousEpochPublishingAllocation(uint72 identityId) external view returns (uint96) {
        uint256 currentEpoch = chronos.getCurrentEpoch();
        if (currentEpoch <= 1) {
            return 0;
        }
        return nodesEpochPublishingAllocation[identityId][currentEpoch - 1];
    }

    function getEpochNodeMaxPublishingAllocation(uint256 epoch) external view returns (uint96) {
        return epochNodeMaxPublishingAllocation[epoch];
    }

    function getCurrentEpochNodeMaxPublishingAllocation() external view returns (uint96) {
        return epochNodeMaxPublishingAllocation[chronos.getCurrentEpoch()];
    }

    function getPreviousEpochNodeMaxPublishingAllocation() external view returns (uint96) {
        uint256 currentEpoch = chronos.getCurrentEpoch();
        if (currentEpoch <= 1) {
            return 0;
        }
        return epochNodeMaxPublishingAllocation[currentEpoch - 1];
    }

    function getNodeEpochPublishingAllocationPercentage(
        uint72 identityId,
        uint256 epoch
    ) external view returns (uint256) {
        if (epochPublishingAllocation[epoch] == 0) {
            return 0;
        }

        return
            (uint256(nodesEpochPublishingAllocation[identityId][epoch]) * 1e18) / epochPublishingAllocation[epoch];
    }

    function getNodeCurrentEpochPublishingAllocationPercentage(uint72 identityId) external view returns (uint256) {
        uint256 currentEpoch = chronos.getCurrentEpoch();

        if (epochPublishingAllocation[currentEpoch] == 0) {
            return 0;
        }

        return ((uint256(nodesEpochPublishingAllocation[identityId][currentEpoch]) * 1e18) /
            epochPublishingAllocation[currentEpoch]);
    }

    function getNodePreviousEpochPublishingAllocationPercentage(uint72 identityId) external view returns (uint256) {
        uint256 currentEpoch = chronos.getCurrentEpoch();
        if (currentEpoch <= 1 || epochPublishingAllocation[currentEpoch - 1] == 0) {
            return 0;
        }
        return ((uint256(nodesEpochPublishingAllocation[identityId][currentEpoch - 1]) * 1e18) /
            epochPublishingAllocation[currentEpoch - 1]);
    }

    function addTokensToEpochRange(
        uint256 shardId,
        uint256 startEpoch,
        uint256 endEpoch,
        uint96 tokenAmount
    ) external onlyContracts {
        // SECURITY FIX: a credit whose startEpoch is already FINALIZED is
        // otherwise lost forever. `_finalizeEpochsUpTo` only folds `diff` for
        // `(lastFinalizedEpoch, currentEpoch-1]` and never revisits a finalized
        // epoch, so `diff[startEpoch] += p` at `startEpoch <= lastFinalizedEpoch`
        // is never folded into `cumulative` (the tokens vanish — stranded in the
        // contract with no payable pool entry) and the paired
        // `diff[endEpoch+1] -= p` later under-credits an unrelated future epoch.
        //
        // Clamp the range up to `lastFinalizedEpoch + 1` — the first epoch NOT
        // yet folded into `cumulative`, and therefore still payable (epochs above
        // `lastFinalizedEpoch` are read via on-the-fly simulation in
        // `getEpochPool`). This is the minimal correction: it rescues only the
        // credits that were genuinely lost (finalized epochs) and lands them in
        // the CLOSEST still-creditable epoch, preserving the caller's intended
        // attribution as much as possible — PublishingConviction deliberately
        // attributes a closed billing window to the chain epochs it overlapped,
        // so forcing `currentEpoch` here would misattribute/delay those rewards
        // on an idle shard. Any stricter "settle into the current epoch" policy
        // belongs at the specific caller, not in this shared primitive. Clamp,
        // don't revert: lazy past-window settlement is an intended pattern.
        uint256 firstOpenEpoch = lastFinalizedEpoch[shardId] + 1;
        if (startEpoch < firstOpenEpoch) {
            startEpoch = firstOpenEpoch;
            if (endEpoch < startEpoch) {
                endEpoch = startEpoch;
            }
        }

        uint256 numEpochs = endEpoch - startEpoch + 1;

        uint96 totalTokens = tokenAmount + accumulatedRemainder[shardId];
        uint96 tokensPerEpochU = uint96(totalTokens / numEpochs);
        uint96 remainder = uint96(totalTokens % numEpochs);

        accumulatedRemainder[shardId] = remainder;

        int96 tokensPerEpoch = int96(tokensPerEpochU);

        diff[shardId][startEpoch] += tokensPerEpoch;
        diff[shardId][endEpoch + 1] -= tokensPerEpoch;

        uint256 currentEpoch = chronos.getCurrentEpoch();
        if (currentEpoch > 1) {
            _finalizeEpochsUpTo(shardId, currentEpoch - 1);
        }

        emit TokensAddedToEpochRange(shardId, startEpoch, endEpoch, tokenAmount, remainder);
    }

    function payOutEpochTokens(
        uint256 shardId,
        uint256 epoch,
        uint72 identityId,
        uint96 amount
    ) external onlyContracts {
        uint256 currentEpoch = chronos.getCurrentEpoch();
        if (currentEpoch > 1) {
            _finalizeEpochsUpTo(shardId, currentEpoch - 1);
        }

        distributed[shardId][epoch] += amount;
        nodesPaidOut[identityId][shardId][epoch] += amount;

        emit EpochTokensPaidOut(shardId, epoch, identityId, amount);
    }

    function getEpochPool(uint256 shardId, uint256 epoch) public view returns (uint96) {
        if (epoch <= lastFinalizedEpoch[shardId]) {
            return cumulative[shardId][epoch];
        } else {
            return _simulateEpochFinalization(shardId, epoch);
        }
    }

    function getEpochRemainingPool(uint256 shardId, uint256 epoch) public view returns (uint96) {
        if (epoch <= lastFinalizedEpoch[shardId]) {
            return cumulative[shardId][epoch] - distributed[shardId][epoch];
        } else {
            return _simulateEpochFinalization(shardId, epoch) - distributed[shardId][epoch];
        }
    }

    function getCurrentEpochPool(uint256 shardId) external view returns (uint96) {
        return getEpochPool(shardId, chronos.getCurrentEpoch());
    }

    function getCurrentEpochRemainingPool(uint256 shardId) external view returns (uint96) {
        return getEpochRemainingPool(shardId, chronos.getCurrentEpoch());
    }

    function getPreviousEpochPool(uint256 shardId) external view returns (uint96) {
        uint256 currentEpoch = chronos.getCurrentEpoch();
        if (currentEpoch <= 1) {
            return 0;
        }
        return getEpochPool(shardId, currentEpoch - 1);
    }

    function getPreviousEpochRemainingPool(uint256 shardId) external view returns (uint96) {
        uint256 currentEpoch = chronos.getCurrentEpoch();
        if (currentEpoch <= 1) {
            return 0;
        }
        return getEpochRemainingPool(shardId, currentEpoch - 1);
    }

    function getEpochRangePool(uint256 shardId, uint256 startEpoch, uint256 endEpoch) external view returns (uint96) {
        uint256 lastFinalized = lastFinalizedEpoch[shardId];
        uint96 totalPool = 0;

        if (startEpoch <= lastFinalized) {
            for (uint256 epoch = startEpoch; epoch <= lastFinalized && epoch <= endEpoch; epoch++) {
                totalPool += cumulative[shardId][epoch];
            }
        }

        uint96 simulatedCumulative = lastFinalized > 0 ? cumulative[shardId][lastFinalized] : cumulative[shardId][1];
        for (uint256 epoch = lastFinalized + 1; epoch <= endEpoch; epoch++) {
            int96 tmp = int96(simulatedCumulative) + diff[shardId][epoch];
            simulatedCumulative = uint96(tmp);
            if (epoch >= startEpoch) {
                totalPool += simulatedCumulative;
            }
        }

        return totalPool;
    }

    function getEpochDistributedPool(uint256 shardId, uint256 epoch) external view returns (uint96) {
        return distributed[shardId][epoch];
    }

    function getPreviousEpochDistributedPool(uint256 shardId) external view returns (uint96) {
        uint256 currentEpoch = chronos.getCurrentEpoch();
        if (currentEpoch <= 1) {
            return 0;
        }
        return distributed[shardId][currentEpoch - 1];
    }

    function getNodeEpochPaidOut(uint256 shardId, uint72 identityId, uint256 epoch) external view returns (uint96) {
        return nodesPaidOut[identityId][shardId][epoch];
    }

    function getNodePreviousEpochPaidOut(uint256 shardId, uint72 identityId) external view returns (uint96) {
        uint256 currentEpoch = chronos.getCurrentEpoch();
        if (currentEpoch <= 1) {
            return 0;
        }
        return nodesPaidOut[identityId][shardId][currentEpoch - 1];
    }

    function _finalizeEpochsUpTo(uint256 shardId, uint256 epoch) internal {
        uint256 startEpoch = lastFinalizedEpoch[shardId] + 1;
        for (uint256 e = startEpoch; e <= epoch; e++) {
            int96 prev = 0;
            if (e > 1) {
                prev = int96(cumulative[shardId][e - 1]);
            }
            cumulative[shardId][e] = uint96(prev + diff[shardId][e]);
        }
        lastFinalizedEpoch[shardId] = epoch;

        emit EpochsFinalized(shardId, startEpoch, epoch);
    }

    function _simulateEpochFinalization(uint256 shardId, uint256 epoch) internal view returns (uint96) {
        if (epoch <= lastFinalizedEpoch[shardId]) {
            return cumulative[shardId][epoch];
        }

        uint96 simulatedCumulative = 0;
        if (lastFinalizedEpoch[shardId] > 0) {
            simulatedCumulative = cumulative[shardId][lastFinalizedEpoch[shardId]];
        }

        for (uint256 e = lastFinalizedEpoch[shardId] + 1; e <= epoch; e++) {
            int96 prev = int96(simulatedCumulative);
            int96 result = prev + diff[shardId][e];
            simulatedCumulative = uint96(result);
        }

        return simulatedCumulative;
    }
}

contracts/storage/Hub.sol.content:
// SPDX-License-Identifier: Apache-2.0

pragma solidity ^0.8.20;

import {IContractStatus} from "../interfaces/IContractStatus.sol";
import {ICustodian} from "../interfaces/ICustodian.sol";
import {IInitializable} from "../interfaces/IInitializable.sol";
import {INamed} from "../interfaces/INamed.sol";
import {IVersioned} from "../interfaces/IVersioned.sol";
import {HubLib} from "../libraries/HubLib.sol";
import {UnorderedNamedContractDynamicSet} from "../libraries/UnorderedNamedContractDynamicSet.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";

contract Hub is INamed, IVersioned, Ownable {
    using UnorderedNamedContractDynamicSet for UnorderedNamedContractDynamicSet.Set;

    event NewContract(string contractName, address newContractAddress);
    event ContractChanged(string contractName, address newContractAddress);
    event NewAssetStorage(string contractName, address newContractAddress);
    event AssetStorageChanged(string contractName, address newContractAddress);
    event ContractRemoved(string contractName, address contractAddress);
    event AssetStorageRemoved(string contractName, address contractAddress);

    string private constant _NAME = "Hub";
    string private constant _VERSION = "1.0.0";

    UnorderedNamedContractDynamicSet.Set internal contractSet;
    UnorderedNamedContractDynamicSet.Set internal assetStorageSet;

    constructor() Ownable(msg.sender) {}

    // @dev Only transactions by HubController owner or one of the owners of the MultiSig Wallet
    modifier onlyOwnerOrMultiSigOwner() {
        _checkOwnerOrMultiSigOwner();
        _;
    }

    function name() external pure virtual override returns (string memory) {
        return _NAME;
    }

    function version() external pure virtual override returns (string memory) {
        return _VERSION;
    }

    function setContractAddress(
        string calldata contractName,
        address newContractAddress
    ) external onlyOwnerOrMultiSigOwner {
        _setContractAddress(contractName, newContractAddress);
    }

    function setAssetStorageAddress(string calldata assetStorageName, address assetStorageAddress) external onlyOwner {
        _setAssetStorageAddress(assetStorageName, assetStorageAddress);
    }

    function removeContractByName(string calldata contractName) external onlyOwner {
        if (contractSet.exists(contractName)) {
            address contractAddress = contractSet.get(contractName).addr;

            contractSet.remove(contractName);

            emit ContractRemoved(contractName, contractAddress);
        }
    }

    function removeContractByAddress(address contractAddress) external onlyOwner {
        if (contractSet.exists(contractAddress)) {
            string memory contractName = contractSet.get(contractAddress).name;

            contractSet.remove(contractAddress);

            emit ContractRemoved(contractName, contractAddress);
        }
    }

    function removeAssetStorageByName(string calldata assetStorageName) external onlyOwner {
        if (assetStorageSet.exists(assetStorageName)) {
            address assetStorageAddress = assetStorageSet.get(assetStorageName).addr;

            assetStorageSet.remove(assetStorageName);

            emit AssetStorageRemoved(assetStorageName, assetStorageAddress);
        }
    }

    function removeAssetStorageByAddress(address assetStorageAddress) external onlyOwner {
        if (assetStorageSet.exists(assetStorageAddress)) {
            string memory assetStorageName = assetStorageSet.get(assetStorageAddress).name;

            assetStorageSet.remove(assetStorageAddress);

            emit AssetStorageRemoved(assetStorageName, assetStorageAddress);
        }
    }

    function getContractAddress(string calldata contractName) external view returns (address) {
        return contractSet.get(contractName).addr;
    }

    function getAssetStorageAddress(string calldata assetStorageName) external view returns (address) {
        return assetStorageSet.get(assetStorageName).addr;
    }

    function getAllContracts() external view returns (UnorderedNamedContractDynamicSet.Contract[] memory) {
        return contractSet.getAll();
    }

    function getAllAssetStorages() external view returns (UnorderedNamedContractDynamicSet.Contract[] memory) {
        return assetStorageSet.getAll();
    }

    function isContract(string calldata contractName) external view returns (bool) {
        return contractSet.exists(contractName);
    }

    function isContract(address selectedContractAddress) external view returns (bool) {
        return contractSet.exists(selectedContractAddress);
    }

    function isAssetStorage(string calldata assetStorageName) external view returns (bool) {
        return assetStorageSet.exists(assetStorageName);
    }

    function isAssetStorage(address assetStorageAddress) external view returns (bool) {
        return assetStorageSet.exists(assetStorageAddress);
    }

    /**
     * @dev Forwards a function call to a specified target contract.
     * @notice This function can only be called by the contract owner or a multisig owner.
     * @param target The address of the target contract.
     * @param data The calldata containing the function signature and arguments for the target contract's function.
     * @return result The return data of the target contract's function call.
     */
    function forwardCall(address target, bytes calldata data) public onlyOwnerOrMultiSigOwner returns (bytes memory) {
        // Check if the target contract is registered in the Hub
        if (!contractSet.exists(target) && !assetStorageSet.exists(target)) {
            revert HubLib.InvalidTargetContract(target);
        }

        // Perform the function call to the target contract with the specified calldata
        (bool success, bytes memory result) = target.call{value: 0}(data);

        // If the call is unsuccessful, revert the transaction with the original revert reason
        if (!success) {
            assembly {
                // Load the free memory pointer from memory slot 0x40
                // Memory slot 0x40 is conventionally used to store the free memory pointer in Solidity, which points
                // to the next available memory slot for storing data during the execution of a contract function.
                let ptr := mload(0x40)
                // Get the size of the return data from the unsuccessful call
                let size := returndatasize()
                // Copy the return data to the memory location pointed to by ptr
                returndatacopy(ptr, 0, size)
                // Revert the transaction with the return data as the revert reason
                revert(ptr, size)
            }
        }

        return result;
    }

    function setAndReinitializeContracts(
        HubLib.Contract[] calldata newContracts,
        HubLib.Contract[] calldata newAssetStorageContracts,
        address[] calldata contractsToReinitialize,
        HubLib.ForwardCallInputArgs[] calldata forwardCallsData
    ) external onlyOwnerOrMultiSigOwner {
        _setContracts(newContracts);
        _setAssetStorageContracts(newAssetStorageContracts);
        _reinitializeContracts(contractsToReinitialize);
        _forwardCalls(forwardCallsData);
    }

    function _setContractAddress(string calldata contractName, address newContractAddress) internal {
        if (contractSet.exists(contractName)) {
            contractSet.update(contractName, newContractAddress);

            address oldContractAddress = contractSet.get(contractName).addr;
            if (_isContract(oldContractAddress)) {
                try IContractStatus(oldContractAddress).setStatus(false) {
                    // success
                } catch {
                    // Best-effort: contract may not implement IContractStatus; ignore.
                }
            }

            emit ContractChanged(contractName, newContractAddress);
        } else {
            contractSet.append(contractName, newContractAddress);

            emit NewContract(contractName, newContractAddress);
        }

        if (_isContract(newContractAddress)) {
            try IContractStatus(newContractAddress).setStatus(true) {
                // success
            } catch {
                // Best-effort: contract may not implement IContractStatus; ignore.
            }
        }

        emit NewContract(contractName, newContractAddress);
    }

    function _setContracts(HubLib.Contract[] calldata newContracts) internal {
        for (uint256 i; i < newContracts.length; ) {
            _setContractAddress(newContracts[i].name, newContracts[i].addr);

            unchecked {
                i++;
            }
        }
    }

    function _setAssetStorageAddress(string calldata assetStorageName, address assetStorageAddress) internal {
        if (assetStorageSet.exists(assetStorageName)) {
            emit AssetStorageChanged(assetStorageName, assetStorageAddress);
            assetStorageSet.update(assetStorageName, assetStorageAddress);
        } else {
            emit NewAssetStorage(assetStorageName, assetStorageAddress);
            assetStorageSet.append(assetStorageName, assetStorageAddress);
        }
    }

    function _setAssetStorageContracts(HubLib.Contract[] calldata newAssetStorageContracts) internal {
        for (uint256 i; i < newAssetStorageContracts.length; ) {
            _setAssetStorageAddress(newAssetStorageContracts[i].name, newAssetStorageContracts[i].addr);

            unchecked {
                i++;
            }
        }
    }

    function _reinitializeContracts(address[] calldata contractsToReinitialize) internal {
        for (uint256 i; i < contractsToReinitialize.length; ) {
            IInitializable(contractsToReinitialize[i]).initialize();
            unchecked {
                i++;
            }
        }
    }

    function _forwardCalls(HubLib.ForwardCallInputArgs[] calldata forwardCallsData) internal {
        for (uint256 i; i < forwardCallsData.length; ) {
            address contractAddress;

            // Try to get the contract address using getContractAddress
            try this.getContractAddress(forwardCallsData[i].contractName) returns (address addr) {
                contractAddress = addr;
            } catch {
                // If getContractAddress fails, try getAssetStorageAddress
                try this.getAssetStorageAddress(forwardCallsData[i].contractName) returns (address addr) {
                    contractAddress = addr;
                } catch {
                    revert HubLib.ContractNotRegistered(forwardCallsData[i].contractName);
                }
            }
            for (uint256 j; j < forwardCallsData[i].encodedData.length; ) {
                forwardCall(contractAddress, forwardCallsData[i].encodedData[j]);
                unchecked {
                    j++;
                }
            }
            unchecked {
                i++;
            }
        }
    }

    function _isContract(address addr) internal view returns (bool) {
        uint256 size;
        assembly {
            size := extcodesize(addr)
        }
        return size > 0;
    }

    function _isMultiSigOwner(address multiSigAddress) internal view returns (bool) {
        try ICustodian(multiSigAddress).getOwners() returns (address[] memory multiSigOwners) {
            for (uint256 i = 0; i < multiSigOwners.length; i++) {
                if (msg.sender == multiSigOwners[i]) {
                    return true;
                }
            }
        } catch {
            // Not a multisig or call reverted; treat as not owner.
        }

        return false;
    }

    function _checkOwnerOrMultiSigOwner() internal view virtual {
        address hubOwner = owner();
        if (msg.sender != hubOwner && !_isMultiSigOwner(hubOwner)) {
            revert HubLib.UnauthorizedAccess("Only Hub Owner or Multisig Owner");
        }
    }
}

contracts/storage/IdentityStorage.sol.content:
// SPDX-License-Identifier: Apache-2.0

pragma solidity ^0.8.20;

import {HubDependent} from "../abstract/HubDependent.sol";
import {IERC734Extended} from "../interfaces/IERC734Extended.sol";
import {INamed} from "../interfaces/INamed.sol";
import {IVersioned} from "../interfaces/IVersioned.sol";
import {ByteArr} from "../libraries/ByteArr.sol";
import {IdentityLib} from "../libraries/IdentityLib.sol";
import {IdentityStorage} from "../storage/IdentityStorage.sol";

contract IdentityStorage is IERC734Extended, INamed, IVersioned, HubDependent {
    using ByteArr for bytes32[];

    string private constant _NAME = "IdentityStorage";
    string private constant _VERSION = "10.0.2";

    uint72 public lastIdentityId;

    struct Identity {
        mapping(bytes32 => Key) keys;
        mapping(uint256 => bytes32[]) keysByPurpose;
    }

    // operationalKey => identityId
    mapping(bytes32 => uint72) public identityIds;
    // identityId => Identity
    mapping(uint72 => Identity) internal identities;

    constructor(address hubAddress) HubDependent(hubAddress) {}

    function name() external pure virtual override returns (string memory) {
        return _NAME;
    }

    function version() external pure virtual override returns (string memory) {
        return _VERSION;
    }

    function deleteIdentity(uint72 identityId) external virtual onlyContracts {
        bytes32[] memory operationalKeys = identities[identityId].keysByPurpose[IdentityLib.OPERATIONAL_KEY];
        uint256 operationalKeysNumber = operationalKeys.length;

        for (uint256 i; i < operationalKeysNumber; ) {
            delete identityIds[operationalKeys[i]];
            unchecked {
                i++;
            }
        }

        delete identities[identityId];
    }

    function addKey(
        uint72 identityId,
        bytes32 _key,
        uint256 _purpose,
        uint256 _type
    ) external virtual override onlyContracts {
        Identity storage identity = identities[identityId];
        identity.keys[_key].purpose = _purpose;
        identity.keys[_key].keyType = _type;
        identity.keys[_key].key = _key;
        identity.keysByPurpose[_purpose].push(_key);

        emit KeyAdded(identityId, _key, _purpose, _type);
    }

    function removeKey(uint72 identityId, bytes32 _key) external virtual override onlyContracts {
        IdentityStorage.Identity storage identity = identities[identityId];

        uint256 index;
        (index, ) = identity.keysByPurpose[identity.keys[_key].purpose].indexOf(_key);
        identity.keysByPurpose[identity.keys[_key].purpose].removeByIndex(index);

        emit KeyRemoved(identityId, identity.keys[_key].key, identity.keys[_key].purpose, identity.keys[_key].keyType);

        delete identity.keys[_key];
    }

    function keyHasPurpose(
        uint72 identityId,
        bytes32 _key,
        uint256 _purpose
    ) external view virtual override returns (bool) {
        return identities[identityId].keys[_key].purpose == _purpose;
    }

    function getKey(
        uint72 identityId,
        bytes32 _key
    ) external view virtual override returns (uint256, uint256, bytes32) {
        return (
            identities[identityId].keys[_key].purpose,
            identities[identityId].keys[_key].keyType,
            identities[identityId].keys[_key].key
        );
    }

    function getKeysByPurpose(
        uint72 identityId,
        uint256 _purpose
    ) external view virtual override returns (bytes32[] memory) {
        return identities[identityId].keysByPurpose[_purpose];
    }

    function getIdentityId(address operational) external view returns (uint72) {
        return identityIds[keccak256(abi.encodePacked(operational))];
    }

    function setOperationalKeyIdentityId(bytes32 operationalKey, uint72 identityId) external virtual onlyContracts {
        identityIds[operationalKey] = identityId;
    }

    function removeOperationalKeyIdentityId(bytes32 operationalKey) external virtual onlyContracts {
        delete identityIds[operationalKey];
    }

    function setLastIdentityId(uint72 identityId) external virtual onlyContracts {
        lastIdentityId = identityId;
    }

    function generateIdentityId() external virtual onlyContracts returns (uint72) {
        unchecked {
            return ++lastIdentityId;
        }
    }
}

contracts/storage/ParametersStorage.sol.content:
// SPDX-License-Identifier: Apache-2.0

pragma solidity ^0.8.20;

import {HubDependent} from "../abstract/HubDependent.sol";
import {INamed} from "../interfaces/INamed.sol";
import {IVersioned} from "../interfaces/IVersioned.sol";
import {ICustodian} from "../interfaces/ICustodian.sol";

contract ParametersStorage is INamed, IVersioned, HubDependent {
    event ParameterChanged(string parameterName, uint256 parameterValue);
    /// @notice Emitted when the protocol treasury recipient changes. The
    ///         address is carried in its own event (rather than the
    ///         `uint256`-valued `ParameterChanged`) so off-chain indexers get a
    ///         typed `address` field.
    event ProtocolTreasurySet(address indexed treasury);

    error ZeroShardingTableSizeLimit();

    string private constant _NAME = "ParametersStorage";
    // protocol treasury fee (`protocolTreasuryFee`, `protocolTreasury`,
    // `MAX_PROTOCOL_TREASURY_FEE`) skimmed from the staker-bound TRAC on
    // every paid publish / update / lifetime-extension.
    string private constant _VERSION = "10.0.4";

    uint96 public minimumStake;
    uint96 public maximumStake;

    uint256 public stakeWithdrawalDelay;
    uint256 public nodeAskUpdateDelay;
    uint256 public operatorFeeUpdateDelay;

    uint16 public opWalletsLimitOnProfileCreation;
    uint16 public shardingTableSizeLimit;

    uint256 public minimumRequiredSignatures;

    uint256 public askUpperBoundFactor;
    uint256 public askLowerBoundFactor;

    uint16 public maxOperatorFee;

    uint256 public v81ReleaseEpoch;
    uint256 public publishingConvictionEpochs;

    /// @notice Protocol treasury fee in basis points (out of 10_000) skimmed
    ///         from the staker-bound TRAC on every paid publish / update /
    ///         lifetime-extension. The fee is taken out of the amount that
    ///         would otherwise flow to the staker reward pool — it does NOT
    ///         change the price a publisher pays. Default 300 (3%).
    ///
    ///         The fee is a no-op while `protocolTreasury == address(0)`
    ///         (the full amount flows to stakers), so it stays dormant until
    ///         governance wires a treasury recipient via `setProtocolTreasury`.
    uint16 public protocolTreasuryFee;

    /// @notice Recipient of the protocol treasury fee. The zero address
    ///         disables the fee entirely regardless of `protocolTreasuryFee`.
    address public protocolTreasury;

    /// @notice Minimum TRAC deposit required to register a Context Graph
    ///         on-chain (`ContextGraphs.createContextGraph`). The deposit is
    ///         held as the CG's prepaid publishing escrow — spendable by the
    ///         CG owner on publish/update/extend into that CG — and is never
    ///         cash-refundable (residue sweeps to the staker reward pool on
    ///         deactivation). Anti-spam for the unbounded-CG-creation DoS
    ///         (OT-RFC-53). Setting it to 0 disables the deposit (dormant).
    uint96 public contextGraphRegistrationDeposit;

    /// @notice Hard upper bound on `protocolTreasuryFee` (10%). Bounds
    ///         governance so the fee can never be set to an extractive level
    ///         that would starve the staker reward pool.
    uint16 public constant MAX_PROTOCOL_TREASURY_FEE = 1_000;

    /// @notice Hard upper bound on `publishingConvictionEpochs`.
    ///
    /// `DKGPublishingConvictionNFT._settleElapsed` / `_finalSweep` loop
    /// `lockDurationEpochs` times in the worst case (dormant account
    /// settled at expiry). Each iteration costs ~30–50k gas
    /// (`windowSpent` SLOAD + one or two `epochStorage.addTokensToEpochRange`
    /// writes + a `WindowSettled` event), so an unbounded
    /// `publishingConvictionEpochs` (the previous cap was `uint16.max`)
    /// would let governance brick PCAs by setting the parameter past
    /// the block-gas budget. 60 chain epochs ≈ 5 years at a 1-month
    /// epoch length and worst-cases at ~3M gas — comfortably below
    /// the block limit while leaving room for the surrounding
    /// `publish` / `topUp` / NFT-transfer work.
    uint256 public constant MAX_PUBLISHING_CONVICTION_EPOCHS = 60;

    // @dev Only transactions by HubController owner or one of the owners of the MultiSig Wallet
    modifier onlyOwnerOrMultiSigOwner() {
        _checkOwnerOrMultiSigOwner();
        _;
    }

    constructor(address hubAddress, uint256 _v81ReleaseEpoch) HubDependent(hubAddress) {
        minimumStake = 50_000 ether;
        maximumStake = 10_000_000 ether;

        stakeWithdrawalDelay = 28 days;
        nodeAskUpdateDelay = 1 days;
        operatorFeeUpdateDelay = 28 days;

        opWalletsLimitOnProfileCreation = 50;
        shardingTableSizeLimit = 500;

        minimumRequiredSignatures = 3;

        askUpperBoundFactor = 1467000000000000000;
        askLowerBoundFactor = 533000000000000000;

        maxOperatorFee = 10_000;

        // Epoch when v8.1 was released on mainnet/testnet
        // Change if you ever redeploy delegatorsInfo contract on either network
        v81ReleaseEpoch = _v81ReleaseEpoch;
        publishingConvictionEpochs = 12;

        // 3% default. Dormant until `protocolTreasury` is set (defaults to
        // the zero address), so a fresh deploy behaves exactly as before
        // until governance opts in.
        protocolTreasuryFee = 300;

        // OT-RFC-53: constructor leaves the registration deposit at 0; the
        // standard deploy sets the live value (100 TRAC) via a post-deploy
        // script that calls `setContextGraphRegistrationDeposit`. This protects
        // production automatically (no manual step, no silent-off) while keeping
        // test fixtures — which don't run that script — unaffected. Governance
        // can retune or disable it anytime.
    }

    function name() external pure virtual override returns (string memory) {
        return _NAME;
    }

    function version() external pure virtual override returns (string memory) {
        return _VERSION;
    }

    function setAskUpperBoundFactor(uint256 _askUpperBoundFactor) external onlyOwnerOrMultiSigOwner {
        askUpperBoundFactor = _askUpperBoundFactor;
    }

    function setAskLowerBoundFactor(uint256 _askLowerBoundFactor) external onlyOwnerOrMultiSigOwner {
        askLowerBoundFactor = _askLowerBoundFactor;
    }

    function setMinimumRequiredSignatures(uint256 _minimumRequiredSignatures) external onlyOwnerOrMultiSigOwner {
        minimumRequiredSignatures = _minimumRequiredSignatures;

        emit ParameterChanged("minimumRequiredSignatures", _minimumRequiredSignatures);
    }

    function setMinimumStake(uint96 newMinimumStake) external onlyOwnerOrMultiSigOwner {
        minimumStake = newMinimumStake;

        emit ParameterChanged("minimumStake", newMinimumStake);
    }

    function setMaximumStake(uint96 newMaximumStake) external onlyOwnerOrMultiSigOwner {
        maximumStake = newMaximumStake;

        emit ParameterChanged("maximumStake", newMaximumStake);
    }

    function setStakeWithdrawalDelay(uint256 newStakeWithdrawalDelay) external onlyOwnerOrMultiSigOwner {
        stakeWithdrawalDelay = newStakeWithdrawalDelay;

        emit ParameterChanged("stakeWithdrawalDelay", newStakeWithdrawalDelay);
    }

    function setNodeAskUpdateDelay(uint256 newNodeAskUpdateDelay) external onlyOwnerOrMultiSigOwner {
        nodeAskUpdateDelay = newNodeAskUpdateDelay;

        emit ParameterChanged("nodeAskUpdateDelay", newNodeAskUpdateDelay);
    }

    function setOperatorFeeUpdateDelay(uint256 newOperatorFeeUpdateDelay) external onlyOwnerOrMultiSigOwner {
        operatorFeeUpdateDelay = newOperatorFeeUpdateDelay;

        emit ParameterChanged("operatorFeeUpdateDelay", newOperatorFeeUpdateDelay);
    }

    function setOpWalletsLimitOnProfileCreation(
        uint16 opWalletsLimitOnProfileCreation_
    ) external onlyOwnerOrMultiSigOwner {
        opWalletsLimitOnProfileCreation = opWalletsLimitOnProfileCreation_;

        emit ParameterChanged("opWalletsLimitOnProfileCreation", opWalletsLimitOnProfileCreation);
    }

    function setShardingTableSizeLimit(uint16 shardingTableSizeLimit_) external onlyOwnerOrMultiSigOwner {
        // Reject 0: ShardingTable._insertNode now enforces this cap
        // (`nodesCount >= limit` reverts ShardingTableIsFull), so a 0 limit would
        // freeze ALL node admission (even the first insert), bricking staking. 0
        // is never a meaningful table size — reject it rather than let it act as
        // an implicit pause switch.
        if (shardingTableSizeLimit_ == 0) revert ZeroShardingTableSizeLimit();
        shardingTableSizeLimit = shardingTableSizeLimit_;

        emit ParameterChanged("shardingTableSizeLimit", shardingTableSizeLimit);
    }

    function setMaxOperatorFee(uint16 maxOperatorFee_) external onlyOwnerOrMultiSigOwner {
        maxOperatorFee = maxOperatorFee_;

        emit ParameterChanged("maxOperatorFee", maxOperatorFee);
    }

    function setV81ReleaseEpoch(uint256 _v81ReleaseEpoch) external onlyOwnerOrMultiSigOwner {
        v81ReleaseEpoch = _v81ReleaseEpoch;

        emit ParameterChanged("v81ReleaseEpoch", _v81ReleaseEpoch);
    }

    function setPublishingConvictionEpochs(
        uint256 _publishingConvictionEpochs
    ) external onlyOwnerOrMultiSigOwner {
        require(_publishingConvictionEpochs > 0, "publishingConvictionEpochs must be > 0");
        // See `MAX_PUBLISHING_CONVICTION_EPOCHS` for the gas-budget
        // rationale. The previous `<= type(uint16).max` bound permitted
        // values that would gas-out PCA settlement.
        require(
            _publishingConvictionEpochs <= MAX_PUBLISHING_CONVICTION_EPOCHS,
            "publishingConvictionEpochs too large"
        );
        publishingConvictionEpochs = _publishingConvictionEpochs;

        emit ParameterChanged("publishingConvictionEpochs", _publishingConvictionEpochs);
    }

    function setContextGraphRegistrationDeposit(uint96 amount) external onlyOwnerOrMultiSigOwner {
        contextGraphRegistrationDeposit = amount;

        emit ParameterChanged("contextGraphRegistrationDeposit", amount);
    }

    function setProtocolTreasuryFee(uint16 protocolTreasuryFee_) external onlyOwnerOrMultiSigOwner {
        // See `MAX_PROTOCOL_TREASURY_FEE` for the rationale on the upper
        // bound. 0 is allowed (disables the fee while keeping the recipient
        // wired) — the floor is enforced implicitly by the unsigned type.
        require(protocolTreasuryFee_ <= MAX_PROTOCOL_TREASURY_FEE, "protocolTreasuryFee too large");
        protocolTreasuryFee = protocolTreasuryFee_;

        emit ParameterChanged("protocolTreasuryFee", protocolTreasuryFee_);
    }

    function setProtocolTreasury(address protocolTreasury_) external onlyOwnerOrMultiSigOwner {
        protocolTreasury = protocolTreasury_;

        emit ProtocolTreasurySet(protocolTreasury_);
    }

    function _isMultiSigOwner(address multiSigAddress) internal view returns (bool) {
        // First check if the address has contract code
        uint256 size;
        assembly {
            size := extcodesize(multiSigAddress)
        }

        // If no contract code, it's an EOA, not a multisig
        if (size == 0) {
            return false;
        }

        try ICustodian(multiSigAddress).getOwners() returns (address[] memory multiSigOwners) {
            for (uint256 i = 0; i < multiSigOwners.length; i++) {
                if (msg.sender == multiSigOwners[i]) {
                    return true;
                }
            }
        } catch {
            // Not a multisig or call reverted; treat as not owner.
        }

        return false;
    }

    function _checkOwnerOrMultiSigOwner() internal view virtual {
        address hubOwner = hub.owner();
        if (msg.sender != hubOwner && msg.sender != address(hub) && !_isMultiSigOwner(hubOwner)) {
            revert("Only Hub Owner, Hub, or Multisig Owner can call");
        }
    }
}

contracts/storage/ProfileStorage.sol.content:
// SPDX-License-Identifier: Apache-2.0

pragma solidity ^0.8.20;

import {HubDependent} from "../abstract/HubDependent.sol";
import {ProfileLib} from "../libraries/ProfileLib.sol";
import {INamed} from "../interfaces/INamed.sol";
import {IVersioned} from "../interfaces/IVersioned.sol";

contract ProfileStorage is INamed, IVersioned, HubDependent {
    string private constant _NAME = "ProfileStorage";
    // Bumped 1.0.0 -> 1.1.0: ProfileInfo struct extended with relayCapable
    // (RFC 04 v0.3 / Issue #461). New mapping reads on existing keys return
    // false for the new field. Multiaddrs were briefly added on a prior
    // revision but are deliberately not stored on Profile (RFC 04 §5.2).
    // 10.0.3 -> 10.0.4: active-fee getters (fee / percentage / effective-date)
    // centralized in `_activeOperatorFee`, fixing the `operatorFees[length - 2]`
    // underflow panic on the single-not-yet-effective-fee state (the effective-date
    // getter still had it).
    string private constant _VERSION = "10.0.4";

    event ProfileCreated(uint72 indexed identityId, string nodeName, bytes nodeId, uint16 initialOperatorFee);
    event ProfileDeleted(uint72 indexed identityId, bytes nodeId);
    event NodeNameUpdated(uint72 indexed identityId, string oldName, string newName);
    event NodeIdUpdated(uint72 indexed identityId, bytes oldNodeId, bytes newNodeId);
    event NodeAskUpdated(uint72 indexed identityId, uint96 oldAsk, uint96 newAsk);
    event OperatorFeeAdded(uint72 indexed identityId, uint16 feePercentage, uint256 effectiveDate);
    event OperatorFeesReplaced(
        uint72 indexed identityId,
        uint16 oldFeePercentage,
        uint16 newFeePercentage,
        uint256 effectiveDate
    );
    event OperatorFeesUpdated(uint72 indexed identityId, ProfileLib.OperatorFee[] operatorFees);
    // RFC 04 v0.3: relay-capability flag (multiaddrs live in attestation KAs, not Profile).
    event RelayCapabilityUpdated(uint72 indexed identityId, bool oldValue, bool newValue);

    mapping(uint72 => ProfileLib.ProfileInfo) public profiles;
    mapping(string => bool) public isNameTaken;
    mapping(bytes => bool) public nodeIdsList;
    mapping(uint72 => uint256) public askUpdateCooldown;

    constructor(address hubAddress) HubDependent(hubAddress) {}

    function name() external pure override returns (string memory) {
        return _NAME;
    }

    function version() external pure override returns (string memory) {
        return _VERSION;
    }

    function createProfile(
        uint72 identityId,
        string calldata nodeName,
        bytes calldata nodeId,
        uint16 initialOperatorFee
    ) external onlyContracts {
        ProfileLib.ProfileInfo storage profile = profiles[identityId];
        profile.name = nodeName;
        profile.nodeId = nodeId;
        profile.operatorFees.push(ProfileLib.OperatorFee(initialOperatorFee, block.timestamp));
        nodeIdsList[nodeId] = true;

        emit ProfileCreated(identityId, nodeName, nodeId, initialOperatorFee);
    }

    function getProfile(
        uint72 identityId
    )
        external
        view
        returns (
            string memory,
            bytes memory,
            uint96,
            ProfileLib.OperatorFee[] memory,
            bool
        )
    {
        ProfileLib.ProfileInfo storage profile = profiles[identityId];

        return (
            profile.name,
            profile.nodeId,
            profile.ask,
            profile.operatorFees,
            profile.relayCapable
        );
    }

    function deleteProfile(uint72 identityId) external onlyContracts {
        bytes memory nodeId = profiles[identityId].nodeId;
        nodeIdsList[nodeId] = false;
        delete profiles[identityId];

        emit ProfileDeleted(identityId, nodeId);
    }

    function getName(uint72 identityId) external view returns (string memory) {
        return profiles[identityId].name;
    }

    function setName(uint72 identityId, string memory _name) external onlyContracts {
        ProfileLib.ProfileInfo storage profile = profiles[identityId];
        string memory oldName = profile.name;

        profile.name = _name;

        emit NodeNameUpdated(identityId, oldName, _name);
    }

    function getNodeId(uint72 identityId) external view returns (bytes memory) {
        return profiles[identityId].nodeId;
    }

    function setNodeId(uint72 identityId, bytes calldata nodeId) external onlyContracts {
        ProfileLib.ProfileInfo storage profile = profiles[identityId];
        bytes memory oldNodeId = profile.nodeId;

        nodeIdsList[oldNodeId] = false;
        profile.nodeId = nodeId;
        nodeIdsList[nodeId] = true;

        emit NodeIdUpdated(identityId, oldNodeId, nodeId);
    }

    function setAsk(uint72 identityId, uint96 ask) external onlyContracts {
        ProfileLib.ProfileInfo storage profile = profiles[identityId];
        uint96 oldAsk = profile.ask;

        profile.ask = ask;

        emit NodeAskUpdated(identityId, oldAsk, ask);
    }

    function setAskUpdateCooldown(uint72 identityId, uint256 cooldownEnd) external onlyContracts {
        askUpdateCooldown[identityId] = cooldownEnd;
    }

    function getAsk(uint72 identityId) external view returns (uint96) {
        return profiles[identityId].ask;
    }

    function addOperatorFee(uint72 identityId, uint16 feePercentage, uint256 effectiveDate) external onlyContracts {
        profiles[identityId].operatorFees.push(ProfileLib.OperatorFee(feePercentage, effectiveDate));

        emit OperatorFeeAdded(identityId, feePercentage, effectiveDate);
    }

    function getOperatorFee(uint72 identityId) external view returns (uint16) {
        return getActiveOperatorFeePercentage(identityId);
    }

    function getOperatorFees(uint72 identityId) external view returns (ProfileLib.OperatorFee[] memory) {
        return profiles[identityId].operatorFees;
    }

    function setOperatorFees(uint72 identityId, ProfileLib.OperatorFee[] memory operatorFees) external onlyContracts {
        profiles[identityId].operatorFees = operatorFees;

        emit OperatorFeesUpdated(identityId, operatorFees);
    }

    // =====================================================================
    // RFC 04 v0.3 / Issue #461 — relay-capability flag.
    //
    // This flag is the operator's "I intend to run as a relay" hint. It
    // gates the operator's per-round attestation publish (RFC 04 Phase 2)
    // — operators with relayCapable=false don't bother running the cosig
    // + submit pipeline at all. Multiaddrs themselves live in the
    // per-round attestation KA body, not on Profile (RFC 04 §5.2).
    // =====================================================================

    function getRelayCapable(uint72 identityId) external view returns (bool) {
        return profiles[identityId].relayCapable;
    }

    function setRelayCapable(uint72 identityId, bool relayCapable) external onlyContracts {
        ProfileLib.ProfileInfo storage profile = profiles[identityId];
        bool oldValue = profile.relayCapable;
        profile.relayCapable = relayCapable;

        emit RelayCapabilityUpdated(identityId, oldValue, relayCapable);
    }

    function replacePendingOperatorFee(
        uint72 identityId,
        uint16 feePercentage,
        uint256 effectiveDate
    ) external onlyContracts {
        if (
            profiles[identityId].operatorFees.length == 0 ||
            block.timestamp >
            profiles[identityId].operatorFees[profiles[identityId].operatorFees.length - 1].effectiveDate
        ) {
            revert ProfileLib.NoPendingOperatorFee();
        }

        uint16 oldFeePercentage = profiles[identityId]
            .operatorFees[profiles[identityId].operatorFees.length - 1]
            .feePercentage;
        profiles[identityId].operatorFees[profiles[identityId].operatorFees.length - 1] = ProfileLib.OperatorFee({
            feePercentage: feePercentage,
            effectiveDate: effectiveDate
        });

        emit OperatorFeesReplaced(identityId, oldFeePercentage, feePercentage, effectiveDate);
    }

    function getOperatorFeesLength(uint72 identityId) external view returns (uint256) {
        return profiles[identityId].operatorFees.length;
    }

    function getOperatorFeeByIndex(
        uint72 identityId,
        uint256 index
    ) public view returns (ProfileLib.OperatorFee memory) {
        return profiles[identityId].operatorFees[index];
    }

    function getOperatorFeeByTimestamp(
        uint72 identityId,
        uint256 timestamp
    ) external view returns (ProfileLib.OperatorFee memory) {
        return _getOperatorFeeByTimestamp(identityId, timestamp, false);
    }

    function getOperatorFeeByTimestampReverse(
        uint72 identityId,
        uint256 timestamp
    ) external view returns (ProfileLib.OperatorFee memory) {
        return _getOperatorFeeByTimestamp(identityId, timestamp, true);
    }

    function getLatestOperatorFee(uint72 identityId) external view returns (ProfileLib.OperatorFee memory) {
        return _safeGetLatestOperatorFee(identityId);
    }

    /// @dev The currently-active operator fee. Centralizes the `length - 2`
    ///      underflow guard so every active-fee getter (fee / percentage /
    ///      effective-date) shares ONE implementation. A single fee is always
    ///      active; with more than one, the latest applies once its effectiveDate
    ///      has passed (strict `>`), otherwise the prior fee. The `length == 1`
    ///      guard also covers the createProfile case where the initial fee's
    ///      effectiveDate == block.timestamp would otherwise hit `length - 2`.
    function _activeOperatorFee(uint72 identityId) internal view returns (ProfileLib.OperatorFee memory) {
        ProfileLib.OperatorFee[] storage fees = profiles[identityId].operatorFees;
        uint256 length = fees.length;
        if (length == 0) {
            return ProfileLib.OperatorFee({feePercentage: 0, effectiveDate: 0});
        }
        if (length == 1 || block.timestamp > fees[length - 1].effectiveDate) {
            return fees[length - 1];
        }
        return fees[length - 2];
    }

    function getActiveOperatorFee(uint72 identityId) external view returns (ProfileLib.OperatorFee memory) {
        return _activeOperatorFee(identityId);
    }

    function getOperatorFeePercentageByIndex(uint72 identityId, uint256 index) external view returns (uint16) {
        return profiles[identityId].operatorFees[index].feePercentage;
    }

    function getOperatorFeePercentageByTimestamp(uint72 identityId, uint256 timestamp) external view returns (uint16) {
        return _getOperatorFeeByTimestamp(identityId, timestamp, false).feePercentage;
    }

    function getOperatorFeePercentageByTimestampReverse(
        uint72 identityId,
        uint256 timestamp
    ) external view returns (uint16) {
        return _getOperatorFeeByTimestamp(identityId, timestamp, true).feePercentage;
    }

    function getLatestOperatorFeePercentage(uint72 identityId) external view returns (uint16) {
        return _safeGetLatestOperatorFee(identityId).feePercentage;
    }

    function getActiveOperatorFeePercentage(uint72 identityId) public view returns (uint16) {
        return _activeOperatorFee(identityId).feePercentage;
    }

    function getOperatorFeeEffectiveDateByIndex(uint72 identityId, uint256 index) external view returns (uint256) {
        return profiles[identityId].operatorFees[index].effectiveDate;
    }

    function getOperatorFeeEffectiveDateByTimestamp(
        uint72 identityId,
        uint256 timestamp
    ) external view returns (uint256) {
        return _getOperatorFeeByTimestamp(identityId, timestamp, false).effectiveDate;
    }

    function getOperatorFeeEffectiveDateByTimestampReverse(
        uint72 identityId,
        uint256 timestamp
    ) external view returns (uint256) {
        return _getOperatorFeeByTimestamp(identityId, timestamp, true).effectiveDate;
    }

    function getLatestOperatorFeeEffectiveDate(uint72 identityId) external view returns (uint256) {
        return _safeGetLatestOperatorFee(identityId).effectiveDate;
    }

    function getActiveOperatorFeeEffectiveDate(uint72 identityId) external view returns (uint256) {
        return _activeOperatorFee(identityId).effectiveDate;
    }

    function isOperatorFeeChangePending(uint72 identityId) external view returns (bool) {
        return (profiles[identityId].operatorFees.length != 0 &&
            block.timestamp <=
            profiles[identityId].operatorFees[profiles[identityId].operatorFees.length - 1].effectiveDate);
    }

    function profileExists(uint72 identityId) external view returns (bool) {
        return keccak256(profiles[identityId].nodeId) != keccak256(bytes(""));
    }

    function _safeGetLatestOperatorFee(uint72 identityId) internal view returns (ProfileLib.OperatorFee memory) {
        if (profiles[identityId].operatorFees.length == 0) {
            return ProfileLib.OperatorFee({feePercentage: 0, effectiveDate: 0});
        } else {
            return profiles[identityId].operatorFees[profiles[identityId].operatorFees.length - 1];
        }
    }

    function _getOperatorFeeByTimestamp(
        uint72 identityId,
        uint256 timestamp,
        bool reverseLookup
    ) internal view returns (ProfileLib.OperatorFee memory) {
        ProfileLib.OperatorFee[] storage fees = profiles[identityId].operatorFees;

        if (fees.length == 0) {
            return ProfileLib.OperatorFee({feePercentage: 0, effectiveDate: 0});
        }
        if (timestamp > fees[fees.length - 1].effectiveDate) {
            return fees[fees.length - 1];
        }
        if (timestamp < fees[0].effectiveDate) {
            return fees[0];
        }
        if (reverseLookup) {
            for (uint256 i = fees.length - 1; i > 0; ) {
                unchecked {
                    --i;
                }
                if (fees[i].effectiveDate <= timestamp) {
                    return fees[i];
                }
            }
            return fees[0];
        } else {
            for (uint256 i; i < fees.length; ) {
                if (fees[i].effectiveDate > timestamp) {
                    return i == 0 ? fees[0] : fees[i - 1];
                }
                unchecked {
                    ++i;
                }
            }
        }
        return ProfileLib.OperatorFee({feePercentage: 0, effectiveDate: 0});
    }
}

contracts/storage/PublishingConvictionSt.content:
// SPDX-License-Identifier: Apache-2.0

pragma solidity ^0.8.20;

import {INamed} from "../interfaces/INamed.sol";
import {IVersioned} from "../interfaces/IVersioned.sol";
import {IInitializable} from "../interfaces/IInitializable.sol";
import {HubDependent} from "../abstract/HubDependent.sol";

/**
 * @title PublishingConvictionStorage
 * @notice Single source of truth for V10 publisher conviction account state.
 *
 * Architecture (mirrors the V10 staking split — `ConvictionStakingStorage`
 * holds positions, `StakingV10` is stateless logic, `DKGStakingConvictionNFT`
 * is a thin ERC-721 wrapper):
 *
 *   - `PublishingConvictionStorage` (this contract) owns every byte of
 *     application state for publisher conviction accounts: the `Account`
 *     struct keyed by `accountId`, per-billing-window TRAC accounting
 *     (`windowSpent`), the persistent top-up buffer (`topUpBalance`), the
 *     agent registration tables, and the governance-tunable
 *     `maxAgentsPerAccount` cap.
 *
 *     This is a fresh-state contract: it ships EMPTY at deploy time
 *     and there is NO automated migration path that copies state out
 *     of the legacy combined `DKGPublishingConvictionNFT` v2.x. PCA
 *     accounts opened against the v2.x contract are NOT readable here
 *     after the upgrade. This is intentional and matches how the V10
 *     line has handled prior storage-split redeploys
 *     (`ProfileStorage`, `ParametersStorage`): network operators bump
 *     `chainResetMarker` in the network config so daemons auto-wipe
 *     their derived chain state on next start, the on-chain Hub
 *     re-points consumers (`KnowledgeAssetsV10`, `ContextGraphs`) at
 *     this contract, and the publisher fleet re-creates conviction
 *     accounts under the new wrapper. PR #650 ships the
 *     `chainResetMarker` bump alongside this storage contract; do
 *     NOT deploy the new PCA stack against a network without the
 *     accompanying marker bump. See `network/testnet.json` and the
 *     PR body's "Migration / fresh-state reset" section.
 *   - `PublishingConviction` (the new logic contract) holds zero
 *     application state — only Hub-resolved contract references and
 *     metadata. It reads/writes here via `onlyContracts`-gated mutators
 *     and runs every business rule (account creation, billing-window
 *     settlement, lazy passive-sink sweeps, post-expiry final sweep, and
 *     active-sink epoch distribution).
 *   - `DKGPublishingConvictionNFT` keeps only the ERC-721 surface
 *     (mint/burn, transfer hook, ownership checks), the
 *     `_nextAccountId` mint counter, and the publisher-facing TRAC
 *     `transferFrom` paths. Every state read/write goes through this
 *     storage contract.
 *
 * Storage independence (the architectural goal):
 *   - The logic contract can be redeployed without touching account or
 *     agent state — Hub re-registers the new logic address, the storage
 *     keeps every existing `accounts[id]`, `topUpBalance[id]`,
 *     `windowSpent[id][w]`, and agent registration intact.
 *   - The NFT wrapper can also be redeployed (e.g. ERC-721 metadata
 *     surface change), at the cost of resetting `_nextAccountId` —
 *     existing accounts keep their state but new mints would clash if
 *     the counter resets, so this is an upgrade path that requires care.
 *
 * State boundaries (what does NOT live here):
 *   - `_nextAccountId` — stays on the NFT wrapper because it is tightly
 *     coupled to ERC-721 mint ordering; the wrapper increments and
 *     supplies the new id to the logic contract on each `createAccount`
 *     forward (mirrors `DKGStakingConvictionNFT.nextTokenId`).
 *   - TRAC vault custody — TRAC sits in `ConvictionStakingStorage`
 *     (the V10 vault, post-v4.0.0 consolidation). This storage contract
 *     never holds TRAC and never moves it. The NFT wrapper drives
 *     `transferFrom(publisher → CSS)` directly on `createAccount` /
 *     `topUp`; this storage only updates the bookkeeping that controls
 *     how that escrowed TRAC eventually flows to staker pools via
 *     `EpochStorage.addTokensToEpochRange`.
 *
 * Caller gates:
 *   - Mutating functions are `onlyContracts` — only Hub-registered
 *     contracts (in practice `PublishingConviction`, with the NFT
 *     wrapper as a fallback for direct-write paths if ever needed) can
 *     invoke them.
 *   - `setMaxAgentsPerAccount` is `onlyHubOwner` because it is a
 *     governance-side parameter (mirrors `setStatus` / parameter
 *     setters on other V10 storage contracts).
 *
 * Invariants enforced inside this contract:
 *   - `agentToAccountId[agent] == accountId` iff
 *     `_isRegisteredAgent[accountId][agent] == true`. Agent register /
 *     deregister / clear-all paths flip both flags atomically so the
 *     two views never drift.
 *   - `_registeredAgents[accountId]` always equals the set of `agent`s
 *     for which `_isRegisteredAgent[accountId][agent] == true`. The
 *     swap-and-pop in `removeAgent` keeps the array in sync.
 */
contract PublishingConvictionStorage is INamed, IVersioned, HubDependent, IInitializable {
    string private constant _NAME = "PublishingConvictionStorage";
    // 1.0.0 — initial split-out from `DKGPublishingConvictionNFT` v2.0.0.
    //         Identical state shape; no semantic changes.
    // 10.0.3 — OT-RFC-51 "Publishing Allocation": `Account` gains
    //          `primaryNode` + `lastPrimaryNodeChangeEpoch`, with the
    //          `setPrimaryNodeData` onlyContracts setter.
    string private constant _VERSION = "10.0.3";

    /// @notice Default cap on registered agents per account, applied on
    ///         first `initialize()` so a fresh deploy has a sane bound
    ///         even before a HubOwner explicitly tunes it.
    uint256 internal constant _DEFAULT_MAX_AGENTS_PER_ACCOUNT = 100;

    // ============================================================
    //                     Account record
    // ============================================================
    //
    // Field semantics (mirrors the legacy v2.x struct exactly so account
    // state migrates 1:1 from the NFT):
    //   - committedTRAC          : original commit at creation. Never
    //                              changes after `createAccount`.
    //   - createdAtEpoch         : Chronos epoch the account was created
    //                              in (informational; not used for math).
    //   - expiresAtEpoch         : first chain epoch past the account's
    //                              lock (exclusive upper bound for
    //                              `getRemainingAllowance`).
    //   - createdAtTimestamp     : wall-clock anchor; billing windows
    //                              are computed relative to this.
    //   - expiresAtTimestamp     : `createdAtTimestamp +
    //                              lockDurationEpochs * epochLength`.
    //   - lockDurationEpochs     : number of billing windows the account
    //                              spans (also the number of base-budget
    //                              slices `committedTRAC` is divided into).
    //   - discountBps            : 6-tier discount fixed at creation;
    //                              top-ups do NOT change it.
    //   - lastSettledWindow      : next unsettled billing-window index
    //                              (exclusive of the highest already-swept
    //                              window). Drives the lazy-settlement loop.
    //   - fullySwept             : terminal flag. True once the post-expiry
    //                              final sweep has accounted leftover
    //                              top-up + dust to the staker pool. Acts
    //                              as a re-entry guard.
    struct Account {
        uint96 committedTRAC;
        uint40 createdAtEpoch;
        uint40 expiresAtEpoch;
        uint40 createdAtTimestamp;
        uint40 expiresAtTimestamp;
        uint16 lockDurationEpochs;
        uint16 discountBps;
        uint16 lastSettledWindow;
        bool fullySwept;
        // OT-RFC-51 "Publishing Allocation": the node this account's
        // committed PCA budget is credited to as publishing allocation
        // (K_n). `0` means no designated node (no allocation seeded).
        uint72 primaryNode; // designated node identityId; 0 = none
        // Rate-limit cursor for `setPrimaryNode`: re-designation is allowed
        // at most once per chain epoch (require currentEpoch > this value).
        uint40 lastPrimaryNodeChangeEpoch; // re-designation rate-limit cursor
    }

    // ============================================================
    //                       Events
    // ============================================================

    /// @notice Emitted when the governance-tunable agent cap changes.
    event MaxAgentsPerAccountUpdated(uint256 oldCap, uint256 newCap);

    // ============================================================
    //                        Errors
    // ============================================================

    error AccountAlreadyExists(uint256 accountId);
    error UnknownAccount(uint256 accountId);
    error AgentAlreadyRegistered(address agent, uint256 existingAccountId);
    error AgentNotRegistered(uint256 accountId, address agent);
    error TopUpUnderflow(uint256 accountId, uint96 amount, uint96 balance);

    // ============================================================
    //                       State
    // ============================================================

    mapping(uint256 => Account) public accounts;

    /// @notice Per-billing-window TRAC drawn against the current
    ///         account's base allowance. Second key is the billing-window
    ///         index (0-based, relative to `Account.createdAtTimestamp`);
    ///         it is NOT a chain-epoch number. The base allowance per
    ///         window is `committedTRAC / lockDurationEpochs`; a window's
    ///         entry is bounded by that value.
    mapping(uint256 => mapping(uint40 => uint96)) public windowSpent;

    /// @notice Persistent top-up buffer per account (NOT per-window).
    ///         Drained only when the current window's base allowance is
    ///         exhausted. Any non-zero balance at account expiry is swept
    ///         to the staker pool by the final-sweep path.
    mapping(uint256 => uint96) public topUpBalance;

    /// @notice Per-account agent enumeration. Kept as an array so the
    ///         transfer hook on the NFT wrapper can iterate and clear
    ///         every registration in one call. The agent-side reverse
    ///         map is `agentToAccountId`.
    mapping(uint256 => address[]) internal _registeredAgents;

    /// @notice Reverse map exposed publicly so external callers
    ///         (`KnowledgeAssetsV10`, `ContextGraphs`) can resolve a
    ///         publishing-agent address to its paying account id without
    ///         caller-supplied authorization. The "not registered"
    ///         sentinel is `0`, which is why `_nextAccountId` on the NFT
    ///         starts at 1.
    mapping(address => uint256) public agentToAccountId;

    /// @notice Membership index that lets `coverPublishingCost` /
    ///         `deregisterAgent` decide whether an `agent` is registered
    ///         under `accountId` in O(1) without scanning
    ///         `_registeredAgents[accountId]`.
    mapping(uint256 => mapping(address => bool)) internal _isRegisteredAgent;

    /// @notice Governance-tunable cap on `_registeredAgents[accountId].length`.
    ///         Initialized to `_DEFAULT_MAX_AGENTS_PER_ACCOUNT` on the
    ///         first `initialize()`; a HubOwner can retune via
    ///         `setMaxAgentsPerAccount`.
    uint256 public maxAgentsPerAccount;

    constructor(address hubAddress) HubDependent(hubAddress) {}

    /// @dev `initialize()` is idempotent across redeploys: the first call
    ///      seeds `maxAgentsPerAccount` to the default; subsequent calls
    ///      (e.g. post-upgrade) preserve whatever value the HubOwner has
    ///      tuned it to.
    function initialize() external onlyHub {
        if (maxAgentsPerAccount == 0) {
            maxAgentsPerAccount = _DEFAULT_MAX_AGENTS_PER_ACCOUNT;
        }
    }

    function name() external pure virtual override returns (string memory) {
        return _NAME;
    }

    function version() external pure virtual override returns (string memory) {
        return _VERSION;
    }

    // ============================================================
    //                  Account read helpers
    // ============================================================

    /// @notice Return the full `Account` record by id. Reverts if the
    ///         account has never been created (sentinel:
    ///         `lockDurationEpochs == 0` because every real account
    ///         carries at least one billing window).
    function getAccount(uint256 accountId) external view returns (Account memory) {
        Account memory a = accounts[accountId];
        if (a.lockDurationEpochs == 0) revert UnknownAccount(accountId);
        return a;
    }

    /// @notice Existence check used by callers that only need to know
    ///         whether an account record is populated (e.g. the public
    ///         `settle()` short-circuit). Returns `false` for any
    ///         accountId that has never been minted.
    function accountExists(uint256 accountId) external view returns (bool) {
        return accounts[accountId].lockDurationEpochs != 0;
    }

    // ============================================================
    //                  Account write helpers
    // ============================================================

    /// @notice Persist a brand-new `Account` record. Used by
    ///         `PublishingConviction.createAccount` after the NFT
    ///         wrapper has allocated `accountId` from its mint counter.
    ///         Reverts if a record at `accountId` already exists, so a
    ///         logic-side bug or replay cannot silently overwrite an
    ///         active account.
    function createAccount(uint256 accountId, Account calldata acct) external onlyContracts {
        if (accounts[accountId].lockDurationEpochs != 0) revert AccountAlreadyExists(accountId);
        accounts[accountId] = acct;
    }

    /// @notice Advance the lazy-settlement cursor. Caller (logic) is
    ///         responsible for never moving it past `lockDurationEpochs`.
    function setLastSettledWindow(uint256 accountId, uint16 w) external onlyContracts {
        accounts[accountId].lastSettledWindow = w;
    }

    /// @notice Mark the account as fully swept. Called once by the
    ///         post-expiry final-sweep path; subsequent settle calls
    ///         observe `fullySwept == true` and short-circuit.
    function setFullySwept(uint256 accountId, bool v) external onlyContracts {
        accounts[accountId].fullySwept = v;
    }

    /// @notice OT-RFC-51: persist the designated `primaryNode` and the
    ///         `lastPrimaryNodeChangeEpoch` rate-limit cursor. Logic-side
    ///         (`PublishingConviction.setPrimaryNode`) is responsible for
    ///         the once-per-epoch gate and for `nodeExists` validation;
    ///         storage just records.
    function setPrimaryNodeData(
        uint256 accountId,
        uint72 node,
        uint40 changeEpoch
    ) external onlyContracts {
        accounts[accountId].primaryNode = node;
        accounts[accountId].lastPrimaryNodeChangeEpoch = changeEpoch;
    }

    // ============================================================
    //                  Window-spent write helpers
    // ============================================================

    /// @notice Add `amount` to `windowSpent[accountId][w]`. Logic-side
    ///         callers are responsible for never exceeding the per-window
    ///         base allowance (`committedTRAC / lockDurationEpochs`); the
    ///         storage contract just records.
    function increaseWindowSpent(
        uint256 accountId,
        uint40 w,
        uint96 amount
    ) external onlyContracts {
        windowSpent[accountId][w] += amount;
    }

    // ============================================================
    //                  Top-up balance write helpers
    // ============================================================

    /// @notice Add to the persistent top-up buffer (publisher pays in
    ///         to extend allowance beyond the base budget).
    function increaseTopUpBalance(uint256 accountId, uint96 amount) external onlyContracts {
        topUpBalance[accountId] += amount;
    }

    /// @notice Drain `amount` from the top-up buffer. Reverts on
    ///         underflow so callers cannot silently overdraw — this is
    ///         a defensive guard; logic-side `coverPublishingCost`
    ///         already rejects insufficient-allowance combinations
    ///         with a richer error.
    function decreaseTopUpBalance(uint256 accountId, uint96 amount) external onlyContracts {
        uint96 bal = topUpBalance[accountId];
        if (amount > bal) revert TopUpUnderflow(accountId, amount, bal);
        unchecked {
            topUpBalance[accountId] = bal - amount;
        }
    }

    /// @notice Zero the top-up buffer in a single SSTORE; used by the
    ///         post-expiry final sweep before crediting the staker pool.
    function clearTopUpBalance(uint256 accountId) external onlyContracts {
        if (topUpBalance[accountId] != 0) {
            topUpBalance[accountId] = 0;
        }
    }

    // ============================================================
    //                  Agent registry helpers
    // ============================================================

    /// @notice Read the registered-agent array for an account. Returns
    ///         an empty array for unknown accounts so callers can
    ///         iterate safely on accounts that never registered an agent.
    function getRegisteredAgents(uint256 accountId) external view returns (address[] memory) {
        return _registeredAgents[accountId];
    }

    /// @notice O(1) membership check used by `coverPublishingCost` and
    ///         `deregisterAgent` to validate (accountId, agent) pairs
    ///         without scanning the array.
    function isRegisteredAgent(uint256 accountId, address agent) external view returns (bool) {
        return _isRegisteredAgent[accountId][agent];
    }

    /// @notice Number of agents registered under `accountId`. Useful for
    ///         the public `getAccountInfo` view on the NFT wrapper.
    function agentCount(uint256 accountId) external view returns (uint256) {
        return _registeredAgents[accountId].length;
    }

    /// @notice Append `agent` under `accountId`. Reverts if `agent` is
    ///         already registered anywhere (the reverse map is global —
    ///         a single agent address may pay for at most one account).
    ///         The cap (`maxAgentsPerAccount`) is enforced by the logic
    ///         contract, NOT here, because storage stays policy-free.
    function addAgent(uint256 accountId, address agent) external onlyContracts {
        if (agentToAccountId[agent] != 0) {
            revert AgentAlreadyRegistered(agent, agentToAccountId[agent]);
        }
        _registeredAgents[accountId].push(agent);
        _isRegisteredAgent[accountId][agent] = true;
        agentToAccountId[agent] = accountId;
    }

    /// @notice Remove `agent` from `accountId`. Reverts if not registered.
    ///         The array is compacted via swap-and-pop; the reverse map
    ///         and membership index are both cleared so the
    ///         agent address can be re-registered later (against the
    ///         same or a different account).
    function removeAgent(uint256 accountId, address agent) external onlyContracts {
        if (!_isRegisteredAgent[accountId][agent]) {
            revert AgentNotRegistered(accountId, agent);
        }

        _isRegisteredAgent[accountId][agent] = false;
        agentToAccountId[agent] = 0;

        address[] storage agents = _registeredAgents[accountId];
        uint256 len = agents.length;
        for (uint256 i; i < len; i++) {
            if (agents[i] == agent) {
                agents[i] = agents[len - 1];
                agents.pop();
                break;
            }
        }
    }

    /// @notice Bulk-clear every agent registration under `accountId`.
    ///         Used by the NFT wrapper's transfer hook so the new owner
    ///         starts with a clean agent slate (no inherited authorities
    ///         from the prior owner). Idempotent on accounts with no
    ///         registered agents.
    function clearAgents(uint256 accountId) external onlyContracts {
        address[] storage agents = _registeredAgents[accountId];
        uint256 len = agents.length;
        for (uint256 i; i < len; i++) {
            _isRegisteredAgent[accountId][agents[i]] = false;
            agentToAccountId[agents[i]] = 0;
        }
        if (len != 0) {
            delete _registeredAgents[accountId];
        }
    }

    // ============================================================
    //                  Governance — agent cap
    // ============================================================

    /// @notice Tune the per-account agent cap. `onlyContracts` here so
    ///         the NFT wrapper's `setMaxAgentsPerAccount` forwarder can
    ///         drive the write — the wrapper enforces the `onlyHubOwner`
    ///         user-facing gate. Direct PCS callers from outside the
    ///         Hub-registered contract set are rejected. Setting the
    ///         cap below an existing account's registered count does
    ///         NOT retroactively unregister anyone — it only blocks
    ///         further `addAgent` calls until the count drops.
    function setMaxAgentsPerAccount(uint256 cap) external onlyContracts {
        uint256 old = maxAgentsPerAccount;
        maxAgentsPerAccount = cap;
        emit MaxAgentsPerAccountUpdated(old, cap);
    }
}

